\caption{Benchmark CNN Studies for MNIST Classification}
\label{tab:mnist_cnn_benchmarks}
\begin{tabular}{|l|c|c|}
\hline
\textbf{Reference} & \textbf{Number of Conv Layers} & \textbf{Test Accuracy (\%)} \\
\hline
