The probability of observing topic $o_1 \in \topics$ in week $i_1 \in [r]$ and topic $o_2 \in \topics$ in week $i_2 \in [r]$ when $i_1 \neq i_2$ can be calculated using the fact that, conditioned on the type $I$, these events are independent.
\begin{align*}
    \prob(o_1 \in S_{i_1} \wedge& o_2 \in S_{i_2})
    = \frac{1}{T} \sum_{t=1}^T \prob(o_1 \in S_{i_1} \wedge o_2 \in S_{i_2} \mid I = t) \\
    &= \frac{1}{T} \sum_{t=1}^T \prob(o_1 \in S_{i_1} \mid I = t)
    \cdot
    \prob(o_2 \in S_{i_2} \mid I = t) \\
    &= \frac{1}{T} \sum_{t=1}^T
    \bigl(1 - N(\theta; t, i_1, \{o_1\})\bigr)
    \cdot
    \bigl(1 - N(\theta; t, i_2, \{o_2\})\bigr)\\
    &=: \qacross(\theta; i_1, i_2, o_1, o_2).
\end{align*}

Finally, all three functions $\qsingle$, $\qwithin$, and $\qacross$ are differentiable functions of $\theta$, since they are differentiable in $N$.
\end{proof}

\lemSensitivity*
\begin{proof}
Let $$D' = D \cup \{(S_0(v), S_1(v))\}$$ for a user $v\notin \users$.
Notice that $f_{11}(D')-f_{11}(D)$ is vector with only 0,1 entries where the $1$ correspond to the ${k \choose 2}$ counts for topics pairs $o_i, o_j \in S_0(v)$  in the corresponding positions in $f_{11}$.

The same is true for  $f_{22}$, while for $f_{12}$ we have a 1 in the $k^2$ counts for topics pairs $o_i \in S_0(v)$ and $o_j \in S_1(v)$ ( in the corresponding positions in $f_{12}$). 
Hence the $\ell_2$ norm of the difference is $\sqrt{{k \choose 2}}$ for $f_{11}$ and $f_{22}$ and $k$ for $f_{12}$.
\end{proof}



