  \multirow{2}*{$(2l, l, 2)$} & $\gcd(l, d_1) = \gcd(l, d_2) = \gcd(l, d_2-d_1) = m$, & \multirow{2}*{$d_1-1$} & \multirow{2}*{Theorem \ref{H=H}}\\
