\subsection{List of LTL laws imposed for each actor}\label{appendix:laws}
\subsubsection{SayCan}
The hard-hand engineered safety rules that prevent illegal actions are given below:


\begin{enumerate}
    \item \texttt{LTL:}$G(\lnot \textsf{obs\_iron\_pickaxe\_equipped} \rightarrow X(\lnot \textsf{action\_mine\_diamond}))$ \\
    \texttt{Explanation:}{Diamonds cannot be mined unless an iron pickaxe is equipped.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_near\_crafting\_table} \rightarrow X(\lnot \textsf{action\_craft\_wooden\_pickaxe} \land \lnot \textsf{action\_craft\_stone\_pickaxe} \land \lnot \textsf{action\_craft\_iron\_pickaxe}))$ \\
    \texttt{Explanation:}{Cannot craft any type of pickaxe unless near a crafting table.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_near\_crafting\_table} \rightarrow X(\lnot \textsf{action\_craft\_furnace}))$ \\
    \texttt{Explanation:}{Cannot craft a furnace unless near a crafting table.}

    \item \texttt{LTL:}$G(\lnot(\textsf{obs\_stone\_pickaxe\_equipped} \lor \textsf{obs\_iron\_pickaxe\_equipped}) \rightarrow X(\lnot \textsf{action\_mine\_iron\_ore}))$ \\
    \texttt{Explanation:}{Cannot mine iron ore unless a stone or iron pickaxe is equipped.}

    \item \texttt{LTL:}$G(\lnot(\textsf{obs\_wood\_pickaxe\_equipped} \lor \textsf{obs\_stone\_pickaxe\_equipped} \lor \textsf{obs\_iron\_pickaxe\_equipped}) \rightarrow X(\lnot \textsf{action\_mine\_stone}))$ \\
    \texttt{Explanation:}{Cannot mine stone unless any pickaxe is equipped.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_iron\_pickaxe} \rightarrow X(\lnot \textsf{action\_equip\_iron\_pickaxe}))$ \\
    \texttt{Explanation:}{Cannot equip an iron pickaxe unless the agent has one.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_3x\_plank} \lor \lnot \textsf{obs\_has\_2x\_stick} \rightarrow X(\lnot \textsf{action\_craft\_wooden\_pickaxe}))$ \\
    \texttt{Explanation:}{Cannot craft a wooden pickaxe without enough planks and sticks.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_4x\_plank} \rightarrow X(\lnot \textsf{action\_craft\_crafting\_table}))$ \\
    \texttt{Explanation:}{Cannot craft a crafting table without 4 planks.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_8x\_cobble} \rightarrow X(\lnot \textsf{action\_craft\_furnace}))$ \\
    \texttt{Explanation:}{Cannot craft a furnace without 8 cobblestone.}

    \item \texttt{LTL:}$G(\lnot(\textsf{obs\_has\_2x\_stick} \land \textsf{obs\_has\_3x\_iron\_ingot}) \rightarrow X(\lnot \textsf{action\_craft\_iron\_pickaxe}))$ \\
    \texttt{Explanation:}{Cannot craft an iron pickaxe without 2 sticks and 3 iron ingots.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_3x\_cobble} \lor \lnot \textsf{obs\_has\_2x\_stick} \rightarrow X(\lnot \textsf{action\_craft\_stone\_pickaxe}))$ \\
    \texttt{Explanation:}{Cannot craft a stone pickaxe without cobblestone and sticks.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_coal\_in\_chunk} \lor \lnot(\textsf{obs\_wood\_pickaxe\_equipped} \lor \textsf{obs\_stone\_pickaxe\_equipped} \lor \textsf{obs\_iron\_pickaxe\_equipped}) \rightarrow X(\lnot \textsf{action\_mine\_coal}))$ \\
    \texttt{Explanation:}{Cannot mine coal unless coal is nearby and a pickaxe is equipped.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_log} \rightarrow X(\lnot \textsf{action\_craft\_planks}))$ \\
    \texttt{Explanation:}{Cannot craft planks without logs.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_2x\_plank} \rightarrow X(\lnot \textsf{action\_craft\_stick}))$ \\
    \texttt{Explanation:}{Cannot craft sticks without 2 planks.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_near\_furnace} \lor \lnot \textsf{obs\_has\_1x\_iron\_ore} \lor \lnot \textsf{obs\_has\_fuel} \rightarrow X(\lnot \textsf{action\_smelt\_iron}))$ \\
    \texttt{Explanation:}{Cannot smelt iron without a furnace, fuel, and iron ore.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_wood\_pickaxe} \rightarrow X(\lnot \textsf{action\_equip\_wood\_pickaxe}))$ \\
    \texttt{Explanation:}{Cannot equip a wooden pickaxe unless the agent has one.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_stone\_pickaxe} \rightarrow X(\lnot \textsf{action\_equip\_stone\_pickaxe}))$ \\
    \texttt{Explanation:}{Cannot equip a stone pickaxe unless the agent has one.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_crafting\_table} \rightarrow X(\lnot \textsf{action\_place\_crafting\_table}))$ \\
    \texttt{Explanation:}{Cannot place a crafting table unless the agent has one.}

    \item \texttt{LTL:}$G(\lnot \textsf{obs\_has\_furnace} \rightarrow X(\lnot \textsf{action\_place\_furnace}))$ \\
    \texttt{Explanation:}{Cannot place a furnace unless the agent has one.}
\end{enumerate}


The soft LTL rules implemented by the critic are as follows:
\begin{enumerate}
    \item \texttt{LTL:} $G(\lnot \mathsf{obs\_has\_log} \land \lnot \mathsf{obs\_has\_plank} \land \lnot \mathsf{obs\_has\_2x\_stick} \land \lnot \mathsf{obs\_has\_iron\_pickaxe} \rightarrow X(\mathsf{action\_mine\_log}))$ \\
    \texttt{Explanation:}{If the agent lacks logs, planks, sticks, and an iron pickaxe, it should mine wood logs.}

    \item \texttt{LTL:}$G(\mathsf{obs\_has\_log} \land \lnot \mathsf{obs\_has\_plank} \rightarrow X(\mathsf{action\_craft\_planks}))$ \\
    \texttt{Explanation:}{If the agent has logs but no planks, it should craft planks.}

    \item \texttt{LTL:}$G(\mathsf{obs\_has\_2x\_plank} \land \lnot \mathsf{obs\_has\_2x\_stick} \rightarrow X(\mathsf{action\_craft\_stick}))$ \\
    \texttt{Explanation:}{If the agent has planks but no sticks, it should craft sticks.}

    \item \texttt{LTL:}$G(\mathsf{obs\_has\_4x\_plank} \land \mathsf{obs\_has\_2x\_stick} \land \lnot \mathsf{obs\_has\_crafting\_table} \land \lnot \mathsf{obs\_near\_crafting\_table} \rightarrow X(\mathsf{action\_craft\_crafting\_table}))$ \\
    \texttt{Explanation:}{If the agent has 4 planks and 2 sticks but no crafting table is nearby or already crafted, it must craft a crafting table.}

    \item \texttt{LTL:}$G(\mathsf{obs\_has\_4x\_plank} \land \mathsf{obs\_has\_2x\_stick} \land \mathsf{obs\_has\_crafting\_table} \land \lnot \mathsf{obs\_near\_crafting\_table} \rightarrow X(\mathsf{action\_place\_crafting\_table}))$ \\
    \texttt{Explanation:}{If the agent has 4 planks, 2 sticks, and a crafting table but is not near one, it should place the crafting table.}

    \item \texttt{LTL:}$G(\mathsf{obs\_has\_3x\_plank} \land \mathsf{obs\_has\_2x\_stick} \land \lnot \mathsf{obs\_has\_wood\_pickaxe} \land \mathsf{obs\_near\_crafting\_table} \rightarrow X(\mathsf{action\_craft\_wooden\_pickaxe}))$ \\
    \texttt{Explanation:}{If the agent has 3 planks, 2 sticks, is near a crafting table, and doesn’t already have a wooden pickaxe, it should craft one.}

    \item \texttt{LTL:}$G(\mathsf{obs\_has\_wooden\_pickaxe} \land \lnot \mathsf{obs\_wooden\_pickaxe\_equipped} \land \lnot \mathsf{obs\_has\_3x\_cobble} \rightarrow X(\mathsf{action\_equip\_wooden\_pickaxe}))$ \\
    \texttt{Explanation:}{If the agent has a wooden pickaxe but it isn’t equipped and it lacks three cobblestones, it should equip the pickaxe.}

    \item \texttt{LTL:}$G(\mathsf{obs\_wood\_pickaxe\_equipped} \land \lnot \mathsf{obs\_has\_3x\_cobble} \land \lnot \mathsf{obs\_has\_stone\_pickaxe} \land \lnot \mathsf{obs\_has\_2x\_stick} \rightarrow X(\mathsf{action\_mine\_stone}))$ \\
    \texttt{Explanation:}{If equipped with a wooden pickaxe and lacking stone, the agent should mine cobblestone.}

    \item \texttt{LTL:}$G(\mathsf{obs\_wood\_pickaxe\_equipped} \land \mathsf{obs\_has\_3x\_cobble} \land \lnot \mathsf{obs\_has\_stone\_pickaxe} \rightarrow X(\mathsf{action\_craft\_stone\_pickaxe}))$ \\
    \texttt{Explanation:}{If the agent has 3 cobblestones and a wooden pickaxe equipped, it should craft a stone pickaxe.}

    \item \texttt{LTL:}$G(\mathsf{obs\_has\_3x\_iron\_ore} \land \mathsf{obs\_near\_furnace} \land \mathsf{obs\_has\_fuel} \land \lnot \mathsf{obs\_has\_3x\_iron\_ingot} \rightarrow X(\mathsf{action\_smelt\_iron}))$ \\
    \texttt{Explanation:}{If the agent has 3 iron ore, is near a furnace, has fuel, and lacks 3 ingots, it should smelt iron.}

    \item \texttt{LTL:}$G(\mathsf{obs\_has\_3x\_iron\_ingot} \land \mathsf{obs\_has\_2x\_stick} \land \mathsf{obs\_near\_crafting\_table} \land \lnot \mathsf{obs\_has\_iron\_pickaxe} \rightarrow X(\mathsf{action\_craft\_iron\_pickaxe}))$ \\
    \texttt{Explanation:}{If the agent has the ingredients but no iron pickaxe, it should craft one.}

    \item \texttt{LTL:}$G(\mathsf{obs\_has\_iron\_pickaxe} \land \lnot \mathsf{obs\_iron\_pickaxe\_equipped} \land \lnot \mathsf{obs\_has\_2x\_stick} \rightarrow X(\mathsf{action\_equip\_iron\_pickaxe}))$ \\
    \texttt{Explanation:}{If the agent owns an iron pickaxe but hasn’t equipped it, it should equip the pickaxe.}

    \item \texttt{LTL:}$G(\mathsf{obs\_iron\_pickaxe\_equipped} \land \lnot \mathsf{obs\_diamond\_in\_chunk} \rightarrow X(\mathsf{action\_explore\_diamond\_down}))$ \\
    \texttt{Explanation:}{If an iron pickaxe is equipped and no diamonds are nearby, explore downward.}

    \item \texttt{LTL:}$G(\lnot \mathsf{obs\_has\_iron\_pickaxe} \land \lnot \mathsf{obs\_iron\_pickaxe\_equipped} \rightarrow X(\lnot \mathsf{action\_explore\_diamond\_down}))$ \\
    \texttt{Explanation:}{Do not explore for diamonds unless an iron pickaxe is available and equipped.}

    \item \texttt{LTL:}$G(\mathsf{obs\_has\_fuel} \land \mathsf{obs\_iron\_in\_chunk} \land \mathsf{obs\_coal\_in\_chunk} \rightarrow X(\lnot \mathsf{action\_explore\_general}))$ \\
    \texttt{Explanation:}{Do not explore if iron and coal are already known to be nearby.}
\end{enumerate}


