\title{Tensor Sketch:\\Fast and Scalable Polynomial Kernel Approximation}
%\title{Fast and Scalable Polynomial Kernels Using Tensor Sketches}

\author{\name Ninh Pham \email ninh.pham@auckland.ac.nz\\ 
