\subsection{AMS Sketch on the Tensor Domain}~\label{sec:ams}

Similar to the Maclaurin-based approach of \citet{Kar12}, AMS Sketches can be employed as random features to approximate polynomial kernels. Below, we focus on the construction of a single random feature; computing 
$D$ features is straightforward by independently repeating this process 
$D$ times.
\citet{Indyk08}, followed by \citet{Braverman10}, analyzed the use of products of AMS Sketches with independently chosen hash functions, and established the following result:

%
\begin{lemma}~\cite[Lemma 4.1]{Braverman10}\label{lem:AMS1}
	%
	Consider $\bx \in \mathbb{R}^{d}$, an integer $p > 1$, and $p$ independently sampled functions $s_1, \ldots, s_p: [d] \mapsto \{-1, 1\}$ from a 4-wise independent family.
	Define $Z = \prod_{j=1}^p Z_{s_j}(\bx)$. Then $\E{Z^2} = \| \bx^{(p)} \|_2^{2} = \| \bx \|_2^{2p}$ and $\Var{Z^2} \leq  (3^p - 1)\|\bx^{(p)}\|_2^{4} = (3^p - 1)\|\bx\|_2^{4p}$. 
	%
\end{lemma}

Since $Z$ is defined as the product of independent AMS sketches, its expectation $\mathbb{E}[Z^2]$ can be directly derived from Lemma~\ref{lem:AMS}. However, analyzing the variance $\mathrm{Var}(Z^2)$ is significantly more challenging and constitutes the main contribution of \citet{Braverman10}.

To proceed, consider defining a composite hash function $S(x_{i_1}, \ldots, x_{i_p}) = \prod_{j=1}^p s_j(x_{i_j})$, which maps a coordinate $x_{i_1}x_{i_2} \ldots x_{i_p}$ of $\bx^{(p)} \in [d]^p$ to $\{-1, 1\}$. Under this definition, $Z$ can be interpreted as an AMS sketch applied to the $p$-th order tensor product $\bx^{(p)}$:
$$Z = Z_{S}(\bx^{(p)}) = \prod_{j=1}^p Z_{s_j}(\bx) \, .$$
However, the hash function $S : [d]^p \rightarrow \{-1, 1\}$ is not drawn from a 4-wise independent family, and thus standard AMS analysis techniques are insufficient to bound the variance.
\citet{Braverman10} address this by analyzing the combinatorial structure of correlations between $S(\bu)$ and $S(\bv)$ for distinct index vectors $\bu, \bv \in [d]^p$. 

Based on this approach, it is natural to generalize Lemma~\ref{lem:AMS1} to handle a pair of tensorized vectors $\bx^{(p)}$ and $\by^{(p)}$, as follows:
\begin{lemma}\label{lem:AMS2}
	%
	Consider $\bx, \by \in \mathbb{R}^{d}$, an integer $p > 1$, and $p$ independently sampled functions $s_1, \ldots, s_p: [d] \mapsto \{-1, 1\}$ from a 4-wise independent family.
	Define $Z = \prod_{j=1}^p Z_{s_j}(\bx)\,Z_{s_j}(\by)$. 
	Then $\E{Z} = \dotxy^{p}$ and $\Var{Z} \leq (3^p - 1) \, \|\bx\|_2^{2p} \, \|\by\|_2^{2p}$.
	%Given two $p$-level tensor products $\bX = \bx^{(p)}, \bY = \by^{(p)} \in \mathbb{R}^{d^p}$ and $p$ independent copies of 4-wise hash functions $s_1, \ldots, s_p: [d] \mapsto \{-1, 1\}$.
	%Define a hash function $S(\bu) = \prod_{i = 1}^{p}s_i(u_i) \in \{-1, 1\}$ where $\bu \in [d]^p$ and a random variable $Z = \left(\sum_{\bu \in [d]^p}{\bX_{\bu}S(\bu)}\right)\left(\sum_{\bv \in [d]^p}{\bY_{\bv}S(\bv)}\right)$. We have $\E{Z} = \left\langle\bX, \bY \right\rangle = \dotxy^{p}$ and $\Var{Z} \leq (3^p - 1)\|\bX\|_2^2 \|\bY\|_2^2 = (3^p - 1)\|\bx\|_2^{2p} \|\by\|_2^{2p}$. 
	%
\end{lemma}
%
% The proof is a simple generalization of the proof in~\cite{Braverman10}(Lemma 4.1) so we leave it in Appendix B.

% since we will show a more general result in Section~\ref{sec:tensorsketch}.
%(\NP{I am not sure that the above statement is correct. Our proof is derived from this lemma. I also changed $Z^2$ to $Z$ since it might confuse that this random value is always non-negative.})
% Note that Lemma~\ref{lem:AMS} is a special case of Lemma~\ref{lem:AMS2}, with $p=1$.

\begin{proof}
	Following the approach of~\cite{Braverman10}, we compute the expectation and variance of \(Z\).
%
	First, we consider the expectation, and for each \(j\), we note that
	\[
	\mathbb{E}\bigl[Z_{s_j}(\bx) \, Z_{s_j}(\by)\bigr] = \mathbb{E}\left[\left(\sum_{i=1}^d x_i\, s_j(i)\right) \left(\sum_{k=1}^d y_k\, s_j(k)\right)\right] = \langle \bx, \by \rangle,
	\]
	where the last equality follows from the 4-wise independence and unbiasedness of the \(s_j\). Since the functions \(s_j\) are independent for different \(j\), we have
	\[
	\mathbb{E}[Z] = \prod_{j=1}^p \mathbb{E}\bigl[Z_{s_j}(\bx)\, Z_{s_j}(\by)\bigr] = \langle \bx, \by \rangle^p \, .
	\]

	Next, we bound the variance \(\operatorname{Var}(Z) = \mathbb{E}[Z^2] - (\mathbb{E}[Z])^2\). Because the hash functions are independent across different \(j\), we may write
	\begin{equation}\label{eq:secondmoment}
		\mathbb{E}[Z^2] = \prod_{j=1}^p \mathbb{E}\Bigl[ \bigl(Z_{s_j}(\bx)\, Z_{s_j}(\by)\bigr)^2 \Bigr] \, .
	\end{equation}
	For each \(j\), expanding the square gives
	\begin{align*}
		\mathbb{E}\Bigl[\bigl(Z_{s_j}(\bx)\, Z_{s_j}(\by)\bigr)^2\Bigr] 
		& = \mathbb{E}\left[ \left( \sum_{i=1}^d x_i\, s_j(i) \right)^2 \left( \sum_{k=1}^d y_k\, s_j(k) \right)^2 \right] \\
		& = \sum_{i=1}^d \sum_{k=1}^d \sum_{i'=1}^d \sum_{k'=1}^d x_i\, y_k\, x_{i'}\, y_{k'}\, \mathbb{E}\left[ s_j(i)\, s_j(k)\, s_j(i')\, s_j(k') \right] \, .
	\end{align*}
	Observing that \(\mathbb{E}\left[s_j(i)s_j(k)s_j(i')s_j(k')\right]\) is nonzero only when the indices form pairs (including the possibility that all four are identical), we have
	\[
	\mathbb{E}\left[ s_j(i)s_j(k)s_j(i')s_j(k') \right] = 
	\begin{cases}
		1 & \text{if } i = k = i' = k', \\
		1 & \text{if } i = k \neq i' = k', \\
		1 & \text{if } i = i' \neq k = k', \\
		1 & \text{if } i = k' \neq k = i', \\
		0 & \text{otherwise}.
	\end{cases}
	\]

	The contribution from terms with \(i = k = i' = k'\) is $\sum_{i=1}^d x_i^2 y_i^2$.
	% \[
	% \sum_{i=1}^d x_i^2 y_i^2.
	% \]
	Terms with \(i = k \neq i' = k'\) contribute
	\[
	\sum_{i\neq i'} x_i\, y_i\, x_{i'}\, y_{i'} = \left(\sum_{i=1}^d x_i\, y_i\right)^2 - \sum_{i=1}^d x_i^2 y_i^2 = \langle \bx, \by \rangle^2 - \sum_{i=1}^d x_i^2 y_i^2 \, .
	\]
	The case \(i = k' \neq k = i'\) is symmetric and yields the same contribution. Finally, for \(i = i' \neq k = k'\) we obtain
	\[
	\sum_{i\neq k} x_i^2\, y_k^2 = \|\bx\|_2^2\, \|\by\|_2^2 - \sum_{i=1}^d x_i^2 y_i^2 \, .
	\]
	Thus, summing these contributions, we have
	\begin{align*}
    \mathbb{E}\Bigl[\bigl(Z_{s_j}(\bx)\, Z_{s_j}(\by)\bigr)^2\Bigr] &= \sum_{i=1}^d x_i^2 y_i^2 + 2\Bigl(\langle \bx, \by \rangle^2 - \sum_{i=1}^d x_i^2 y_i^2\Bigr) + \Bigl(\|\bx\|_2^2\, \|\by\|_2^2 - \sum_{i=1}^d x_i^2 y_i^2\Bigr) \\
    &= 2\langle \bx, \by \rangle^2 + \|\bx\|_2^2\, \|\by\|_2^2 - 2\sum_{i=1}^d x_i^2 y_i^2 \, .
	\end{align*}
	% This simplifies to
	% \[
	% \mathbb{E}\Bigl[\bigl(Z_{s_j}(\bx)\, Z_{s_j}(\by)\bigr)^2\Bigr] = 2\langle \bx, \by \rangle^2 + \|\bx\|_2^2\, \|\by\|_2^2 - 2\sum_{i=1}^d x_i^2 y_i^2.
	% \]
	Using the Cauchy--Schwarz inequality, \(\langle \bx, \by \rangle^2 \leq \|\bx\|_2^2\, \|\by\|_2^2\), and noting that \(\sum_{i=1}^d x_i^2 y_i^2 \geq 0\), it follows that
	\[
	\mathbb{E}\Bigl[\bigl(Z_{s_j}(\bx)\, Z_{s_j}(\by)\bigr)^2\Bigr] \leq 3\, \|\bx\|_2^2\, \|\by\|_2^2 \, .
	\]
	Substituting this bound into \eqref{eq:secondmoment} yields
	\[
	\mathbb{E}[Z^2] \leq \Bigl( 3\, \|\bx\|_2^2\, \|\by\|_2^2 \Bigr)^p,
	\]
	which completes the proof since
	\[
	\operatorname{Var}(Z) = \mathbb{E}[Z^2] - \langle \bx, \by \rangle^{2p} \leq 3^p\, \|\bx\|_2^{2p}\, \|\by\|_2^{2p} \, .
	\]
\end{proof}


Lemma~\ref{lem:AMS2} shows that the AMS sketch can be interpreted as a variant of the Maclaurin-based approach of \citet{Kar12}, where the Rademacher vectors $\mathbf{w}_i$ are replaced by hash functions $s$ drawn from a 4-wise independent family. This substitution enables a provable variance bound for the resulting random feature maps.

\section{Tensor Sketch}\label{sec:tensorsketch}


We now describe how to compute the Count Sketch of a tensor product $\bx^{(p)}$, which serves as a random feature map for approximating polynomial kernels $\kappa(\bx, \by) = \dotxy^p$, for an integer $p > 0$. 
For the kernel  $\kappa(\bx, \by) = \left( c + \dotxy \right)^p$,  we can avoid the constant $c > 0$ by adding an extra dimension of value $\sqrt{c}$ to all data vectors. 
For a fixed polynomial degree $p > 1$, our method maps an input vector $\bx \in \mathbb{R}^d$ to a low-dimensional feature vector in $\mathbb{R}^D$ in time $\mathcal{O}(d + D \log D)$.
This runtime represents a significant improvement over the AMS Sketch-based approach described in Section~\ref{sec:ams}, both in terms of computational efficiency and practical scalability.





\subsection{Convolution of Count Sketches}

\citet{Pagh13} introduced a fast algorithm for computing the Count Sketch of the outer product of two vectors. As our method builds on this technique, we briefly review it here.
Rather than explicitly forming the outer product, the key idea is to first compute the Count Sketches of the input vectors and then derive the sketch of their outer product directly from these compressed representations. As we will show, this process reduces to polynomial multiplication, which can be efficiently implemented using the Fast Fourier Transform (FFT).~\footnote{
For background on FFT, see for example \citet[Section~5.6]{Kleinberg05}.}
This yields an algorithm to compute the Count Sketch of an outer product in time near-linear in the size of the sketches.



More precisely, given a vector $\bx \in \mathbb{R}^d$, we denote by $\bCxone, \bCxtwo \in \mathbb{R}^D$ two different Count Sketches using hash functions $h_1, h_2 : [d] \mapsto [D]$ and $s_1, s_2: [d] \mapsto \left\{ -1, 1 \right\}$, all independently sampled from \textit{2-wise} independent families.
The aim is to compute a Count Sketch of the outer product $\bx \otimes \bx \in \mathbb{R}^{d^2}$, denoted $\bCx^{(2)} \in \mathbb{R}^D$, from $\bCxone$ and $\bCxtwo$. 
We define the Count Sketch $\bCx^{(2)}$ in terms of the hash functions $H : [d^2] \mapsto [D]$ and $S: [d^2] \mapsto \left\{ -1, 1 \right\}$ derived from the functions $h_1, h_2, s_1, s_2$, where:
% XXX
%
\begin{align}\label{eq:Hash}
	H(i_1, i_2) = \left( h_1(i_1) + h_2(i_2) \right) \text{ mod } D \text{ and } S(i_1, i_2) = s_1(i_1)s_2(i_2) \enspace .
\end{align}
%

It is well known that since $h_1$, $h_2$, $s_1$, $s_2$ are sampled from 2-wise independent families, $H$ and $S$ are also sampled from 2-wise independent families~\citep{Patrascu11}. 
Na\"ively computing $\bCx^{(2)}$ would require $\BO{d^2}$ time.
However, by thinking of Count Sketches as polynomials, we are able to exploit FFT to fast compute $\bCx^{(2)}$ given hash functions $H$ and $S$ defined in Equation~\ref{eq:Hash}.

In particular, we represent Count Sketches $\bCxone, \bCxtwo \in \mathbb{R}^D$ as polynomials of degree $D-1$
where each entry $(\bCxone)_k$ or $(\bCxtwo)_k$ is the coefficient of $\omega^k$ in the polynomial:
%For example, we consider two degree-$(D-1)$ polynomials representing for $\bCx_1$ and $\bCx_2$:
%
$$P_\bx(\omega) = \sum_{i=1}^{d}{s_1(i)x_i \, \omega^{h_1(i)}} \text{ and } Q_\bx(\omega) = \sum_{i=1}^{d}{s_2(i)x_i \, \omega^{h_2(i)}} \, .$$
%
In other words, the $k$-th features of $\bCxone$ and $\bCxtwo$ corresponding to the coefficients of the term $\omega^k$ are $\sum_{i, h_1(i) = k} s_1(i)x_i$ and $\sum_{i, h_2(i) = k} s_2(i)x_i$, respectively.
%
We will derive the polynomial multiplication $P_\bx(\omega) \times Q_\bx(\omega)$ as follows.

\begin{align*}
	&P_\bx(\omega) \times Q_\bx(\omega) = \left( \sum_{i=1}^{d}{s_1(i)x_i \, \omega^{h_1(i)}} \right) \left( \sum_{i=1}^{d}{s_2(i)x_i \, \omega^{h_2(i)}} \right) \\
	&= \sum_{i_1,i_2=1}^{d}{s_1(i_1)s_2(i_2)x_{i_1}x_{i_2} \, \omega^{h_1(i_1) + h_2(i_2)}} 
	= \sum_{i_1,i_2=1}^{d}{S(i_1, i_2)x_{i_1}x_{i_2} \, \omega^{h_1(i_1) + h_2(i_2)}} \, . 
%	&=\sum_{i_1,i_2=1}^{d}{S(i_1, i_2)x_{i_1}x_{i_2} \, \omega^{H(i_1, i_2)}} = \sum_{i_1,i_2=1}^{d}{s_1(i_1)s_2(i_2)x_{i_1}x_{i_2} \, \omega^{h_1(i_1) + h_2(i_2) \text{ mod } D}} \\
%	&= \sum_{i_1,i_2=1}^{d}{s_1(i_1)s_2(i_2)x_{i_1}x_{i_2} \, \omega^{ \left( ( h_1(i_1) \text{ mod } D ) + ( h_2(i_2) \text{ mod } D ) \right) \text{ mod } D}}
\end{align*} 

We note that the polynomial $P_\bx(\omega) \times Q_\bx(\omega)$ has degree $2D - 2$ since $h_1, h_2: [d] \mapsto [D]$.
We transform the polynomial $P_\bx(\omega) \times Q_\bx(\omega)$ to the polynomial of degree $D - 1$ by casting coefficients of the term $\omega^k$ as the coefficients of the term $\omega^{k \text{ mod } D}$ where $0 \leq k \leq 2D - 2$.
We denote by $P_{\bx^{(2)}}(\omega)$ the transformation polynomial of $(D - 1)$-degree from $P_\bx(\omega) \times Q_\bx(\omega)$.
It is clear that $P_{\bx^{(2)}}(\omega)$ is polynomial representation of the Count Sketch of the $\bCx^{(2)} \in \mRD$ of $\bx^{(2)}$ using $H$ and $S$ as
\begin{align*}
	P_{\bx^{(2)}}(\omega) &= \sum_{i_1,i_2=1}^{d}{S(i_1, i_2)x_{i_1}x_{i_2} \, \omega^{\left( h_1(i_1) + h_2(i_2) \right) \text{ mod } D}} = \sum_{i_1,i_2=1}^{d}{S(i_1, i_2)x_{i_1}x_{i_2} \, \omega^{H(i_1, i_2)}} \, .
%	&= \sum_{i_1,i_2=1}^{d}{s_1(i_1)s_2(i_2)x_{i_1}x_{i_2} \, \omega^{ \left( ( h_1(i_1) \text{ mod } D ) + ( h_2(i_2) \text{ mod } D ) \right) \text{ mod } D}}
\end{align*} 

The $(D-1)$-degree polynomial $P_{\bx^{(2)}}(\omega)$ derived from the polynomial multiplication $P_\bx(\omega) \times Q_\bx(\omega)$ can be computed in time $\BO{D\log{D}}$ using FFT and its inverse FFT$^{-1}$: %~\citep{Kleinberg05},
%Therefore, we represent the Count Sketch $\bCx^{(2)}$ of outer product $\bx \otimes \bx$ using hash functions $H$ and $S$ as $(D-1)$-degree polynomial as follows:
%
%$$P_{\bx^{(2)}}(\omega) = \sum_{i_1,i_2=1}^{d}{S(i_1, i_2)x_{i_1}x_{i_2} \, \omega^{H(i_1, i_2)}} .$$ 
%
%Since $H(i_1, i_2) = h_1(i_1) + h_2(i_2) \text{ mod } D$, we can exploit FFT-based convolution using $D$ interpolation points to compute $P_{\bx^{(2)}}(\omega)$:
%
$$P_{\bx^{(2)}}(\omega) = \text{FFT}^{-1} \left( \text{FFT}(P_\bx(\omega)) \circ \text{FFT}(Q_\bx(\omega)) \right) \, ,$$
%
where $\circ$ is the component-wise product operator defined by $({\bf a} \circ {\bf b})_i = a_i b_i$. 
In other words, the Count Sketch $\bCx^{(2)}$ of $\bx \otimes \bx$ can be efficiently computed by Count Sketches $\bCxone$ and $\bCxtwo$ in $\BO{d + D\log{D}}$ time.
The first term comes from constructing the count sketches and the latter comes from running FFT three times.


\subsection{Tensor Sketch}

We now extend the previous method to compute Tensor Sketch of a $p$-th tensor power $\bxp$.
This is achieved by convolving $p$ independent Count Sketches, each constructed using hash functions $h_1, \ldots, h_p : [d] \to [D]$ and $s_1, \ldots, s_p : [d] \to \{-1, 1\}$.
The hash functions $h_i$ are drawn from 2-wise independent families, but the sign functions $s_i$ are drawn from \textit{4-wise} independent families to ensure variance bounds in the resulting sketch.
This construction yields a Count Sketch for $\bx^{(p)}$, referred to as the $p$th-order \textit{Tensor Sketch}, defined by the following composite hash functions:
%
\begin{displaymath}
\begin{aligned}
%
H(i_1, \ldots , i_p) = \left( \sum_{j=1}^{p}{h_j(i_j)} \right) \text{ mod } D \text{ and } 
S(i_1, \ldots , i_p) = \prod_{j=1}^{p}{s_j(i_j)} \, .
%
\end{aligned}
\end{displaymath}

We leverage the efficient computation of Count Sketches over tensor domains to develop a fast algorithm for approximating the homogeneous polynomial kernel $\kappa(\bx, \by) = \langle \bx, \by \rangle^p$, where $p$ is a positive integer.
For each input vector $\bx \in \mathbb{R}^d$, Tensor Sketch computes a Count Sketch of the $p$-fold tensor product $\bx^{(p)}$, producing a $D$-dimensional random feature map in $\mathbb{R}^D$ that approximates the kernel.
The full procedure is outlined in Algorithm~\ref{algorithm:tensorsketch}, which illustrates how Tensor Sketch efficiently maps input vectors to the lower-dimensional kernel feature space.
%
\begin{algorithm}[t]
\caption{Tensor Sketch($\bx, p, D$)}
\label{alg1} 									
\begin{algorithmic} [1]
%-----------------------------------------
\REQUIRE { Vector $\bx \in \mRd$, integer $D$, $p > 1$, $h_1, \ldots, h_p: [d] \mapsto [D]$ independently sampled from a 2-wise independent family, $s_1, \ldots, s_p: [d] \mapsto \{-1, 1\}$ independently sampled from a 4-wise independent family. }
\ENSURE { Return a feature vector $f(\bx)\in\mathbb{R}^D$ such that $\E{\left\langle f(\bx),f(\by) \right\rangle} = \kappa(\bx, \by) = \left\langle \bx, \by \right\rangle^p$  }
%-----------------------------------------
%\STATE { $ f(\mS) \gets \emptyset $}
%\STATE { Randomly pick $p$ 2-wise independent hash functions $h_1, \ldots, h_p: [d] \mapsto [D]$}
%\STATE { Randomly pick $p$ 4-wise independent hash functions $s_1, \ldots, s_p: [d] \mapsto \left\{ -1, 1 \right\}$}
%\FOR {each $\bx \in \mS$}
%
	\STATE {For $i = 1, \ldots , p$ create Count Sketch $\bf{C_i x}$ using hash functions $h_i, s_i$ }
	\STATE {For $i = 1, \ldots , p$ let $\bf{\widehat{C}_i x} \gets \text{FFT}(\bf{C_i x}) $ }
%	\STATE {$ (\bf{C_1x}, \ldots , \bf{C_px}) \gets \text{FFT}(\bf{C_1x}, \ldots , \bf{C_px}) $}
	\STATE {Let $\bf{\widehat{C}x} \gets \bf{\widehat C_1x} \circ \ldots \circ \bf{\widehat C_px}$} \hfill (component-wise multiplication)
    \STATE {Let $f({\bf x}) \gets \text{FFT}^{-1}(\bf{\widehat{C}x})$}
%	\STATE {$ f(\bx) \gets \text{FFT}^{-1}(f(\bx)) $ } 
%	\STATE {Insert $f(\bx)$ into $f(\mS)$}	
%
%\ENDFOR
%
\RETURN {$f({\bx})$}
%
\normalsize
\end{algorithmic}\label{algorithm:tensorsketch}
\end{algorithm}

We maintain $2p$ independent hash functions: $h_1, \ldots, h_p$, which are 2-wise independent, and $s_1, \ldots, s_p$, which are 4-wise independent.
For each input vector $\bx$, we construct $p$ independent Count Sketches of size $D$ using these hash functions (Line 1 of Algorithm~\ref{algorithm:tensorsketch}).
The final sketch of the $p$-fold tensor product $\bx^{(p)}$ is then computed via fast polynomial multiplication using the Fast Fourier Transform (FFT).
This procedure yields a random feature map $f$ that serves as an unbiased estimator of the homogeneous polynomial kernel for any pair of input vectors.

We now analyze the computational and space complexity of Tensor Sketch.
Since the degree $p$ is fixed and typically small, only $\mathcal{O}(1)$ space is required to store the $2p$ hash functions~\citep{Carter79, Thorup12}.
For each vector, computing the sketch of its $p$-fold tensor product takes $\mathcal{O}(d + D \log D)$ time, due to the use of FFT.
Hence, given $n$ data points, the total runtime of Tensor Sketch is $\mathcal{O}(n(d + D \log D))$.

To improve the accuracy of kernel approximation, $D$ is often chosen to be $\mathcal{O}(d)$, resulting in an overall time complexity of $\mathcal{O}(nd \log d)$.
This is significantly faster than earlier approaches such as \citet{Kar12}, \citet{Hamid14}, and \citet{Pennington15}, which typically require $\mathcal{O}(nd^2)$ time.
Furthermore, Tensor Sketch only requires $\mathcal{O}(1)$ additional memory to store the hash functions, while previous methods demand $\mathcal{O}(d)$ space~\citep{Kar12, Hamid14, Meister19} or even $\mathcal{O}(d^2)$~\citep{Pennington15, Krein}.

\subsection{Error Analysis}\label{sec:error}

In this section, we analyze the estimation accuracy of the polynomial kernel $\kappa(\bx, \by) = \langle \bx, \by \rangle^p$ for a positive integer $p$, focusing on the concentration behavior of the estimator produced by Tensor Sketch.
We derive bounds on the variance of the estimator as a function of the number of random features $D$, and show that the estimate concentrates tightly around its expected value.
The following theorem establishes both the unbiasedness and a variance bound for the approximation provided by Tensor Sketch.

%
\begin{theorem}\label{thm:main}
Given two vectors $\bx, \by \in \mathbb{R}^d$, we denote by $\bCx^{(p)}, \bCy^{(p)} \in \mathbb{R}^D$ the Count Sketches of $\bx^{(p)}, \by^{(p)} \in \mathbb{R}^{d^p}$ using hash functions $h_1, \ldots , h_p: [d] \mapsto [D]$ and $s_1, \ldots , s_p: [d] \mapsto \left\{ -1, 1 \right\}$ chosen independently from \textit{2-wise} and \textit{4-wise} independent families, respectively.
Then we have
\begin{displaymath}
\begin{aligned}
%
\E{\left\langle \bCx^{(p)}, \bCy^{(p)} \right\rangle } &= \left\langle \bxp, \byp \right\rangle = \dotxy^{p},\\
\Var{\left\langle \bCx^{(p)}, \bCy^{(p)} 
\right\rangle } &\leq 
\frac{3^p - 1}{D} \|\bx\|_2^{2p}\|\by\|_2^{2p}
% \frac{3^p - 1}{D} \left\langle \bx^{(p)}, \by^{(p)} \right\rangle^2 = \frac{3^p - 1}{D} \left\langle \bx, \by \right\rangle^{2p}  
\enspace. 
%
\end{aligned}
\end{displaymath}
%
\end{theorem}
%
\begin{proof}
We note that the Tensor Sketches $\bCx^{(p)}, \bCy^{(p)}$ are the Count Sketches of the tensor product $\bX = \bx^{(p)}, \bY = \by^{(p)}$ using the two new hash functions $H : [d]^p \mapsto [D]$ and $S: [d]^p \mapsto \left\{-1, 1 \right\}$ such that:
$$H(i_1, \ldots, i_p) = \left( \sum_{j = 1}^{p}{h_j(i_j)}\right) \text{ mod } D \text{ and } S(i_1, \ldots, i_p) = \prod_{j = 1}^{p}{s_j(i_j)} \, .$$

For notational simplicity we define by $\bu, \bv \in [d]^p$ as the index of vectors $\bX, \bY$ of $d^p$ dimensions.
Also note that $H(\bu)$ is still 2-wise independent~\citep{Patrascu11} but $S(\bu)$ is \textit{not} 4-wise independent anymore~\citep{Indyk08, Braverman10}.
That leads to the incorrect result on the variance bound on Lemma 6 of the conference version~\citep{TS} as the dependence on $p$ is missing.

Define the indicator variable $\xi_{\bu \bv} = \mathbb{I}[H(\bu) = H(\bv)]$ for any $\bu, \bv \in [d]^p$, we have

\begin{align*}
\left\langle \bCx^{(p)}, \bCy^{(p)} \right\rangle &= \sum_{\bu, \bv \in [d]^p}{\bX_{\bu} \bY_{\bv} S(\bu)S(\bv) \xi_{\bu \bv}} 
&= \left\langle \bX, \bY \right\rangle + \sum_{\bu \neq \bv \in [d]^p}{\bX_{\bu} \bY_{\bv} S(\bu)S(\bv) \xi_{\bu \bv}} \, .
\end{align*}
%
Recall that $S: [d]^p \rightarrow \left\{-1, 1\right\}$ is 2-wise independent, applying the independence property of this hash function, we can verify that 
$\mathbb{E}  \left[\left\langle \bCx^{(p)}, \bCy^{(p)}  \right\rangle \right] = \left\langle \bX, \bY \right\rangle = \dotxy^{p}$.
%

For the variance, we compute $\E{\left[\left\langle \bCx^{(p)}, \bCy^{(p)}  \right\rangle^2 \right]}$ by expanding $\left\langle \bCx^{(p)}, \bCy^{(p)} \right\rangle^2$:
%
\begin{align*}
%
&\left\langle \bCx^{(p)}, \bCy^{(p)} \right\rangle^2 = \left(  \left\langle \bX, \bY \right\rangle + \sum_{\bu \neq \bv}{\bX_{\bu} \bY_{\bv} S(\bu)S(\bv) \xi_{\bu \bv}} \right)^2 \\
&= \left\langle \bX, \bY \right\rangle^2 + 2\left\langle \bX, \bY \right\rangle \sum_{\bu \neq \bv}{\bX_{\bu} \bY_{\bv} S(\bu)S(\bv) \xi_{\bu \bv}} + \left( \sum_{\bu \neq \bv}{\bX_{\bu} \bY_{\bv} S(\bu)S(\bv) \xi_{\bu \bv}} \right)^2 \, ,
%
\end{align*}
%
where the expectation for the second term is~0.
Applying the independence between $S$ and $H$ together with Lemma~\ref{lem:AMS2}, we can bound the expectation of the last term and prove the variance claim as follows.
\begin{align*}
&\E{ \left( \sum_{\bu \neq \bv}{\bX_{\bu} \bY_{\bv} S(\bu)S(\bv) \xi_{\bu \bv}} \right)^2}  \\
&= \E{ \sum_{\substack{\bu_1 \neq \bv_1 \\ \bu_2 \neq \bv_2}} \bX_{\bu_1} \bY_{\bv_1}\bX_{\bu_2} \bY_{\bv_2} S(\bu_1)S(\bv_1)S(\bu_2)S(\bv_2) \xi_{\bu_1 \bv_1} \xi_{\bu_2 \bv_2} } \\
&= \sum_{\substack{\bu_1 \neq \bv_1 \\ \bu_2 \neq \bv_2}} \E{\bX_{\bu_1} \bY_{\bv_1}\bX_{\bu_2} \bY_{\bv_2} S(\bu_1)S(\bv_1)S(\bu_2)S(\bv_2)} \, \cdot \, \E{\xi_{\bu_1 \bv_1}\xi_{\bu_2 \bv_2}} \\
&\leq \frac{1}{D} \sum_{\substack{\bu_1 \neq \bv_1 \\ \bu_2 \neq \bv_2}} \E{\bX_{\bu_1} \bY_{\bv_1}\bX_{\bu_2} \bY_{\bv_2} S(\bu_1)S(\bv_1)S(\bu_2)S(\bv_2)}  \\
&\leq \frac{1}{D} \sum_{\substack{\bu_1 \neq \bv_1 \\ \bu_2 \neq \bv_2}} \E{|\bX_{\bu_1}| |\bY_{\bv_1}| |\bX_{\bu_2}| |\bY_{\bv_2}| S(\bu_1)S(\bv_1)S(\bu_2)S(\bv_2)} \\
&= \frac{1}{D} \, \E{\left(\sum_{\bu \neq \bv \in [d]^p} |\bX_{\bu}| \, |\bY_{\bv}| S(\bu) S(\bv)\right)^2} \leq \frac{3^p - 1}{D} \|\bX\|_2^2 \|\bY\|_2^2 = \frac{3^p - 1}{D} \|\bx\|_2^{2p}\|\by\|_2^{2p}.
\end{align*}
%
The last line holds using the variance bound from Lemma~\ref{lem:AMS2} over $|\bX|, |\bY|$, coordinate-wise absolute vectors of $\bX, \bY$.
Note that when $p = 1$, this general bound matches the bound of Lemma~\ref{lem:CS}.
\end{proof}

Empirically, it has been shown that normalizing a kernel may improve the performance of SVMs. 
One way to do so is to normalize the data such as $\|\bx\|_2=1$ so that the exact kernel is properly normalized, i.e. $\kappa(\bx, \bx) = \left\langle \bx, \bx \right\rangle^p = 1$. 
Theorem~\ref{thm:main} shows that Tensor Sketches can preserve the normalization of kernels given sufficiently large $D$ random features.

