\begin{algorithm}
\caption{Enhanced Smart Wrapper}
\label{alg:enhanced_smart_wrapper}
\LinesNumbered
\KwIn{Top-ranked source $\Delta$ (retrieved from the Findability module)}
\KwOut{Generated dataset $D_f$}
\textbf{Initialization:} $D_f \gets \emptyset$, $L \gets \emptyset$, $L_f \gets \emptyset$, $E \gets \emptyset$ \;

\textbf{Step 1: Identify Data Access Paths} \;
\Indp
    Extract associated links $L$ from the main database access link in $\Delta$\;
    Filter $L$ based on relevance using contextual learning to obtain $L_f$\;
\Indm

\textbf{Step 2: Analyze Filtered Links} \;
\Indp
    \ForEach{link $l \in L_f$}{
        \If{link contains downloadable file}{
            Append $l$ to $E$ (downloadable file links)\;
        }
        \ElseIf{link contains HTML table}{
            Parse the table and convert it into a structured format;
            Append the parsed table to $D_f$\;
        }
        \ElseIf{link contains web forms}{
            Identify the list of forms and their input fields\;
            Generate a form submission schema based on the user query\;
            Submit the form and extract the resulting page content\;
            \If{result contains tables}{
                Parse the table and append to $D_f$\;
            }
            \Else{
                Generate data dynamically using LLM-assisted analysis of the page\;
                Append generated data to $D_f$\;
            }
        }
        \Else{
            Flag $l$ as inaccessible or irrelevant\;
        }
    }
\Indm

\textbf{Step 3: Select the Final Data Source} \;
\Indp
    \If{$E \neq \emptyset$}{
        Perform vector similarity-based ranking on $E$ using query semantics\;
        Select the most relevant downloadable link from $E$ and append to $D_f$\;
    }
    \ElseIf{$D_f = \emptyset$}{
        Flag the source as unsuitable for data extraction\;
    }
\Indm

\Return dataset $D_f$\;
\end{algorithm}

