\begin{algorithm}[H]
\caption{Query Processor}
\label{alg:query_processor}
\LinesNumbered
\KwIn{User Query $Q$}
\KwOut{Retrieval Query $\tilde{q}$, Expanded Queries $Q_e$, Metadata $M$}
Parse $Q$ to identify key parameters\;
Generate optimized search query $\tilde{q}$\;
Construct metadata $M$ \;
Convert $\tilde{q}$ to vector $v_{\tilde{q}}$\;
Compute similarity scores between $v_{\tilde{q}}$ and vectors in the database\;
Retrieve top-$n$ similar contexts $C = \{c_1, c_2, \dots, c_n\}$\;

Generate expanded query $\hat{q}_i$ using RAG based on $\tilde{q}$ and $C$\;

Form the expanded query set $Q_e = \{\hat{q}_1, \hat{q}_2, \dots, \hat{q}_k\}$\;
\Return $\tilde{q}$, $Q_e$, $M$\;
\end{algorithm}
