%\tcc*[l]{updating all $x_i$-labeled transitions $\transtree {q} {x_i} {q_0, q_1}$ to jump to the primed version depending on the value of $b$}     
%\PrintSemicolon
\Return {$M_i^{=b}(\aut)=\tuple{Q\cup Q', \Sigma,
	\Delta^{={x_i}}\cup \Delta^{\neq{x_i}}\cup\Delta', \rootstates, \globconstr}$}\;
\caption{Algorithm for measurement}
\label{alg:measure}
\end{algorithm}
