  \KwIn{A TA $\autr = (S_\R, \Delta_\R, F_\R)$, a~TA
    $\autq = (S_\Q, \Delta_\Q, F_\Q)$}
  \KwOut{$\mathit{true}$ if $\autr \entailedbyuptosc \autq$, $\mathit{false}$ otherwise}

  $\processed \gets \emptyset$\;
  $\worklist \gets \{(s_\R, U_\Q) \mid \transleaf{s_\R}{v_\R} \in \Delta_\R,$\\
  \hspace*{8.7mm} $U_\Q = \{(u_\Q, c) \in S_\Q \times \realsext \mid
  \transleaf{u_\Q}{v_\Q} \in \Delta_\Q \land (v_\R \neq 0 \Rightarrow (v_\Q = c
  \cdot v_\R \land c \neq 0)) \land {}$\\[1mm]
  \hspace*{66.5mm} $(v_\R = 0 \Rightarrow (v_\Q = 0 \land c = ?))\}\}$\label{ln:workset}\;
  \While{$\worklist \neq \emptyset$}{
    $(s_\R, U_\Q) \gets \mathit{Worklist}.\mathit{pop}()$\label{ln:pop}\;
    \lIf{$s_\R \in F_\R \land \forall (u_q, c) \in U_\Q\colon u_q \notin F_\Q$}{\label{ln:roottest}
      \Return{$\mathit{false}$}
    }
    $\processed \gets \processed \cup \{(s_\R, U_\Q)\}$\;\label{ln:processed}

    $\mathit{tmp} \gets (\{(s_\R, U_\Q)\} \times \processed) \cup (\processed
      \times \{(s_\R, U_\Q)\})$\label{ln:tmp}\;
    \ForEach{$((s_\R^1, U_\Q^1), (s_\R^2, U_\Q^2)) \in \mathit{tmp}, \alpha \in
    \vars$}{
      $H_\R \gets \{s_\R' \in S_\R \mid \transtree{s_\R'}{\alpha}{s_\R^1, s_\R^2} \in \Delta_\R \}$\;
      $U_\Q' \gets \emptyset$\;
      \ForEach{$(s_\Q^1, c^1) \in U_\Q^1, (s_\Q^2, c^2) \in U_\Q^2$}{
        \lIf{$c^1 \neq c^2 \land c^1 \neq ? \land c^2 \neq
        ?$}{\label{ln:connecttrees}
          \Continue
        }
        \ForEach{$\transtree{s_\Q}{\alpha}{s_\Q^1, s_\Q^2} \in \Delta_\Q$}{
          $U_\Q' \gets U_\Q' \cup \{(s_q, c) \mid c = c^2 \textbf{ if } c^1 = ? \textbf{ otherwise } c^1\}$\;
        }
      }
      % $U_\Q' \gets \{(s_\Q, c) \in Q_\Q \times \realsext \mid \exists (s_\Q^1, c^1) \in U_\Q^1,\ \exists (s_\Q^2, c^2) \in
      %   U_\Q^2\colon$\\
      %   $\transtree{s_\Q}{\alpha}{s_\Q^1, s_\Q^2} \in \Delta_\Q \land (c^1 = ? \Rightarrow c = c^2) \land (c^2 = ? \Rightarrow c = c^1) \land (c^1 = c^2 \Rightarrow c = c^1\}$\;
      \ForEach{$s_\R' \in H_\R$ s.t.\ $(s_\R', U_\Q') \notin \processed \cup \worklist$}{
        \label{ln:downcltest}
        $\worklist \gets \worklist \cup \{(s_\R', U_\Q')\}$\label{ln:addnew}\;
      }
    }
  }
  \Return{$\mathit{true}$}\;
\end{algorithm}
}


