\newcommand{\algStateCorr}[0]{
\begin{algorithm}[t]
\KwIn{Set of transitions $\Gamma_\aut\subseteq \Delta_\aut$, map $f\colon\{\topof{\delta} \mid \delta\in\Gamma_\aut\} \to 2^{Q_\autb}$}
\KwOut{The set of pairs $(f', g')$ of mappings compatible with~$\Gamma_\aut$ obtained from~$f$}
\SetArgSty{normalfont}
\SetKw{KwBreak}{break}
\SetKwProg{Func}{Procedure}{:}{}
\SetKwIF{IfNot}{ElseIfNot}{}{if not}{then}{else if not}{}{}
\SetKwFunction{FindAllFeasibleTransitions}{FindAllFeasibleTransitions}
\SetKwFunction{FindAllMappings}{FindAllMappings}
% $Q \gets \bigcup\left\{f(q_\aut) \mid q_\aut\in\domof f \right\}$;
$Q \gets \bigcup \imgof f$;\label{ln:imgoff}
$F' \gets \emptyset$\;
\ForEach{$\Gamma_\autb\in\ \feasibletransof \autb Q$}{\label{ln:feasibleb}
    $f' \gets \emptyset$;
    $g' \gets \emptyset$;
    $\mathit{failed} \gets \FF$\;
    % $\mathit{pairs} \gets \emptyset$;
    % $\mathit{success} \gets \TT$\;
    % \ForEach{$\delta_\aut\in\Gamma_\aut$ and $\delta_\autb\in \Gamma_\autb$ such that $\topof{\delta_\autb}\in f(\topof{\delta_\aut})$}{\label{ln:forgammastart}
    \ForEach{$\delta_\aut\in\Gamma_\aut$ and $q \in f(\topof{\delta_\aut})$}{\label{ln:forgammastart}
      $\{\delta_\autb\} \gets \{\delta_\autb \in \Gamma_\autb \mid q = \topof{\delta_\autb}\}$\label{ln:find:deltaB}\;
      % \lIf{$B = \emptyset$}{
      %   $\mathit{failed} \gets \TT$; \KwBreak
      % }
      % $\{\delta_B\} \gets B$\;
      \lIf{$a = \symof{\delta_\aut}$ and $b=\symof{\delta_\autb}$ are both leaf symbols}{\label{ln:symbolcheckstart}\label{ln:symbolsleaf}
        % $B \gets \{\delta_\autb\in \Gamma_\autb \mid \topof{\delta_\autb}\in
        %   f(\topof{\delta_\aut}), \symof{\delta_\autb} \text{ is a leaf
          % symbol}\}$\;
      $g'(a).\text{insert}(b)$
      }
      \ElseIf{$\symof{\delta_\aut} = \symof{\delta_\autb}$ is an internal symbol}{\label{ln:symbolsinternal}
          $f'(\leftof{\delta_\aut})$.insert($\leftof{\delta_\autb}$);
          $f'(\rightof{\delta_\aut})$.insert($\rightof{\delta_\autb}$)\;
      }\label{ln:symbolcheckend}
      \lElse{\label{ln:symbolsother}
        $\mathit{failed} \gets \TT$; \KwBreak
      }
      \label{ln:forgammaend}
  }
  \lIf{$\neg \mathit{failed}$}{
    $F'.\text{insert}((f', g'))$
  }
}
\KwRet $F'$\;\label{ln:mappingreturn}
\caption{FindAllMappings($\Gamma_\aut, f$).}
\label{algo:statecorr}
\end{algorithm}
