        \ForEach{$(f,g) \in F$}{\label{ln:entail:F}
            $U\gets {}$\FindAllMappings{$\Gamma_\aut, f$}\;
            $F' \gets F' \cup \{(f', g \merge g') \mid (f', g') \in U\}$\label{ln:entail:merge}\;
        }
        \lIf{$(D', F')\not\in \mathit{processed} \cup \mathit{workset}$}{
          $\mathit{workset}.\text{insert}((D', F'))$\label{ln:entail:insert}
        }
    }
}
\Return \TT\;
\caption{Checking if $\aut \entailedbyuptosc \autb$.}
\label{algo:inclusion}
\end{algorithm}
}

\algStateCorr

Next, we will show how to construct the set of all feasible pairs of mappings
$\{(f'_1, g'_1),
\ldots, (f'_n, g'_n)\}$ for some $\Gamma_\aut$ and a~pair of upper level mappings~$(f,g)$.
Each pair of mappings $(f'_j, g'_j)$ at the lower level is derived from some pair of mappings~$(f_i,g_i)$ at
the upper level and a set of downward transitions $\Gamma_\autb$ from~$\autb$.
The construction process is described in~\cref{algo:statecorr}, where we use
$(f, g)$ to denote an upper level state and term mapping respectively and
$(f',g')$ to denote their lower level counterparts.

The basic idea of the algorithm is simple:
%
\begin{inparaenum}[(1)]
  \item  we use the upper level mapping $f$ and transitions
    $\Gamma_\aut$ to compute the set of top states $Q$ (\lnref{ln:imgoff}), 
  \item  then, we find all feasible transitions $\Gamma_\autb$ from $Q$
    (\lnref{ln:feasibleb}), and, finally,
  \item  for each pair $(\Gamma_\aut, \Gamma_\autb)$, we construct one pair of lower
    level state and term mappings~$(f',g')$ (\lnrangeref{ln:forgammastart}{ln:forgammaend}).
    \label{item:one-lower}
\end{inparaenum}
%
Specifically, in step (\ref{item:one-lower}),
it must hold that for each transition~$\delta_\aut \in \Gamma_\aut$,
every state $q \in f(\topof{\delta_\aut})$ needs to be able to
match~$\delta_\aut$ by a~transition from~$\Gamma_\autb$.
To check this, for every such~$q$ we select from~$\Gamma_\autb$ the transition
$\delta_\autb$, which is the transition of~$\Gamma_\autb$ with~$q$ as its top
(it follows from $\feasibletrans$ that there is exactly one).
There are three possible cases:
%
\begin{itemize}
    \item \emph{Both $\delta_{\aut}$ and $\delta_{\autb}$ are leaf transitions
      (\lnref{ln:symbolsleaf}):} we remember in~$g'$ that the symbol of $\delta_\autb$
      need to be able to match the symbol of $\delta_\aut$, which will be
      checked later for all such matchings together.
    \item \emph{The symbols of both $\delta_{\aut}$ and $\delta_{\autb}$ are
      internal (\lnref{ln:symbolsinternal}):} in this case, we add new entries
      to the lower level mapping~$f'$.
    \item \emph{One transition is internal while the other is leaf
      (\lnref{ln:symbolsother}):} the pair $(\Gamma_\aut, \Gamma_\autb)$
      cannot form a feasible lower level mapping.
\end{itemize}
%
% For the first two cases, we found a potential feasible lower level mapping $f'$
% (\lnref{ln:success}).
% For the case of leaf transitions (which are labelled by terms over variables
% from~$\vars$ and complex numbers from~$\complex$), we, however, need to further
% verify if they are equivalent up to scaling (\lnref{ln:utscheck}).
% Specifically, we need to ensure for all assignments to $\vars$ that satisfy the
% common global constraints $\globconstr_\aut \land \globconstr_\autb$, the leaf
% symbols of $\aut$, i.e., $t_1$, are a scaled version of the corresponding leaf
% symbols of $\autb$, i.e., $t_2$. 
% \ol{return here later}

\algInclusion

Finally, the main entailment testing routine is summarized in~\cref{algo:inclusion}.
\lnref{ln:sourcevertices} creates the set of source vertices of the explored graph.
\lnrangeref{ln:entail:nonempty}{ln:entail:remove} pick a~vertex $(D,F)$ that has
not been processed yet.
\lnrangeref{ln:entail:terminalstart}{ln:entail:terminalend} check whether
$(D,F)$ is a terminal vertex and conclude that the entailment test fails when
such a~vertex is reached.
This check consists of looking at all pairs $(\emptyset, g)$ in~$F$ and checking
whether there is a~way how the $\autb$-terms from the~$g$'s can together cover
(modulo a~scaling factor) the behaviour of the $\aut$-terms.
\lnrangeref{ln:entail:foreach}{ln:entail:insert} are the edge construction
procedure.
\lnrangeref{ln:entail:foreach}{ln:entail:d} enumerate all feasible
$\Gamma_\aut$ and use them to create the next vertex $(D',F')$.
Specifically, $D'$ are the bottom states from $\Gamma_\aut$
(\lnref{ln:entail:d}), and $F'$ are the union of all feasible mappings of
$\Gamma_\aut$ (\lnrangeref{ln:entail:F}{ln:entail:insert}). 
The successor term mapping is computed from the upper-level one and from the
one returned by \FindAllMappings by, for each term of~$\aut$, merging the
corresponding sets of terms of the two mappings: $g \merge g' = \{x \mapsto Y
\mid x \in \domof{g \cup g'}, Y = g(x) \cup g'(x)\}$ (\lnref{ln:entail:merge}).

A~crucial part of the algorithm is the term mapping~$g$ check between
the terms from~$\aut$ and the terms from~$\autb$
(\lnrangeref{ln:entail:checkstart}{ln:entail:checkend}).
Here, we want to check that for every possible value that we can obtain from
a~term~$t$ on the left-hand side of the entailment (satisfying~$\aut$'s global
constraint~$\globconstr_\aut$) and every term~$t_i$ from $g(t) = \{t_1, \ldots,
t_k\}$, there is a way to obtain a~value (satisfying $\autb$'s global
constraint~$\globconstr_\autb$) such that for all these values, there is
a~common scaling factor~$r$ to make them equal to the value from~$t$.
We emphasize the way how we need to deal with the quantified variables.
Variables $\varsY$ occurring on the left-hand side (and possibly also on the
right-hand side, since we may need to synchronize the values) are quantified
universally, while variable~$\varsZ$ occuring only on the right-hand side of the
entailment are quantified existentially.
This scaling check requires invoking an SMT solver with a formula in the \texttt{NIRA}
(non-linear integer and real arithmetic) logic.
In the special case where all leaf symbols are constants, $r$~is the only
variable, and global constraints are $\TT$, the problem reduces to a simple \texttt{QF\_LRA} (quantifier-free
linear real arithmetic) formula.
