\begin{theorem}[Soundness]
    When \cref{algo:inclusion} terminates, it returns true iff $\aut \entailedbyuptosc \autb$.
\end{theorem}


\begin{theorem}[Termination]
  % \cref{algo:inclusion} generates a graph with at most $2^{|Q_\aut| +
  % 2^{|Q_\aut|\cdot|Q_\autb|}}$ vertices. When the leaf symbols
  % of either $\aut$ or $\autb$ are only constants, the algorithm always
  % terminates.
  When the terms in leaf symbols and the global constraints of $\aut$
  and~$\autb$ use a~decidable theory, the algorithm always terminates.
\end{theorem}
\begin{proof}
Since the number of states and terms occurring in~$\aut$ and~$\autb$ is finite, 
the constructed graph is also finite.
Further, since the underlying theory for the terms and global constraints is assumed to be
decidable, the check at \lnref{ln:entail:check} always terminates.
