\section{Performance Metrics}\label{PerformanceAnalysis}

\subsection{Outage Probability}
The OP, considering the cascaded multiwire-PLC/multiple-VLC system, is denoted by $P_{\text{out}} = F_{\Gamma_{\rm eq}}(\gamma_{\text{th}})$ and can be calculated from~(\ref{eq:CDFENDTOEND}) as
\begin{align}
    P_{\text{out}}  &= \left[ \Phi\left(a_0 -a_1\left(\gamma_{\text{th}}/\bar{\gamma}_{R}\right)^{-\frac{a_2}{\kappa}}\right)\right]^{M}\nonumber\\
    &+ \sum_{i=0}^{N}(-1)^i\binom{N}{i}\varepsilon^{N-i} \upsilon^i\left(\gamma_{\text{th}}/\bar{\gamma}_{\text{VLC}}\right)^{-\frac{i}{m_\text{v} + 3}}\nonumber\\
    &-\left[ \Phi\left(a_0 -a_1\left(\gamma_{\text{th}}/\bar{\gamma}_{R}\right)^{-\frac{a_2}{\kappa}}\right)\right]^{M}\nonumber\\
    &\times\sum_{i=0}^{N}(-1)^i\binom{N}{i}\varepsilon^{N-i} \upsilon^i\left(\gamma_{\text{th}}/\bar{\gamma}_{\text{VLC}}\right)^{-\frac{i}{m_\text{v} + 3}},
    \end{align}
in which $\gamma_{\text{th}}$ is a specified threshold.

\subsection{Average BEP}

The average BEP can be calculated for binary constellations as~\cite[Eq. (12)]{Ansari}
    \begin{align}\label{eq:PeCDF}
        P_{\text{e}} = \frac{q^p}{2\Gamma(p)}\int_{0}^{\infty}\frac{e^{-q\gamma}}{\gamma^{1-p}}F_{\Gamma_{\text{eq}}}(\gamma)\text{d}\gamma,
    \end{align}
in which $\Gamma(\cdot)$ is the Gamma function and $p$ and $q$ are parameters determined by the specific modulation scheme. 
For instance, $p=0.5$ and $q=1$ for a binary phase shift keying (BPSK) constellation~\cite{Ansari}.

Replacing~(\ref{eq:CDFENDTOEND}) in~(\ref{eq:PeCDF}) and considering the intervals of the function $F_{\Gamma_{\text{VLC}}^{\text{MAX}}}(\gamma)$, it follows that
    \begin{align}\label{eq:BERGERAL}
        P_{\text{e}} = \frac{\mathcal{I}_{1} - \mathcal{I}_{2} +\mathcal{I}_{3}+\mathcal{I}_{4}}{2q^{-p}\Gamma(p)},
    \end{align}
with 
    \begin{align}\label{eq:I1}
        \mathcal{I}_{1} = \int_{0}^{\gamma_{\text{c}}} \gamma^{p-1} e^{-q\gamma}
        \left[ \Phi\left(a_0 - a_1 \left( \frac{\gamma}{\bar{\gamma}_{R}} \right)^{-\frac{a_2}{\kappa}}\right)\right]^M \text{d}\gamma,
    \end{align}
    \begin{align}\label{eq:I2}
        \mathcal{I}_{2} &= \sum_{i=0}^{N} (-1)^i \binom{N}{i} \varepsilon^{N-i} \upsilon^i 
        \left( \frac{1}{\bar\gamma_{\text{VLC}}} \right)^{-\frac{i}{m_\text{v} + 3}}\nonumber\\
        &\times     \int_{\gamma_{\text{e}}}^{\gamma_{\text{c}}} \frac{\gamma^{p-1-\frac{i}{m_\text{v} + 3}}}{e^{q\gamma}}
        \left[ \Phi\left(a_0 - a_1 \left( \frac{\gamma}{\bar{\gamma}_{R}} \right)^{-\frac{a_2}{\kappa}}\right)\right]^M\text{d}\gamma,
    \end{align}
    \begin{align}\label{eq:I3}
        \mathcal{I}_{3} &=  \sum_{i=0}^{N} (-1)^i \binom{N}{i} \varepsilon^{N-i} \upsilon^i 
        \left( \frac{1}{\bar\gamma_{\text{VLC}}} \right)^{-\frac{i}{m_\text{v} + 3}}\nonumber\\
        &\times \int_{\gamma_{\text{e}}}^{\gamma_{\text{c}}} \gamma^{p-1-\frac{i}{m_\text{v} + 3}} e^{-q\gamma} \text{d}\gamma,
    \end{align}
and
    \begin{align}\label{eq:I4}
        \mathcal{I}_{4} &= \int_{\gamma_{\text{c}}}^{\infty} \gamma^{p-1} e^{-q\gamma} \text{d}\gamma.
    \end{align}

Changing the integration intervals to $[-1,1]$ by means of~\cite[Eq. (3.021)]{Gradshteyn2007}, and using the $N_{a}$-order Gauss-Legendre quadrature with roots $x_{j}$ and weights $w_{j}$, it follows that
    \begin{align}
        \mathcal{I}_1  &= \frac{\gamma_{\text{c}}}{2}\tilde{\mathcal{I}}_{1}\left(\frac{\gamma_{\text{c}}}{2}x_j+\frac{\gamma_{\text{c}}}{2}\right),
    \end{align}

\begin{align}
    \mathcal{I}_2  &= \sum_{i=0}^{N} (-1)^i \binom{N}{i} \varepsilon^{N-i} \upsilon^i 
    \left( \frac{1}{\bar\gamma_{\text{VLC}}} \right)^{-\frac{i}{m_\text{v} + 3}} \frac{(\gamma_{\text{c}}-\gamma_{\text{e}})}{2}\nonumber\\
    \end{align}
and
    \begin{align}
        \mathcal{I}_3  &= \sum_{i=0}^{N} (-1)^i \binom{N}{i} \varepsilon^{N-i} \upsilon^i 
        \left( \frac{1}{\bar\gamma_{\text{VLC}}} \right)^{-\frac{i}{m_\text{v} + 3}} \frac{(\gamma_{\text{c}}-\gamma_{\text{e}})}{2}\nonumber\\
    &\times\tilde{\mathcal{I}}_{3}\left(\frac{\gamma_{\text{c}}-\gamma_{\text{e}}}{2}x_j+\frac{\gamma_{\text{c}}+\gamma_{\text{e}}}{2}\right),
        \end{align}
in which
\begin{align}
    \tilde{\mathcal{I}}_{1}(x) &= \sum_{j=1}^{N_a} w_j x^{p-1}e^{-qx} \left[ \Phi\left(a_0 -a_1\left(x/\bar{\gamma}_{R}\right)^{-\frac{a_2}{\kappa}}\right)\right]^{M},
\end{align}
\begin{align}
    \tilde{\mathcal{I}}_{2}(x) &= \sum_{j=1}^{N_a} w_j x^{p-1-\frac{i}{m_\text{v}+3}}e^{-qx} \left[ \Phi\left(a_0 -a_1\left(x/\bar{\gamma}_{R}\right)^{-\frac{a_2}{\kappa}}\right)\right]^{M},
\end{align}
and
\begin{align}
    \tilde{\mathcal{I}}_{3}(x) &= \sum_{j=1}^{N_a} w_j x^{p-1-\frac{i}{m_\text{v}+3}}e^{-qx}.
\end{align}
In turn, by means of~\cite[Eq. (8.350.2)]{Gradshteyn2007},
 \begin{align}
    \mathcal{I}_4     &=\frac{1}{q^{p}}\Gamma(p, q\gamma_{\text{c}}),
\end{align}
in which $\Gamma(\cdot, \cdot)$ is the upper incomplete Gamma function.

Note that the solutions for $\mathcal{I}_1$, $\mathcal{I}_2$ and $\mathcal{I}_3$ are obtained using the Gauss-Legendre quadrature. 
This technique enables a numerical approximation of integral expressions, significantly reducing the computational cost of the evaluations. 

\subsection{Average Channel Capacity}

The average channel capacity, under the cascaded multiwire-PLC/multiple-VLC system, is given by
\begin{align}
    C &= \frac{1}{\ln(2)}\int_{0}^{\infty}\ln(1+x)f_{{\Gamma}_{\rm eq}}(x)\text{d}x \nonumber\\
    &= \frac{1}{\ln(2)}\int_{0}^{\infty}\ln(1+x)f_{{\Gamma}_{\rm PLC}}(x)\tilde{F}_{\Gamma_{\text{VLC}}^{\text{MAX}}}(x)\text{d}x\nonumber\\
&+\frac{1}{\ln(2)}\int_{0}^{\infty}\ln(1+x)f_{\Gamma_{\text{VLC}}^{\text{MAX}}}(x)\tilde{F}_{{\Gamma}_{\rm PLC}}(x)\text{d}x,
    % C &= \int_{0}^{\infty}\ln(1+x)[f_{{\Gamma}_{\rm PLC}}(x)(1-F_{\Gamma_{\text{VLC}}^{\text{MAX}}}(x))+f_{\Gamma_{\text{VLC}}^{\text{MAX}}}(x)(1-F_{{\Gamma}_{\rm PLC}}(x))]\text{d}x\nonumber\\
    % & = C_1+C_2+C_3,
\end{align}
in which $\tilde{F}_{\Gamma_{\text{VLC}}^{\text{MAX}}}(x)$ and $\tilde{F}_{{\Gamma}_{\rm PLC}}(x)$ are, respectively, the complementary CDF of $\Gamma_{\text{VLC}}^{\text{MAX}}$ and ${\Gamma}_{\rm PLC}$. Proceeding with some simplifications,
$C = C_1+C_2-C_3$,
in which 
  \begin{align}\label{eq:C1}
    C_1 &= \frac{1}{\ln(2)}\int_{0}^{\gamma_{\text{c}}}\ln(1+x)f_{{\Gamma}_{\rm PLC}}(x)\text{d}x,
\end{align}
  \begin{align}\label{eq:C2}
    C_2 &= \frac{1}{\ln(2)}\int_{\gamma_{\text{e}}}^{\gamma_{\text{c}}}\ln(1+x)f_{\Gamma_{\text{VLC}}^{\text{MAX}}}(x)(1-F_{{\Gamma}_{\rm PLC}}(x))\text{d}x,
\end{align}
and
  \begin{align}\label{eq:C3}
    C_3 &= \frac{1}{\ln(2)}\int_{\gamma_{\text{e}}}^{\gamma_{\text{c}}}\ln(1+x)F_{\Gamma_{\text{VLC}}^{\text{MAX}}}(x)f_{{\Gamma}_{\rm PLC}}(x)\text{d}x.
\end{align}

Plugging~(\ref{eq:PDFPLC}) into~(\ref{eq:C1}), changing the integration interval to $[-1,1]$ by means of~\cite[Eq. (3.021)]{Gradshteyn2007}, and using the Gauss-Legendre quadrature,
\begin{align}
    C_1 &= \frac{Ma_1a_2\gamma_{\text{c}}}{2\ln(2)\kappa\sqrt{2\pi}\bar{\gamma}_{R}^{-\frac{a_2}{\kappa}}}\tilde{\mathcal{I}}_{5}\left(\frac{\gamma_{\text{c}}}{2}x_j+\frac{\gamma_{\text{c}}}{2}\right),
\end{align}
in which
    \begin{align}
        \tilde{\mathcal{I}}_{5}(x) &= \sum_{j=1}^{N_a} w_j\ln(1+x)x^{-\left(\frac{a_2}{\kappa}+1\right)}e^{-\frac{1}{2}\left[a_0-a_1\left(x/\bar{\gamma}_{R}\right)^{-\frac{a_2}{\kappa}}\right]^2}\nonumber\\
        &\times \left[ \Phi\left(a_0 -a_1\left(x/\bar{\gamma}_{R}\right)^{-\frac{a_2}{\kappa}}\right)\right]^{M-1}.
    \end{align}
In turn, substituting~(\ref{eq:CDFPLC}) and~(\ref{eq:pDFVLC}) in~(\ref{eq:C2}) and using ~\cite[Eq. (3.021)]{Gradshteyn2007} and the Gauss-Legendre quadrature, it follows that
{\small\begin{align}
    &C_2 = \frac{N}{(m_\text{v}+3)\ln(2)}\sum_{i=0}^{N-1}(-1)^{i}\binom{N-1}{i}\frac{\varepsilon^{N-i-1}v^{i+1}}{\bar\gamma_{\text{VLC}}^{-\frac{i+1}{m_\text{v}+3}}}\frac{(\gamma_{\text{c}}-\gamma_{\text{e}})}{2}\nonumber\\
    &\times\left[\tilde{\mathcal{I}}_{6}\left(\frac{\gamma_{\text{c}}-\gamma_{\text{e}}}{2}x_j+\frac{\gamma_{\text{c}}+\gamma_{\text{e}}}{2}\right)-\tilde{\mathcal{I}}_{7}\left(\frac{\gamma_{\text{c}}-\gamma_{\text{e}}}{2}x_j+\frac{\gamma_{\text{c}}+\gamma_{\text{e}}}{2}\right)\right],
\end{align}}
with
\begin{align}%\label{eq:I4}
    \tilde{\mathcal{I}}_{6}(x) =  \sum_{j=1}^{N_a}w_j\ln(1+x)x^{-\frac{m_\text{v}+4+i}{m_\text{v}+3}},
\end{align}
and
\begin{align}\label{eq:I5}
    \tilde{\mathcal{I}}_{7}(x) = \sum_{j=1}^{N_a} w_j\frac{\ln(1+x)}{x^{\frac{m_\text{v}+4+i}{m_\text{v}+3}}}
    \left[ \Phi
    \left(a_0 - a_1 \left( \frac{x}
    {\bar{\gamma}_{R}}
    \right)^{-\frac{a_2}{\kappa}}\right)
    \right]^{M}.
\end{align}

Finally, using~(\ref{eq:PDFPLC}) and~(\ref{eq:CDFVLC}) in~(\ref{eq:C3}) and proceeding in a similar manner to $C_1$, we have
\begin{align}
    C_3 &= \frac{Ma_1a_2}{\ln(2)\kappa\sqrt{2\pi}\bar{\gamma}_{R}^{-\frac{a_2}{\kappa}}}\sum_{i=0}^{N}(-1)^{i}\binom{N}{i}\frac{\varepsilon^{N-i}v^{i}}{\bar\gamma_{\text{VLC}}^{-\frac{i}{m_\text{v}+3}}}\frac{(\gamma_{\text{c}}-\gamma_{\text{e}})}{2}\nonumber\\
&\times \tilde{\mathcal{I}}_{8}\left(\frac{\gamma_{\text{c}}-\gamma_{\text{e}}}{2}x_j+\frac{\gamma_{\text{c}}+\gamma_{\text{e}}}{2}\right),
\end{align}
where
\begin{align}%\label{eq:I5}
    \tilde{\mathcal{I}}_{8}(x) &= \sum_{j=1}^{N_a} w_j\frac{\ln(1+x)}{x^{\frac{i}{m_\text{v}+3}+\frac{a_2}{\kappa}+1}}e^{-\frac{1}{2}\left[a_0-a_1\left(x/\bar{\gamma}_{R}\right)^{-\frac{a_2}{\kappa}}\right]^2}\nonumber\\
&\times \left[ \Phi\left(a_0 -a_1\left(x/\bar{\gamma}_{R}\right)^{-\frac{a_2}{\kappa}}\right)\right]^{M-1}.
\end{align}

