\section{Distributionally Robust Rényi Loss}


To further capitalize on the strengths of SL and CCL while circumventing their limitations, a straightforward approach is to maintain their DRO-enhanced objective (\confer Eq.(\ref{eqs:Distributionally Contrastive Loss})) while utilizing a more appropriate divergence measure. This work proposes leveraging Rényi divergence~\cite{van2014renyi}, a natural generalization of both KL-divergence and worst-case regret-divergence used by SL and CCL. The proposed Distributionally Robust Rényi Loss ($\lossName$) is formulated as follows:
\begin{equation}
\small{
\begin{aligned}
\label{eqs:renyi optimization objective}
        \loss_{\lossName}(u) = -&\frac{1}{\vert \posU \vert}\sum\limits_{i \in \posU} \similarity(u,i) + \max\limits_{\userUncertainDis} \E_{j \sim \userUncertainDis}\left[f(u,j)\right] \\
        \st & D_{\wNormal}(\userUncertainDis,\userNegDis) := \sum\limits_{j \in \negU} \userNegDis(j)\phi_{\wNormal}\left(\frac{\userUncertainDis(j)}{\userNegDis(j)}\right)  \le \eta \\
        & \phi_{\wNormal}(t) = \frac{1}{\wNormal(\wNormal - 1)}(t^{\wNormal} - \wNormal t + \wNormal - 1)
\end{aligned}
}
\end{equation}

Rényi divergence $D_{\wNormal}(\userUncertainDis,\userNegDis)$ offers enhanced flexibility by using a parameter $\gamma$ to adjust the polynomial relationships of the probability distance measure with the probability ratio. Here, we adopt the Cressie-Read family of Rényi divergence~\cite{duchi2021learning}, which offers analytical benefits. Notably, while Eq.(\ref{eqs:renyi optimization objective}) is complex and challenging to optimize directly, it can be substantially simplified with the following lemma:
\begin{lemma}
\label{lemma2: renyi loss}
    Suppose $\wNormal \in (1,+\infty)$, optimizing the objective in Eq.(\ref{eqs:renyi optimization objective}) is equivalent to optimizing:

%     \begin{equation}
% \label{eqs: close form renyi loss}
% \small{
%         \begin{aligned}
% &\loss_{\lossName}(u) \!\!=\!\! -\frac{1}{\vert \posU \vert}\!\!\sum\limits_{i \in \posU}\!\!\similarity(u,i)  \!+\!\negFac\!\!\left[ \!\frac{1}{\vert \negU \vert}\!\!\sum\limits_{j \in \negU} \!(\similarity(u,j)\! - \!\optimalBeta)_+^{\wStar}\!\right]^{\!\!\frac{1}{\wStar}} \\
% &\st \optimalBeta = \mathop{\arg\min}\limits_{\beta} \Big\{\normalBeta + \negFac  \left[\frac{1}{\vert \negU \vert} \sum\limits_{j \in \negU}(\similarity(u,j) - \normalBeta)_+^{\wStar}\right]^{\frac{1}{\wStar}}\!\!\!\!\Big\}
%         \end{aligned}
%             }
%     \end{equation}



    \begin{equation}
\label{eqs: close form renyi loss}
\small{
        \begin{aligned}
&\loss_{\lossName}(u) = -\frac{\sum\limits_{i \in \posU}\similarity(u,i)}{\vert \posU \vert}    \!+\!\negFac\!\!\left[ \!\frac{1}{\vert \negU \vert}\!\!\sum\limits_{j \in \negU} \!(\similarity(u,j)\! - \!\optimalBeta)_+^{\wStar}\!\right]^{\!\!\frac{1}{\wStar}} \\
&\st \optimalBeta = \mathop{\arg\min}\limits_{\beta} \Big\{\normalBeta + \negFac  \left[\frac{1}{\vert \negU \vert} \sum\limits_{j \in \negU}(\similarity(u,j) - \normalBeta)_+^{\wStar}\right]^{\frac{1}{\wStar}}\!\!\!\!\Big\}
        \end{aligned}
            }
    \end{equation}
where $\wStar = \frac{\wNormal}{\wNormal - 1}$, and $\negFac = (1 + \wNormal(\wNormal - 1)\eta)^{\frac{1}{\wNormal}}$.
\end{lemma}

