In addition to ALCS of two strings for $\delta={H}$, Flouri et al. \cite{Flouri2015LongestMismatches} compute $LCP^{H,k}_{(s_1,s_2)}$ in $\bigo(|s_1||s_2|)$ time. Hence, for two strings of equal length, we establish the following lemma.

\begin{lemma}\label{lem:flouri} 
    (\cite{Flouri2015LongestMismatches}) For strings $s_1$ and $s_2$, each of length $\ell$, and $k \in \mathbb{N}$, the $LCP^{H,k}_{(s_1,s_2)}$ table can be computed in $\bigo(\ell^2)$ time.

\end{lemma}

\begin{definition}[LengthStat Data Structure]\label{def:ls}
For $S=\{s_1,s_2,\ldots,s_m\}$, $1 \leq i,j \leq m$, $1 \leq p \leq |s_i|$, and $1 \leq l \leq |s_i| -p +1$, $lengthStat^k_{(p,i)}[l,j] = 1$ iff there exists a position $1 \leq q \leq |s_j|$ such that $LCP^{H,k}_{(s_i,s_j)}[p,q] \geq l$; otherwise, $lengthStat^k_{(p,i)}[l,j] = 0$. The last $(m+1)$-th column contains the sum of the values in each row.
\end{definition}

\begin{algorithm}
\caption{Computes $lengthStat$ table for suffix $p$ of $s_i$}
\label{alg:lengthStat}
\begin{algorithmic}[1]
\Procedure{lengthStat}{$LCP^{H,k}_{(s_i,s_j)},p,i$}
\State $lengthStat^k_{(p,i)}[1..|s_i|-p+1,1..m+1] \leftarrow 0$    \Comment{Initial table with all zeros}
\For{all $j,q$ values} 

    \State $l \leftarrow LCP^{H,k}_{(s_i,s_j)}[p,q]$
    \State $lengthStat^k_{(p,i)}[l,j] \leftarrow 1$

\EndFor 
\For{$r$ from $|s_i|-p+1$ to $2$} 
    \State $lengthStat^k_{(p,i)}[r-1,1..m] \leftarrow lengthStat^k_{(p,i)}[r,1..m] \lor lengthStat^k_{(p,i)}[r-1,1..m]$
    \State $lengthStat^k_{(p,i)}[r,m+1]= \Sigma^m_{j=1} lengthStat^k_{(p,i)}[r,j]$

\EndFor
\State $lengthStat^k_{(p,i)}[1,m+1]= \Sigma^m_{j=1} lengthStat^k_{(p,i)}[1,j]$

\State \textbf{return} $lengthStat^k_{(p,i)}$
\EndProcedure
\end{algorithmic}
\end{algorithm}

Thus, $lengthStat^k_{(p,i)}[l,j]=1$ indicates the existence of a $k$-approximate occurrence of $s_i[p,p+l-1]$ (the $l$-length prefix of the suffix of $s_i$ starting at position $p$) in $s_j$. It checks whether there exists at least one $q$ such that $d_H(s_i[p,p+l-1],s_j[q,q+l-1]) \leq k$.
We present Algorithm~\ref{alg:lengthStat} to compute the $lengthStat$ table for a suffix starting at position $p$ of $s_i$, where $\delta=H$. Line 7 performs an element-wise OR operation between rows.
