\begin{lemma}
For a given set $\s{S}$ of $m$ strings, $LCP^{H,k}_{(s_i,s_j)}$ for all $i$ and $j$ values, $1 \leq i,j \leq m$, can be computed in $\bigo(N^2)$ time, where $N=m\ell$.
\end{lemma}
\begin{proof}
By Lemma~\ref{lem:flouri}, computing $LCP^{H,k}$ between any two strings in $\s{S}$ requires $\bigo(\ell^2)$ time. Therefore, computing $LCP^{H,k}_{(s_i,s_j)}$ $1 \leq i,j \leq m$, for all pairs of strings in $\s{S}$; that is, $\binom{m}{2} = \bigo(m^2)$ pairs, requires $\bigo(m^2 \ell^2) = \bigo(N^2)$ time. \QEDB
\end{proof}

\begin{lemma}\label{lem:lengthstat}
   Given $LCP^{H,k}_{(s_i,s_j)}$ for all $(s_i,s_j)$ pairs, $1 \leq i,j \leq m$, $lengthStat^k_{(p,i)}$ for any suffix of any string $s_i \in \s{S}$ can be computed in $\bigo(N)$ time.
\end{lemma}
\begin{proof}
The \texttt{for} loop in line 3 of Algorithm~\ref{alg:lengthStat} takes $\bigo(m \ell)=\bigo(N)$ time to iterate through all the $LCP^{H,k}_{(s_i,s_j)}[p,q]$ values, where $1 \leq j \leq m$ and $1 \leq q \leq \ell$. The \texttt{for} loop in line 6 takes $\bigo(N)$ time. Hence, the total time complexity is $\bigo(N)$. \QEDB
\end{proof}
In a greedy approach, since each substring can be a solution to \textit{Rk}-LCS or \textit{Rkt}-LCS, we compute the $lengthStat$ table for all $N$ suffixes in $\s{S}$. Using the last column of $lengthStat_{(p,i)}$ table, we pick the substring $s_i[p..p+l'-1]$ with maximum $l'$, that has $k$-approximate occurrences in $m$ ($t$) distinct strings for \textit{Rk}-LCS (\textit{Rkt}-LCS) problems. Our approach computes the set of the longest prefix of every suffix in set \s{S}, which has $k$-approximate occurrences in at least $t$ (or $m$) distinct strings and finally selects the longest one.

\begin{theorem}\label{theo:complexity}
    The restricted ALCS problems for $\s{S}=\{s_1, s_2, \ldots , s_m\}$ for $\delta={H}$ can be computed in $\bigo(N^2)$ time and $\bigo(N)$ additional space.
\end{theorem}

\begin{proof}
Algorithm~\ref{alg:ktlcs} is a solution to restricted ALCS problems. The \texttt{for} loop in line 3 takes $\bigo(N)$ time. Line 4 computes $lengthStat$ table for each suffix in $\bigo(N)$ time using Lemma~\ref{lem:lengthstat}. The \texttt{for} loop in line 5 takes at most $\bigo(\ell)$ time, where $\ell$ is the length of each string in \s{S}. Therefore, the total time complexity is $\bigo(N(N+\ell))=\bigo(N^2)$. Line 20 releases the space used by $lengthStat$ of a particular suffix, which will be used by the next suffix. Hence, the total space required is $\bigo(m \ell)=\bigo(N)$. \QEDB
\end{proof}

\begin{algorithm}[]
\caption{Computes solution to restricted ALCS problems}
\label{alg:ktlcs}
\begin{algorithmic}[1]
\Procedure{ALCS}{$k,t$}
\State $rkLCS, rktLCS, msktLCS,mcktLCS \leftarrow \varnothing$

\For{each suffix $p$ of every $s_i$ in $\s{S}$} \Comment{$\bigo(N)$ time}
    \State Compute $lengthStat^k_{(p,i)}[1..|s_i|-p+1,1..m+1]$ \Comment{$\bigo(N)$ time}
    \For{$l = |s_i|-p+1$ to $1$}
        \If{$lengthStat^k_{(p,i)}[l,m+1] = m$ \&\& $|rkLCS|<l$ }
            \State $rkLCS \leftarrow s_i[p..p+l-1]$
        \EndIf
        \If{$lengthStat^k_{(p,i)}[l,m+1] \geq t$ \&\& $|rktLCS|<l$ }
            \State $rktLCS \leftarrow s_i[p..p+l-1]$
            \State $msktLCS,mcktLCS \leftarrow \varnothing$
            \State $mcktLCS.append(s_i[p..p+l-1])$
            \For{$str = 1$ to $m$}
                \If{$lengthStat^k_{(p,i)}[l,str]=1$}
                    \State $msktLCS.append(s_i[p..p+l-1],str) $
                \EndIf
            \EndFor
        \EndIf
        \If{$lengthStat^k_{(p,i)}[l,m+1] \geq t$ \&\& $|rktLCS|=l$}
            \State $mcktLCS.append(s_i[p..p+l-1])$
            \For{$str = 1$ to $m$}
                \If{$lengthStat^k_{(p,i)}[l,str]=1$}
                    \State $msktLCS.append(s_i[p..p+l-1],str) $
                \EndIf
            \EndFor
        \EndIf
    \EndFor   

    \State $lengthStat^k_{(p,i)} \leftarrow 0$

\EndFor 
\State \textbf{return} $rkLCS, rktLCS, msktLCS,mcktLCS$
\EndProcedure
\end{algorithmic}
\end{algorithm}

For finding the solutions to restricted ALCS problems for $\delta=\{L,E\}$, we use the \textit{Longest Approximate Prefix} data structure introduced by K{\c{e}}dzierski and Radoszewski in~\cite{Kedzierski2022K-ApproximateDistance}.

\textbf{Longest Approximate Prefix}. Given strings $s_1$ and $s_2$, a distance metric $\delta=\{L, E\}$, and $k \in \mathbb{Z}$, compute table $P^{\delta,k}_{(s_1,s_2)}$ such that $P^{\delta,k}_{(s_1,s_2)}[a,b,a']$ is the maximum $b'\geq a'-1$, where $d_{\delta}(s_1[a,b],s_2[a',b']) \leq k$, or $-1$ if no such $b'$ exists.

\begin{lemma}\label{lem:ptable}
    (\cite{Kedzierski2022K-ApproximateDistance}) For two strings $s_1$ and $s_2$, each of length $\ell$, $P^{\{L,E\},k}_{(s_1,s_2)}$ can be computed in $\bigo(k\ell^3)$ time.
\end{lemma}
\begin{lemma}
    Computing the $P^{\{L,E\},k}_{(s_i,s_j)}$ table for all $i$ and $j$ values, $1 \leq i,j \leq m$, takes $\bigo(k\ell N^2)$ time.
\end{lemma}
\begin{proof}
    There are $\bigo(m^2)$ string pairs and by Lemma~\ref{lem:ptable}, $P^{\{L,E\},k}_{(s_i,s_j)}$ can be computed in $\bigo(k\ell^3)$ for each string pair $(i,j)$. The time complexity of $P^{\{L,E\},k}_{(s_i,s_j)}$ for all $i$ and $j$ values is $\bigo(m^2\cdot k\ell^3)=\bigo(k \ell N^2)$. 
   \QEDB 

\end{proof}
For $\delta=\{L,E\}$, we fill $lengthStat^{k}_{(p,i)}$ auxiliary tables using $P^{\delta,k}_{(s_i,s_j)}$ tables for each suffix of any string in set \s{S}, similar to $\delta={H}$.

\begin{multline}
\label{eq:lengthStatlev}
lengthStat^{k}_{(p,i)}[l,j]=
\begin{cases}
  1, & \text{if }
       \begin{aligned}[t]
        \exists q: P^{\{L,E\},k}_{(s_i,s_j)}[p,p+l-1,q] \neq -1  
       \end{aligned}
\\
  0, & \text{otherwise } 
\end{cases}\\
\text{where } 1 \leq p \leq |s_i|,1 \leq  l \leq |s_i|-p+1 \text{ and } 1 \leq i,j \leq m
\end{multline}
Analogous to Lemma~\ref{lem:lengthstat}, Theorem~\ref{theo:complexity}, and Algorithms~\ref{alg:lengthStat} and~\ref{alg:ktlcs}, we get
\begin{lemma}
        Given $P^{\{L,E\},k}_{(s_i,s_j)}$ for all $(s_i,s_j)$ pairs, $1 \leq i,j \leq m$, the \textit{lengthStat} table can be computed in $\bigo(N)$-time for each suffix of a string in $\s{S}$.
\end{lemma}

\begin{theorem}
    The restricted ALCS problems for $\delta=\{L,E\}$ and $\s{S}=\{s_1, s_2, \ldots , \\ s_m\}$ can be computed in $\bigo(k \ell N^2)$ time.
\end{theorem}

\subsection{Polylog Time Solution for Restricted ALCS}\label{sec:polylog}

Thankachan \textit{et al.} describe a $\bigo(\ell \log^k \ell)$-time and $\bigo(\ell)$-space solution for ALCS of two strings, each of length $\ell$, for $\delta={H}$~\cite{Thankachan2016AProblem} and $\delta=\{L,E\}$~\cite{thankachan2018algorithmic}. Their method uses \textit{k}-errata trie data structure proposed by Cole \textit{et al.} in~\cite{Cole2004DictionaryCares}.
Let $LCP^{E,k}_{(s_i,s_j)}[i',j']$ be the length of the longest common prefix between the suffixes $s_i[i'..|s_i|]$ and $s_j[j'..|s_j|]$, with at most $k$ edit operations. $MaxLCP^{H,k}_{(s_i,s_j)}[i']$ ($MaxLCP^{E,k}_{(s_i,s_j)}[i']$) is an array of size $|s_i|$, where each element $i'$ contains the maximum value of $LCP^{H,k}_{(s_i,s_j)}[i',j']$ ($LCP^{E,k}_{(s_i,s_j)}[i',j']$) for all $1 \leq j' \leq |s_j|$.

\begin{theorem}\label{theo:lcpk*}
    (\cite{Thankachan2016AProblem},\cite{thankachan2018algorithmic}) Let $s_i$ and $s_j$ be strings of length $\ell$. $MaxLCP^{H,k}_{(s_i,s_j)}[i']$ and $MaxLCP^{E,k}_{(s_i,s_j)}[i']$ arrays can be computed in $\bigo(\ell \log^k \ell)$ overall time using $\bigo(\ell)$ space for \textbf{all} values of $i'$.
\end{theorem}

\begin{theorem}
    For any $\delta=\{H,L,E\}$, $Rk$-LCS problem can be computed by solving $T=\max\limits_{1 \leq i \leq m} \max\limits_{1 \leq i' \leq |s_i|} \min\limits_{1 \leq j \leq m} MaxLCP^{\delta,k}_{(s_i,s_j)}[i']$.
\end{theorem}
\begin{proof}
For a string $s_i$ and its suffix $s_i[i'..|s_i|]$, $\min\limits_{1 \leq j \leq m} MaxLCP^{\delta,k}_{(s_i,s_j)}[i']$ is the length of the longest prefix of $s_i[i'..|s_i|]$ that occurs in all $\s{S}-\{s_i\}$ strings with at most $k$ errors. $T=\max\limits_{1 \leq i \leq m} \max\limits_{1 \leq i' \leq |s_i|} \min\limits_{1 \leq j \leq m} MaxLCP^{\delta,k}_{(s_i,s_j)}[i']$ is the length of a $Rk$-LCS of set \s{S}. To compute an answer to this problem, we need to find a $(i,i')$ pair that maximizes $T$. Argument pair $(i,i')$ maximizing $T$ corresponds to $i'$-th suffix of the string $s_i$, which constitutes an answer to the $Rk$-LCS of $\s{S}$; such that substring $s_i[i'..T-i'+1]$ is a $Rk$-LCS.
We prove the correctness of this solution by contradiction. Assume that pair $(i,i')$ is not a $Rk$-LCS and there exists a pair $(v,v')$ which is an answer to this problem. Therefore, $T$ value for $(v,v')$ is larger than its value for $(i,i')$; however, pair $(v,v')$ has not been captured by $T$. This is in contradiction with maximizing $T$. \QEDB
\end{proof}

\begin{theorem}\label{theo:klcslcpk*}
    The Rk-LCS problem for $\s{S}=\{s_1, s_2, \ldots , s_m\}$ can be computed in $\bigo(mN\log^k \ell)$ time with $\bigo(N)$ additional space, for any $\delta=\{H,L,E\}$. 
\end{theorem}

\begin{proof}
    The time complexity for computing $MaxLCP^{\delta,k}_{(s_i,s_j)}[i']$ for all $i'$, $i$, and $j$ values (string pairs) is $\bigo(m^2 \ell \log^k \ell) = \bigo(mN \log^k \ell)$. This is achieved by calculating $MaxLCP^{\delta,k}_{(s_i,s_j)}[i']$ for $\bigo(m^2)$ string pairs. Finding argument pair $(i,i')$ of $T$ takes $\bigo(m^2 \ell) = \bigo(mN)$ time, which is less than the time complexity of computing $MaxLCP^{\delta,k}_{(s_i,s_j)}[i']$ for all $i'$, $i$, and $j$ values, Thus, the overall time complexity of the $Rk$-LCS problem under any distance metric in $\delta$ is $\bigo(mN \log^k \ell)$. 
    For a given string $s_i$, $MaxLCP^{\delta,k}_{(s_i, s_j)}[i']$ must be computed for all $1 \leq j \leq m$, $j \neq i$. This requires  $\bigo(m\ell) = \bigo(N)$ space. Since this space can be reused for other values of $i$, the overall space complexity remains $\bigo(N)$.  \QEDB  
\end{proof}

\begin{corollary}
The $\bigo(mN\log^k \ell)$-time solution of the $Rk$-LCS problem outperforms the $\bigo(N^2)$-time solution for $\delta={H}$ when $k< \frac{\log \ell}{\log \log \ell}$, and the $\bigo(k \ell N^2)$-time solution for $\delta=\{L,E\}$ when $k< \frac{\log k+ 2\log \ell}{\log \log \ell}$.
\end{corollary}

\section{SETH-Hardness of \texorpdfstring{$Rk$-LCS}{Rk-LCS} for $\delta={H}$}\label{sec:seth}

We show the conditional lower bound of $\bigo(N^2)$ for the $Rk$-LCS problem (defined in Section~\ref{sec:DefforApproxLCS}) for $\delta=H$, by reducing the OV problem to $Rk$-LCS.

\begin{definition}\label{def:ov}
    [Orthogonal Vector (OV) Problem] Given a set $A$ of $N_v$ boolean vectors $\in \{0, 1\}^d$, is there a pair of orthogonal vectors $U,V \in A$, such that $\Sigma^d_{p=1}U[p]V[p]=0$?
\end{definition} 

In~\cite{WILLIAMS2005357}, it has been shown that the Orthogonal Vector problem does not have a strongly sub-quadratic time solution, unless SETH\footnote{The Strong Exponential Time Hypothesis (SETH) asserts that for every $\varepsilon > 0$, there exists an integer $q$ such that SAT on \textit{q}-CNF formulas with $m$ clauses and $n$ variables cannot be solved in $m^{O(1)}2^{(1-\varepsilon)n}$ time~\cite{Kedzierski2022K-ApproximateDistance}.} is false (see Theorem~\ref{theo:ovhard}).

\begin{theorem}\label{theo:ovhard}(\cite{WILLIAMS2005357})
Suppose there is $\varepsilon > 0$ such that for all constant $c$, OV problem on a set of $N_v$ boolean vectors of dimension $d = c\log N_v$ can be solved in $2^{o(d)}N^{2-\varepsilon}_v$ time. Then SETH is false.
\end{theorem}

Kociumaka et al.~\cite{Kociumaka2019LongestMismatches} demonstrate the SETH-hardness of the \textit{Rk}-LCS problem for two strings ($m=2$) for $\delta={H}$ by constructing two morphisms. We generalize this result to the \textit{Rk}-LCS problem for more than two strings; that is, for $m > 2$ as shown in Figure~\ref{fig:morphism1}.
In our proof, we construct $m$ distinct morphisms, each of length $8m+5$, denoted as $\mu, \tau_i$ for $1 \leq i \leq m-1$.
We also introduce a string gadget $\gamma = 1{0}^{4m+1} \, 1{0}^{4m+2}$, which is distinct from all defined morphisms, $\mu, \tau_i$ for $1 \leq i \leq m-1$.

Observe that Lemma~\ref{lem:instance}, together with the defined string morphisms, establishes upper and lower bounds on the length of the $Rk$-LCS among the strings in $\s{S}$, depending on whether an orthogonal vector pair exists.

