\begin{fact}\label{fact1}
For $1 \leq i \leq m-1$, $d_H(\mu(0), \tau_i(0)) = d_H(\mu(0), \tau_i(1)) = d_H(\mu(1),$ $\tau_i(0)) = 2m$ and $ d_H(\mu(1), \tau_x(1)) = 2m+4$.
\end{fact}

We call the prefix of length $4m+2$ as \textbf{core part} and the suffix of length $4m+3$ as the \textbf{fixed part} of the morphisms $\mu, \tau_i, \gamma$ where $1\leq i\leq m-1$. Note that, all the morphisms contain the fixed part as their suffix and have variable core parts as their prefix.

\begin{fact}\label{fact2}
String $10^{4m+2}$ has exactly two occurrences in $10^{4m+2}a_1\ldots a_{4m+2}10^{4m+2}$ for $a_i \in \{0,1\}$ and $i \in \{1,...,4m+2\}$.
\end{fact} 

\begin{lemma}\label{lem:instance}
    Consider boolean vectors $A=\{U_1,\ldots,U_{N_v}\}$, of dimension $d$, c and $H = \gamma^d$. The following string constructions are assigned to the strings of set $\s{S}=\{s_1,s_2,\ldots,s_m\}$:
\[
\begin{aligned}
s_1   &= H^q\tau_1(U_1)\,H^q\tau_1(U_2)\,\ldots\,\tau_1(U_{N_v})\,H^q\\
s_2   &= H^q\tau_2(U_1)\,H^q\tau_2(U_2)\,\ldots\,\tau_2(U_{N_v})\,H^q\\
\;\; &\vdots\\
s_{m-1} &= H^q\tau_{m-1}(U_1)\,H^q\tau_{m-1}(U_2)\,\ldots\,\tau_{m-1}(U_{N_v})\,H^q\\
s_m   &= H^q\mu(U_1)\,H^q\mu(U_2)\,\ldots\,\mu(U_{N_v})\,H^q
\end{aligned}
\]
For some $q \geq 1$ and $k=2md$:\\
(a) If the set $A$ contains two orthogonal vectors, then Rk-LCS for $\s{S}$ has a length $\ell' \geq (8m+5)(2q+1)d$.\\
(b) If the set $A$ does not contain two orthogonal vectors, then Rk-LCS for $\s{S}$ has a length $\ell'' \leq (8m+5)(q+1)d$.
\end{lemma}

\begin{proof}
    (a) Assume $U_g$ and $U_h$ are orthogonal. Strings $s_m$ and $s_i$, $1 \leq i \leq m-1$, contain the substrings $u_m=H^q\mu(U_g)H^q$ and $u_i=H^q\tau_i(U_h)H^q$, respectively. By Fact \ref{fact1}, $d_H(u_m,u_i)=2md=k$ for any $i$. Hence, $|u_m|=|u_i|=\ell' = (8m+5)(2q+1)d$.\\
    (b) Assume there is no orthogonal vector pair in $A$, and there exist positions $a,b$ such that substrings $u'=s_m[a,a+\ell''-1]$ and $u''=s_i[b,b+\ell''-1]$ (of length $\ell''$) have at most $k$ mismatches for some $i$. We must have $8m+5 \mid a-b$, as otherwise $u'$ contains at least $\lfloor{(\ell''-(4m+2))/(8m+5)}\rfloor$
    fixed parts ($10^{4m+2}$) and they do not align (match) with the fixed parts in $u''$. By Fact \ref{fact2}, they result in more than $k$ mismatches, contradicting $d_H(u',u'')\le k$.
    By above, we have the fixed parts aligned, hence the core parts of $u'$ and $u''$ are also aligned. Since  the core parts of the $\gamma$ morphism in $u'$ and $u''$ can match exactly, the mismatches must come from the core parts of the $\mu$ and $\tau$ morphisms. As we are allowed at most $k=2md$ mismatches, there can be at most $d$ core parts from each of the $\mu$ and $\tau$ morphisms in both $u'$ and $u''$. The $d$ core parts must correspond to two different vectors; as otherwise $A$ would contain a pair of orthogonal vectors. Consequently, we have exactly $qd$ core parts
    contributed  by the $\gamma$ morphism in $u'$ and $u''$, each. Moreover, the number of fixed parts is at most one greater than the number of core parts. Therefore, we obtain:
    \begin{equation}\label{eq:ell2}
        \lfloor \frac{\ell''-(4m+2)}{8m+5} \rfloor \leq (q+1)d 
    \end{equation} 
    Hence, we have $\ell'' \leq (8m+5)(q+1)d$ for $m \geq 2$ and $q \geq 1$.
    \QEDB
\end{proof}

