% For simplicity, the two noise variances are assumed to be same, \emph{i.e.,} $\epsilon^2_1=\epsilon^2_2=\epsilon^2$.
% Thus, the two channels have the same SNR, which is defined as $\frac{P}{\epsilon^2}$.


To enable arithmetic coding, a hyperprior variable $\mathbf{z}_i\in\mathbb{R}^{N_z}$ is introduced to characterize the PDF of $\mathbf{y}_i$, where $N_z\ll N_y$.
A parametric analysis transform $h_{a_i}$, with parameters $\boldsymbol{\phi}_{h_i}$, maps $\mathbf{y}_i$ to $\mathbf{z}_i$.
The hyperprior represents the dependencies among the elements of $\mathbf{y}_i$, allowing them to be assumed independent given $\mathbf{z}_i$\cite{hyperprior}.
Additionally, it summarizes the means and standard deviations of $\mathbf{y}_i$, and is quantized, compressed, and transmitted to the receiver.
Specifically, each element $y_i^j$ of $\mathbf{y}_i$, for $j=1,...,N_y$, is modeled as a Gaussian variable with mean $\mu_i^j$ and standard deviation $\sigma_i^j$, both estimated by applying a parametric synthesis transform $h_{s_i}$ to the quantized hyperprior $\mathbf{\bar{z}}_i$.
Note that, to be able to use gradient descent methods for the optimization of the network, quantization is approximated by adding uniform noise during training and replaced with actual rounding during inference.
We denote the approximated version of $\mathbf{\bar{y}}_i$ and $\mathbf{\bar{z}}_i$ as $\mathbf{\tilde{y}}_i$ and $\mathbf{\tilde{z}}_i$, respectively.
Therefore, the probability of $\mathbf{\tilde{y}}_i$ given $\mathbf{\tilde{z}}_i$ is obtained by convolving the probability of $\mathbf{y}_i$ with a standard uniform density, which can be written as
\begin{equation}
p(\mathbf{\tilde{y}}_i|\mathbf{\tilde{z}}_i)=\prod_j \left ( \mathcal{N}(\mu_i^j, \sigma_i^j)*\mathcal{U}(-\frac{1}{2}, \frac{1}{2}) \right )(\tilde{y}_i^j),
\label{py}
\end{equation}
with
\begin{equation}
    \boldsymbol{\sigma}_i, \boldsymbol{\mu}_i =h_{s_i}(\mathbf{\tilde{z}}_i;\boldsymbol{\theta}_{h_{i}}),
\end{equation}
where $*$ denotes the convolution operation, and $\boldsymbol{\theta}_{h_{i}}$ encapsulates the parameters of $h_{i}$.
Therefore, the expected code length required to transmit $\mathbf{y}_i$ is given by 
\begin{equation}
    R_{y_i}=\mathbb{E}_{p_{\mathbf{x}_i}}[-\log_2 p(\mathbf{\bar{y}}_i|\mathbf{\bar{z}}_i)] \ \ \ bits.
\end{equation}


% with the transmission rate of the channel input $\mathbf{s}_i$ constrained proportionally to this value.
% For transmission, the real-valued $\mathbf{s}_i$ is then reshaped into a complex-valued vector $\mathbf{s}_i\in\mathbb{C}^{n}$, where $n$ denotes the number of channel use.
% After this, the power of $\mathbf{s}_i$ is normalized to meet the average transmit power constraint 
% $P$, which is assumed to be the same for both transmitters.

Moreover, since the hyperpriors contain information about the code rate, they must also be available at the receiver for decoding.
Assuming error-free transmission, we estimate their transmission cost using a joint density model $p(\mathbf{\tilde{z}}_1, \mathbf{\tilde{z}}_2|\boldsymbol{\psi})$, where $\boldsymbol{\psi}$ denotes the distribution parameters.
Details of this joint density model are provided in Section IV-C.
Therefore, their joint entropy can be expressed as
\begin{equation}
    H(\mathbf{\bar{z}}_1, \mathbf{\bar{z}}_2) = \mathbb{E}_{p(\mathbf{\bar{z}}_1, \mathbf{\bar{z}}_2|\boldsymbol{\psi})}[-\log_2 p(\mathbf{\bar{z}}_1, \mathbf{\bar{z}}_2|\boldsymbol{\psi})] \ \ \ bits,
\end{equation}
and the total code rate $R_i$ for User $i$ is
\begin{equation}
    R_i = R_{y_i} + \frac{1}{2}H(\mathbf{\bar{z}}_1, \mathbf{\bar{z}}_2) \ \ \ bits.
    \label{code rate}
\end{equation}

