        &\overset{(c)}{=}\!\overset{=0}{\boxed{\mathbb{E}_{p_{\mathbf{x}_1,\mathbf{x}_2}}\mathbb{E}_{q_{\mathbf{\tilde{y}}_1,\mathbf{\tilde{y}}_2,\mathbf{\tilde{z}}_1,\mathbf{\tilde{z}}_2|\mathbf{x}_1,\mathbf{x}_2}}\!  \log q(\mathbf{\tilde{y}}_1,\mathbf{\tilde{y}}_2,\mathbf{\tilde{z}}_1,\mathbf{\tilde{z}}_2|\mathbf{x}_1,\mathbf{x}_2)}}\nonumber
        \\&\ \ \ \ \ +\mathbb{E}_{p_{\mathbf{x}_1,\mathbf{x}_2}}\mathbb{E}_{q_{\mathbf{\tilde{y}}_1,\mathbf{\tilde{y}}_2,\mathbf{\tilde{z}}_1,\mathbf{\tilde{z}}_2|\mathbf{x}_1,\mathbf{x}_2}}\left\{-\log p(\mathbf{x}_1,\mathbf{x}_2|\mathbf{\tilde{y}}_1,\mathbf{\tilde{y}}_2,\mathbf{\tilde{z}}_1,\mathbf{\tilde{z}}_2)-\log p(\mathbf{\tilde{y}}_1|\mathbf{\tilde{z}}_1)-\log p(\mathbf{\tilde{y}}_2|\mathbf{\tilde{z}}_2)-\log p(\mathbf{\tilde{z}}_1,\mathbf{\tilde{z}}_2) \right\}+\text{\small const}\nonumber\\
        &=\!\mathbb{E}_{p_{\mathbf{x}_1,\mathbf{x}_2}}\mathbb{E}_{q_{\mathbf{\tilde{y}}_1,\mathbf{\tilde{y}}_2,\mathbf{\tilde{z}}_1,\mathbf{\tilde{z}}_2|\mathbf{x}_1,\mathbf{x}_2}}\! \left\{ -\log p(\mathbf{x}_1,\mathbf{x}_2|\mathbf{\tilde{y}}_1,\mathbf{\tilde{y}}_2,\mathbf{\tilde{z}}_1,\mathbf{\tilde{z}}_2)-\log p(\mathbf{\tilde{y}}_1|\mathbf{\tilde{z}}_1)-\log p(\mathbf{\tilde{y}}_2|\mathbf{\tilde{z}}_2)-\log p(\mathbf{\tilde{z}}_1,\mathbf{\tilde{z}}_2) \right\}+\text{\small const}
        \label{expansion ntsc}
    \end{align}
    \begin{equation}
    q(\mathbf{\tilde{y}}_1,\mathbf{\tilde{y}}_2,\mathbf{\tilde{z}}_1,\mathbf{\tilde{z}}_2|\mathbf{x}_1,\mathbf{x}_2)=\prod_k\mathcal{U}(\tilde{y}_1^k|y_1^k-\frac{1}{2},y_1^k+\frac{1}{2})\prod_j\mathcal{U}(\tilde{y}_2^j|y_2^j-\frac{1}{2},y_2^j+\frac{1}{2})\prod_m\mathcal{U}(z_1^m|z_1^m-\frac{1}{2},z_1^m+\frac{1}{2})\prod_n\mathcal{U}(\tilde{z}_2^n|z_2^n-\frac{1}{2},z_2^n+\frac{1}{2})
    \label{q ntsc}
    \end{equation}
