\hypertarget{fig_pos_neg}{\includegraphics[width=\textwidth]{positive_negative_summary.pdf}}
\caption{\textbf{Multi-positive contrastive learning.}
\textbf{(A)} Same-tumor embeddings are \emph{positives} (yellow); different tumors are \emph{negatives} (gray).
\textbf{(B)} Radiomics feature subsets.
