\begin{lemma}\label{lemme-transfert-strategies}
%
If $T(\game^1_S) \preceq_s T(\game^2_S)$ then for all $\sigma_1$ strategy of $\playerone$ in $T(\game_S^1)$, there exists $\sigma_1'$ a strategy of $\playerone$ in $T(\game^2_S)$ such that 
\[
\{ \tr(\rho') \mid \rho' \in \outcome({\sigma_1'}) \}  \subseteq
\{ \tr(\rho) \mid \rho \in \outcome({\sigma_1}) \}
\]
\end{lemma}
The relevance of this lemma is the following: if we may prove that a game $\game$ is 
bisimilar with a simpler game $\game'$ and are able to build a strategy $\sigma'$ for \playerone in $\game'$ which 
satisfies some property, then Lemma \ref{lemme-transfert-strategies} allows us to translate $\sigma'$ into a strategy $\sigma$ which 
satisfies the same property. Therefore, if $\game'$ lies in a decidable class of games $\Gamma$, we may use the decision algorithm for $\Gamma$ to 
synthesize $\sigma'$ and, hence, provide a methodology for attacking the strategy synthesis problem in the class of games where $\game$ lies. 

The plan for the rest of the paper is then to show that ISR games are alternating bisimilar with simpler games in which 
the strategy synthesis problem is decidable. 



\section{From Initialized Singular Games to Stopwatch Game}
We extend the construction from \cite{HENZINGER199894} used for automata to the more general case of turn-based games. The first step is 
to reduce, through an alternating bisimulation, each initialized singular game to a 
\emph{stopwatch game}. 
%
\begin{definition}[Initialized Stopwatch Game]
An initialized stopwatch game %$\game_{W}$ 
of $n$-dimension is an initialized singular game in which the flow is either $1$ or $0$, that is, for any location $l$ and variable $x$, $flow(l,x) \in \{0,1\}$.
%
\end{definition}

\subsection{Transformation}
\label{trans:singToStop}
Given an initialized singular game 
$\game_{S} = (l_0, L_1, L_2, \var, \act, \obs, \flow, \edge, \labeling)$
we construct from $\game_S$ an initialized stopwatch game $\game_W$, where we change the dynamic to $\flow(l,x)=1$ when it is not zero, 
for that we adapt the constraints and the reset functions; we divide the constraints values with the flow of the current location and the reset values with the flow of the successor location. The game is built as follows: 
$$\game_{W} = (l_0, L_1, L_2, \var, \act, \obs, \flow_W, \edge_W, \labeling)$$
\begin{enumerate}
  \item $l_0$, $L_1$, $L_2$, $\act$, $\obs$ and $\labeling$ are kept the same as $\game_S$.
  \item $\flow_W: L \times \var \to \mathbb{Q}^n$ where for all $x \in \var$, 
  \begin{align}
  \label{eq:flow}
  \flow_W(l,x)=
     \begin{cases}
      0 & \text{ if }\flow(l,x)=0\enspace,\\
      1 & \text{otherwise}\enspace.
          \end{cases}
    \end{align}
    %
   \item $\edge_W$ is the set of edges $e_W=(l,a,\varphi_{e_W}, \post_{e_W},l')$ such that 
   \begin{enumerate}
   \item there exists $e=(l,a,\varphi_e,\post_e,l') \in \edge$.
       \item If we denote 
         \begin{align*}
 \varphi_{e_W}(x)=
     \begin{cases}
      \frac{\varphi(x)}{\flow(l,x)} & \text{ if }\flow(l,x)\neq 0\enspace,\\
      \varphi(x) & \text{otherwise}\enspace.
          \end{cases}
    \end{align*}
%
then the constraint $\varphi_{e_W}$ is the following conjunction: $ \varphi_{e_W}= \bigwedge_{x\in \var} \varphi_e(x) $. 
%
       \item $\post_{e_W}: \var \to \mathbb{Q}^n \cup \{ \bot\}$ where 
  to each $x \in \var$ and edge $e=(l,a,\varphi_e,\post_e,l')\in \edge$
        \begin{align}
        \label{eq:post}
       \post_{e_W}(x) = 
        \begin{cases}
            \bot & \text{ if }\post(x)= \bot\enspace,\\
            \frac{\post(x)}{\flow(l',x)} & \text{ if } \flow(l',x)\neq 0  \enspace,\\
            \post(x) & \text{ if } \flow(l',x) = 0 \enspace.
        \end{cases}
    \end{align}
%
   \end{enumerate}
\end{enumerate}
For the sequel, we denote the semantics of $\game_S$ as 
$T(\game_S) = (Q(\game_S), \mvs{\game_S}, q_0,\delta)$
and the semantics of $\game_{W}$ as 
$T(\game_W) = (Q(\game_W), \mvs{\game_W}, q_0,\delta_W)$.

For the sequel, given a configuration $(l,v)\in Q(\game_S)$, we denote $v^*$ the following variable valuation:
\begin{align}
\label{eq:vstar}
\forall~x \in \var\colon~
v^*(x) = 
\begin{cases}
   \frac{v(x)}{\flow(l,x)}  & \text{ if } \flow(l,x)\neq 0 \\
   v(x) & \text{ otherwise }
\end{cases}
\end{align}

We define the mapping
%
$\gamma_1: Q(\game_S) \to Q(\game_W)$ as follows: 
\[\forall q=(l,v) \in Q(\game_S),~\gamma_1 \colon (l,v) \mapsto (l,v^*)\enspace.\]
%
Clearly enough, $\gamma_1^{-1}$, the inverse of $\gamma_1$, exists.
%$$\gamma_1^{-1}: Q(\game_W) \to Q(\game_S)$$
Therefore, for any $(l,v^*)\in Q(\game_W)$, 
$\gamma_1^{-1} \colon (l,v^*) \mapsto (l,v)$ where 
\begin{align}
\forall~x \in \var\colon
v(x) = 
\begin{cases}
   v^*(x) \cdot {\flow(l,x)}  & \text{ if } \flow(l,x)\neq 0 \enspace,\\
   v^*(x) & \text{ otherwise}\enspace.
\end{cases}
\end{align}
By construction of $T(\game_W)$ we have $(l,v)\in Q(\game_S)$.
\subsection{Bisimulation between $T(\game_S)$ and $T(\game_W)$}
We now show that the mapping $\gamma_1$ defined above is an alternating bisimulation.
%
\begin{lemma}
$\gamma_1$ witnesses that $T(\game_S) \preceq_s T(\game_W)$. 
%
\end{lemma}
%
\begin{proof}
Note that, by definition, $q_0^*=\gamma_1(q_0) = q_0$ the initial configurations in the two games $(q_0,q^*_0)\in \gamma_1$ as required. 

Let $q =(l,v)$ be a configuration in $Q(\game_S)$, and let $q^* = \gamma_1(q)=(l,v^*)$ be a configuration in $Q(\game_W)$. 
Since the location $l$ is the same, the observation is preserved thus $\labeling(q) = \labeling(q^*)$, so the first point in Def.~\ref{def-bisim} holds.

We need to show that the 2nd item in Def.~\ref{def-bisim} holds, that is, 
for any two configurations $(l,v)$ in $Q_1(\game_S)$, and $(l,v^*)$ in 
$Q_1(\game_W)$ with $((l,v),(l,v^*)) \in \gamma_1 $
and for any move $m$ in $\mvs{\game_S}$, there exists a move $m^*$ in $\mvs{\game_W}$
such that the following holds:
\begin{align}
\label{eq:singSim1}
    \left(
\delta_S((l,v),m),
\delta_W((l,v^*), m^*)
\right) \in \gamma_1
\enspace.
\end{align}
The trick here, is to use the same move $m$ in both $T(\game_S)$ and $T(\game_W)$. 

Let $(l,v)$ be a configuration of $\playerone$, and let $m$ be a move, we first prove that $\delta_W((l,v^*), m)$ is well defined.
%
Since $(l',v') = \delta_S((l,v),m)$ with $m=(a,t)$, 
there exists $e=(l,a,\varphi_e,\post_e,l')$ in $\game_S$ 
such that for each $x \in \var$,
\begin{equation}\label{eq-tr3-v1}
v(x) + t \cdot \flow(l,x) \in \varphi_e(x)
\end{equation}
and $v' = \post_e(v)$.
By transformation of Sec.~\ref{trans:singToStop}, there exists an edge
$e^*=(l,a,\varphi_{e^*},\post_{e^*},l^{'})$ in $\game_W$.
Now, we show that:
$v^{*}+ t \cdot \flow_W(l,\cdot )$ satisfies $\varphi_{e^*}$.
To this end, observe that Identity \eqref{eq-tr3-v1} implies that for all $ x \in \var$: 
\begin{align*}
 \flow(l,x) \neq 0 &\implies
 \frac{v(x)}{\flow(l,x)} + t \in \frac{\varphi_e(x)}{\flow(l,x)}\\
 &\implies v^*(x) + t \in  \varphi_{e^*}(x) 
\end{align*}
Where the second implication is because $\flow(l,x) \neq 0 \implies \flow_W(l,x) = 1$.

When $\flow(l,x) = 0$, $v^*(x) = v(x)$, $\varphi_{e^*}(x) = \varphi_e(x)$ and 
%
Identity~\eqref{eq-tr3-v1} becomes $v(x) \in \varphi_e(x)$. 
Hence $v^*(x) \in \varphi_{e^*}(x)$.
This implies that 
$\delta_W(((l,v^*),m)$ is indeed well defined. 
We still need to show that it is the image of $\delta_S((l,v),m)$ by $\gamma_1$.

Let $(l',v') = \delta_S((l,v),m)$, then we need to study the following cases: \\
%
(1) For $x\in \var$ with $\flow(l, x) \neq 0$ and $\post_e(x) = \bot$:
\begin{align*}
%
  \gamma_1((l',v'(x)) &= 
  \left(l', \frac{v'(x)}{\flow(l',x)}\right)
  =\left(
  l', \frac {v(x) + t \cdot \flow(l,x)}{\flow(l',x)}
  \right)\\
  %
  &= \left(
  l',\frac{v(x)}{\flow(l,x)} + t
  \right)\text{ because $\flow(l',x)=\flow(l,x)$, cf. Eq.~\eqref{eq:vstar},}\\
  &=(l', v^*(x) + t)\text{ because $\flow_W(l',x)=1$, cf. Eq.~\eqref{eq:flow}}\\
  %
  &= \delta_W((l,v^*(x)),m) \enspace.
  \end{align*}
(2) For all $x\in \var$ with $\flow(l, x) = 0$ and $\post_e(x) = \bot$:
\begin{align*}
%
  \gamma_1((l',v'(x)) &= 
  \gamma_1(l', v(x)) \text{ because $\flow(l,x) = 0$, cf. Eq.~\eqref{eq:flow}}\\ 
  &=\left( l', v^*(x) \right)= \delta_W((l,v^*(x)),m) 
\text{ because $\flow_W(l',x) = 0$, cf. Eq.~\eqref{eq:flow}.}
  \end{align*}
(3) For all $x\in \var$ with $\flow(l', x) \neq 0$ and $\post_e(x) \neq \bot$:
\begin{align*}
  \gamma_1((l',v'(x)) &= 
  \left(l', \frac{v'(x)}{\flow(l',x)}\right)\\ 
  &=\left(
  l', \frac {\post_e(x)}{\flow(l',x)}
  \right) \text{ because $\post_e(x) \neq \bot$}\\
  &=\left(l',\post_{e^*}(x)\right) \text{ because $\flow(l',x) = 1$, cf. Eq.~\eqref{eq:flow}}\\
  &= \delta_W((l,v^*(x)),m) \enspace.
  \end{align*}
(4) Finally for all $x\in \var$ with $\flow(l, x) = 0$ and $\post_e(x) \neq \bot$:
\begin{align*}
  \gamma_1((l',v'(x)) &= 
  \left(l',v'(x)\right)
  =\left(
  l', \post_e(x)
  \right)
  =\left(l',\post_{e^*}(x)\right) 
  = \delta_W((l,v^*(x)),m) \enspace.
  \end{align*}
In all of the above cases, we have shown that $\gamma_1(\delta_S((l,v), m)) = \delta_W(\gamma_1((l,v)), m)$,
that is, $\gamma_1$ preserves the transition relation in both 
$T(\game_S)$ and $T(\game_W)$.

Now, for proving the 3rd point in Def. \ref{def-bisim},
Let $q=(l,v)$ be a configuration of $\playertwo$, and let $m$ be a move in $\mvs{\game_W}$, we take the same move in $\mvs{\game_S}$, we first prove that $\delta_S((l,v),m)$ is well defined in $T(\game_S)$. \\
Since $(l',{v^*}')= \delta_W((l,v^*),m)$ with $m=(a,t)$ there exists $e^*=(l,a,\varphi_{e^*}, \post_{e^*},l')$ in $\game_W$ such that for each $x\in \var$, 
\begin{equation}\label{eq-tr3-v2}
v^*(x) + t \cdot \flow_W(l,x) \in \varphi_{e^*}(x)
\end{equation}
and ${v^*}'= \post_{e^*}(v)$. By transformation of Sec.~\ref{trans:singToStop}, the existence of $e^*$ in $\game_W$ is the result of the existence of $e=(l,a,\varphi_e, \post_e,l')$ in $\game_S$. Now we show that $v+ t \cdot \flow(l,\cdot)$ satisfies $\varphi_e$. Observe that identity \eqref{eq-tr3-v2} implies that for all $x \in \var$:
\begin{align*}
 \flow_W(x) \neq 0 &\implies v^*(x)+ t \in \varphi_{e^*}(x) \\
& \implies \frac{v(x)}{\flow(l,x)} + t \in \frac{\varphi_e(x)}{\flow(l,x)}\\
 &\implies v(x) + t \cdot \flow(l,x) \in \varphi_e(x)
\end{align*}
Where the second implication is because $\flow_W(x)=1$ implies $\flow(x) \neq 0$. 
When $\flow_W(l,x)=0$, $v(x)=v^*(x)$, $\varphi_e(x)= \varphi_{e^*}(x)$, and identity \eqref{eq-tr3-v2} becomes $v^*(x)\in \varphi_{e^*}(x)$, hence $v(x)\in \varphi_{e}(x)$. This implies that $q'=\delta_S((l,v),m)$ is indeed well defined with $q'=(l',v')$ and $v'=\post_e(v+t\cdot \flow(l,\cdot))$. We still need to prove that the image of $\delta_S((l,v),m)$ by $\gamma_1$ is $\delta_W((l,v^*),m)$.
%

For $(l',{v^*}')= \delta_W((l,v^*),m)$ and we name $(l',v')= \delta_S((l,v),m)$, we have $\forall x \in \var$ with $\flow_W(l,x) \neq 0$ and $\post_{e^*}(x)= \bot$:
\begin{align*}
 (l',{v^*}'(x)) &=(l',{v^*}(x) +t ) =\left(l',\frac {v(x)}{\flow(l,x)} + t \right)\\
 &=\left(l',\frac {v(x) +t \cdot \flow(l,x) } {\flow(l,x)}\right) 
            =\left(l',\frac { v(x) +t \cdot \flow(l,x) } {\flow(l',x)} \right)\\
 &=\left(l',\frac {v'(x)} {\flow(l',x)} \right) 
       = \gamma_1(l', v'(x))
    \end{align*}
Consider the case $\flow_W(l,x) = 0$, hence for all $x \in \var$ with $\post_{e^*}(x)= \bot$:
\begin{align*}
 (l',{v^*}'(x)) &=(l',{v^*}(x)) =\gamma_1(l',v(x)) = \gamma_1(l', v'(x))
\end{align*}
Now for all $x \in \var$ with $\flow_W(l',x) \neq 0$ and $\post_{e^*}(x) \neq \bot$: 
\begin{align*}
 (l',{v^*}'(x)) &=(l',\post_{e^*}(x) ) 
    =\left(l',\frac {\post_{e^*}(x)}{\flow(l',x)}\right)\\
  &=\left(l',\frac {v(x) +t \cdot \flow(l,x) } {\flow(l,x)}\right)
  =\left(l',\frac { v(x) +t \cdot \flow(l,x) } {\flow(l',x)} \right)\\
&=\left(l',\frac {v'(x)} {\flow(l',x)} \right)
     = \gamma_1(l', v'(x))
    \end{align*}
Finally, for all $x \in \var$ with $\flow_W(l',x) = 0$ and $\post_{e^*}(x) \neq \bot$: 
\begin{align*}
 (l',{v^*}'(x)) =(l',\post_{e^*}(x) ) 
 =(l',\post_{e}(x)
=(l',v'(x))
= \gamma_1(l', v'(x))
    \end{align*}
Therefore,
$\gamma_1(\delta_S((l,v), m)) = \delta_W(\gamma_1((l,v)), m)$.
This ends the proof of this lemma. 
\qed\end{proof}

\begin{lemma}
$\gamma^{-1}$ witnesses that
$T(\game_W) \preceq_s T(\game_S)$.  
\end{lemma}

\begin{proof}
Note that, by definition, $q_0=\gamma_1^{-1}(q_0^*)$ the initial configurations in the two games as required. 

Let $q^*=(l,v^*)$ be a configuration in $Q(\game_W)$ and let $q=(l,v)= \gamma_1^{-1}(q^*)$ be a configuration in $Q(\game_S)$.
Since the location $l$ is the same, the observation is preserved thus $\labeling(q) = \labeling(q^*)$, so the first point in Def.~\ref{def-bisim} holds.

We now show that $\gamma_1^{-1}$ satisfies the 2nd point in Def.~\ref{def-bisim}, for all $q^*=(l,v^*) \in Q(\game_W) $ and $q=(l,v)=\gamma_1^{-1}(q^*) \in Q(\game_S)$. Assume that $q^*$ a configuration of $\playerone$, for all $m=(a,t) \in \mvs{T(\game_W)}$ and ${q^*}'=(l',{v^*}')=\delta_W(q^*,m)$ in $T(\game_W)$, we take the same move $m$ in $T(\game_S)$, we first prove that $\delta_S(q,m)$ is well defined in $T(\game_S)$, let us call it $q'$. Afterwards we prove that $q'=\gamma_1^{-1}({q^*}')$. We have for each $x\in \var$,
$$ {v^*}'(x) ={v^*}(x) +t \cdot \flow_W(l,x) \in \varphi_{e^*}(x)$$
And ${v^*}'=\post_{e^*}(v^*)$ for the edge $e^*=(l,a,\varphi_{e^*}(x), \post_{e^*}(x),l')$, $e^*$ is obtained from the edge $e=(l,a,\varphi(x), \post(x),l')$ in $\game_S$ by transformation of Sec.~\ref{trans:singToStop}. Now we show that $v + \flow(l,\cdot) \in \varphi_e$. For all $x\in \var$ and $\flow(l,x)\neq 0$ we have
\begin{align*}
&{v^*}(x) +t \cdot \flow_W(l,x) \in \varphi_{e^*}(x)\\
&\implies {v^*}(x) \cdot \flow(l,x) +t \cdot \flow_W(l,x) \cdot \flow(l,x) \in \varphi_{e^*}(x)\cdot \flow(l,x)\\
&\implies v(x)+t \cdot \flow(l,x) \in \varphi_{e^*}(x)\cdot \flow(l,x)\\
&\implies v(x)+t \cdot \flow(l,x) \in \varphi_e(x)
\end{align*}
For all $x\in \var$ and $\flow(l,x) = 0$, we obtain $v^*(x)=v(x)$ and $\varphi_{e^*}(x)=\varphi_e(x)$. It follows that $v(x)\in \varphi_e(x)$. This implies that indeed $q'=\delta_S(q,m)=(l',v')$ with $v'=\post_e(v +t \cdot \flow(l,\cdot))$ is well defined. 

Now let us prove $q'=\gamma_1^{-1}({q^*}')$. For all $x\in\var$: \\
(1) For $\flow(l,x)\neq 0$ and $\post_{e^*}=\bot$ we have:
\begin{equation*}
\begin{split}
\gamma_1^{-1}(l', {v^*}')  &= (l', v^{*'}(x) \cdot {\flow(l',x)}
= (l', ( v^*(x) + t \cdot \flow_W(l,x) ) \cdot {\flow(l',x)})\\
&= (l', ( v^*(x) + t )  \cdot \flow(l,x) )
= (l', ( v^*(x)  \cdot \flow(l,x)  + t \cdot \flow(l,x)))\\
&= (l', v + t \cdot \flow(l,x))=(l',v'(x))
\end{split}
    \end{equation*}
(2) For $\post_{e^*}\neq \bot$ and $\flow(l',x)\neq 0$ we have:
\begin{equation*}
\begin{split}
\gamma_1^{-1}(l', {v^*}')  &= (l', v^{*'}(x) \cdot {\flow(l',x)}= (l', \post_{e^*}(x) \cdot {\flow(l',x)})\\
&= (l', \post_e(x) )=(l',v'(x))
\end{split}
    \end{equation*}
(3) For $\post_{e^*}\neq \bot$ and $\flow(l',x)=0$ we have:
\begin{equation*}
\begin{split}
\gamma_1^{-1}(l', {v^*}')  &= (l', v^{*'}(x))= (l', \post_{e^*}(x))= (l', \post_e(x) )=(l',v'(x))
\end{split}
    \end{equation*}
%
We conclude that $(l',v')=\gamma_1^{-1}(l', {v^*}')$.

Now, for proving the 3rd point in Def. \ref{def-bisim}: let $q^*$ be a configuration of $\playertwo$, and let $m$ be a move in $\mvs{\game_S}$ and $q'=(l',v')=\delta_S((l,v),m)$ in $T(\game_S)$, we take the same move in $\mvs{\game_W}$, we first prove that $q{^*}'=\delta_W((l,v^*),m)$ is well defined in $T(\game_W)$, and then we prove that $\gamma_1^{-1}(q{^*}')=(q')$. \\
Since $q'=(l',v')=\delta_S((l,v),m)$ then there exists an edge $e=(l,a,\varphi_{e},\post_{e},l')$. 
By transformation there exists an edge in $\game_W$ $e^*=(l,a,\varphi_{e^*},\post_{e^*},l')$. 

For each $x \in \var$ with $\flow(l,x) \neq 0$, we have:
\begin{align}
   v(x) + t \cdot \flow(l,x) & \in \varphi_e(x) \notag \\
   & \implies v^*(x) \cdot \flow(l,x) + t \cdot \flow(l,x) \in \frac{\varphi_e(x)}{\flow(l,x)} \cdot \flow(l,x) \notag \\
      &\implies v^*(x) + t \in \varphi_{e^*}(x) \notag \\
    &\implies v^*(x) + t \cdot \flow_W(l,x) \in \varphi_{e^*}(x) 
    \label{varphigammainverse}
\end{align}
Notice that for $\flow(l,x) = 0$, we obtain $\flow_W(l,x) = 0$, $v^*(x)=v(x)$, $\varphi_e(x)=\varphi_{e^*}(x)$, hence $v^*(x) \in \varphi_{e^*}(x)$. 
Let ${v^*}'= \post_{e^*}(v^* + t \cdot \flow_W(l,\cdot))$. We have proved that $q{^*}'= (l,{v^*}')=\delta_W((l,v^*),m)$ is well defined. 

Now we prove that $\gamma_1^{-1}(l',{v^*}')=(l',v')$. For each $x \in \var$ consider the case $\flow(l',x) \neq 0$ and $\post_{e^*}=\bot$,
\begin{align*}
\gamma_1^{-1}(l',v^{*'}(x))&= (l',v^{*'}(x) \cdot \flow(l',x)) 
= \big(l',( v^*(x) + t \cdot \flow_W(l,x) ) \cdot \flow(l',x) \big) \\
&=  \big(l',v^*(x) \cdot \flow(l',x) + t \cdot \flow(l',x)  \big) \\
& =  \big(l',v^*(x) \cdot \flow(l,x) + t \cdot \flow(l,x) \big)  \\
&=  \big(l',v(x)  + t \cdot \flow(l,x) \big) 
= (l',v'(x))
    \end{align*}
Now for each $x \in \var$ $\flow(l',x) = 0$ and $\post_{e^*}=\bot$,
\begin{align*}
\gamma_1^{-1}(l',v^{*'}(x))&= (l',v^{*'}(x)) = (l',v^*(x)) 
= (l',v(x)) 
= (l',v'(x))
\end{align*}
Same for the case for each $x \in \var$ with $\post_{e^*}(x)\neq\bot$ and $\flow(l',x) = 0$,
\begin{align*}
\gamma_1^{-1}(l',v^{*'}(x))&=(l',v^{*'}(x))=(l',\post_{e^*}(x)) = (l',\post_e(x)) = (l',v'(x))
    \end{align*} 
Finally consider the case for each $x \in \var$ with $\post_{e^*}(x)\neq\bot$ and $\flow(l',x) \neq 0$,
\begin{align*}
\gamma_1^{-1}(l',v^{*'}(x))&= (l',\post_{e^*}(x)\cdot \flow(l',x)) = \left( l', \frac{\post_e(x)}{\flow(l',x)}\cdot \flow(l',x) \right) \\
&=  \big(l',\post_e(x) \big) 
= (l',v'(x))
    \end{align*}
%
This ends the proof.\qed
\end{proof}
\section{From Initialized Stopwatch to Updatable Timed Games}
The next step is to transform each initialized stopwatch game into a game where the dynamics of each variable is never zero, by eliminating all the flows of value zero. The games obtained by this transformation are called \emph{updatable timed games}. 
\begin{definition}[Updatable Timed Game]
An updatable timed game $\game_{U}$ of $n$-dimension is an initialized singular game in 
which all variables are clocks, i.e. $\flow(l,x) = 1$ for any location $l$ and any 
variable $x\in \var$.
\end{definition}
Note that these structures generalize timed games by allowing updates with any rational value, similarly with updatable timed automata from \cite{BouyerDFP04}. 
%
\subsection{Transformation}
Given $\game_W$ an initialized stopwatch game with $n$ variables (whose semantics is denoted $T(\game_W)$ in the sequel) we construct an updatable timed game in two steps.
We first transform $\game_W$ into another stopwatch game $\overline{\game_W}$ 
in which the locations carry some extra information about resets.
Then this stopwatch game is transformed into an updatable timed game.

The need for the intermediate stopwatch game comes from the fact that each stopwatch in the original game is simulated by a clock in the resulting game.  But clocks 
are always incremented when time pass, so when some stopwatch in a location $l$ in which the stopwatch's flow is $0$ must be encoded with a clock, 
we need to reset this clock on any transition leaving $l$. The value to which this clock must be updated depends on the sequence of transitions through which $l$ has been reached.
Along a finite run $\rho$ ending with the edge $e$ this reset value it is the update to which the stopwatch was reset on the latest edge $e'$ when the stopwatch's flow changed from $1$ to $0$. 
These bits of memory are modeled by the extra information encoded into locations of the new stopwatch game.

The formalization of the first transformation is the following: 
$$\overline{\game_W}= (\overline{l_0}, \overline{L_1}, \overline{L_2},\var, \act, \obs,\flow, \overline{\edge},\labeling)$$
\begin{enumerate}
    \item $\overline{l_0}=(l_0,f_{l_0})$ where $f_{l_0}: \var \to \{0\}$.
    \item $\overline{L_1}= L_1 \times F$ where $F$ is the set that consists of 
    functions $f : \var \to K_{\bot}$, where $K$ 
    is the set of all constants used in $\game_W$ and 
    $K_{\bot}=K \cup \{\bot\}$.
    \item $\overline{L_2}=L_2 \times F$. 
    \item $\labeling$ is extended over $\overline{L_1} \cup \overline{L_2}$ as expected.
    \item $\overline{\edge}$ is the set of edges $\overline{e}=(\overline{l_1},a,\varphi, \post,\overline{l_2})$ where 
    $\overline{l_1} =(l_1,f_{l_1}), \overline{l_2} = (l_2,f_{l_2})$ and
    there exists an edge $e\in \edge$ with $e=(l_1,a,\varphi,\post,l_2)$ 
    and for all $x \in \var$:
    \begin{equation}
    \label{transformation-2}
        f_{l_2}(x) = 
        \begin{cases}
            \bot & \text{ if } \flow(l_2,x)=1\enspace,\\
            \post(x) & \text{ if } \flow(l_2,x) = 0 \land \post(x)\neq \bot\enspace,\\
            f_{l_1}(x) & \text{ if } \flow(l_2,x) = 0 \land \post(x)=\bot\enspace.
        \end{cases}
    \end{equation}
\end{enumerate}
The semantics of $\overline{\game_W}$ that we call $T(\overline{\game_W})$ is as follows
$$T(\overline{\game_W}) = (Q(\overline{\game_W}), \mvs{\overline{\game_W}}, \overline{q_0},\overline{\delta_W})$$
Now we construct $\game_U$ an updatable timed game from $\overline{\game_W}$ in the next step.\\
Step 2:
$$\game_{U} = (\overline{l_0}, \overline{L_1}, \overline{L_2}, \var, \act, \obs, \edge_U, \labeling)$$
\begin{enumerate}
    \item $\overline{l_0}, \overline{L_1}, \overline{L_2}, \obs, \act,\labeling$ are all same as in $\overline{\game_W}$.
    \item $\edge_U$ is the set of edges $e_U=(\overline{l_1},a,\varphi, \post_U,\overline{l_2})$ with $\post_U: \var\to \mathbb{Q}^n \cup \{\bot\}$ such that for all $\overline{e} \in \overline{\edge}$ with $\overline{e}=(\overline{l_1}, a, \varphi, \post,\overline{l_2})$ we have for all $x \in \var$,
    \begin{equation}
       \label{overline.post}
       \post_U(x)=
     \begin{cases}
        f_l(x) & \text{ if }f_l(x) \neq \bot\enspace,\\
        \post(x) & \text{ otherwise }\enspace.     
      \end{cases}
    \end{equation}

Note that if we have a reset of a variable $x$ with $flow(l,x)=0$, then $\post_U(x)=\post(x)=f_l(x)$. Note that $\edge_U$ is same as $\overline{\edge}$ with different reset function $\post_U(\var)$ on each edge.
\end{enumerate}
The transition system of the updatable timed game $\game_U$, that we call $T(\game_U)$ is as follows
$$T(\game_U)= (Q(\game_U),\mvs{\game_U}, q_{0_U},\delta_U)$$
We define the relation 
$\beta_1 \subseteq Q(\game_W) \times Q(\overline{\game_W})$ as follows: 
\[
\beta_1 = \{ ((l,v), (\overline{l},\overline{v})) \mid (l,v) \in Q(\game_W), \overline{l}=(l,f_l) \text{ where } f_l : X \to K_{\bot} \text{ and } \overline{v} = v \}
\]
And its inverse $\beta_1^{-1} \subseteq Q(\overline{\game_W}) \times Q(\game_W)$,
\[
\beta_1^{-1}=\{ \left( (\overline{l},\overline{v}),(l,v)\right)  \mid (\overline{l},\overline{v}) \in Q(\overline{\game_W}), ((l,v),(\overline{l},\overline{v}))\in \beta_1\}
\]
%
