\section{From Updatable Timed Game to Timed Game}
\begin{definition} [Timed Turn Based Game]
A timed turn based game $\game_{T}$ of $n$-dimension is an updatable timed game in which clocks can only be reset to 0.
%the reset of all clocks is only to zero. 
\end{definition}
In the sequel, in an edge $e=(l,a,\varphi_e,r,l')$ of a timed automaton, we consider that $r \subseteq X$ denotes the set of clocks which are reset along this edge.  
%$$\game_T= (l_0,L_1, L_2, \clocks, \act, \obs, \edge, \labeling)$$
%where $\edge \subseteq L_1\times \act \times \Constr(\clocks) \times 2^\clocks \times L_2  \cup L_2 \times \act \times \Constr(\clocks) \times 2^\clocks \times L_1$ is the set of edges, for each edge $e=(l,a,\varphi_e,r,l')$ to be taken with an action $a$, the constraint $\varphi_e$ must be satisfied by the valuation of clocks, then the set $r$ is reset to zero, we use the notation $v[r:=0]$ to say that in the valuation $v$ only the set $r$ of clocks is now of value zero for the successor location $l'$.

\subsection{Transformation}
\label{updatabletotimed}
Given an updatable game $\game_U= (l_0,L_1, L_2, \var, \act, \obs, \edge, \labeling)$ whose semantics is denoted $T(\game_U)= (Q(\game_U),\mvs{\game_U}, q_0, \delta_U)$ we now construct the timed game $\game_T$ as:
\[
\game_T= (l_0^t, L_1^t, L_2^t, \var, \act, \obs,\edge^t,\labeling)
\]
where 
\begin{enumerate}
\item  $l_0^t=(l_0,g_{l_0})$ where $g_{l_0}: \var \to \{0\}$.
    \item $L_1^t= L_1 \times F_t $ where $F_t$ is the set of functions $g: \var \to K_U$, where $K_U$ is the set of constants used in the definition of $\game_U$.
    \item $L_2^t=L_2 \times F_t$. 
    \item $\labeling$ is extended over $L_1^t \cup L_2^t$ as expected.
    \item $\edge^t$ is the set of edges $e^t=(l^t_1,a,\varphi_{e^t},r,l^t_2)$ where $l_1^t=(l_1, g_{l_1})$ and $l_2^t=(l_2, g_{l_2})$ such that there exists an edge $e\in \edge$ with $e=(l_1,a,\varphi_e,\post_e,l_2)$ and for all $x \in \var$:
\begin{align}
        \label{varphi.t}
    \varphi_{e^t} & = \bigwedge_{x\in \var} \varphi_e(x) \text{ with  } \varphi_{e^t}(x) = \varphi(x)- g_{l_1}(x)    \\
    \label{g.t}
     g_{l_2}(x) & = 
        \begin{cases}
            \post(x) & \text{ if } \post(x)\neq \bot \land x\in r \\
            g_{l_1}(x) & \text{ if } \post(x)=\bot
        \end{cases} \\
        \label{r}
     x \in r & \iff \post_e(x)\neq \bot
\end{align}
\end{enumerate}
The  transition system of the constructed timed game $\game_T$ is denoted:
$$T(\game_T)=(Q(\game_T),\mvs{\game_T},q_0^t,\delta_T) $$

We define the relation 
$\gamma_2 \subseteq Q(\game_U) \times Q(\game_T)$ as follows: 
\begin{align*}
\gamma_2 = \{ ((l,v),(l^t,v^t)) \mid & (l,v) \in Q(\game_U),~l^t=(l,g_l) \text{ where }  g_l : X \to K_U   \\
& \text{ and for all } x\in\var~v^t(x)=v(x) - g_l(x) \}
\end{align*}
And its inverse $\gamma_2^{-1} \subseteq Q(\game_T) \times Q(\game_U)$,
\begin{align*}
\gamma_2^{-1}  =\{ \left( (l^t,v^t),(l,v)\right)  \mid & (l^t,v^t)=((l,g_l),v^t) \in Q(\game_T),  \\
 &\forall~x\in\var~ v(x)=v^t(x) + g_l(x) \}
\end{align*}
\subsection{Bisimulation between $T(\game_U)$ and $T(\game_T)$}
We now show that the mapping $\gamma_2$ defined above is an alternating bisimulation.
\begin{lemma}
\label{lemma.gamma2}
   $\gamma_2$ witnesses that $T(\game_U) \preceq_s T(\game_T)$.
\end{lemma}

\begin{proof}
Recall that $(l_0^t,v^t_0)=((l_0,g_{l_0}),v_0^t)$ is the initial configuration in $T(\game_T)$ and $(l_0,v_0)$ is the initial configuration in $T(\game_U)$, where $v_0=v_0^t$, hence $((l_0,v_0),(l_0^t,v_0^t))\in \gamma_2$ as required. 

Let $(l,v) \in Q(\game_U)$ and $(l^t,v^t)=((l,g_{l}),v^t) \in Q(\game_T)$ with $((l,v),(l^t,v^t))\in \gamma_2$.
Since the location $l$ is the same, the observation is preserved thus $\labeling(l,v) = \labeling(l^t,v^t)$, so the first point in Def.~\ref{def-bisim} holds.

We now show that $\gamma_2$ satisfies the 2nd point in Def.~\ref{def-bisim}. 
Let $(l,v) \in Q_1(\game_U)$, $m=(a,t) \in \mvs{\game_U}$ and $\delta_U((l,v),m)=(l',v')$.
We then apply the same move in $T(\game_T)$ and prove that $\delta_T((l^t,v^t),m)=({l^t}',{v^t}')$ is well defined, and $\left((l',v'),({l^t}',{v^t}')\right) \in \gamma_2$.

Note that $\delta_U((l,v),m)=(l',v')$ implies that there exists an edge $e=(l,a,\varphi_e,\post_e,l')$ in $\game_U$. We obtain by transformation of Sect.~\ref{updatabletotimed} the  
edge $e^t =((l,g_{l}), a, \varphi_{e^t}(\var),r,(l',g_{l'}))$ in $\game_T$. For all $x\in \var$ we have:
\begin{align*}
&v (x)+ t  \in \varphi_{e}(x)\\
&\implies v (x) + t - g_l (x)  \in \varphi_{e}(x) - g_l(x) \\
&\implies v(x) - g_l(x) +t \in \varphi_{e^t}(x) \text{ cf.~ the Identity \eqref{varphi.t}.}\\
&\implies v^t(x) +t  \in \varphi_{e^t}(x) \text{ because $((l,v),(l^t,v^t))\in \gamma_2$.}
\end{align*}
We obtain $\delta_T(((l,g_{l}),v^t),m)=((l',g_{l'}),{v^t}')$, where ${v^t}'= v^t + t [r:=0]$ is indeed well defined in $T(\game_T)$.
It remains to show that $\left((l',v'),\left((l',g_{l'}),{v^t}'\right)\right)$  are in $\gamma_2$. 
For each $x \in \var$, consider the case $x \notin r$:
%
        \begin{align*}
            {v^t}'(x) = v^t (x)+t  &= v(x) - g_{l}(x)+ t \\
            &= v(x) +t - g_{l'}(x) \text{ since, by construction, $g_{l}(x)=g_{l'}(x)$ for $x \notin r$.} \\
            &= v'(x)-g_{l'}(x) \text{ because $\post(x)=\bot$ cf. Identity~\eqref{r}}
                \end{align*}
 Now consider $x \in r$:       
                  \begin{align*}
%
           {v^t}'(x) = 0 &= \post_e(x) - g_{l'}(x) \text{ since, by construction,  $g_{l'}(x)= \post_e(x)$ for $x\in r$ }\\
            &= v'(x)- g_{l'}(x) \text{ since $\post_e(x)\neq \bot$.}
                \end{align*}
We conclude that $\left((l',v'),((l',g_{l'}),{v^t}')\right) \in \gamma_2$.

To show that $\gamma_2$ satisfies the third point in Def.~\ref{def-bisim}, let $(l,v) \in Q_2(\game_U)$, 
let $m=(a,t)\in \mvs{\game_T}$ and $\delta_T(((l,g_{l}),v^t),m)=((l',g_{l'}),{v^t}')$. We again apply the same move in $T(\game_U)$ and
prove, first, that $\delta_U((l,v),m)=(l',v')$ is well defined, and then that $\left((l',v'),((l',g_{l'}),{v^t}')\right) \in \gamma_2$.

Note that $\delta_T(((l,g_{l}),v^t),m)=((l',g_{l'}),{v^t}')$ implies that there exists an edge $e^t=((l,g_{l}),a,\varphi_{e^t},r,(l',g_{l'}))$ in $\game_T$. 
$e^t$ is constructed by the transformation in Subsection \ref{updatabletotimed} from the edge $e =(l, a, \varphi_{e},\post_e,l')$ in $\game_U$. For all $x\in \var$ we have:
\begin{align*}
&v^t(x)+ t  \in \varphi_{e^t}(x)\\
&\implies v(x) - g_l(x) + t \in \varphi_{e^t}(x) \text{ because $((l,v),(l^t,v^t))\in \gamma_2$.} \\
&\implies v(x) - g_l(x) + t \in \varphi_{e}(x)- g_l(x) \text{ cf. Identity \ref{varphi.t}.} \\
&\implies v(x) +t  \in \varphi_{e}(x) 
\end{align*}
Hence $\delta_U((l,v),m)=(l',v')$ with $v'(x)=\post_e(v+t)(x)$ for all $x\in \var$ is indeed well defined in $T(\game_U)$. 

Now we prove that $\left((l',v'),((l',g_{l'}),{v^t}')\right) \!\in \!\gamma_2$. For $x\!\in\! \var$ consider the case $x \notin r$:
\begin{align*}
          v'(x) - g_{l'}(x) &=  v(x) +t - g_{l'}(x) \text{ because $x \notin r$ implies $\post(x) = \bot$ by identity \ref{r}.} \\
                &=  v(x) +t - g_{l}(x) \text{ by identity \ref{g.t}, $\post(x) = \bot \implies g_l(x)=g_{l'}(x)$.}\\
                 &=  v(x)^t+t \text{ because $\left((l,v),((l,g_{l}),{v^t}\right) \in \gamma_2$.}\\
                  &={v^t}'(x)
\end{align*}
%
On the other hand, for the case $x \in r$:
\begin{align*}
 v'(x) - g_{l'}(x) &=  \post_e(x) - g_{l'}(x) 
 \text{ %because $x \in r \implies 
  because $\post(x) \neq \bot$.} \\
                &= 0 \text{ because $g_{l'}(x)=\post_e(x)$}\\
                &= {v^t}'(x) \text{ because $x\in r$.}
\end{align*}
This concludes the proof.\qed
%
\end{proof}
\begin{lemma}
 $\gamma_2^{-1}$  witnesses that $T(\game_T) \preceq_s T(\game_U)$.
\end{lemma}

\begin{proof}
Recall that $(l_0^t,v^t_0)=((l_0,g_{l_0}),v_0^t)$ is the initial configuration in $T(\game_T)$ and $(l_0,v_0)$ is the initial configuration in $T(\game_U)$, where $v_0^t=v_0$ because $g_{l_0}=0$, hence $((l_0^t,v_0^t),(l_0,v_0))\in \gamma_2^{-1}$ as required. 

Let $(l^t,v^t)=((l,g_{l}),v^t) \in Q(\game_T)$ and $(l,v) \in Q(\game_U)$ with $((l^t,v^t),(l,v))\in \gamma_2^{-1}$.
Since the location $l$ is the same, the observation is preserved thus $\labeling(l^t,v^t)=\labeling(l,v)$, therefore the first point in Def.~\ref{def-bisim} holds.

We now show that $\gamma_2^{-1}$ satisfies the second point in Def.~\ref{def-bisim}. Let $(l^t,v^t) \in Q_1(\game_T)$, a configuration of $\playerone$,
let $m=(a,t)\in \mvs{\game_T}$ and $\delta_T(((l,g_{l}),v^t),m)=((l',g_{l'}),{v^t}')$. By applying the same move in $T(\game_U)$, we prove in the first place $\delta_U((l,v),m)=(l',v')$ is well defined, and later on we prove $\left(((l',g_{l'}),{v^t}'),(l',v')\right) \in \gamma_2^{-1}$.

Note that $\delta_T(((l,g_{l}),v^t),m)=((l',g_{l'}),{v^t}')$ implies that there exists an edge $e^t=((l,g_{l}),a,\varphi_{e^t},r,(l',g_{l'}))$ in $\game_T$. $e^t$ is constructed by the transformation of the Sect. \ref{updatabletotimed} from the edge $e =(l, a, \varphi_{e},\post_e,l')$ in $\game_U$. For all $x\in \var$ we have:
\begin{align*}
& v(x)+ t  \in \varphi_{e}(x)\\
&\implies v^t(x) + g_l(x) + t \in \varphi_{e}(x) \text{ because $\left(\left(l^t,v^t\right),(l,v)\right)\in \gamma_2^{-1}$.} \\
&\implies {v^t}'(x) + g_l(x) \in \varphi_{e}(x) \\
&\implies {v^t}'(x) \in \varphi_{e}(x) - g_l(x)  \\
&\implies {v^t}'(x)  \in \varphi_{e^t}(x) \text{ cf.~ Identity \eqref{varphi.t}.}
\end{align*}

Hence $\delta_U((l,v),m)=(l',v')$ with $v'(x)=\post_e(v+t)(x)$ for all $x\in \var$ is well defined in $T(\game_U)$. 

To prove that $\left(\left((l',g_{l'}),{v^t}'\right),(l',v')\right) \in \gamma_2^{-1}$, for $x\in \var$ with $x \notin r$ we have:
\begin{align*}
          {v^t}'(x) + g_{l'}(x) &=  {v^t}'(x) + g_{l}(x)  \intertext{ since $x\notin r$ implies $\post(x) = \bot$ by Identity \eqref{r}, hence $g_l(x)=g_{l'}(x)$.}
         & =  v^t(x) +t + g_{l}(x)  =  v(x)+t \text{ because $\left(((l,g_{l}),{v^t}),(l',v')\right) \in \gamma_2^{-1}$.}\\
          &=v'(x)      
\end{align*}
Now consider the case $x \in r$:
\begin{align*}
          {v^t}'(x) + g_{l'}(x) &=  g_{l'}(x)  \text{ because for all $x\in r,~{v^t}'(x)=0$}\\
          &=  \post_e(x) \text{ cf.~ transformation of Sect.~\ref{updatabletotimed}.} \\ 
          &=v'(x) \text{ because $\post_e(x) \neq \bot$ by Identity \eqref{r}.}     
\end{align*}
%
We conclude that $\left(\left((l',g_{l'}),{v^t}'\right),(l',v')\right) \in \gamma_2^{-1}$.
%

We now show that $\gamma_2^{-1}$ satisfies the third point in Def.~\ref{def-bisim}. 
Let $\left((l,g_{l}),v^t\right) \in Q_2(\game_T)$, a configuration of \playertwo, let $m=(a,t)\in \mvs{T(\game_U)}$ and $\delta_U((l,v),m)=(l',v')$. 
Again we take the same move $m$ in $\mvs{T(\game_T)}$ and show that $\delta_T(((l,g_{l}),v^t),m)=((l',g_{l'}),{v^t}')$ is well defined and that $\left(\left((l',g_{l'}),{v^t}'\right),(l',v')\right) \in \gamma_2^{-1}$.

Note that $\delta_U((l,v),m)=(l',v')$ implies the edge $e=(l,a,\varphi_e,\post_e,l')$ must exist in $\game_U$. We obtain by transformation \ref{updatabletotimed} the 
%
edge $e^t =((l,g_{l}), a, \varphi_{e^t}(\var),r,(l',g_{l'}))$ in $\game_T$. For all $x\in \var$ we have:
\begin{align*}
v (x)+ t  \in \varphi_{e}(x)
&\implies v^t (x) + t + g_l (x)  \in \varphi_{e}(x) \text{ because $((l^t,v^t),(l,v))\in \gamma_2^{-1}$.} \\
&\implies v^t(x) +t \in \varphi_{e}(x) - g_l(x)\\ 
&\implies v^t(x) +t  \in \varphi_{e^t}(x) \text{ cf.~ Identity \eqref{varphi.t}.}
\end{align*}
We obtain $\delta_T(((l,g_{l}),v^t),m)=((l',g_{l'}),{v^t}')$, where ${v^t}'= v^t + t [r:=0]$ is indeed well defined in $T(\game_T)$.
Let's show that $\left(\left((l',g_{l'}),{v^t}'\right),(l',v')\right) \in \gamma_2$. For all $x \in \var$, consider the case $x \notin r$:
\begin{align*}
        v'(x)&=v(x)+t \text{ because $x \notin r \implies \post_e(x)\neq\bot$ }  \\
        &= v^t(x)+g_l(x)+t \text{ because $((l^t,v^t),(l,v))\in \gamma_2^{-1}$.}\\
        &={v^t}'(x)+g_l(x) \text{ because $x \notin r$.} \\
        &={v^t}'(x)+g_{l'}(x) \text{ by the construction of Sect.~\ref{updatabletotimed} $g_{l}(x)=g_{l'}(x)$ for $x \notin r$.} 
        \end{align*}
 Now consider $x \in r$:       
                  \begin{align*}
          v'(x)= \post_e(x)&= g_{l'}(x) \text{ since, by construction, $g_{l'}(x)= \post_e(x)$ for $x\in r$ }\\
            &= {v^t}'(x)+ g_{l'}(x) \text{ because ${v^t}'(x)=0$ for $x \in r$.}
                \end{align*}

%
This concludes the proof. 
\qed\end{proof}
%
\section{Conclusion}
We have shown that each initialized singular game is bisimilar with a timed game.
We recall the different constructions in the figure below.
The  decidability of the synthesis problem for LTL specifications and initialized singular games can then be seen as a corollary of this result.
