% \begin{equation}\label{eq:coreset-size-lp}
% \textnormal{nnz}(\bm{S}) = \begin{cases}
% \frac{k}{\varepsilon^{4/p+2}}(\log(k/\varepsilon \delta))^{O(1)} \qquad \text{ if $p \in [1, 2)$}, \\
% \frac{k^{p/2}}{\varepsilon^{p^2/2+p}}(\log(k/\varepsilon \delta))^{O(p)} \qquad \text{ if $p \in (2, \infty)$}.
