\begin{definition}[\SPExp: Typing Judgment and  Typing Rules]
  The judgment $\Gamma\SPExpJud P$ describes a well-typed process under the typing environment~$\Gamma$. The typing rules for $\SPExp$ are shown in \Cref{fig:typ_rules}.
We shall write  $P \in \SPExp$ if $\Gamma\SPExpJud P$, for some $\Gamma$.
\end{definition}


We now state the properties of well-typed $\SPExp$ processes, whose proofs follow~\cite{vasco_sess_typ}: 
\begin{theorem}[\SPExp: Preservation~\cite{vasco_sess_typ}]\label{theorem: preservation equivalence SP}
\label{theorem: preservation reduction SP}
Suppose $\Gamma\SPExpJud P$. 
    If $P\equiv Q$ then $\Gamma\SPExpJud Q$.
Also, if $P\ReductionSP Q$ then $\Gamma\SPExpJud Q$.
\end{theorem}

We will be interested in \emph{well-formed processes}, defined using two auxiliary notions.
First, we 
say that $P$ is \emph{prefixed at $x$}, written $\mathtt{Pr}(P)=x$, if $P$ has one of the following forms:  $\EmptyInputSP{x}P'$, $\EmptyOutputSP{x}P$, $\InputSP{x}{z}P'$, or $\OutputSP{x}{v}P'$.
Second, we say a process $\news{x}{y}(P\para Q)$ is a \emph{redex} if:
    \textup{(1)}~$P=\EmptyInputSP{x}P'$ and $Q=\EmptyOutputSP{y}Q'$, or 
    \textup{(2)}~$P=\InputSP{x}{z}P'$ and $Q=\OutputSP{y}{v}Q'$.
We may now define:

\begin{definition}[\SPExp: Well-formedness]
 A process is well-formed if for each of its structural congruent processes of the form 
 $\news{x_1}{y_1}\dots\news{x_n}{y_n}(P_1\para \cdots \para P_m)$ where  $\mathtt{Pr}(P_i)=x_k$ and $\mathtt{Pr}(P_j)=y_k$, then $\news{x_k}{y_k}(P_i\para P_j)$ is a redex.
\end{definition}
\begin{theorem}[Safety~\cite{vasco_sess_typ}]\label{theorem: Typable processes are not ill-formed}
    Typable processes are well-formed.
\end{theorem}

As a consequence of \Cref{theorem: preservation reduction SP,theorem: Typable processes are not ill-formed} we obtain the main guarantee of $\SPExp$: \emph{typable  processes only reduce to  well-formed processes}.
\begin{corollary}[\cite{vasco_sess_typ}]\label{corollary: wellformedness SP}
    If $\Gamma\SPExpJud P$ and $P\ReductionSP^* Q$, then $Q$ is well-formed.
\end{corollary}


Even though typability ensures well-formedness,
which excludes error processes such as
 $\news{x}{y}(\OutputSP{x}{v}P\para \EmptyInputSP{y}Q)$ and $\news{x}{y}(\EmptyInputSP{x}P\para \EmptyInputSP{y}Q)$,
 typability in \SPExp also admits well-typed process that exhibit unwanted behaviors, in particular deadlocks. 
Before illustrating this fact, we give the first definition of deadlock freedom that we will encounter, which follows~\cite{ComparingDeadlock}. 
We write $\new{\widetilde{xy}}Q$ to stand for $\news{x_1}{y_1}\cdots\news{x_n}{y_n}Q$, for some $n\geq 0$.

\begin{definition}[$\SPExp$: Deadlock Freedom]\label{def: deadlock freedom in SP}
    A process $P\in \SPExp$ is deadlock free, written $\DeadlockFreedomSP{P}$, if the following  condition holds: whenever $P\ReductionSP^* P'$ and one of the following holds:
        \textup{(1)}~$P'\equiv \new{\widetilde{xy}}(\OutputSP{x_i}{v}Q_1\para Q_2)$,
     \textup{(2)}~$P'\equiv \new{\widetilde{xy}}(\InputSP{x_i}{z}Q_1\para Q_2)$,
        \textup{(3)}~$P'\equiv \new{\widetilde{xy}}(\EmptyInputSP{x_i}Q_1\para Q_2)$, or
        \textup{(4)}~$P'\equiv \new{\widetilde{xy}}(\EmptyOutputSP{x_i}Q_1\para Q_2)$   
    (with $x_i \in \widetilde{x}$ in all cases), 
    then $P'\ReductionSP R$, for some $R$.
\end{definition}

Hence, $\DeadlockFreedomSP{P}$ is read as `$P$ is deadlock-free in \SPExp'.
Later on, we will encounter analogous notations for \HCP and \Padovani; they will be denoted $\DeadlockFreedomHCP{P}$ and $\DeadlockFreedomPado{P}$, respectively. 
\begin{example}[\SPExp: A Typable but Deadlocked Process]\label{example: type derivation} 
Consider the  process $P_{\ref{example: type derivation}}$ defined as \[P_{\ref{example: type derivation}} \DefEq\news{x_1}{y_1}\news{x_2}{y_2}\news{v_1}{k_1}\news{v_2}{k_2}(\InputSP{x_1}{z_1}\InputSP{x_2}{z_2}C_1\para  \OutputSP{y_2}{v_2}\OutputSP{y_1}{v_1}C_2)\]
where 
$C_1\DefEq\EmptyInputSP{x_1}\EmptyInputSP{x_2}\EmptyInputSP{z_1}\EmptyInputSP{z_2}\Inact$ and $C_2\DefEq\EmptyOutputSP{y_1}\EmptyOutputSP{y_2}\EmptyOutputSP{k_1}\EmptyOutputSP{k_2}\Inact$. 
Similar to   $P_2$ (\Cref{sec: introduction}), the structure of actions in process $P_{\ref{example: type derivation}}$ induces a circular dependency that prevents synchronizations: we have that $\neg\DeadlockFreedomSP{P_{\ref{example: type derivation}}}$
and yet $P_{\ref{example: type derivation}}$ is well-typed with the empty environment.
\end{example}


\subsection{\texorpdfstring{$\CP$}{CP} and \texorpdfstring{$\HCP$}{HCP}}\label{sec: CP and HCP}


The languages $\CP$ and $\HCP$ use the same syntax. Here we consider $\HCP$ as presented by Kokke \etal ~\cite{betterlate} (other variants have been studied in, e.g.,~\cite{separating}).
Assuming an infinite set of \emph{names} ($x, y, z,\dots$), the set of \emph{processes} ($P, Q,\dots$) in $\CP$ and $\HCP$ is defined as follows:
\begin{align*}
    P,Q::= \Inact& \mybar  (\nu xy)P \mybar  P\para Q \mybar  \forward{x}{y} \Sep  \boutHCP{y}{x}P \Sep \InputHCP{x}{y}P \Sep \EmptyOutputHCP{x}P\Sep \EmptyInputHCP{x}P    
\end{align*}
\noindent  
Most constructs are similar to those in 
$\SPExp$;  differences are 
the forwarder process $\forward{x}{y}$, which equates $x$ and $y$, and process  
$\boutHCP{y}{x}P$, 
which denotes the output of the private name $y$ along $x$, with continuation 
$P$.
Also, the empty output is now denoted $\EmptyOutputHCP{x}P$.
In $\boutHCP{y}{x}P$ 
and $\InputHCP{x}{y}P$, the name $y$ is bound in $P$. 
We write $P\subst{x}{y}$ to denote the capture-avoiding substitution of $y$ for $x$ in $P$.
$\FreeNamesHCP{P}$ denotes the free names of $P$. We use $\pi$ to range over  prefixes: $\boutHCPLabel{y}{x},\InputHCPLabel{x}{y},\EmptyInputHCPLabel{x}$, $\EmptyOutputHCPLabel{x}$.



The types assigned to names correspond to  formulas of classical linear logic~(\CLL):
\[A,B::= \unit \Sep  \bot \Sep  A\Tensor B \Sep  A\InputTypeHCP B\]
%
The assignment $x:A$ says that $x$ follows the input/output interactions described by~$A$.
Assignments $x: A\Tensor B$ and $x:A\InputTypeHCP B$ are read as sending and receiving an object of type $A$ along $x$, with continuation $B$, respectively.
There is a duality in the interpretation of the following pairs: $\Tensor$ and $\InputTypeHCP$; $\unit$ and $\bot$.  
 Formally, the dual type of $A$, denoted $\Dual{A}$, is defined as
%
\[\Dual{\unit}\DefEq  \bot
\qquad
\Dual{\bot} \DefEq \unit
\qquad
\Dual{(A\Tensor B)} \DefEq \Dual{A} \InputTypeHCP\Dual{B}
\qquad\Dual{(A\InputTypeHCP B)} \DefEq \Dual{A} \Tensor \Dual{B}\]
Let $\Gamma,\Delta$ range over \emph{environments}, unordered collections of assignments. 
Given an environment $\Delta=x_1:A_1,\dots,x_n:A_n$, its domain,  written $dom(\Delta)$, is the set $\{x_1,\dots,x_n\}$.
\begin{definition}[$\CP$]\label{def: CP}
Typing judgements for $\CP$  
are of the form $P\CPJud \Gamma$, with typing rules  as given in \Cref{fig:CP Rules}.
     We shall write  $P \in \CP$ if $P\CPJud \Gamma$, for some $\Gamma$.
\end{definition}

