We now recall some useful notions and results from~\cite{betterlate}.
\begin{definition}[$\HCP$: Weak LTS and Bisimilarity~\cite{betterlate}]\label{def: weak transition HCP}
\label{def: bisimilarity HCP}
    $\WeakTransitionHCP{l}$ is the smallest relation such that:
     \textup{(1)}~$P\WeakTransitionHCP{\tau} P$ for all $P$; 
    \textup{(2)}~and if $P\WeakTransitionHCP{\tau} P'$, $P'\TransitionHCP{l}Q'$, and $Q'\WeakTransitionHCP{\tau} Q$, then $P\WeakTransitionHCP{l}Q$.
\noindent
A symmetric relation $\mathcal{R}$   is a bisimulation if $P \mathrel{\mathcal{R}} Q$ implies that if $P\WeakTransitionHCP{l}P'$ then $Q\WeakTransitionHCP{l}Q'$ for some $Q'$ such that $P' \mathrel{\mathcal{R}} Q'$. Bisimilarity is the largest relation $\BisimilarityHCP$ that is a bisimulation.
   \end{definition}



Well-typed processes satisfy readiness, defined as follows:
\begin{theorem}[$\HCP$: Readiness~\cite{betterlate}]\label{theorem: readiness HCP}
    Let $P\HCPJud \Gamma_1\SequentPara \cdots \SequentPara \Gamma_n$. For every $i \in[1,n]$, there exist $x\in dom(\Gamma_i)$, $l_x$, and $P'$ such that $P\WeakTransitionHCP{l_x}P'$. 
\end{theorem} 

In $\HCP$, transitions associated to sessions in different partitions can be fired in parallel:


\begin{lemma}[\cite{betterlate}]\label{lemma: parallel transitions}
    If $P\HCPJud \HypG\parallel \Gamma,x:A\parallel \Delta,y:B$, $P\WeakTransitionHCP{l_x}P'$, and $P\WeakTransitionHCP{l_y}P''$, then there exists $Q$ s.t.  $P\WeakTransitionHCP{l_x\para l_y}Q$ (up to $\alpha$-renaming). 
\end{lemma}


\begin{definition}[\HCP: Structural Congruence]\label{ldef: zero equive}  
Let $\EquivHCP$ be the smallest congruence relation generated by the axioms: 
        \begin{align*}
P \para Q\ &\EquivHCP\ Q \para P                     &  \quad P \para \Inact\ &\EquivHCP\ P\\
  P \para (Q \para R)\ &\EquivHCP\ (P \para Q) \para R     &    \news x y P &\EquivHCP \news y x P \\
  \news x yP \para Q\ &\EquivHCP \ \news x y(P \para Q) \ \  \text{if $x, y \notin \FreeNamesHCP{Q}$} & \news x y\news w z P\ &\EquivHCP\ \news w z\news x yP
\end{align*}
\end{definition}


Because of Readiness (\Cref{theorem: readiness HCP}), $\HCP$ also satisfies \emph{progress}:
\begin{corollary}[$\HCP$: Progress~\cite{betterlate}]\label{corollary:progress}
    If $P \in \HCP$ and $P\not\EquivHCP\Inact$, then $P\TransitionHCP{l}P'$ for some $l$, $P'$.
\end{corollary}

In order to relate with reduction-based semantics (in \SPExp), we define the following:
\begin{definition}[\HCP: Reduction]
\label{hcp:reduction}
    We write $\TransitionHCPClo$ for the reflexive, transitive closure of $\TransitionHCP{\tau}$. 
\end{definition}


\begin{lemmaapxrep}\label{lemma: deadlock freedom HCP}
 Let $P\in$ $\HCP$   s.t. $P\HCPJud\cdot~$, then exists $P'$ s.t. $P\TransitionHCP{\empty}^*P'\EquivHCP\Inact$.
\end{lemmaapxrep}
\begin{proof}
	Note that the judgement $P
	\HCPJud\cdot$ can only be obtained via  Rules $\Hname$\MixZero and $\Hname$\textsc{Cut}. In the former case $P \EquivHCP \Inact$ and there is nothing to prove. 
	In the latter case, we split the proof in two parts: (i) we prove that there exists an $R$ such that $P\TransitionHCP{\tau}R$, with the transition involving a cut on session $xy$, therefore specializing \Cref{corollary:progress} (which ensures the existence of some transition, not necessarily a $\tau$-transition); (ii) we prove that there exist $k \geq 0$ and $Q$ s.t. $R\longrightarrow^k Q$ and there are no cuts on $xy$ in $Q$.

	    For part (i), we have $P\HCPJud\cdot~$ and $P\not\EquivHCP\Inact$; we proceed by induction on the number $n$ of parallel components of $P$.
    \begin{itemize}
        \item \emph{Base case ($n = 1$)}.        
    In this case, the last rule applied is $\Hname$\textsc{Cut}:
	\begin{prooftree}
		\AxiomC{$P'\HCPJud x:A\SequentPara y: \LinearDual{A}$}
		\UnaryInfC{$\news{x}{y}P'\HCPJud \cdot$}
	\end{prooftree}
	 By \Cref{theorem: readiness HCP},  there exist labels $l_x,l_y$ and processes $Q_1,Q_2$ s.t. $P'\WeakTransitionHCP{l_x}Q_1$ and $P'\WeakTransitionHCP{l_y}Q_2$.  \Cref{lemma: parallel transitions} ensures that there exists $Q$ s.t. $P'\WeakTransitionHCP{l_x\para l_y}Q$. Hence, by \Cref{def: bisimilarity HCP}, there exist processes $P''$ and $Q'$ s.t.
     $P'\WeakTransitionHCP{\tau}P''\TransitionHCP{l_x\para l_y}Q'\WeakTransitionHCP{\tau}Q$.
     To show the existence of $R$, we consider two possibilities.
     First, if the first sequence of $\tau$ transitions is not empty, then we must have
     $P' \TransitionHCP{\tau}R\TransitionHCPClo P''\TransitionHCP{l_x\para l_y}Q' \TransitionHCPClo Q$, and $P\TransitionHCP{\tau}R$. 
     Second, if 
  $P''=P'$ then we have  $P' \TransitionHCP{l_x\para l_y}Q' \TransitionHCPClo Q$, and $R$ results from a synchronization on $xy$, as follows.   
  By typability of $P'$, the actions $l_x$ and $l_y$ are dual, thus $\news{x}{y}P'$ has a $\tau$-transition due to  either Rule $\bot\unit$ or $\OutputTypeHCP\InputTypeHCP$, depending on the type $A$. Hence, $R = \news{x}{y}Q'$. So far we have proven that a well-typed closed process always can execute a $\tau$-transition. As a consequence of \emph{subject reduction} (cf. \cite[Theorem 3.9]{betterlate}), we also have $R \HCPJud\cdot~$.

  \item \emph{Inductive step ($n>1$)}. In this case, the last rule applied is $\Hname$\MixTwo. Hence,  $P=P_1\para P_2$:
  \begin{prooftree}
      \AxiomC{$P_1\HCPJud\HypG$}
      \AxiomC{$P_2\HCPJud\HypH$}
      \BinaryInfC{$P_1\para P_2\HCPJud\HypG\parallel\HypH$}
  \end{prooftree}
Clearly, $P_1$ and $P_2$ have less than $n$ parallel components, and the result follows by IH.
   \end{itemize}
We now proceed to prove part (ii); we require an auxiliary definition:
    \begin{definition}[Degree]
    The degree of a type $A$ is inductively defined by:
    \begin{itemize}
        \item $\DegreeType{\unit}\DefEq\DegreeType{\bot}\DefEq1$.
        \item  $\DegreeType{ A\OutputTypeHCP B}\DefEq\DegreeType{ A\InputTypeHCP B}\DefEq
        \max(\DegreeType{A},\DegreeType{B})+1$.
    \end{itemize}
        The degree of an $\Hname$\textsc{Cut} on the session $xy$ is defined to be the degree of the type which it eliminates (from the judgement). The degree of an $\Hname$\textsc{Cut} on a session $xy$ that does not occur in the process is 0. 
    \end{definition}
    This way, we prove:
given $R\HCPJud\cdot$ with a $\Hname$\textsc{Cut} of degree $d>0$ along the session $xy$, then there exist $k\geq 0$ and $Q$ s.t. $R\longrightarrow^k Q$, $Q\HCPJud\cdot$ and  the degree of the $\Hname$\textsc{Cut} along $xy$ is 0.
 We proceed by induction on the number $n$ of parallel components of $P$.
\begin{itemize}
    \item \emph{Base case $(n=1)$},
 The last rule applied must be $\Hname$\textsc{Cut}.
We proceed by induction on the degree of the type $A$ involved in the cut $xy$.
  \begin{itemize}
      \item Base case ($\DegreeType{A}= 1$). We must then have:
      \begin{prooftree}
		\AxiomC{$R'\HCPJud x:\unit\SequentPara y: \bot$}
		\UnaryInfC{$\news{x}{y}R'\HCPJud \cdot$}
	\end{prooftree}
     By the analysis in the first part,  there exist $R'',Q'$ s.t. 
 $R'\WeakTransitionHCP{\tau}R''\TransitionHCP{l_x\para l_y}Q'$. Since the first chain of $k'$ $\tau$-transitions does not occur along session $xy$, its degree remains unchanged. We have $\news{x}{y}R'\WeakTransitionHCP{\tau} \news{x}{y}R''\TransitionHCP{\tau}Q'$ and $Q'\HCPJud\cdot$, where the degree of $\Hname$\textsc{Cut} along $xy$ is 0, thus $Q=Q'$ and $k=k'+1$.

    \item Inductive step ($\DegreeType{A}>1$). We must then have:
    \begin{prooftree}
		\AxiomC{$R'\HCPJud x:A\OutputTypeHCP B\SequentPara y: \Dual{A}\InputTypeHCP \Dual{B}$}
		\UnaryInfC{$\news{x}{y}R'\HCPJud \cdot$}
	\end{prooftree}
	 Thus, the degree of $\Hname$\textsc{Cut} along $xy$ is $\DegreeType{ A\OutputTypeHCP B}=
        \max(\DegreeType{A},\DegreeType{B})+1>0$. By the analysis in the first part,   there exist $R'',Q'$ s.t. 
 $R'\WeakTransitionHCP{\tau}R''\TransitionHCP{l_x\para l_y}Q'$. Since the first chain of $k'$ $\tau$-transitions does not occur along session $xy$, its degree remains unchanged and we have:
 \begin{prooftree}
		\AxiomC{$R''\HCPJud x:A\OutputTypeHCP B\SequentPara y: \Dual{A}\InputTypeHCP \Dual{B}$}
		\UnaryInfC{$\news{x}{y}R''\HCPJud \cdot$}
	\end{prooftree}
    By Rule $\Hname\OutputTypeHCP\InputTypeHCP$ we have $\news{x}{y}R''\TransitionHCP{\tau}\news{x}{y}\news{x'}{y'}R^*$, typed as follows:
     \begin{prooftree}
		\AxiomC{$R^*\HCPJud x:A\SequentPara x':B\SequentPara y: \Dual{A},y': \Dual{B}$}
		\UnaryInfC{$\news{x'}{y'}R^*\HCPJud  x:A\SequentPara y: \Dual{A}$}
        \UnaryInfC{$\news{x}{y}\news{x'}{y'}R^*\HCPJud \cdot$}
	\end{prooftree}
    where the degree of $\Hname$\textsc{Cut} along $xy$ is $\DegreeType{A}<\DegreeType{ A\OutputTypeHCP B}$. By IH, there exist $k''$ and $Q$ s.t. $\news{x}{y}R''\longrightarrow^{k+m+1}Q$, whose degree of $\Hname$\textsc{Cut} on $xy$ is 0, thus $k=k'+k'+1$.
  \end{itemize}
 \item \emph{Inductive step ($n>1$)}. In this case, the last rule applied is $\Hname$\MixTwo. We have $P=P_1\para P_2$ and:
  \begin{prooftree}
      \AxiomC{$P_1\HCPJud\HypG$}
      \AxiomC{$P_2\HCPJud\HypH$}
      \BinaryInfC{$P_1\para P_2\HCPJud\HypG\parallel\HypH$}
  \end{prooftree}
Clearly, $P_1$ and $P_2$ have less than $k$ parallel components, thus the result follows by IH.
  \end{itemize}

  By the repeated application of part~(ii) for all the instances of Rule $\Hname$\textsc{Cut}, we finally find a process with no instances of Rule $\Hname$\textsc{Cut}. This concludes the proof, since a type derivation for a well-typed closed process $R$ with no instances of Rule $\Hname$\textsc{Cut} 
  must necessarily be $R\EquivHCP\Inact$.
\end{proof}



Inspired by \Cref{lemma: deadlock freedom HCP} we have the following definition of deadlock freedom  for \HCP.
 \begin{definition}[$\HCP$: Deadlock Freedom]\label{def: deadlock freedom delayed}
     Let $P\in\HCP$. We say that $P$ is deadlock free, written $\DeadlockFreedomHCP{P}$, iff there exists $P'$ s.t. $P\TransitionHCPast P'\EquivHCP \Inact$. 
 \end{definition}


$\HCP$ has a \emph{denotational semantics} that interprets well-typed processes as sets of possible interactions on  their free names. 
Given a process $P$, its set of denotations is written $\HCPDenotations{P}$. 

\begin{toappendix}
Below, we write $\FinitePowerSet{S}$ to denote the finite powerset of the set $S$.
\begin{definition}[$\HCP$: Denotations of Types~\cite{betterlate}] We define:
\label{d:denot}
\begin{align*}
    \HCPDenotations{\unit}&=\{\triangleleft\}\times \mathbb{N}\times \{*\} & 
     \HCPDenotations{A\OutputTypeHCP B}&=\{\triangleleft\}\times \mathbb{N}\times(\FinitePowerSet{ \mathbb{N}}\times \HCPDenotations{A}\times\FinitePowerSet{ \mathbb{N}}\times \HCPDenotations{B})
    \\
       \HCPDenotations{\bot}&=\{\triangleright\}\times \mathbb{N}\times \{*\}
 & \HCPDenotations{A\InputTypeHCP B}&=\{\triangleright\}\times \mathbb{N}\times (\HCPDenotations{A}\times \HCPDenotations{B})
\end{align*}
We write $a \DualDenotations b$ whenever $a\in\HCPDenotations{A}$ and $b\in\HCPDenotations{A^\bot}$.
\end{definition}


Natural numbers act as identifiers that describe dependencies with other channels. 
Note that `$\triangleleft$' and `$\triangleright$' are associated to output- and input-like behaviors, respectively; in particular, this entails that 
$\unit$ and $\bot$, which both capture the closing of a session, have different denotations.
The denotation of a process $P$ is written $\HCPDenotations{P}$; the definition  relies on a notion of \emph{antiderivatives} for sets of denotations. Intuitively, given an action label $l$ and a set of denotations $D$, $\int_{l}D$ returns a set of denotations $D'$ such that for some transformation $T_l$ on denotations, if $g\in D$, then $T_l(g)\in D'$. For instance:
$ \int_{\EmptyOutputHCPLabel{x}} D\DefEq\{g\cdot\SingleDenotation{\SingleDenotation{\MapstoDenotation{x}{(\triangleleft,n,*)}}}\Sep g\in D\}$.
\Cref{def: antiderivatives} gives 
a detailed definition.



\begin{definition}[$\HCP$: Antiderivates~\cite{betterlate}]\label{def: antiderivatives}
For $D$ a set of denotations, the antiderivate $\int_l D$ of $D$ wrt an action label $l$ is the set defined by: 
    \begin{align*}
        \int_{\EmptyOutputHCPLabel{x}} D&\DefEq\{g\cdot\SingleDenotation{\SingleDenotation{\MapstoDenotation{x}{(\triangleleft,n,*)}}}\Sep g\in D\}\\
        \int_{\EmptyInputHCPLabel{x}} D&\DefEq\{g\cdot\SingleDenotation{\gamma\cdot\SingleDenotation{\MapstoDenotation{x}{(\triangleright,n,*)}}}\Sep g\cdot\SingleDenotation{\gamma}\in D\}\\
         \int_{\boutHCPLabel{y}{x}} D&\DefEq
         \{g\cdot\SingleDenotation{\gamma\cdot\delta\cdot\SingleDenotation{\MapstoDenotation{x}{(\triangleleft,n,ids(\gamma),a,ids(\delta),b)}}}\Sep g\cdot\SingleDenotation{\gamma\cdot\SingleDenotation{\MapstoDenotation{x}{b}},\delta\cdot\SingleDenotation{\MapstoDenotation{y}{a}}}\in D\}\\
         \int_{\InputHCPLabel{x}{y}} D&\DefEq\{g\cdot\SingleDenotation{\gamma\cdot\SingleDenotation{\MapstoDenotation{x}{(\triangleright,n,a,b)}}} \Sep g\cdot\SingleDenotation{\gamma\cdot\SingleDenotation{\MapstoDenotation{x}{b},\MapstoDenotation{y}{a}}} \in D\\
         \int_{\forwardHCPLabel{x}{y}} D&\DefEq\{g\cdot\SingleDenotation{\SingleDenotation{\MapstoDenotation{x}{a},\MapstoDenotation{y}{a^\bot}}}\Sep g\in D\}\\
         \int_{\tau} D&\DefEq D
    \end{align*}
\end{definition}


\begin{definition}[$\HCP$: Denotational Equivalence~\cite{betterlate}]\label{def: denoations in HCP}
\label{def: denotatinal equivalence}
Let $\pi$ be a prefix. Denotations of processes are defined as follows:
\begin{align*}
\HCPDenotations{\Inact}&\DefEq\{\SingleDenotation{\empty}\}\qquad 
\HCPDenotations{\pi.P} \DefEq\int_\pi\HCPDenotations{P}\qquad 
\HCPDenotations{P\para Q} \DefEq\HCPDenotations{P}\times\HCPDenotations{Q}\\ 
\HCPDenotations{\forwardHCP{x}{y}} &\DefEq \{\SingleDenotation{\MapstoDenotation{x}{a},\MapstoDenotation{y}{a'}}\Sep a \DualDenotations a' \}\\  \HCPDenotations{\news{x}{y}P}&\DefEq \{g \cdot \SingleDenotation{\gamma\cdot \delta} \Sep g\cdot \SingleDenotation{\gamma\cdot \SingleDenotation{\MapstoDenotation{x}{a}},\delta\cdot\SingleDenotation{\MapstoDenotation{y}{a'}}}\in \HCPDenotations{P} \text{ and } a\DualDenotations a' \}
\end{align*}

Denotational equivalence is the relation on typed processes defined as: $P\ObservationalEq Q$ iff $\HCPDenotations{P}=\HCPDenotations{Q}$.
\end{definition}
\begin{example}[Denotations at work]\label{example: denotations}
Consider the processes $P_{\ref{example: denotations},1}\DefEq \EmptyOutputHCP{x}P$ and 
$P_{\ref{example: denotations},2}\DefEq \EmptyOutputHCP{x}\Inact \para P$, for some process
$P$ s.t. $P\HCPJud \HypH$. The following holds: $P_{\ref{example: denotations},1}\HCPJud \HypH\parallel x:\unit$ and  $P_{\ref{example: denotations},2}\HCPJud \HypH\parallel x:\unit$. Thus we have
\begin{align*}
    \HCPDenotations{P_{\ref{example: denotations},1}}= 
    \int_{\EmptyOutputHCPLabel{x}}\HCPDenotations{P}&=
    \{g\cdot\SingleDenotation{\SingleDenotation{\MapstoDenotation{x}{(\triangleleft,n,*)}}}\Sep g\in \HCPDenotations{P}\}\\
    &=
    \{\SingleDenotation{\SingleDenotation{\MapstoDenotation{x}{(\triangleleft,n,*)}}}\}\times\HCPDenotations{P} 
    =\HCPDenotations{\EmptyOutputHCP{x}\Inact \para P}
     =\HCPDenotations{P_{\ref{example: denotations},2}}
\end{align*}
Hence, $P_{\ref{example: denotations},1}\ObservationalEq P_{\ref{example: denotations},2}$.
\end{example}
    \end{toappendix}

We notice that  $\EquivHCP$ is sound wrt $\ObservationalEq$ and that  our results are reflected by bisimilarity, as ensured by the following result:

\begin{theorem}[$\HCP$: Full Abstraction \cite{betterlate}]\label{theorem: full abstraction}
    For well-typed processes: $\BisimilarityHCP\,\mathrel{=}\,\ObservationalEq$.
\end{theorem}

\section{The Role of Delayed Actions and Self-Synchronizations in DF}\label{sec: results}


We have seen that 
\SPExp defines a flexible typing discipline that admits  deadlocked and deadlock-free processes. Also, we saw the way in which \CP and \HCP enforce DF by typing, and that the latter's LTS allows for delayed actions and self-synchronizations. 
By defining two classes of \SPExp processes, $\ClassL$ and $\ClassH$, which capture typability   as in \CP and \HCP, respectively (\Cref{Def: ClassL and ClassH}), we study 
whether delayed actions and self-synchronizations influence DF. 

We will proceed as follows. 
As we have seen, $\DeadlockFreedomHCP{P}$ means that $P$ is deadlock free by considering all sources of behavior,  including delayed actions and self-synchronizations; we shall also define $\DeadlockFreedomHCPRR{P}$ to mean that $P$ is deadlock free by considering \emph{regular transitions only}. 
Our main result is \cref{corollary: main corollary HCP}, which ensures: 
    \textup{(1)}~Delayed actions and Self-synchronizations are \emph{inessential} when it comes to DF, and
    \textup{(2)}~given an encoding $\SPExptoHCP{\cdot}: \SPExp  \to \HCP$, 
    for a  process $P \in \SPExp$ such that $\DeadlockFreedomHCP{\SPExptoHCP{P}}$, there is a $P'$ that \emph{simulates} $P$, and 
    $\DeadlockFreedomHCPRR{\SPExptoHCP{P'}}$.




\subsection{From \texorpdfstring{$\SPExp$}{SP} to \texorpdfstring{$\HCP$}{HCP}}

We start by translating processes in $\SPExp$ into processes in $\HCP$:
\begin{definition}\label{def: encoding SPexp to HCP} Let $P\in \SPExp$. The encoding
$\SPExptoHCP{\cdot}: \SPExp \to \HCP$ is a homomorphism except for the case of free output, defined as
$\SPExptoHCP{\OutputSP{x}{v}P}\DefEq\boutHCP{y}{x}(\forwardHCP{y}{v}\para \SPExptoHCP{P})$. 
For types, we define:
$$\SPExptoHCP{\EndTypeI}\DefEq\bot
\qquad \SPExptoHCP{\EndTypeO}\DefEq\unit
\qquad \SPExptoHCP{\InputST{\empty}{T}{S}}\DefEq\SPExptoHCP{T}\InputTypeHCP \SPExptoHCP{S}
\qquad \SPExptoHCP{\OutputST{\empty}{T}{S}}\DefEq\Dual{\SPExptoHCP{T}}\OutputTypeHCP \SPExptoHCP{S}$$
For typing environments, we define: 
$\SPExptoHCP{\emptyset}\DefEq\emptyset$ and
$\SPExptoHCP{\Gamma,x:T}\DefEq\SPExptoHCP{\Gamma},x:\SPExptoHCP{T}$.
\end{definition}




 \emph{Regular Transitions}  do not depend on self-syn\-chro\-ni\-za\-tion or delayed actions:

\begin{definition}[$\HCP$: Regular Transitions]\label{def: regular reductions}
  A derivation $T$ for $P\TransitionHCP{l}Q$ is denoted $T:P\TransitionHCP{l}Q$. We define $\RegularReduction{T}$ iff $T$ is derived only using rules above the horizontal line in \Cref{fig: labelled  transitions HCP}.
\end{definition} 
\begin{example}
    Recall the processes 
    $P_{\ref{example:intrigue}}$
    and 
    $Q_{\ref{example:intrigue}}$ 
from \Cref{example:intrigue},
which use self-synchronizations and delayed actions, respectively:
we have that  $T_1:P_{\ref{example:intrigue}}\TransitionHCP{\tau}\Inact$, and  $T_2:Q_{\ref{example:intrigue}}\TransitionHCP{\tau}\news{y}{y'}(\EmptyOutputHCP{y}\Inact
\para
\EmptyInputHCP{y'}\Inact)$. Therefore, $\neg\RegularReduction{T_1}$ and $\neg\RegularReduction{T_2}$.
\end{example}

The encoding of free output induces transitions involving the forwarder process, not present in the source $\SPExp$ process. We handle the substitutions induced by forwarders in Rule~AxCut (\Cref{fig: labelled  transitions HCP}) as follows:

\begin{definition}[$\HCP$: Ready-for-Substitution]
    Let $P\in$ $\HCP$. We say that $P=\news{x}{y}P'$ is ready for substitution of $z$ for $x$, written $\ReadySubstitution{z}{x}{P}$, if there exists $z\in \FreeNamesHCP{P}$ and $P'$ s.t. $P\TransitionHCP{\forwardHCP{y}{z}}P'$, and $\news{x}{y}P\TransitionHCP{\tau}P'\subst{x}{z}$. Otherwise, we write $\NotReadySubstitution{P}$.
\end{definition}

We may now define transitions for processes that are ready for a substitution.

\begin{definition}[$\HCP$: Eager-to-Rename]\label{def: transition eager to rename}
The relation $\TransitionEagerHCP{l}$ on $\HCP$ processes is defined  as:
\begin{align*}
(P\TransitionHCP{l}Q)  \land \ReadySubstitution{x}{z}{Q}
& \Rightarrow P\TransitionEagerHCP{l}Q\subst{x}{z}
\qquad \text{and} \qquad
(P\TransitionHCP{l}Q)  \land \NotReadySubstitution{Q}  \Rightarrow P\TransitionEagerHCP{l}Q	
\end{align*}
\end{definition}

Intuitively, $\TransitionEagerHCP{l}$ executes outputs and forwarders in one single step.
When $\SPExptoHCP{P}$ only relies on regular transitions we have the following operational correspondence result.
\begin{toappendix}
	We start by proving a series of auxiliary results. First, we have that $\SPExptoHCP{\cdot}$ respects the sequential order of prefixes. We define contexts, with holes denoted `$\HoleSP$':
	\begin{definition}[Contexts in $\SPExp$ and $\HCP$] Contexts $\ContextSPC$ in $\SPExp$ and $\ContextHCPK$ in $\HCP$ are defined as: 
		\begin{align*}
			\ContextSPC::=&~ \HoleSP \Sep \ContextSPC\para P \Sep \news{x}{y}\ContextSPC \Sep \OutputSP{x}{v}\ContextSPC \Sep \InputSP{x}{y}\ContextSPC\\
			\ContextHCPK::=&~ \HoleHCP \Sep \ContextHCPK\para P \Sep \news{x}{y}\ContextHCPK \Sep \boutHCP{y}{x}(\forwardHCP{y}{z}\para \ContextHCPK) \Sep \InputHCP{x}{y}\ContextHCPK
		\end{align*}
	\end{definition}

	The encoding 
	$\SPExptoHCP{\cdot}$ (\Cref{def: encoding SPexp to HCP}) extends to contexts as expected, i.e., $\SPExptoHCP{\,\HoleSP\,} = \HoleHCP$.


	\begin{lemma}\label{lemma: translation preserves order of prefixes}
		Let $\alpha,\beta$ range over prefixes in \SPExp, and $\alpha'$ and $\beta'$ their corresponding in $\HCP$. 
		\[\alpha.\ContextSPIndex{C}{2}{\beta.Q}\Rightarrow \SPExptoHCP{\alpha.\ContextSPIndex{C}{2}{\beta.Q}}={\alpha'.\ContextHCPIndex{K}{2}{\beta'.Q'}}\]
