	\end{lemma}

	\begin{proof}
		By case analysis of $\tau$-transitions using the fact that $\RegularReduction{T}$.
	\end{proof}


	\begin{lemma}\label{lemma: substitution} 
		Let $P\in$ $\ClassH$. Then $\SPExptoHCP{P}\subst{y}{z}=\SPExptoHCP{P\subst{y}{z}}$.
	\end{lemma}
    \begin{proof}
        By induction on the structure of $P$ and \Cref{def: encoding SPexp to HCP}.
    \end{proof}

	\begin{lemma}\label{lemma: regular reductions and process}
		Let $P\in\ClassH$. If $T:\SPExptoHCP{P}\TransitionEagerHCP{\tau}P'$ and $\RegularReduction{T}$, then 

		\begin{enumerate}
			\item $P\equiv \news{x}{y}(\OutputSP{x}{v}Q\para \InputSP{y}{w}R)\para S$, or
			\item $P\equiv\news{x}{y}(\EmptyOutputSP{x}Q\para \EmptyInputSP{y}R)\para S$.
