    \begin{lemma}\label{lemma: equivalence and encoding} Let $\SPExptoHCP{\cdot}$ be as in \Cref{def: encoding SPexp to HCP}. We have:
    \begin{enumerate}
        \item Let $P\in\ClassH$.  $P\equiv P'$ iff $\SPExptoHCP{P}\EquivHCP\SPExptoHCP{P'}$.
        \item Let $P\in\HCP$. If $P\EquivHCP P'$ and $P'\TransitionHCP{l}Q'$, then there exist $Q$ s.t. $P\TransitionHCP{l}Q$, and $Q\EquivHCP Q'$.
    \end{enumerate}

    \end{lemma}
    \begin{proof}
        Item~(1) follows by \Cref{def: encoding SPexp to HCP} and case analyses in $\equiv$ and $\EquivHCP$, respectively. Item~(2) follows by a case analysis in both $\EquivHCP$ and $\TransitionHCP{l}$.
    \end{proof}

	We may now   prove the desired result:
\end{toappendix}
 %%%=====

\begin{theoremapxrep}[$\SPExptoHCP{\cdot}$: Operational Correspondence]\label{theorem: Operational correspondence SPExp-HCP}
Let $P\in\ClassH$.

\begin{enumerate}
\item If $T:\SPExptoHCP{P}\TransitionEagerHCP{\tau} R$ and $\RegularReduction{T}$, then $P\ReductionSP Q$ s.t. $\SPExptoHCP{Q}\EquivHCP R$.
    \item If $P\ReductionSP Q$, then $\SPExptoHCP{P}\TransitionEagerHCP{\tau}R$ s.t. $R \EquivHCP \SPExptoHCP{Q}$. 
\end{enumerate}
\end{theoremapxrep}
\begin{proof}
Part (1) follows by case analysis in $\TransitionEagerHCP{\tau}$.
There are two cases depending on the transition rule used: (i) $\OutputTypeHCP\InputTypeHCP$, or (ii) $\unit\bot$. We consider the case (i); the case (ii) follows similarly.

By assumption $\SPExptoHCP{P}\TransitionEagerHCP{\tau} R$ and $\RegularReduction{T}$, and
by \Cref{lemma: shape of processes in HCP with regular reductions}(2), $$\SPExptoHCP{P}\EquivHCP \news{x}{y}(\boutHCP{k}{x}(\forward{k}{v} \para\SPExptoHCP{Q_1})\para\InputHCP{y}{z}\SPExptoHCP{Q_2}\para \SPExptoHCP{S})\TransitionEagerHCP{\tau}\news{x}{y}( \SPExptoHCP{Q_1}\para\SPExptoHCP{Q_2\subst{v}{z}}\para \SPExptoHCP{S})$$ 

By \Cref{def: encoding SPexp to HCP} we have  $$P\equiv \news{x}{y}(\OutputSP{x}{v}Q_1\para\InputSP{y}{z}Q_2\para S)\ReductionSP \news{x}{y}(Q_1\para Q_2\subst{v}{z}\para S)$$
By \Cref{def: encoding SPexp to HCP} and \Cref{lemma: equivalence and encoding}(2),  $\SPExptoHCP{\news{x}{y}(Q_1\para Q_2\subst{v}{z}\para S)}= \news{x}{y}( \SPExptoHCP{Q_1}\para\SPExptoHCP{Q_2\subst{v}{z}}\para \SPExptoHCP{S})\EquivHCP R$, which concludes the proof.


Part (2) follows induction on the derivation of  $P\ReductionSP Q$. We detail the case  \textsc{R-Struct}. (The remaining cases follow immediately.)
\begin{prooftree}
\AxiomC{$P \equiv P' $}
    \AxiomC{$ P' \longrightarrow Q'$}
    \AxiomC{$Q' \equiv Q$}
    \RightLabel{\textsc{R-Struct}}
    \TrinaryInfC{$P \longrightarrow Q$}
\end{prooftree}
By IH $\SPExptoHCP{P'}\TransitionEagerHCP{\tau}R'$ s.t. $\SPExptoHCP{Q'}\EquivHCP R$. By \Cref{lemma: equivalence and encoding}(1) we have both $\SPExptoHCP{P}\EquivHCP \SPExptoHCP{P'}$ and $\SPExptoHCP{Q'}\EquivHCP \SPExptoHCP{Q}$. Thus, the proof concludes by  \Cref{lemma: equivalence and encoding}(2). 
\end{proof}


Following Dardha and P\'{e}rez~\cite{ComparingDeadlock}, 
 we now define $\ClassL$ and $\ClassH$ as the classes of \SPExp processes that are also typable in $\CP$ and \HCP, respectively: 
\begin{definition}[Classes $\ClassL$ and $\ClassH$] \label{Def: ClassL and ClassH}
    The classes  $\ClassL$ and $\ClassH$ of \SPExp processes are defined as:
    \begin{align*}
                 \ClassL&\DefEq\{P\in \text{$\SPExp$} \Sep \Gamma \SPExpJud P\,\wedge\,\SPExptoHCP{P}\CPJud\SPExptoHCP{\Gamma} \}\\
     \ClassH&\DefEq\{P \in \SPExp\Sep
     \Gamma\SPExpJud P\,\wedge\,\Gamma= \Gamma_1,\dots,\Gamma_n \,\wedge\,
     \SPExptoHCP{P}\HCPJud \SPExptoHCP{\Gamma_1}\SequentPara\cdots\SequentPara\SPExptoHCP{\Gamma_n} \}
    \end{align*}
\end{definition}
Hence, in writing `$P \in \ClassH$' we are not referring to an \HCP process directly, but rather to a \SPExp process $P$ (in the sense of \Cref{ss:sp}) that is related (up to $\SPExptoHCP{\cdot}$) to some (typable) \HCP process. This is how   \SPExp offers a  unifying framework for comparing different type systems.

As a direct consequence of \Cref{lemma: connection between CP and HCP} and \Cref{example: process in HCP not in CP} we have that
$\ClassL\subsetneq\ClassH$.


\subsection{A Refined Account of \texorpdfstring{$\ClassH$}{H}, Based on Deadlock Freedom}
As explained in the previous section, $\HCP$ enjoys liveness properties corresponding to the LTS. If we focus only on $\tau$-transitions (cf. \Cref{hcp:reduction}) we obtain the following results.

We extend \Cref{def: regular reductions} (regular transitions) to  sequences of transitions, as follows:
\begin{definition}[\HCP: Regular Sequence of Transitions]
Assume $P_1,\dots,P_n$  in $\HCP$ and transitions $T_i: P_i\TransitionHCP{l_i}P_{i+1}$. 
    We say that a transition sequence $\rho: P\TransitionHCP{l_1}\cdots\TransitionHCP{l_n}P_n$ transitions regularly iff $\RegularReduction{T_i}$ for all $i=1,\dots,n$. We write $\RegularReduction{\rho}$.
\end{definition}

We are interested in processes whose transitions are regular, thus we refine deadlock freedom in \HCP (\Cref{def: deadlock freedom delayed}) as follows: 
 \begin{definition}[$\HCP$: Deadlock Freedom based on Regular Transitions]\label{def: deadlock freedom no delayed}
    Let $P\in\HCP$. We say that $P$ is deadlock free without delayed actions and self-syn\-chro\-ni\-za\-tions, written $\DeadlockFreedomHCPRR{P}$, iff $\DeadlockFreedomHCP{P}$, $\rho: P\TransitionHCPClo P' \EquivHCP \Inact$, and $\RegularReduction{\rho}$.  
 \end{definition}

In turn, \Cref{def: deadlock freedom delayed,def: deadlock freedom no delayed} allow us to refine the definition of $\ClassH$ (\Cref{Def: ClassL and ClassH}):


\begin{definition}[$\HCP$: Sub-classes of $\ClassH$]\label{def: sub-classes of ClassH}
	We define the following classes of DF processes:
\begin{align*}
    \DeadlockFreedomHCPSet&\DefEq\{P\in\ClassH \Sep \DeadlockFreedomHCP{\SPExptoHCP{P}}\}
    \qquad \qquad 
    \DeadlockFreedomHCPRRSet \DefEq\{P\in\ClassH \Sep \DeadlockFreedomHCPRR{\SPExptoHCP{P}}\}
\end{align*}
\end{definition}

 By \Cref{Def: ClassL and ClassH,def: sub-classes of ClassH} we have $\DeadlockFreedomHCPRRSet\subsetneq\DeadlockFreedomHCPSet\subsetneq\ClassH$.

\begin{example}\label{example: Hrt and Hf}
Consider the \SPExp processes: 
\[
P_{\ref{example: Hrt and Hf}}\DefEq  ~\news{w}{z}(\EmptyOutputSP{w}\news{x}{y}(\EmptyOutputSP{x}\Inact \para \EmptyInputSP{y}\EmptyInputSP{z}\Inact))
\quad
 Q_{\ref{example: Hrt and Hf}}\DefEq  ~\news{w}{z}(\EmptyOutputSP{w}\Inact \para \news{x}{y}(\EmptyOutputSP{x}\Inact \para \EmptyInputSP{z}\EmptyInputSP{y}\Inact)) 
 \]

We have $P_{\ref{example: Hrt and Hf}} \in\DeadlockFreedomHCPSet \setminus   \DeadlockFreedomHCPRRSet$ and 
$Q_{\ref{example: Hrt and Hf}}  \in \DeadlockFreedomHCPRRSet$. 
Although $\neg \DeadlockFreedomSP{P_{\ref{example: Hrt and Hf}}}$, the $\HCP$ process $\SPExptoHCP{P_{\ref{example: Hrt and Hf}}}$ has a $\tau$-transition due to a delayed action, and therefore $\DeadlockFreedomHCP{\SPExptoHCP{P_{\ref{example: Hrt and Hf}}}}$. 
\end{example}

\begin{theorem}\label{theorem: deadlock freedom SPExp}
    If $P\in\DeadlockFreedomHCPRRSet$, then $\DeadlockFreedomSP{P}$.
\end{theorem}
\begin{proof}
     It follows from \Cref{theorem: Operational correspondence SPExp-HCP} and \Cref{def: sub-classes of ClassH,def: deadlock freedom in SP}.
\end{proof}



\subparagraph{From $\DeadlockFreedomHCPSet$ to  $\DeadlockFreedomHCPRRSet$ via process optimizations}
We now embark to show how to transform processes in $\DeadlockFreedomHCPSet$ (where self-synchronizations and delayed actions are used) into processes in $\DeadlockFreedomHCPRRSet$ (where they are not). 
Intuitively, we would like to transform, e.g.,  
\[\news{w}{z}(\EmptyOutputSP{w}\news{x}{y}(\EmptyOutputSP{x}\Inact \para \EmptyInputSP{y}\EmptyInputSP{z}\Inact))
~~~~\text{into}~~~~ 
    \news{w}{z}(\EmptyOutputSP{w}\Inact \para \news{x}{y}(\EmptyOutputSP{x}\Inact \para \EmptyInputSP{z}\EmptyInputSP{y}\Inact))\]
The transformation from $\DeadlockFreedomHCPSet$ to $\DeadlockFreedomHCPRRSet$  is formalized by \Cref{tehorem: deadlock free disentanglement HCP}. To achieve it, we leverage two existing  ingredients.
The \emph{first ingredient} is the notion of \emph{commuting conversions}: sound transformations on processes that involve actions from  independent sessions (cf.~\cite{DeYoungCPT12,LogicalRelations}). 
\begin{definition}[$\HCP$: Commuting Conversions]\label{def: commuting conversions}
We define $\CommutingConversion$  as the smallest congruence on \HCP processes induced by the   equalities in \Cref{fig: commuting conversions}. 
\end{definition}


