\begin{definition}[$\HCP$: Disentanglement~\cite{TakingLinearLogicApart}]\label{def: disentanglement}
Disentanglement is described by the smallest relation $\Disentangle$ on (typed) processes closed under the rules in \Cref{fig: full disnetanglement}.
 We write $\DisentangleClo$ for the reflexive and transitive closure of $\Disentangle$.
\end{definition}

Disentanglement proceeds by the repeated application of the rules from \Cref{fig: full disnetanglement} to the derivation of $P\HCPJud \Gamma_1\SequentPara \cdots \SequentPara \Gamma_n$, which aims at moving downwards the instances of Rule \Hname\MixTwo (cf.~\Cref{fig:type system HCP}). If \Hname\MixTwo gets stuck in either $\Hname$\textsc{Cut} or $\Hname\OutputTypeHCP$, then it becomes an instance of $\C$\textsc{Cut} or $\C\OutputTypeHCP$, respectively (cf.~\Cref{fig:CP Rules}). 
 Disentanglement increases the parallelism in processes. This way, e.g., for  $P_{\ref{example: process in HCP not in CP}}$ and $Q_{\ref{example: process in HCP not in CP}}$  (\Cref{example: process in HCP not in CP}) we have: $P_{\ref{example: process in HCP not in CP}}\DisentangleClo Q_{\ref{example: process in HCP not in CP}}$.
Also, note that Rule $\Hname\unit$ types $\EmptyOutputHCP{x}P\HCPJud \Gamma \SequentPara x:\unit$, induces a discrepancy: at the process level, the rule places the empty output in sequential composition with $P$,  whereas at the level of typing  $x:\unit$ is placed in its own partition, enforcing independence from all names in $\FreeNamesHCP{P}$. Disentanglement solves this discrepancy. Consider, e.g., process $P_{\ref{example:intrigue}}=\news{x}{x'}(\EmptyOutputHCP{x}\EmptyInputHCP{x'}\Inact)$: we have  $P_{\ref{example:intrigue}}\DisentangleClo\,\news{x}{x'}(\EmptyOutputHCP{x}\Inact\para\EmptyInputHCP{x'}\Inact)$.

\begin{lemma}[Disentanglement~\cite{betterlate}]\label{lemma: disentanglement}
    If there exists a derivation $d$ of $P\HCPJud \Gamma_1\SequentPara \cdots \SequentPara \Gamma_n$, then there exist derivations $d_1,\dots,d_n$ of $P_1\CPJud \Gamma_1, \dots ,P_n\CPJud \Gamma_n$ in $\CP$, and 

    \begin{tabular}{ccc}
        $P\HCPJud \Gamma_1\SequentPara \cdots \SequentPara \Gamma_n$ & $\DisentangleClo$ & 
        \begin{minipage}{4cm}
        \begin{prooftree}
            \AxiomC{ $P_1\CPJud \Gamma_1\, \cdots\, P_n\CPJud \Gamma_n$ }
            \RightLabel{$\Hname$\MixTwo}
            \doubleLine
            \UnaryInfC{$P_1\para\cdots\para P_n\HCPJud \Gamma_1\SequentPara \cdots \SequentPara \Gamma_n$}
            \end{prooftree}
        \end{minipage}
    \end{tabular}
    \\
    where we use the double line to indicate multiple uses of the same rule.
\end{lemma}

The following result ensures that process observations are invariant under disentanglement. Moreover, since instances of $\Hname$\textsc{Cut} are turned into  instances of $\C$\textsc{Cut}, disentangled processes do not feature occurrences of restriction between sessions in sequential composition.
\begin{lemma}\label{lemma: denotations preserved in disentanglement}
     Suppose $P\in\HCP$. If  $P\Disentangle^* P'$ then $P\BisimilarityHCP P'$.
\end{lemma}
\begin{proof}

We prove that if  $P\Disentangle^* P'$ then $P\ObservationalEq P'$ by induction on the length $k$ of $\Disentangle^*$. For the base case ($k = 1$)  we proceed by a case analysis in the last rule applied in the type derivation of $P\HCPJud\HypG$. The fact that $P\BisimilarityHCP P'$ follows from \Cref{theorem: full abstraction}.
\end{proof}


Given a process $P$, the rules for disentanglement can be applied in any order; we therefore define a set of disentangled processes:
\begin{definition}[\HCP: Disentangled Processes]\label{def: disentangled process HCP} Given $P\in \HCP$, the set  $\Disentangled{P}$ is defined as follows:
\begin{mathpar}
 \Disentangled{P}     
    \DefEq\left\{P' \in \HCP ~\mathrel{\big |}~
    \begin{gathered}[l]
    P\DisentangleClo P',\\[-1.5em]
     P'=P_1\para\cdots\para P_n\HCPJud \Gamma_1\SequentPara\cdots\SequentPara \Gamma_n , ~~
      P_1\CPJud \Gamma_1, ~\cdots~ ,P_n\CPJud \Gamma_n
      \end{gathered}
\right\}
\end{mathpar}
\end{definition}
From \Cref{lemma: denotations preserved in disentanglement} we have that 
all disentangled processes are observationally equivalent:
\begin{lemma}
\label{lem:disentrans}
    Let $P\in\HCP$. If $Q,R\in\Disentangled{P}$, then $Q\BisimilarityHCP R$.
\end{lemma}
\begin{proof}
 From \Cref{lemma: denotations preserved in disentanglement},  $P\BisimilarityHCP P'$ for all $P'\in\Disentangled{P}$.  By \Cref{def: weak transition HCP}, $\BisimilarityHCP$  is transitive.
 Hence, for all $Q, R\in\Disentangled{P}$, $Q\BisimilarityHCP R$.  
\end{proof}

We use disentanglement to prove that if $\DeadlockFreedomHCP{P}$ then there is a  $P'$ s.t. $\DeadlockFreedomHCPRR{P'}$, with $P\BisimilarityHCP P'$. 

The following  main result establishes that the notions of $\DeadlockFreedomHCP{\cdot}$ 
(\Cref{def: deadlock freedom delayed})
and $\DeadlockFreedomHCPRR{\cdot}$ 
(\Cref{def: deadlock freedom no delayed})
are equivalent, up to commuting conversions and disentanglement. 

% \begin{toappendix}
% \subsection{Proof of \Cref{tehorem: deadlock free disentanglement HCP} (Page~\pageref{tehorem: deadlock free disentanglement HCP})}
%    \label{proof:deadlock free disentanglement HCP}
% \end{toappendix}
\begin{theoremapxrep}\label{tehorem: deadlock free disentanglement HCP}
For all processes  $P\in \HCP$ s.t. $\DeadlockFreedomHCP{P}$, then there exist $P',Q\in \HCP$ s.t.: 
% \begin{enumerate*}
\textup{(1)} $P'\in\Disentangled{P}$, 
\textup{(2)} $P'\CommutingConversion Q$,
\textup{(3)} $P\BisimilarityHCP Q$,
\textup{(4)} $\DeadlockFreedomHCPRR{Q}$.
% \end{enumerate*}
\end{theoremapxrep}
% \begin{proofsketch}
%     Parts (1)-(3) follow from \Cref{def: disentangled process HCP,def: commuting conversions,lemma: denotations preserved in disentanglement}. For part~(4) we show that self-synchronizations and delayed actions are eliminated by means of disentanglement and commuting conversions, respectively.  See  \Cref{proof:deadlock free disentanglement HCP} for details.
% \end{proofsketch}
\begin{proof}
    %\todo{There is macro for writing in the margin.}
    Part (1), on the existence of $P'$, is immediate from \Cref{def: disentangled process HCP}.  
    Part (2) follows from \Cref{def: commuting conversions} and the soundness of commuting conversions with respect to bisimilarity.
    Part (3) is immediate from \Cref{lemma: denotations preserved in disentanglement} and Part (2). 
    As for Part (4), because $P$ and $Q$ are bisimilar, the analysis of deadlock freedom reduces to the analysis of self-synchronizations and delayed actions in $Q$. We detail this analysis next, considering these two cases separately.

\subparagraph{Self-synchronizations}
    By assumption, $\DeadlockFreedomHCP{P}$. Therefore, $P\TransitionHCPClo\Inact$ relying on $\TransitionHCP{\tau}$. This means that self-synchronizations  must happen on dual names, inside a restriction. By the previous analysis, we know that for each self-synchronization there is a subprocess of $P$ $P''=\news{x}{y}\pi.R$ s.t.  $\FreeNamesHCP{\pi}=x, \FreeNamesHCP{l}=y$, and $\pi.R\TransitionHCP{\pi\para l}R'$, where $\Partition{x}{\pi.R}{y}$. 
    By the definition of $\Partition{x}{\pi.R}{y}$ (\Cref{d:separation}), we infer that 
    $\pi.R\HCPJud \HypG$, where $\HypG=\Gamma_1\parallel \cdots \parallel \Gamma_{n-1},x:A\parallel\Gamma_n,y:\Dual{A}$. 

Recall that disentanglement turns instances of Rule \Hname \textsc{Cut} into instances of Rule \C \textsc{Cut}:
\begin{prooftree}
    \AxiomC{$\pi.R\HCPJud\Gamma_1\parallel\cdots \parallel \Gamma_{n-1},x:A\parallel\Gamma_n,y:\Dual{A}$}
    \RightLabel{\Hname\textsc{Cut}}
    \UnaryInfC{$\news{x}{y}\pi.R\HCPJud\Gamma_1\parallel\cdots  \parallel \Gamma_{n-1},\Gamma_n$}
\end{prooftree}
    By \Cref{lemma: disentanglement}, there exist 
    $R_1, \cdots, R_n$  such that  $R_1\CPJud \Gamma_1, \cdots, R_{n-1}\CPJud \Gamma_{n-1}$ and also $x:A, R_{n}\CPJud$ and $\Gamma_{n},y:\Dual{A}$.  Thus we have:
    \begin{prooftree}
        \AxiomC{$R_1\para \cdots\para R_{n-2}\HCPJud\Gamma_1\parallel\cdots \parallel \Gamma_{n-2} $}
        \AxiomC{$ R_{n-1}\para R_n\HCPJud \Gamma_{n-1},x:A\parallel\Gamma_n,y:\Dual{A}$}
        \RightLabel{\C \textsc{Cut}}
        \UnaryInfC{$ \news{x}{y}(R_{n-1}\para R_n)\HCPJud \Gamma_{n-1},\Gamma_n$}
        \BinaryInfC{$R_1\para \cdots\para R_{n-2}\para\news{x}{y}(R_{n-1}\para R_n)\HCPJud\Gamma_1\parallel\cdots \parallel \Gamma_{n-2}\para \Gamma_{n-1},\Gamma_n$}
    \end{prooftree}

    By \Cref{lemma: denotations preserved in disentanglement},  
    $\news{x}{y}\pi.R\BisimilarityHCP R_1\para \cdots\para R_{n-2}\para\news{x}{y}(R_{n-1}\para R_n)$. Moreover, by typability ensures that $x$ and $y$ are free names only in $R_{n-1}$ and $R_n$, respectively. Therefore $R_{n-1}\para R_n\TransitionHCP{\pi\para l} R''$, for some $R''$ s.t. $R'\BisimilarityHCP R''$. Note that $R_{n-1}\para R_n\TransitionHCP{\pi\para l} R''$ is not an instance of Rule $|\pi$ (which induces self-synchronizations), because the actions $\pi$ and $l$ occur in different parallel components. Thus, if we take a process $P'\in\Disentangled{P}$ in which all the instances of Rule \Hname    {\textsc{Cut}} have been transformed into instances of  Rule \C{\textsc{Cut}}, then we obtain a process  that does not rely in self-synchronizations. 

 \subparagraph{Delayed actions} If $P'$ does not rely on delayed actions, then we take $Q=P'$. Otherwise, $P'$ has transitions that rely on Rules $\pi_1,\pi_2,\otimes$ or $\parr$. Two observations: 
  \begin{enumerate}
   \item Free names are invariant under commuting conversions; and
       \item We can always bring to the top-level those actions that are happening under some guard.
 \end{enumerate}
While Item (1) follows by straightforward inspection of the the rules in \Cref{def: commuting conversions}, Item (2) follows by induction in the number of prefixes/restrictions guarding the delayed action. The base case follows immediately by \Cref{def: commuting conversions}. The inductive step follows by a case analysis in the last rule applied and IH. Thus, by repeated application of commuting conversions, we can find a process $Q$ s.t. $Q\BisimilarityHCP P'$ (and by transitivity $Q\BisimilarityHCP P$) and $\DeadlockFreedomHCPRR{Q}$.
     \end{proof}

\Cref{tehorem: deadlock free disentanglement HCP} concerns $\HCP$ processes.  To lift this result to~$\SPExp$, we need some  results. 
\begin{lemma}\label{lemma: disentanglement in SP}
      Let $P\in \ClassH$. There exists $P'\in \ClassH$ s.t.:  
             \textup{(1)} $\SPExptoHCP{P}\Disentangle^*\SPExptoHCP{P'}$.
          \textup{(2)} $\SPExptoHCP{P}\CommutingConversion^*\SPExptoHCP{P'}$.
\end{lemma}
\begin{proof}
The items follow by induction on the length of $\Disentangle^*$ and $\CommutingConversion^*$, respectively. For 1. in the base cases we proceed by a case analysis in the last rule applied in the type derivation of $\SPExptoHCP{P}\HCPJud\SPExptoHCP{\Gamma}$; it shows the structure of $\SPExptoHCP{P}$ and by \Cref{def: encoding SPexp to HCP} we obtain the structure of $P$. The proof finishes by applying a single step of $\Disentangle$ to the type derivation of $\SPExptoHCP{P}\HCPJud\SPExptoHCP{\Gamma}$ and replicating it to the derivation of $\Gamma \SPExpJud P$. The proof of 2. proceeds similarly.
\end{proof}

\Cref{lemma: disentanglement in SP}  ensures that the following definition is sound:
\begin{definition}[Lifting Commuting Conversions and Disentanglement to $\SPExp$]\label{def: lifting disentanglement}
    Let $P, P' \in\ClassH$. We write $P\DisentangleClo P'$ and $P\CommutingConversion^*P'$, whenever $\SPExptoHCP{P}\DisentangleClo  \SPExptoHCP{P'}$ and $\SPExptoHCP{P}\CommutingConversion^* \SPExptoHCP{P'}$ hold, respectively. 
\end{definition}
Having disentanglement in $\SPExp$, we aim to prove that the resulting disentangled process \emph{simulates} the original process. To define simulation in $\SPExp$, we need the following notion:
\begin{definition}[$\SPExp$: Labelled Reduction Semantics]\label{def: labelled reduction semantics SPExp}
Let $P\in\SPExp$, then $P \LabelledReduction{x}{y} Q$   whenever:
\textup{(1)}~$P\equiv\news x y(\OutputSP{x}{v}P' \para \InputSP{y}{z}Q'\ \para\ R) \longrightarrow \news x y(P'\ \para\ Q'\subst{v}{z} \para R)\equiv Q $, or
    \textup{(2)}~$P\equiv\news xy(\EmptyInputSP{x}P'\para \EmptyOutputSP{y} Q'\para R)\ReductionSP \news xy (P' \para Q'\para R)\equiv Q$.
\end{definition}
\begin{definition}[$\SPExp$: Simulation]
\label{def:simulation}
    A binary relation $\mathbb{S}$ in $\SPExp$ is a (typed)  simulation if whenever $(P,Q)\in \mathbb{S}$ then 
    $\Gamma\SPExpJud P$, $\Gamma\SPExpJud Q$ and $P\LabelledReduction{x}{y}P'$ implies
    $Q\LabelledReduction{x}{y} Q'$ for some $Q'$ s.t. $(P',Q')\in \mathbb{S}$. We write $P \ReductionSimulation Q$ whenever $(P,Q)\in \mathbb{S}$ for a (typed) simulation $\mathbb{S}$.
\end{definition}
In the LTS semantics of $\HCP$, the processes $P$ and $Q$ from \Cref{tehorem: deadlock free disentanglement HCP} are bisimilar; however, in a reduction semantics, any transitions of $P$ that use delayed actions or self-synchronization would be considered as deadlocks, and then $Q$ would only simulate $P$. Formally:


\begin{theoremapxrep}\label{theorem: Rs in a reduction simulation}
The relation
$\mathbb{S}=\{(P,R) \,\mid\, P\in \ClassH, \text{and } P\Disentangle R\}$ is a    simulation.
\end{theoremapxrep}
\begin{proof}
We check the conditions of \Cref{def:simulation} by induction on the structure of $P$. 
We consider two interesting cases; the remaining cases proceed similarly.
\begin{itemize}
    \item Case $P=\EmptyOutputSP{x}P'$ . 
    By \Cref{def: disentanglement} we have that disentanglement is applied as follows:\\
    \begin{tabular}{ccc}
\hspace*{-1.3cm}  
 \begin{minipage}{7cm}
         \begin{prooftree}
             \AxiomC{$\SPExptoHCP{P'}\HCPJud \HypG$}
             \UnaryInfC{$\SPExptoHCP{\EmptyOutputSP{x}P'}\HCPJud \HypG \SequentPara x:\unit$}
         \end{prooftree}
     \end{minipage}
     &$\Disentangle$&
     \begin{minipage}{7cm}
     \begin{prooftree}
         \AxiomC{$\SPExptoHCP{\Inact} \HCPJud \cdot$}
         \UnaryInfC{$\SPExptoHCP{\EmptyOutputSP{x}\Inact}\HCPJud x:\unit$}
         \AxiomC{$\SPExptoHCP{P}\HCPJud \HypG$}
         \RightLabel{$\Hname$\MixTwo}
         \BinaryInfC{$\SPExptoHCP{\EmptyOutputSP{x}\Inact\para P}\HCPJud \HypG\SequentPara x:\unit$}
          \end{prooftree}
     \end{minipage}
\end{tabular}

 Thus $(\EmptyOutputSP{x}P', \EmptyOutputSP{x}\Inact \para P')\in\mathbb{S}$. By \Cref{def: reduction semantics sp}
is clear that   $\EmptyOutputSP{x}P'$ has no reduction, which concludes this case. Cases $P=\EmptyInputHCP{x}P',P=\InputHCP{x}{y}P'$ and $P=\boutHCP{v}{x}P'$ follow similarly.


\item Case $P=\news{x}{y}(Q\para R)$. 

By \Cref{def: disentanglement} we have that disentanglement is applied as follows:\\
\begin{tabular}{ccc}
\hspace*{-1.3cm}  
\begin{minipage}{7cm}
	\begin{prooftree}
		\AxiomC{$\SPExptoHCP{Q}\HCPJud \HypG \SequentPara\Gamma,x:A\SequentPara \Delta ,y:\Dual{A}$}
		\AxiomC{$\SPExptoHCP{R}\HCPJud \HypH$}
		\BinaryInfC{$\SPExptoHCP{Q}\para \SPExptoHCP{R}\HCPJud \HypG\SequentPara \HypH,\SequentPara\Gamma,x:A\SequentPara \Delta ,y:\Dual{A}$}
		\UnaryInfC{$\cut{xy}{\SPExptoHCP{Q}}{\SPExptoHCP{R}}\HCPJud \HypG\SequentPara \HypH\SequentPara\Gamma\SequentPara \Delta$}
	\end{prooftree}

\end{minipage}
	&
$\Disentangle$&
\begin{minipage}{7cm}
	\begin{prooftree}
		\AxiomC{$\SPExptoHCP{Q}\HCPJud \HypG \SequentPara\Gamma,x:A\SequentPara \Delta ,y:\Dual{A}$}

		\UnaryInfC{$\news{x}{y}  \SPExptoHCP{Q}\HCPJud \HypG\SequentPara \HypH,\SequentPara\Gamma\SequentPara \Delta$}
		\AxiomC{$\SPExptoHCP{R}\HCPJud \HypH$}
		\BinaryInfC{$\news{x}{y}(\SPExptoHCP{Q})\para{\SPExptoHCP{R}}\HCPJud \HypG\SequentPara \HypH\SequentPara\Gamma\SequentPara \Delta$} 
	\end{prooftree}
\end{minipage}
\end{tabular}
\\
Thus $(\news{x}{y}(Q\para R),\news{x}{y}(Q)\para R)\in\mathbb{S}$. If $\news{x}{y}(Q\para R)\ReductionSP S$, \Cref{def: reduction semantics sp} we have the following cases:
\begin{enumerate}

    \item $R\ReductionSP R'$ and $S=(\news{x}{y}(Q\para R')$,
    \item $Q\ReductionSP Q'$ in a session different to $xy$ and $S=(\news{x}{y}(Q'\para R)$, or
 \item $\news{x}{y}(Q\para R)\ReductionSP S$ on session $xy$, and we have either
           \begin{enumerate}

           \item \sloppy reduction due to \textsc{R-Com}, then $Q\equiv \InputSP{y}{z}Q_1\para \OutputSP{x}{v}Q_2\para Q_3$
           and  $S\equiv\news{x}{y}(Q_1\subst{v}{z}\para Q_2\para Q_3\para R)$, or 
           \item reduction due to \textsc{R-EmptyCom}, then $Q\equiv \EmptyInputSP{y}Q_1\para \EmptyOutputSP{x}Q_2\para Q_3$
           and $S\equiv Q_1\para Q_2\para Q_3\para R$.
