		\BinaryInfC{$\SPExptoHCP{Q}\para \SPExptoHCP{R'}\HCPJud \HypG\SequentPara \HypH,\SequentPara\Gamma,x:A\SequentPara \Delta ,y:\Dual{A}$}
		\UnaryInfC{$\cut{xy}{\SPExptoHCP{Q}}{\SPExptoHCP{R'}}\HCPJud \HypG\SequentPara \HypH\SequentPara\Gamma\SequentPara \Delta$}
	\end{prooftree}

\end{minipage}
	&
$\Disentangle$&
\begin{minipage}{7cm}
	\begin{prooftree}
		\AxiomC{$\SPExptoHCP{Q}\HCPJud \HypG \SequentPara\Gamma,x:A\SequentPara \Delta ,y:\Dual{A}$}

		\UnaryInfC{$\news{x}{y}  \SPExptoHCP{Q}\HCPJud \HypG\SequentPara \HypH,\SequentPara\Gamma\SequentPara \Delta$}
		\AxiomC{$\SPExptoHCP{R'}\HCPJud \HypH$}
		\BinaryInfC{$\news{x}{y}(\SPExptoHCP{Q})\para{\SPExptoHCP{R'}}\HCPJud \HypG\SequentPara \HypH\SequentPara\Gamma\SequentPara \Delta$} 
