\end{minipage}
\end{tabular}\\
and  $(\news{x}{y}(Q\para R'),\news{x}{y}(Q)\para R')\in\mathbb{S}$.

Case (2) is similar to case (1).

In Case (3a) we have:\\

\begin{tabular}{c}
\hspace*{-1.3cm}  
\begin{minipage}{7cm}
	\begin{prooftree}
		\AxiomC{$\SPExptoHCP{Q_1\subst{v}{z}}\para\SPExptoHCP{Q_2}\para \SPExptoHCP{Q_3}\HCPJud \HypG \SequentPara\Gamma,x:A\SequentPara \Delta ,y:\Dual{A}$}
		\AxiomC{$\SPExptoHCP{R}\HCPJud \HypH$}
		\BinaryInfC{$\SPExptoHCP{Q_1\subst{v}{z}}\para\SPExptoHCP{Q_2}\para \SPExptoHCP{Q_3}\para \SPExptoHCP{R}\HCPJud \HypG\SequentPara \HypH,\SequentPara\Gamma,x:A\SequentPara \Delta ,y:\Dual{A}$}
		\UnaryInfC{$\cut{xy}{\SPExptoHCP{Q_1\subst{v}{z}}\para\SPExptoHCP{Q_2}\para \SPExptoHCP{Q_3}}{\SPExptoHCP{R}}\HCPJud \HypG\SequentPara \HypH\SequentPara\Gamma\SequentPara \Delta$}
	\end{prooftree}

\end{minipage}\\

$\Disentangle$\\
\begin{minipage}{7cm}
	\begin{prooftree}
		\AxiomC{$\SPExptoHCP{Q_1\subst{v}{z}}\para\SPExptoHCP{Q_2}\para \SPExptoHCP{Q_3}\HCPJud \HypG \SequentPara\Gamma,x:A\SequentPara \Delta ,y:\Dual{A}$}

		\UnaryInfC{$\news{x}{y}  \SPExptoHCP{Q_1\subst{v}{z}}\para\SPExptoHCP{Q_2}\para \SPExptoHCP{Q_3}\HCPJud \HypG\SequentPara \HypH,\SequentPara\Gamma\SequentPara \Delta$}
		\AxiomC{$\SPExptoHCP{R}\HCPJud \HypH$}
		\BinaryInfC{$\news{x}{y}(\SPExptoHCP{Q_1\subst{v}{z}}\para\SPExptoHCP{Q_2}\para \SPExptoHCP{Q_3})\para{\SPExptoHCP{R}}\HCPJud \HypG\SequentPara \HypH\SequentPara\Gamma\SequentPara \Delta$} 
