    \and
    \inferrule[M-In]{\Gamma,x:\Shift{n}{t_1}, y:\Shift{n}{t_2}\MuPadoJud P\qquad n<|\Gamma|}
    {\Gamma\PartialComposition u:\InputTypePado{t_1,t_2}{n}\MuPadoJud \InputPado{u}{x,y}P}
           \and 
    \inferrule[M-New-Par]{\Gamma_1,a:\TypePado{p}{t}{n}\MuPadoJud P\qquad 
    \Gamma_2, a:\TypePado{q}{t}{n}\MuPadoJud Q\qquad dom(\Gamma_1)\cap dom(\Gamma_2)=\emptyset,\,p\cup q \text{ even}}
    {\Gamma_1\PartialComposition \Gamma_2 \MuPadoJud \new{a}(P\para Q)}\\
     \vspace*{-0.7cm}
   \end{mathpar}
    }\vspace*{-0.5cm}
    \caption{$\MuPadovani$: Modified typing rules for asynchronous processes. 
    }
    \label{fig:type system mu padovani}
     \vspace*{-0.3cm}
  \end{figure}


   $\MuPadovani$ results from $\Padovani$ by replacing Rules \textsc{T-Par} and \textsc{T-New} in \Cref{fig:type system padovani} with Rule \textsc{M-New-Par},  which combines restriction and parallel  just as Rule $\C$\textsc{Cut} in \Cref{fig:CP Rules}.  
\begin{lemmaapxrep}\label{lemma: mupadovani in padovani}
   If $\Gamma \MuPadoJud P$ then  $\Gamma \PadoJud P$. 
\end{lemmaapxrep}
\begin{proof}
By induction on the type derivation, with a case analysis in the last rule applied.
We only consider two cases.
\begin{itemize}
	\item Rule~\textsc{M-Idle}: This case is immediate: if $\Gamma\MuPadoJud\Inact$ then $\Gamma\PadoJud\Inact$.
	\item Rule \textsc{M-New-Par}: This is the only interesting case. We have:
	\begin{prooftree}
	\AxiomC{$\Gamma_1,a:\TypePado{p}{t}{n}\MuPadoJud P$}
	\AxiomC{$\Gamma_2, a:\TypePado{q}{t}{n}\MuPadoJud Q$} 
		\AxiomC{ $\Gamma_1\cap \Gamma_2=\emptyset,\,p\cup q \text{ even}$}
		\TrinaryInfC{$ {\Gamma_1\PartialComposition \Gamma_2 \MuPadoJud \new{a}(P\para Q)}$}
	\end{prooftree}
	By IH, $\Gamma_1,a:\TypePado{p}{t}{n}\PadoJud P$ and $\Gamma_2, a:\TypePado{q}{t}{n}\PadoJud Q$. The proof concludes by applying Rules \textsc{T-Par} and \textsc{T-New} from \Cref{fig:type system padovani} in sequence. 
\end{itemize}
\end{proof}

\begin{corollary}
    If $\MuPadoJud P$, then $\DeadlockFreedomPado{P}$.
\end{corollary}
\begin{proof}
    It follows by \Cref{lemma: mupadovani in padovani,theorem: deadlock freedom padovani}.
\end{proof}

We now define an   encoding from $\SPExp$ to $\Padovani$, following a continuation-passing style (cf.~\cite{Dardha:2012:STR:2370776.2370794}). Let $f$  be a function from names to names. We use the following conventions: $f_x$ stands for $f(x)$, and $f,\{x\mapsto c\}$ stands for the function $f'$ s.t. $f'(x)=c$ and $f'(y)=f(y)$ if $x\neq y$.
\begin{definition}\label{def: encoding SPExp to Padovani}
The (partial) encoding $\SPExptoPado{f}{\cdot}: \SPExp \to \Padovani$  is parameterized by a function, ranging over $f,g$, from names to names, and is defined for processes as follows:
    \begin{align*}
    \SPExptoPado{f}{\OutputSP{x}{v}P}&\DefEq \new{m}(\OutputPado{f_x}{f_v,m}\para \InputPado{m}{k}\new{c}(\OutputPado{k}{c}\para \SPExptoPado{f,\{x\mapsto c\}}{P}))\\
    \SPExptoPado{f}{\InputSP{x}{z}P}&\DefEq \InputPado{f_x}{z,m}\new{a}(\OutputPado{m}{a}\para \InputPado{a}{c}\SPExptoPado{f,\{x\mapsto c\}}{P})
    \\
    \SPExptoPado{f}{\EmptyOutputSP{x}\Inact}&\DefEq \new{r}\OutputPado{f_x}{r}
    \\
    \SPExptoPado{f}{\EmptyInputSP{x}P}&\DefEq \InputPado{f_x}{r}\SPExptoPado{f}{P} \qquad \text{(with $r \notin \mathtt{fv}(P)\cup \mathtt{bv}(P)$)}
\\   
\SPExptoPado{f}{\news{x}{y}P}&\DefEq \new{d}\SPExptoPado{f,\{x,y\mapsto d\}}{P}
    \end{align*}
    and as a homomorphism for $P\para Q$ and $\Inact$.
  The encoding of session types is as follows:
    \begin{align*}
     \SPExptoPadoType{\EndTypeI}&\DefEq\TypePado{?}{\TypePado{\emptyset}{\empty}{\empty}}{n}
     &
          \SPExptoPadoType{\LinOutputST{S}{T}}&\DefEq \TypePado{?}{\SPExptoPadoType{T},\TypePado{!}{\TypePado{!}{\SPExptoPadoType{S}}{i}}{j}}{n}
\\
      \SPExptoPadoType{\EndTypeO}&\DefEq\TypePado{!}{\TypePado{\emptyset}{\empty}{\empty}}{n} & 
     \SPExptoPadoType{\LinInputST{S}{T}}&\DefEq \TypePado{!}{\SPExptoPadoType{T},\TypePado{!}{\TypePado{!}{\SPExptoPadoType{\DualSPExp{S}}}{i}}{j}}{n}
\end{align*}
Typing environments are encoded inductively as $\SPExptoPado{f}{\emptyset}\DefEq\emptyset$ and  $\SPExptoPado{f}{\Gamma,x:T}\DefEq\SPExptoPado{f}{\Gamma}, f_x:\SPExptoPadoType{T}$. The values of $i,j$ and $n$ are calculated when checking in $\MuPadovani$ the typablity of $\SPExptoPado{f}{\Gamma}\MuPadoJud\SPExptoPado{f}{P}$. 
\end{definition}

Intuitively, the encoding of processes in \Cref{def: encoding SPExp to Padovani} collapses the two endpoints of a session into a single name in $\Padovani$. The encoding of $\OutputSP{x}{v}P$ mimics both the sequential structure of a session and  synchronous communication.   $\SPExptoPado{f}{\OutputSP{x}{v}P}$ sends the (renamed) value $f_v$ and a new channel $m$ along which an input $\InputPado{m}{k}$ blocks the continuation $\SPExptoPado{f,\{x\mapsto c\}}{P}$, and receives the channel along which the the continuation $c$ of the session $x$ will be sent.
 Dually,  $\SPExptoPado{f}{\InputSP{x}{z}P}$ receives the intended value and the channel $m$, which sends the channel $a$, along which the continuation of the session $x$ will be received. 
 Finally, the encoding is partial because $\SPExptoPado{f}{\EmptyOutputSP{x}P}$ is only defined when $ P = \Inact$: this allows us to characterize the session processes captured in $\CP$,  where the empty output has no continuation (see \Cref{def: CP}).


\begin{example}\label{example: operational correspondence SP Pado}
Consider the process $P_{\ref{example: operational correspondence SP Pado}}\DefEq\news{x}{y}(\OutputSP{x}{v}R\para \InputSP{y}{z}Q)$ in $\SPExp$.
  We show $\SPExptoPado{f}{P_{\ref{example: operational correspondence SP Pado}}}$ and illustrate its reductions.
    Let us assume $P_{\ref{example: operational correspondence SP Pado}}$ is well-typed. Because of linearity of $x$ and $y$, they only appear in the left and right subprocess, respectively. Let $f=\{x,y\mapsto d\}$ and $g_1=\{x\mapsto c\}$,$g_2=\{y\mapsto c'\}$, then we have:
\begin{align*}
    \SPExptoPado{\emptyset}{P_{\ref{example: operational correspondence SP Pado}}} & = \new{d}(\SPExptoPado{f}{\OutputSP{x}{v}R}\para \SPExptoPado{f}{\InputSP{y}{z}Q})\\
    & =\new{d}( \new{m}(\OutputPado{d}{v,m}\para \InputPado{m}{k}\new{c}(\OutputPado{k}{c}\para \SPExptoPado{g_1}{R}))
    \\
    &\quad \phantom{=\new{d}}\para  \InputPado{d}{z,m'}\new{a}(\OutputPado{m'}{a}\para \InputPado{a}{c'}\SPExptoPado{g_2}{Q}))
    \\
    & \ReductionPado \new{m}(\InputPado{m}{k}\new{c}(\OutputPado{k}{c}\para \SPExptoPado{g_1}{R}) \para  \new{a}(\OutputPado{m}{a}\para \InputPado{a}{c'}\SPExptoPado{g_2}{Q}\subst{v}{z}))
    \\
    &  \ReductionPado \new{a}( \new{c}(\OutputPado{a}{c}\para \SPExptoPado{g_1}{R})\para \InputPado{a}{c'}\SPExptoPado{g_2}{Q}\subst{v}{z})\\
     & \ReductionPado \new{c}(\SPExptoPado{g_1}{R}\para \SPExptoPado{g_2}{Q}\BiSubstitution{v}{z}{c}{c'})
\end{align*}
\end{example}

Our main result concerns the classes of processes associated to $\Padovani$ and $\MuPadovani$, which we define by mirroring the definition of $\ClassL$ and $\ClassH$ (\Cref{Def: ClassL and ClassH}):
\begin{definition}[$\ClassLP$ and  $\ClassMuP$]\label{def: class muP} 
	The classes of processes $\ClassLP$ and $\ClassMuP$ are defined as follows:
	\begin{align*}
		\ClassLP&\DefEq\{P\in \text{$\SPExp$} \Sep \Gamma \SPExpJud P\,\wedge\,\SPExptoPado{f}{\Gamma}\PadoJud\SPExptoPado{f}{P} \} \qquad 
		\ClassMuP \DefEq\{P\in \text{$\SPExp$} \Sep \Gamma \SPExpJud P\,\wedge\,\SPExptoPado{f}{\Gamma}\MuPadoJud\SPExptoPado{f}{P} \} \label{class muLP}
	\end{align*}
\end{definition}



The following result establishes an operational correspondence between a process and its encoding, what will allows us to capture deadlock free session processes via the encoding.
\begin{theorem}[Operational Correspondence for $\SPExptoPado{f}{\cdot}$]\label{theorem: operational correspondence SP and pado}
    Let $P\in \ClassMuP$. We have:

    \begin{enumerate}
        \item 
        \begin{enumerate}
            \item If $P\equiv \new{\widetilde{xy}}(\EmptyOutputSP{x}Q_1\para\EmptyInputSP{y}Q_2\para S )$, then $\exists Q\in \Padovani$ such that $\SPExptoPado{f}{P}\ReductionPado Q$ and 
        $Q\EquivPado \SPExptoPado{f}{\new{\widetilde{xy}}(Q_1\para Q_2\para S )}$.
        \item If $P\equiv \new{\widetilde{xy}}(\OutputSP{x}{v}Q_1\para \InputSP{y}{z}Q_2\para S)$, then $\exists Q\in \Padovani$ such that $\SPExptoPado{f}{P}\ReductionPado^3 Q$ and 
        $Q\EquivPado \SPExptoPado{f}{\new{\widetilde{xy}}(Q_1\para Q_2\subst{v}{z}\para S)}$. 
        \end{enumerate}
        \item If $\SPExptoPado{f}{P}\ReductionPado R$, then either: 
        \begin{enumerate}
        \item  $\exists P'\in\SPExp$ such that $P\ReductionSP P'$ and $R\EquivPado \SPExptoPado{f}{P'}$, or
            \item   $\exists Q\in\Padovani$, and $P'\in\SPExp$ such that $R\ReductionPado^2 Q$, $P\ReductionSP P'$ and $Q\EquivPado \SPExptoPado{f}{P'}$.
        \end{enumerate}

    \end{enumerate}

\end{theorem}
\begin{proof}
 By assumption, $P\in\ClassMuP$ and so we have that $\Gamma\SPExpJud P$, for some $\Gamma$, and $\SPExptoPado{f}{\Gamma}\MuPadoJud\SPExptoPado{f}{P}$ is defined. Moreover, by \Cref{corollary: wellformedness SP} $P$ is well-formed. 
 We consider each item separately. 
 Item~1(b) follows by \Cref{def: encoding SPExp to Padovani} and the rest of the analysis proceeds as in \Cref{example: operational correspondence SP Pado}; Item 1(a) is similar.
 Item~(2): If $\SPExptoPado{f}{P}\ReductionPado R$, then $\SPExptoPado{f}{P}\EquivPado\new{\tilde{a}}(\OutputPado{d}{\tilde{v}}\para \InputPado{d}{\tilde{x}}K\para S)$. By typability of $P$ and \Cref{def: encoding SPExp to Padovani}  one of the two possibilities apply:

 \begin{enumerate}
 	\item[i] $P\equiv \new{\widetilde{xy}}(\EmptyOutputSP{x}\Inact\para 
\EmptyInputSP{y}K'\para S')$, $\SPExptoPado{f}{S'}=S$, $\SPExptoPado{f}{K'}=K$ and $f=f',\{x,y\mapsto d\}$,
\item[ii] $P\equiv \new{\widetilde{xy}}(\OutputSP{x}{v}S_1\para \InputSP{y}{z}K'\para S_2)$ and $f=f',\{x,y\mapsto d\}$
 \end{enumerate}
  \sloppy In case (i)  $\SPExptoPado{f}{P}\EquivPado\new{\tilde{a}}(\new{r}\OutputPado{d}{r}\para \InputPado{d}{r'}K\para S)\ReductionPado\new{\tilde{a}}(K\para S)$  
  and $P\equiv \new{\widetilde{xy}}(\EmptyOutputSP{x}\Inact\para 
\EmptyInputSP{y}K'\para S')\ReductionSP \new{\widetilde{xy}'}( 
K'\para S'') $, which verifies case (2a). In case (ii) we proceed as in \Cref{example: operational correspondence SP Pado}, which verifies case (2b).
\end{proof}



As a consequence of \Cref{theorem: operational correspondence SP and pado} we have the following result, which shows the relation between deadlock free processes in $\ClassMuP$.

\begin{corollary}\label{corollary: deadlock freedom in pado and SP}
     Let $P\in \ClassMuP$. $\DeadlockFreedomSP{P}$ iff $\DeadlockFreedomPado{\SPExptoPado{f}{P}}$.
\end{corollary}
\begin{proof}
For each direction we prove its contrapositive. 
We discuss only the right-to-left direction; the analysis for the left-to-right direction is similar.
By \Cref{def: deadlock freedompadovani body}, there exist $R$ and $a$ s.t. $\SPExptoPado{f}{P}\ReductionPadoClo \new{\tilde{a}}R\longarrownot\ReductionPado$ and $\mathsf{wait}(a,R)$. If $\mathsf{wait}(a,R)$ holds because $\mathsf{in}(a,R)$ then 
$R\EquivPado \new{\tilde{a}}(\InputPado{a}{x}Q\para S)$.
 By \Cref{theorem: operational correspondence SP and pado,def: encoding SPExp to Padovani}  there exists $P'\equiv \new{\widetilde{xy}}(\InputSP{z}{w}Q'\para S')$ s.t. $P\ReductionSP^*P'$ and $R\EquivPado \SPExptoPado{f}{P'}$. Note that $P'\longarrownot\ReductionSP$, since otherwise by \Cref{theorem: operational correspondence SP and pado}(1), $\new{\tilde{a}}R\ReductionPado R''$ for some process $R''$, contradicting our assumption, thus $\neg\DeadlockFreedomSP{P}$. The case when $\mathsf{wait}(a,R)$ holds because $\mathsf{out}(a,R)$ proceeds similarly.
\end{proof}

\Cref{corollary: deadlock freedom in pado and SP} allows us to detect DF session processes via the encoding.

\subsection{Comparing \texorpdfstring{$\ClassH$}{H} and \texorpdfstring{$\ClassLP$}{P}}
\label{sec: comparing H and MuLP}



From \Cref{sec: results} we infer that  a process $P\in\ClassH$, typed as $\SPExptoHCP{P}\HCPJud \Gamma_1\SequentPara \cdots\SequentPara\Gamma_n$, can be decomposed into processes $P_1\CPJud \Gamma_1$, $\ldots$, $P_n\CPJud \Gamma_n$. Moreover, by \Cref{lemma: disentanglement in SP} (disentanglement in $\SPExp$) we infer that processes $P_1, \ldots, P_n$ have a pre-image in $\SPExp$, therefore $\forall i\in[1,n]$ $P_i\in\ClassL\subsetneq\ClassH$. 


As an important preliminary step, we first prove that $\ClassL = \ClassMuP$ (\Cref{corollary: L equal to mupadovani}). 
We split the proof in two separate inclusions. 
The following lemma is useful to prove that $\ClassL\subseteq\ClassMuP$.



\begin{lemma}\label{lemma: big lemma}
    Let $\Gamma$ and $P$ be an environment and a process in $\Padovani$, resp. The following hold:
    \begin{enumerate}
    \item   If $\Gamma \PadoJud P$, then $\Shift{n}{\Gamma}\PadoJud P$.
     \item   If $\Gamma \MuPadoJud P$, then $\Shift{n}{\Gamma}\MuPadoJud P$.
    \item  Let $P\in \Padovani$. If $\Gamma\MuPadoJud P$ and $\UnrestrictedPado{T}$, then $\Gamma,x:T \MuPadoJud P$, with $x$ fresh wrt $P$.

        \item   Let $\Gamma_1,\dots, \Gamma_n$ be typing environments in $\SPExp$, then 
    $\SPExptoPado{f}{\Gamma_1,\cdots,\Gamma_n}=\SPExptoPado{f}{\Gamma_1}\PartialComposition\cdots\PartialComposition\SPExptoPado{f}{\Gamma_n}$, 
    for some renaming function $f$.
    \item Let $T$ be a session type. Then $\SPExptoPado{f}{T}\PartialComposition\Shift{m}{\SPExptoPado{f}{\DualSPExp{T}}}=\TypePado{p}{T'}{n}$,  for some $m\geq 0$, $n\in\mathbb{Z}$, $T'$ a type in $\Padovani$, and $p$ even.
\end{enumerate}
\end{lemma}
\begin{proof}
    \textup{(1)}~Proven in \cite{padovani_linear_pi}. \textup{(2)}~ Follows from \Cref{lemma: mupadovani in padovani} and item 1.
    \textup{(3)}~Follows by induction on the type derivation. (\Cref{fig:type system mu padovani}).
    \textup{(4)}~ Follows immediately by linearity of names in $\Gamma_i$, for $i\in[1,n]$.
    \textup{(5)}~Follows by induction on the structure of $T$.
\end{proof}

\begin{theoremapxrep}\label{theorem: L equal to mupadovani}
    $\ClassL\subseteq\ClassMuP$.
\end{theoremapxrep}

\begin{proof}
    By induction on the type derivation $\Gamma\SPExpJud P$ with a case analysis in the last rule applied.
    \begin{itemize}
    \item \textsc{Inact}. It is immediate.
        \item \textsc{Res}. 
    By assumption, \Cref{def: encoding SPexp to HCP,Def: ClassL and ClassH},
 we have that $\SPExptoHCP{\news{x}{y}P'}\CPJud \SPExptoHCP{\Gamma}$, and there exist $P_1$, $P_2$, $\Gamma_1$, and $\Gamma_2$ s.t. $\Gamma=\Gamma_1,\Gamma_2$,  $dom(\Gamma_1)\cap dom(\Gamma_2)=\emptyset$, and  $P'=P_1\para P_2$ s.t:
    \begin{prooftree}
        \AxiomC{$\SPExptoHCP{P_1}\CPJud \SPExptoHCP{\Gamma_1},x:\SPExptoHCP{T}$}
        \AxiomC{$\SPExptoHCP{P_2}\CPJud \SPExptoHCP{\Gamma_1},y:\SPExptoHCP{\DualSPExp{T}}$}
        \RightLabel{\C\textsc{Cut}}
        \BinaryInfC{$\news{x}{y}(\SPExptoHCP{P_1}\para\SPExptoHCP{P_2})\CPJud\SPExptoHCP{\Gamma}$}
    \end{prooftree}
   and we want to prove that $\SPExptoPado{f}{\Gamma_1,\Gamma_2}\MuPadoJud\SPExptoPado{f}{\news{x}{y}P'}$.
    By IH we have that 
   \[
        \SPExptoPado{f}{\Gamma_1},d:\SPExptoPadoType{T}\MuPadoJud\SPExptoPado{f}{P_1}\quad  
        \text{and}
   \quad \SPExptoPado{f}{\Gamma_2},d:\SPExptoPadoType{\DualSPExp{T}}\MuPadoJud\SPExptoPado{f}{P_2} 
    \]
    where $f=f',\{x,y\mapsto d\}$.
    By \Cref{lemma: big lemma}(5), there exist $m$ s.t. $\SPExptoPado{f}{T}\PartialComposition\Shift{m}{\SPExptoPado{f}{\DualSPExp{T}}}=\TypePado{p}{T'}{n}$, for  an even polarity $p$. 
    By \Cref{lemma: big lemma}(2), we have   $\Shift{m}{\SPExptoPado{f}{\Gamma_2}},d:\Shift{m}{\SPExptoPadoType{\DualSPExp{T}}}\MuPadoJud\SPExptoPado{f}{P_2}$. Then, applying Rule \textsc{M-New-Par}, we have $\SPExptoPado{f}{\Gamma_1}\PartialComposition\Shift{m}{\SPExptoPado{f}{\Gamma_2}}\MuPadoJud\new{d}(\SPExptoPado{f}{P_1}\para \SPExptoPado{f}{P_2}$) holds. By \Cref{def: encoding SPExp to Padovani} the priorities of types are to be assigned; thus we can assume that $\SPExptoPado{f}{\Gamma_1}\PartialComposition{\SPExptoPado{f}{\Gamma_2}}\MuPadoJud\new{d}(\SPExptoPado{f}{P_1}\para \SPExptoPado{f}{P_2}$) and by \Cref{lemma: big lemma}(4) and \Cref{def: encoding SPExp to Padovani} we obtain $\SPExptoPado{f}{\Gamma_1,\Gamma_2}\MuPadoJud\SPExptoPado{f}{\news{x}{y}P'}$,  which concludes this case.


\item \textsc{EInput}.   $\Gamma, x:\EndTypeI\SPExpJud \EmptyInputSP{x}P'$ is derived as
\begin{prooftree}
    \AxiomC{$\Gamma\SPExpJud P'$}
    \UnaryInfC{$\Gamma, x:\EndTypeI\SPExpJud \EmptyInputSP{x}P'$}
\end{prooftree}
By assumption and \Cref{def: encoding SPexp to HCP,Def: ClassL and ClassH},
 we have that \[\SPExptoHCP{\EmptyInputSP{x}P'}\CPJud \SPExptoHCP{\Gamma,x:\EndTypeI}\]

 we want to prove
 \[\SPExptoPado{f}{\Gamma,x:\EndTypeI}\MuPadoJud\SPExptoPado{f}{\EmptyInputSP{x}P'}\]
 By IH $\SPExptoPado{f}{\Gamma}\MuPadoJud\SPExptoPado{f}{P'}$. By \Cref{lemma: big lemma}(3), we have that 
 $\SPExptoPado{f}{\Gamma},r:\Shift{n}{\TypePado{\emptyset}{\empty}{\empty}}\MuPadoJud\SPExptoPado{f}{P'}$, for some $n$ s.t.
 $n<\PriorityFunction{\SPExptoPado{f}{\Gamma}}$. Thus, applying Rule~\textsc{M-Input}, we obtain:
 \begin{prooftree}
     \AxiomC{ $\SPExptoPado{f}{\Gamma},r:\Shift{n}{\TypePado{\emptyset}{\empty}{\empty}}\MuPadoJud\SPExptoPado{f}{P'}\quad n<\PriorityFunction{\SPExptoPado{f}{\Gamma}}$}
     \RightLabel{\textsc{M-Input}}
     \UnaryInfC{$\SPExptoPado{f}{\Gamma},f_x:\TypePado{?}{\Shift{n}{\TypePado{\emptyset}{\empty}{\empty}}}{n}\MuPadoJud \InputPado{f_x}{r}\SPExptoPado{f}{P'}$}
 \end{prooftree}

 Finally, by \Cref{def: encoding SPExp to Padovani} we obtain $\SPExptoPado{f}{\Gamma,x:\EndTypeI}\MuPadoJud\SPExptoPado{f}{\EmptyInputSP{x}P'}$.

\item \textsc{EOutput}, \textsc{Out} and \textsc{In} follow similarly, using \Cref{lemma: big lemma}(3)  when $x$ has no continuation, since $c$ is typed with the empty polarity.

    \end{itemize}
    \end{proof}


To prove the other direction we need the following result.


\begin{lemma}\label{lemma: 63}
\label{lemma: duality session types and HCP}
    Let $S$ and $T$ be session types.  We have:
    	\textup{(1)}~$\SPExptoPado{f}{S}\PartialComposition\SPExptoPado{f}{T}$ is defined iff $T=\DualSPExp{S}$.
\textup{(2)}~$\SPExptoHCP{\DualSPExp{S}}=\LinearDual{\SPExptoHCP{S}}$.
\end{lemma}
\begin{proof}
 Item (1) follows by \Cref{def: encoding SPExp to Padovani} and def. of $\PartialComposition$.
Item (2) follows immediately by induction in the structure of $S$ and \Cref{def: encoding SPexp to HCP}.
\end{proof}

\begin{theoremapxrep}\label{theorem: mupadovani in L}
    $\ClassMuP\subseteq \ClassL$.
\end{theoremapxrep}

\begin{proof}
By induction on the type derivation  of $\Gamma\SPExpJud P$ with a case analysis in the last rule applied. The interesting case is  \textsc{Res}, i.e, $\Gamma\SPExpJud \news{x}{y}P$. By the assumption $P\in\ClassMuP$, we have that $\SPExptoPado{f}{\Gamma}\MuPadoJud\SPExptoPado{f}{\news{x}{y}P}$, therefore there exist $\Gamma_1,\Gamma_2$, $P_1,P_2$ s.t.  $\Gamma=\Gamma_1,\Gamma_2$,  $dom(\Gamma_1)\cap dom(\Gamma_2)=\emptyset$,  $P'=P_1\para P_2$, $\SPExptoPado{f}{\Gamma_1,x:T}\MuPadoJud \SPExptoPado{f}{P_1}$ and $\SPExptoPado{f}{\Gamma_1,y:\DualSPExp{T}}\MuPadoJud \SPExptoPado{f}{P_2}$. Thus $\Gamma\SPExpJud \news{x}{y}P$ can be split as  $\Gamma_1,x:T\SPExpJud P_1$ and $\Gamma_2,y:\DualSPExp{T}\SPExpJud P_2$. \Cref{lemma: 63} ensures that $\SPExptoHCP{\DualSPExp{T}}=\LinearDual{\SPExptoHCP{T}}$, thus the proof concludes by IH and applying Rule $\C$\textsc{Cut}. The rest of the cases follow by IH. 
\end{proof}


 \begin{corollary}\label{corollary: L equal to mupadovani}
     $\ClassL=\ClassMuP$.
 \end{corollary}
 \begin{proof}
     It follows by \Cref{theorem: L equal to mupadovani,theorem: mupadovani in L}.
 \end{proof}

\subparagraph{Main Results}
We may now return to considering $\ClassH$. Note that  $\ClassH\setminus \ClassLP\neq \emptyset$: to see this, consider, e.g., the self-synchronizing process $P_1\in\DeadlockFreedomHCPSet$ from \Cref{example:intrigue}. 
Using \Cref{corollary: L equal to mupadovani} and disentanglement (\Cref{def: disentanglement}) we show that given a process $P\in\DeadlockFreedomHCPSet$, we can find  a deadlock-free process $P'\in\ClassLP$. Formally, we have:

    \begin{theorem}\label{theorem: Hrt and Pado}
          Given $P\in\DeadlockFreedomHCPSet$,   $\exists P'\in\DeadlockFreedomHCPRRSet$ s.t. $P'\in\ClassLP$, $\SPExptoHCP{P}\BisimilarityHCP \SPExptoHCP{P'}$,   and $\DeadlockFreedomPado{\SPExptoPado{f}{P'}}$.
    \end{theorem}
    \begin{proof}
        By \Cref{corollary: main corollary HCP}, $\SPExptoHCP{P}\DisentangleClo\CommutingConversion^*\SPExptoHCP{P'}=P_1\para\cdots\para P_n$, and by \Cref{lemma: disentanglement in SP} $\forall i\in[1,n]$, there exists $P'_i\in \ClassL$ s.t. $\SPExptoHCP{P'_i}=P_i$. From \Cref{corollary: L equal to mupadovani,lemma: mupadovani in padovani} we infer $\SPExptoPado{f}{P'_i}\in\ClassLP$, $\forall i\in[1,n]$. Moreover, by repeatedly applying  Rule~\textsc{T-Par} we have that $P'\in\ClassLP$. Finally, $\DeadlockFreedomPado{\SPExptoPado{f}{P'}}$ follows from \Cref{theorem: deadlock freedom SPExp,corollary: deadlock freedom in pado and SP}.
    \end{proof}



The following result relates $\ClassH$, its subclasses $\DeadlockFreedomHCPSet$ and $\DeadlockFreedomHCPRRSet$, and $\ClassLP$.


\begin{theoremapxrep}\label{lemma: comparing ClassH and Padovani}
 The following hold:
 \textup{(1)}~$\ClassLP\setminus\ClassH\neq\emptyset$.
     \textup{(2)}~$\DeadlockFreedomHCPSet\setminus \ClassLP\neq \emptyset$.
      \textup{(3)}~$\ClassLP\cap\DeadlockFreedomHCPRRSet\neq\emptyset$.
\end{theoremapxrep}
    \begin{proof}
     We give witnesses for each statement:
    \begin{enumerate}
        \item Consider the $\SPExp$ process $P_{\ref{lemma: comparing ClassH and Padovani}}\DefEq \news{x}{y}(R_1\para R_2)$, with $R_1$ and $R_2$ defined as:
        \begin{align*}
            R_1\DefEq&\news{v_1}{v_2}(\OutputSP{x}{v_1}\OutputSP{x}{v_2}\EmptyOutputSP{x}\Inact)
            \qquad
            R_2\DefEq \InputSP{y}{z_1}\InputSP{y}{z_2}\EmptyInputSP{y}(\EmptyOutputSP{z_1}\Inact\para\EmptyInputSP{z_2}\Inact)
        \end{align*}
To check that $P_{\ref{lemma: comparing ClassH and Padovani}}\in\ClassLP$, we need to verify that $\PadoJud\SPExptoPado{f}{P_{\ref{lemma: comparing ClassH and Padovani}}}$. Its  type derivation is similar to the derivation for $ Q_{\ref{exmaple: typing in LP}}$ (\Cref{exmaple: typing in LP}); however $P_{\ref{lemma: comparing ClassH and Padovani}}\notin\ClassH$, since $R_1\notin\ClassH$:
\[\SPExptoHCP{R_1}=\news{v_1}{v_2}(\boutHCP{v'_1}{x}(\forward{v'_1}{v_1}\para \boutHCP{v'_2}{x}(\forward{v'_2}{v_2}\para \EmptyOutputHCP{x}\Inact)))\]
 we have $\boutHCP{v'_1}{x}(\forward{v'_1}{v_1}\para\boutHCP{v'_2}{x}(\forward{v'_2}{v_2}\para \EmptyOutputHCP{x}\Inact))
    \HCPJud x:\unit\OutputTypeHCP(\bot\OutputTypeHCP\unit),v_1:\bot , v_2:\unit$.
However the restriction $\news{v_1}{v_2}$ cannot be typed since $v_1$ and $v_2$ are in the same partition; see Rule~$\Hname$\textsc{Cut} in \Cref{fig:type system HCP}. 

\item Consider a self-synchronizing process  in $\DeadlockFreedomHCPSet$ such as $P_1$ (\Cref{example:intrigue}) or $P_{\ref{example: section 3 at work}}$ (\Cref{example: section 3 at work}).

\item      Consider the  $\SPExp$ process $P_3 \DefEq    \news{x_1}{y_1}\news{x_2}{y_2}\news{v_1}{k_1}\news{v_2}{k_2}(Q_1\para Q_2)$ with
\begin{align*}
Q_1&\DefEq\InputSP{x_1}{z_1}\InputSP{x_2}{z_2}\EmptyInputSP{x_1}\EmptyInputSP{x_2}\EmptyInputSP{z_1}\EmptyInputSP{z_2}\Inact \\
Q_2&\DefEq\OutputSP{y_1}{v_1}\OutputSP{y_2}{v_2}(\EmptyOutputSP{y_1}\Inact\para \EmptyOutputSP{y_2}\Inact\para \EmptyOutputSP{k_1}\Inact\para\EmptyOutputSP{k_2}\Inact)
\end{align*}
       It is easy to check that $P_3\in\ClassLP$ since $\DeadlockFreedomSP{P_3}$. Note that $\SPExptoHCP{P_3}=P_{\ref{example: process in HCP not in CP}}$, thus $P\in\ClassH$. It is straightforward to check that $P\in\DeadlockFreedomHCPRRSet$.
     \end{enumerate}
    \end{proof}

Finally, from \Cref{theorem: Hrt and Pado} we have the following result, which complements  \Cref{corollary: main corollary HCP}: given $P\in\DeadlockFreedomHCPSet$, there exists a bisimilar process $P'\in\DeadlockFreedomHCPRRSet\cap \ClassLP$ via disentanglement. Note that this result applies in particular  to processes in $\DeadlockFreedomHCPSet\setminus \ClassLP$.

\begin{corollary}\label{corollary: main result mupado}
Given $P\in \DeadlockFreedomHCPSet$,   there exists $P'\in \DeadlockFreedomHCPRRSet$ s.t.
\textup{(1)}~$P\ReductionSimulation P'$,
    \textup{(2)}~$\SPExptoHCP{P}\BisimilarityHCP\SPExptoHCP{P'}$, and  
    \textup{(2)}~$\DeadlockFreedomPado{\SPExptoPado{f}{P'}}$.
\end{corollary}




