By a similar analysis to the one for \Cref{theorem: operational correspondence SP and pado}, we have the following result:
\begin{theorem}[$\SPAtoSP{\cdot}$: Operational Correspondence]\label{theorem: operational correspondence ASP and SP}
Let $P\in \SPExpA$. The following holds:

\begin{enumerate}
\item if $P\equiv \news{x}{y}(\AInputSP{x}{w}{z}P\para \AOutputSP{y}{v_1}{v_2}\para R)$, then   $\exists Q\in\SPExp$ s.t. $\SPAtoSP{P}\ReductionSP^3 Q$ and $Q=\SPAtoSP{P\BiSubstitution{v_1}{w}{v_2}{z}\para R}$.

\item If $P\equiv \news{x}{y}(\EmptyInputSP{x}P\para \EmptyOutputSP{y}\Inact\para R)$, then   $\exists Q\in\SPExp$ s.t. $\SPAtoSP{P}\ReductionSP Q$ and $Q=\SPAtoSP{P\para R}$.

\item If $\SPAtoSP{P}\ReductionSPA Q'$, then either:
(i)~there exists $Q\in\SPExp$ s.t. $Q'\ReductionSP^2 Q$, $P\ReductionSPA P'$ and $\SPAtoSP{P'}=Q$, or 
	(ii)~$P \ReductionSPA P'$ and $\SPAtoSP{P'}=Q'$.
\end{enumerate}
\end{theorem}


Using  \Cref{theorem: operational correspondence ASP and SP,def: deadlock freedom in SP,def: deadlock freedom in ASP} we formalize our claim from \Cref{Example: SPAtoSP does not add deadlocks}: $\SPAtoSP{\cdot}$ does not add deadlocks.
\begin{theoremapxrep}[Correspondence DF]\label{theorem: correspondence deadlock freedom ASP and SP}
For all $P\in\SPExpA$, $\DeadlockFreedomSPA{P}$ iff $\DeadlockFreedomSP{\SPAtoSP{P}}$.
\end{theoremapxrep}
\begin{proof}
	For each direction we prove its contrapositive and proceed by contradiction.
We discuss only the left-to-right direction; the analysis for the right-to-left direction proceeds similarly.
 If $\neg \DeadlockFreedomSPA{P}$, then there exists a $P'\in\SPExpA$, such that $P\ReductionSP^* P'$, $P'\longarrownot\ReductionSPA$
	, and $P'$ is equivalent to one of the four forms in \Cref{def: deadlock freedom in ASP}, thus $P'\not\equiv \Inact$. 
	 By (repeated applications of) \Cref{theorem: operational correspondence ASP and SP}(3), there exists $R\not\equiv\Inact$ s.t. $\SPAtoSP{P}\ReductionSPA^* R$ and $\SPAtoSP{P'}=R$.  If $\DeadlockFreedomSP{\SPAtoSP{P}}$, then there exists $Q$ s.t $\SPAtoSP{P'}\ReductionSPA Q$, and by \Cref{theorem: operational correspondence ASP and SP}(3), then $P'\ReductionSP Q'$ for some $Q'$, which is a contradiction. The right-to-left direction proceeds similarly using \Cref{def: deadlock freedom in SP}.
\end{proof}



Using the encoding $\SPAtoSP{\cdot}$, and  inspired by \Cref{theorem: operational correspondence ASP and SP,theorem: correspondence deadlock freedom ASP and SP}, we can define the following classes of asynchronous processes by relying on their synchronous counterparts:

     \begin{definition}
     \label{d:asyncclasses}
    The classes of asynchronous processes are defined as follows:\\
        % \hspace*{-0.5cm}
    \begin{minipage}{12cm}
            \begin{align*}
    \ClassLA&\DefEq\{P \in \SPExpA\Sep \SPAtoSP{P}\in \ClassL\} &  \ClassLPA&\DefEq\{P \in \SPExpA\Sep \SPAtoSP{P}\in \ClassLP\}  & 
       \ClassMuPA&\DefEq\{P \in \SPExpA\Sep \SPAtoSP{P}\in \ClassMuP\}
    \\
     \ClassHA&\DefEq\{P \in \SPExpA\Sep \SPAtoSP{P}\in \ClassH\}
 & 
    \DeadlockFreedomHCPSetA&\DefEq\{P \in\SPExpA\Sep \SPAtoSP{P}\in\DeadlockFreedomHCPSet\}& \DeadlockFreedomHCPRRSetA&\DefEq\{P \in\SPExpA\Sep \SPAtoSP{P}\in\DeadlockFreedomHCPRRSet\} 
    \end{align*}
    \end{minipage}

\end{definition}


Each asynchronous class is contained (up to $\SPAtoSP{\cdot}$) in its corresponding synchronous class:

\begin{lemma}\label{lemma: classes of processes ASP}
  Let $P\in\SPExpA$.  The following hold:
        \textup{(1)}~If $P\in\ClassLA$, then $\SPAtoSP{P}\in\ClassL$. 
        \textup{(2)}~If $P\in\ClassHA$, then $\SPAtoSP{P}\in\ClassH$.
        \textup{(3)}~If $P\in\ClassLPA$, then $\SPAtoSP{P}\in\ClassLP$.
        \textup{(4)}~If $P\in\ClassMuPA$, then $\SPAtoSP{P}\in\ClassMuP$.
        \textup{(5)}~If $P\in\DeadlockFreedomHCPSetA$, then $\SPAtoSP{P}\in\DeadlockFreedomHCPSet$.
        \textup{(6)}~If $P\in\DeadlockFreedomHCPRRSetA$, then $\SPAtoSP{P}\in\DeadlockFreedomHCPRRSet$.
\end{lemma}
\begin{proof}
	It follows straightforwardly from \Cref{d:asyncclasses}.
\end{proof}
Thus, we can transfer our main results (\Cref{corollary: main corollary HCP,corollary: main result mupado,corollary: L equal to mupadovani}) to $\SPExpA$ via $\SPAtoSP{\cdot}$.
For instance,  \Cref{corollary: main corollary HCP} is transferred to $\SPExpA$ as follows, using \Cref{lemma: classes of processes ASP}, and \Cref{theorem: operational correspondence ASP and SP}:
\begin{corollary}
\label{c:transfer}
Given  $P\in\DeadlockFreedomHCPSetA$, there exist $Q\in\ClassH$ and $P'\in\DeadlockFreedomHCPRRSetA$ s.t.:
    \textup{(1)}~$\SPExptoHCP{Q}\in \Disentangled{\SPExptoHCP{\SPAtoSP{P}}}$,
    \textup{(2)}~$\SPExptoHCP{Q}\CommutingConversion^*\SPExptoHCP{\SPAtoSP{P'}}$,
    \textup{(3)}~$\SPAtoSP{P}\ReductionSimulation \SPAtoSP{P'}$,
    \textup{(4)}~$\SPExptoHCP{\SPAtoSP{P}}\BisimilarityHCP\SPExptoHCP{\SPAtoSP{P'}}$. 
\end{corollary}


