Before presenting our code construction, we provide a precise definition of $\mathrm{CCR}(\boldsymbol{X})$ and $\mathrm{RIR}(\boldsymbol{X})$.

\begin{comment}
\begin{definition}
  For any $q$-ary sequence $\boldsymbol{x}$, let $c_i$ be the number of occurrences of the symbol `$i$'s in $\boldsymbol{x}$ for $i \in [0,q-1]$. We then define the \emph{composition} of $\boldsymbol{x}$ as $c(\boldsymbol{x})=(c_0,c_1,\ldots,c_{q-1})$.
\end{definition}
\end{comment}

\begin{definition}  
  For a given array $\boldsymbol{X} \in \Sigma_q^{n \times n}$, let $\mathrm{CCR}(\boldsymbol{X})$ be its \emph{column composition representation}, which is defined as 
  \begin{align*}
    \mathrm{CCR}(\boldsymbol{X}) := \big(\mathrm{CCR}(X)_1, \mathrm{CCR}(X)_2, \ldots, \mathrm{CCR}(X)_n\big),
  \end{align*}
  where $\mathrm{CCR}(X)_k := \mathrm{Comp}(\boldsymbol{X}_{[1:n],k})$ represents the composition of the $k$-th column of $\boldsymbol{X}$ for $k \in [1:n]$.  
\end{definition}  


\begin{definition}  
  For a given array $\boldsymbol{X} \in \Sigma_q^{n \times n}$, let $\mathrm{RIR}(\boldsymbol{X})$ be its \emph{row integer representation}, which is defined as
  \begin{align*}
    \mathrm{RIR}(\boldsymbol{X}) := \big(\mathrm{RIR}(X)_1, \mathrm{RIR}(X)_2, \ldots, \mathrm{RIR}(X)_n\big),
  \end{align*}
  where $\mathrm{RIR}(X)_k := \sum_{j=1}^n X_{k,j} q^{n-j}$ represents the integer representation of the $k$-th row of $\boldsymbol{X}$ in base $q$ for $k \in [1:n]$.  
\end{definition}

We are now prepared to present our code construction.

\begin{construction}\label{constr1}
  For fixed sequences $\boldsymbol{a}= (a_1,a_2,\cdots,a_n), \boldsymbol{b}= (b_1,b_2,\ldots,b_n)\in \Sigma_q^n$ and $c,d\in \Sigma_n$, we define the code 
  $\mathcal{C}_1(\boldsymbol{a},\boldsymbol{b},c,d)$ in which each array $\boldsymbol{X}$ satisfies the following constraints:
  \begin{itemize}
    \item \emph{Row/Column Sum Constraints:} $\sum_{t=1}^n X_{t,k} \equiv a_k \pmod{q}$ and $\sum_{t=1}^n X_{k,t} \equiv b_k \pmod{q}$ for $k\in [1:n]$;
    \item \emph{Column Composition Constraints:} $\sum_{t=1}^{n-1} t \cdot \alpha\big(\mathrm{CCR}(X)\big)_t \equiv c \pmod{n}$ and $\mathrm{CCR}(X)_k \neq \mathrm{CCR}(X)_{k+1}$ for $k\in [1:n-1]$;
    \item \emph{Row Integer Constraint:} $\sum_{t=1}^{n-1} t\cdot \alpha\big(\mathrm{RIR}(X)\big)_t \equiv d \pmod{n}$.
  \end{itemize}
\end{construction}    

\begin{theorem}\label{thm:non-binary}
  For fixed sequences $\boldsymbol{a}= (a_1,a_2,\cdots,a_n), \boldsymbol{b}= (b_1,b_2,\ldots,b_n)\in \Sigma_q^n$ and $c,d\in \Sigma_n$, the code $\mathcal{C}_1(\boldsymbol{a},\boldsymbol{b},c,d)$ defined in Construction \ref{constr1} is a $(1,1)$-cirss-cross deletion correcting code.
\end{theorem}

\begin{proof}
We will demonstrate that $\mathcal{C}_1(\boldsymbol{a},\boldsymbol{b},c,d)$ is a $(1,1)$-criss-cross deletion correcting code by presenting a decoding algorithm.
Assume that $\boldsymbol{X} \in \mathcal{C}_1(\boldsymbol{a},\boldsymbol{b},c,d)$ undergoes a row deletion at position $i$ followed by a column deletion at position $j$, resulting in the array $\boldsymbol{Y}$, as illustrated in Figure \ref{fig:array}. 

Observe that for $k\in [1:j-1]\cup [j+1:n]$, the symbol $X_{i,k}$ can be determined as follows:
\begin{equation}\label{eq:row}
  X_{i,k}= a_k- \sum_{t\neq i}X_{t,k} \pmod{q},
\end{equation}
and for $k\in [1:n]$, the symbol $X_{k,j}$ can be computed as:
\begin{equation}\label{eq:column}
  X_{k,j}= b_k- \sum_{t\neq j}X_{k,t} \pmod{q}.
\end{equation}
We define an array $\boldsymbol{X}'' \in \Sigma_q^{n \times n}$ that satisfies the row/column sum constraints, where the subarray indexed by the first $n-1$ rows and the first $n-1$ columns is equal to $\boldsymbol{Y}$.
Clearly, by Figure \ref{fig:array}, $\boldsymbol{X}'' \in \Sigma_q^{n \times n}$ can be obtained from $\boldsymbol{X}$ by moving its $i$-th row to the bottom followed by shifting its $j$-th column to rightmost position.

Next, we consider the column sum representation of $\boldsymbol{X}''$, denoted as $\mathrm{CCR}(\boldsymbol{X}'')$. 
We observe that $\mathrm{CCR}(\boldsymbol{X}'')_{[1:n-1]}$ is obtained from $\mathrm{CCR}(\boldsymbol{X})$ by deleting $\mathrm{CCR}(X'')_n$ at position $j$.
Since $\sum_{t=1}^{n-1} t \cdot \alpha(\mathrm{CCR}(\boldsymbol{X}))_t \equiv c \pmod{n}$, by Corollary \ref{cor:VTdecoder}, we can utilize the non-binary VT decoder to recover $\mathrm{CCR}(\boldsymbol{X})$ from $\mathrm{CCR}(\boldsymbol{X}'')$.
Moreover, given that $\mathrm{CCR}(X)_k \neq \mathrm{CCR}(X)_{k+1}$ for $k \in [1:n-1]$, we can precisely determine the column deletion position $ j $ by comparing $\mathrm{CCR}(\boldsymbol{X})_{[1:n-1]}''$ and the recovered $\mathrm{CCR}(\boldsymbol{X})$.
We then move the last column of $\boldsymbol{X}''$ to the $ j $-th column to obtain the desired array $\boldsymbol{X}'$.
%This leads us to cyclically left-shift the last column of $\boldsymbol{X}''$, one position at a time, until the resulting array satisfies the column composition constraints. 
%At this point, we denote the array as $\boldsymbol{X}'$.
Note that, by Figure \ref{fig:array}, $\boldsymbol{X}'$ can be obtained from $\boldsymbol{X}$ by moving its $i$-th row to the bottom.

Now, we consider the row integer representation of $\boldsymbol{X}'$, denoted as $\mathrm{RIR}(\boldsymbol{X}')$. 
We find that $\mathrm{RIR}(\boldsymbol{X}')_{[1:n-1]}$ is derived from $\mathrm{RIR}(\boldsymbol{X})$ by deleting $\mathrm{RIR}(X')_n$ at position $i$.
Since $\sum_{t=1}^{n-1} t \cdot \alpha(\mathrm{RIR}(\boldsymbol{X}))_t \equiv d \pmod{n}$, by Corollary \ref{cor:VTdecoder}, we can again employ the non-binary VT decoder to recover $\mathrm{RIR}(\boldsymbol{X})$ from $\mathrm{RIR}(\boldsymbol{X}')$.
%This leads us to cyclically up-shift the last row of $\boldsymbol{X}'$, one position at a time, until the resulting array satisfies row integer constraint. 
This process yields the correct $\boldsymbol{X}$, as the function $\mathrm{RIR}(\cdot)$ is a bijection.
The proof is completed.
\end{proof}

\begin{remark}
The decoding algorithm described in the proof of Theorem \ref{thm:non-binary} operates with a time complexity of $O(n^2)$, as detailed below:
\begin{itemize}
    \item Each $X_{i,k}$ and $X_{k,j}$ can be computed in $O(n)$ time. Since a total of $2n-1$ values need to be calculated, the overall complexity for this step is $O(n^2)$.
    \item The composition of each column can also be computed in $O(n)$ time. With $n$ columns to calculate, the overall complexity for this step is $O(n^2)$.
    \item The non-binary VT decoder operates in $O(n)$ time.
    \item The location of the column deletion can be determined in $O(n)$ time when obtaining $\mathrm{CCR}(\boldsymbol{X})_{[1:n-1]}''$ and $\mathrm{CCR}(\boldsymbol{X})$.
    \item The integer representation of each row can be computed in $O(n)$ time. Since there are $n$ rows to calculate, the overall complexity for this step is $O(n^2)$.
\end{itemize}
In summary, the total complexity is linear with respect to the codeword size, which makes it optimal for two-dimensional scenarios.
\end{remark}

To determine the redundancy of $\mathcal{C}_1(\boldsymbol{a},\boldsymbol{b},c,d)$, we need to calculate the number of arrays for which the column composition representation satisfies the condition that adjacent entries are distinct.

\begin{definition}\label{def:good}
  An array $\boldsymbol{X} \in \Sigma_q^{n \times n}$ is called \emph{good} if the compositions of any two adjacent columns of $\boldsymbol{X}$ are distinct.
\end{definition}

In the following, we will assume $n$ is a multiple of $q$. In cases where this assumption does not hold, we may need to use either the floor or ceiling function in specific instances.
While this could introduce more intricate notation, it does not affect the asymptotic analysis when using Stirling’s formula.

\begin{lemma}\label{lem:good}
  When $q\geq 3$, $n\geq q^2$, and $q|n$, the number of $q$-ary good arrays of size $n\times n$ is at least $q^{n^2-1}$.
\end{lemma}

\begin{proof}
Let $M$ denote the maximum size of a set of $q$-ary sequences of length $n$ with identical composition. 
Then, the number of $q$-ary good arrays is lower bounded by
\begin{equation}\label{eq:number}
  q^n\left(q^n-M \right)^{n-1}
  = q^{n^2} \left( 1-\frac{M}{q^n} \right)^{n-1}.
\end{equation}
In what follows, we will demonstrate that $M\leq \frac{q^n}{n}\leq \frac{q^n}{n-1}$.
Once this is established, we can further evaluate Equation (\ref{eq:number}) as follows:
\begin{align*}
    q^n\left(q^n-M \right)^{n-1}
    &= q^{n^2} \left( 1-\frac{M}{q^n} \right)^{n-1} \\
    &\geq q^{n^2} \left( 1-\frac{1}{n-1} \right)^{n-1}\\
    &\geq q^{n^2-1},
\end{align*}
where the last inequality follows from the fact that $\left(1-\frac{1}{n-1} \right)^{n-1}$ is an increasing function of $n$ that is always great than or equal to $\left(1-\frac{1}{8}\right)^8\geq \frac{1}{3}\geq \frac{1}{q}$ when $n\geq q^2$ and $q\geq 3$.


Next, we show that the inequality $M\leq \frac{q^n}{n}$ holds. By definition, we have
\begin{align*}
  M\leq \binom{n}{\frac{n}{q}, \frac{n}{q}, \ldots, \frac{n}{q}}= \frac{n!}{\left(\frac{n}{q}!\right)^q}.
\end{align*}
By \cite[Page 6, Equation (1.7)]{Jukna}, we can use the well-known Stirling's formula to obtain the following bounds for $n!$:
\begin{equation}\label{eq:stirling}
    \sqrt{2\pi n} \left(\frac{n}{e}\right)^n e^{\frac{1}{12n+1}}< n! \leq \sqrt{2\pi n}\left(\frac{n}{e} \right)^n e^{\frac{1}{12n}}.
\end{equation}
We can then compute
\begin{align}\label{eq:M}
  M\leq \frac{n!}{\left(\frac{n}{q}!\right)^q} 
  &\leq \frac{\sqrt{2\pi n}\left(\frac{n}{e} \right)^n e^{\frac{1}{12n}}}{\left( \sqrt{2\pi \frac{n}{q}} \left(\frac{n}{eq}\right)^\frac{n}{q} e^{\frac{1}{12\frac{n}{q}+1}}\right)^q} \nonumber \\
  &= \frac{\sqrt{2\pi n}}{\sqrt{\left(2\pi \frac{n}{q}\right)^q}} \cdot \frac{\left(\frac{n}{e} \right)^n}{\left(\frac{n}{eq}\right)^n} \cdot \frac{e^{\frac{1}{12n}}}{e^{\frac{q^2}{12n+q}}} \nonumber\\
  &\leq \sqrt{\frac{q^q}{(2\pi)^{q-1}n^{q-3}}} \cdot \frac{q^n}{n} \\
  &\leq \frac{q^n}{n}\nonumber,
\end{align}
where the last inequality follows by the fact that 
\begin{itemize}
  \item when $q=3$, $\sqrt{\frac{q^q}{(2\pi)^{q-1}n^{q-3}}}= \frac{3\sqrt{3}}{2\pi}\leq 1$;
  \item when $4\leq q\leq 5$, $\sqrt{\frac{q^q}{(2\pi)^{q-1}n^{q-3}}}\leq \sqrt{\frac{q^q}{(2\pi)^{q-1}q^{2(q-3)}}} \leq \left(\frac{q}{2\pi}\right)^{\frac{q-1}{2}}\leq 1$;
  \item when $q\geq 6$, $\sqrt{\frac{q^q}{(2\pi)^{q-1}n^{q-3}}}\leq \sqrt{\frac{q^q}{(2\pi)^{q-1}q^{2(q-3)}}} \leq \left(\frac{1}{2\pi}\right)^{\frac{q-1}{2}}\leq 1$.
\end{itemize}
The proof is completed.
\end{proof}


\begin{remark}\label{rmk:binary}
  When $q=2$, we can establish that $M\leq K\cdot \frac{q^n}{\sqrt{n}}$ for some constant $K$, by utilizing Equation (\ref{eq:M}).  In this scenario, there exists some constant $K'$ such that the quantity $q^n\left(q^n-M \right)^{n-1}$ can be estimated as follows:
  \begin{align*}
    q^n\left(q^n-M \right)^{n-1}\sim q^{n^2} \left(1-\frac{K'}{\sqrt{n}} \right)^{n}\stackrel{(\ast)}{\sim} \frac{q^{n^2}}{e^{\sqrt{n}K'}},
  \end{align*}
  where $(\ast)$ follows from the fact that $\left(1-\frac{1}{m} \right)^{m}$ approaches $\frac{1}{e}$ as $m$ increases.
  The resulting redundancy is of order $\sqrt{n}$.
  Consequently, the code defined in Construction \ref{constr1} may be significantly distant from the optimal redundancy.
\end{remark}

With the help of Lemma \ref{lem:good}, we are now prepared to calculate the redundancy of $\mathcal{C}_1(\boldsymbol{a},\boldsymbol{b},c,d)$.

\begin{corollary}
  When $q\geq 3$, $n\geq q^2$, and $q|n$, there exists a choice of parameters such that the redundancy of $\mathcal{C}_1(\boldsymbol{a},\boldsymbol{b},c,d)$ (as defined in Construction \ref{constr1}) is at most $2n\log q+2\log n+\log q$, which is optimal up to an additive constant.
\end{corollary}

\begin{proof}
By considering all possible choices for $\boldsymbol{a}, \boldsymbol{b} \in \Sigma_q^n$ and $c, d \in \Sigma_n$, we find that the total number of codes $\mathcal{C}_1(\boldsymbol{a}, \boldsymbol{b}, c, d)$ is $n^2 q^{2n}$, which forms a partition of good arrays in $\Sigma_q^{n \times n}$. Consequently, by the pigeonhole principle, there exists at least one choice of $\boldsymbol{a}, \boldsymbol{b} \in \Sigma_q^n$ and $c, d \in \Sigma_n$ such that the code $\mathcal{C}_1(\boldsymbol{a}, \boldsymbol{b}, c, d)$ contains at least $\frac{q^{n^2-1}}{n^2q^{2n}}$ codewords. Thus, the conclusion follows.
\end{proof}

\begin{remark}\label{rmk:improve}
  We can improve the redundancy of $\mathcal{C}_1(\boldsymbol{a}, \boldsymbol{b}, c, d)$ to $2n\log q+2\log n$ by considering the following relaxed version of the row/column sum constraints imposed in Construction \ref{constr1}:
  \begin{gather*}
    \sum_{t=1}^n X_{t,k} \equiv a_k \pmod{q} \text{ for } k\in [1:n],\\
    \sum_{t=1}^n X_{k,t} \equiv b_k \pmod{q} \text{ for } k\in [1:n-1].
  \end{gather*}
  The rationale behind this adjustment is that the quantity $\sum_{t=1}^n X_{n,t} \pmod{q}$ can be determined using the values $(a_1,a_2,\ldots,a_n)$ and $(b_1,b_2,\ldots,b_{n-1})$:
  \begin{align*}
    \sum_{t=1}^n X_{n,t}
    &= \sum_{k=1}^n \sum_{t=1}^n X_{k,t}- \sum_{k=1}^{n-1} \sum_{t=1}^n X_{k,t}\\
    &= \sum_{k=1}^n \sum_{t=1}^n X_{t,k}- \sum_{k=1}^{n-1} \sum_{t=1}^n X_{k,t}\\
    &\equiv \sum_{k=1}^n a_k- \sum_{k=1}^{n-1} b_k \pmod{q}.
  \end{align*}
\end{remark}


\section{Construction of Optimal \texorpdfstring{$(1,1)$}{}-Criss-Cross deletion correcting  Codes over Arbitrary Alphaets}\label{sec:binary}%

This section presents a construction of $(1,1)$-criss-cross deletion correcting codes that exhibits optimal redundancy (up to an additive constant term) over arbitrary alphabets. As noted in Remark \ref{rmk:binary}, the code defined in Construction \ref{constr1} may be inefficient for the binary alphabet due to the high redundancy associated with good arrays. Consequently, we need to introduce several new ideas.  

Our main strategy is to identify appropriate constraints for each codeword over the binary alphabet that require a redundancy of $O(1)$ and fulfill the same role as the good array introduced in Definition \ref{def:good}. By relaxing the requirements of the good array and adding several additional constraints, we achieve this goal and derive an optimal $(1,1)$-criss-cross deletion correcting code. %modifying the constraints imposed on the rows
Let $\boldsymbol{X}, \boldsymbol{X}', \boldsymbol{X}'', \boldsymbol{Y}$ be defined in Figure \ref{fig:array}, the detailed approach is explained  as follows:

\begin{itemize}
  \item \emph{Determine the missing symbols in each row and column:} 
  This step follows the procedure introduced in the previous section, allowing us to derive $\boldsymbol{X}''$ from $\boldsymbol{Y}$.

  \item \emph{Locate the row deletion position $i$ and the column deletion position $j$ within small intervals:} Using $\boldsymbol{X}''$, we can determine the composition of each column of $\boldsymbol{X}$. 
  This enables us to compute $\mathrm{CCR}(\boldsymbol{X})$. We require that $\mathrm{CCR}(\boldsymbol{X})$ belongs to a one-dimensional single deletion correcting code, with the additional constraint that no three consecutive entries are all identical.
  Following the approach of the previous section, we can recover $\mathrm{CCR}(\boldsymbol{X})$. However,  since adjacent entries in $\mathrm{CCR}(\boldsymbol{X})$ may be identical, the column deletion position $j$ can only be localized to an interval of length two in the worst case. 
  Similarly, by applying the same constraints to the rows of $\boldsymbol{X}$ as those applied to the columns, we can also locate the row deletion position $i$ within an interval of length two in the worst case. 

  \item \emph{Determine the column deletion position $j$:} Let $\ell > 0$ be an integer satisfying $\frac{n}{\ell} \geq 3$.
      We consider three subarrays: $\boldsymbol{X}_{[1:\ell],[1:n]}$, $\boldsymbol{X}_{[\ell+1,2\ell],[1:n]}$, and $\boldsymbol{X}_{[2\ell+1:3\ell],[1:n]}$. Since two adjacent rows can span at most two of these subarrays, we independently encode these subarrays to ensure that at least one subarray, without loss of generality, assumed to be the first subarray $\boldsymbol{X}_{[1:\ell],[1:n]}$, does not experience a row deletion.
      We observe that $\boldsymbol{X}_{[1:\ell],[1:n-1]}''$ is derived from $\boldsymbol{X}_{[1:\ell],[1:n]}$ by deleting its $j$-th column $\boldsymbol{X}_{[1:\ell],n}''$. 
      By mapping each column of $\boldsymbol{X}_{[1:\ell],[1:n]}$ as an integer (using a bijective mapping), we obtain a vector 
      \[\mathrm{CIR}(\boldsymbol{X}_{[1:\ell],[1:n]}):= \mathrm{RIR}\big((\boldsymbol{X}_{[1:\ell],[1:n]})^T\big),\] 
      which has length $ n $ and is defined over an alphabet of size $ q^{\ell} $.
       We then record the parity of the number of inversions in $\mathrm{CIR}(\boldsymbol{X}_{[1:\ell],[1:n]})$.
       Here, the number of inversions in a sequence $ \boldsymbol{u} $ of length $ n $ is defined as 
       \[
        \mathrm{Inv}(\boldsymbol{u}):= \left| \{(s,t) : 1 \leq s < t \leq n, u_s > u_t \} \right|.
       \]
       %In other words, $ \mathrm{Inv}(\boldsymbol{u}) $ counts the number of pairs $ (s,t) $ such that $ s< t$ and $ u_s > u_t$.
       This constraint allows us to recover $\mathrm{CIR}(\boldsymbol{X}_{[1:\ell],[1:n]})$ given $\mathrm{CIR}(\boldsymbol{X}_{[1:\ell],[1:n]}'')$ and an interval of length at most two containing the column deletion position $ j $.
       Additionally, we require that any two consecutive entries in $\mathrm{CIR}(\boldsymbol{X}_{[1:\ell],[1:n]})$ are distinct. This condition enables us to precisely determine the column deletion position $ j $ by comparing $\mathrm{CIR}(\boldsymbol{X}_{[1:\ell],[1:n]})$ with $\mathrm{CIR}(\boldsymbol{X}_{[1:\ell],[1:n]}'')$.
       Finally, we move the last column of $\boldsymbol{X}''$ to the $j$-th column to obtain the desired array $\boldsymbol{X}'$.


  \item \emph{Recover the array $\boldsymbol{X}$:}
      From the recovered $\boldsymbol{X}'$, we can compute its row integer representation $\mathrm{RIR}(\boldsymbol{X}')$.
      Observe that $\mathrm{RIR}(\boldsymbol{X}')_{[1:n-1]}$ is obtained from $\mathrm{RIR}(\boldsymbol{X})$ by deleting its $i$-th entry $\mathrm{RIR}(X')_{n}$.
      By recording the parity of the number of inversions in $\mathrm{RIR}(\boldsymbol{X})$, we can recover $\mathrm{RIR}(\boldsymbol{X})$ by using $\mathrm{RIR}(\boldsymbol{X}')$ and an interval of length at most two that contains the row deletion position $ i $.
      This process yields the correct $\boldsymbol{X}$, as the function $\mathrm{RIR}(\cdot)$ is a bijection.
\end{itemize}


Before presenting our code construction, we provide the following definition to be used.

\begin{definition}\label{def:valid}
Let $\ell$ be a positive integer satisfying $n\geq 3\ell$, an array $\boldsymbol{X} \in \Sigma_q^{n \times n}$ is termed \emph{$\ell$-valid} if it satisfies the following conditions:
\begin{itemize}
    \item The compositions of any three consecutive columns of $\boldsymbol{X}$ are not all identical.
    \item The compositions of any three consecutive rows of $\boldsymbol{X}$ are not all identical.
    \item For $k\in [1:3]$, in rows $(k-1)\ell+1$ to $k\ell$ of $ \boldsymbol{X} $, any two adjacent columns are distinct.
\end{itemize}
Moreover, if $\boldsymbol{X}$ satisfies only the last condition, we say that $\boldsymbol{X}$ is \emph{$\ell$-weakly-valid}.
\end{definition}

Our code construction is presented as follows.

\begin{construction}\label{constr2}
  Let $\ell$ be a positive integer satisfying $n\geq 3\ell$. For fixed sequences $\boldsymbol{a}= (a_1,a_2,\cdots,a_n)\in \Sigma_q^n$, $\boldsymbol{b}= (b_1,b_2,\ldots,b_{n-1})\in \Sigma_q^{n-1}$,  $\boldsymbol{c}= (c_1,c_2)\in \Sigma_n^2$, and $\boldsymbol{d}=(d_1,d_2,d_3,d_4)\in \Sigma_2^4$, we define the code $\mathcal{C}_2(\boldsymbol{a},\boldsymbol{b},\boldsymbol{c},\boldsymbol{d})$ in which each array $\boldsymbol{X}$ satisfies the following constraints:
  \begin{itemize}
    \item $\boldsymbol{X}$ is $\ell$-valid;
    \item \emph{Row/Column Sum Constraints:} $\sum_{t=1}^n X_{t,k} \equiv a_k \pmod{q}$ for $k\in [1:n]$ and $\sum_{t=1}^n X_{k,t} \equiv b_k \pmod{q}$ for $k\in [1:n-1]$;
    \item \emph{Row/Column Composition Constraints:} $\sum_{t=1}^{n-1} t \cdot \alpha\big(\mathrm{CCR}(X)\big)_t \equiv c_1 \pmod{n}$ and $\sum_{t=1}^{n-1} t \cdot \alpha\big(\mathrm{CCR}(X^T)\big)_t \equiv c_2 \pmod{n}$;
    \item \emph{Row/Column Inversion Constraints:}  $\mathrm{Inv}\big(\mathrm{CIR}(\boldsymbol{X}_{[(k-1)\ell+1:k\ell], [1:n]})\big) \equiv d_k \pmod{2}$ for $k\in [1:3]$ and $\mathrm{Inv}\big(\mathrm{RIR}(\boldsymbol{X})\big) \equiv d_4 \pmod{2}$.%where $\mathrm{CIR}(X_{[(k-1)\ell+1:k\ell], [1:n]}):= \mathrm{RIR}\big((X_{[(k-1)\ell+1:k\ell], [1:n]})^T\big)$,
  \end{itemize}
\end{construction}

\begin{theorem}\label{thm:binary}
  Let $\ell\geq 1$ be an integer satisfying $n\geq 3\ell$. For fixed sequences $\boldsymbol{a}= (a_1,a_2,\cdots,a_n)\in \Sigma_q^n$, $\boldsymbol{b}= (b_1,b_2,\ldots,b_{n-1})\in \Sigma_q^{n-1}$,  $\boldsymbol{c}= (c_1,c_2)\in \Sigma_n^2$, and $\boldsymbol{d}=(d_1,d_2,d_3,d_4)\in \Sigma_2^4$, the code $\mathcal{C}_2(\boldsymbol{a},\boldsymbol{b},\boldsymbol{c},\boldsymbol{d})$ defined in Construction \ref{constr2} is a $(1,1)$-cirss-cross deletion correcting code.
\end{theorem}

\begin{proof}
We will demonstrate that $\mathcal{C}_2(\boldsymbol{a},\boldsymbol{b},\boldsymbol{c},\boldsymbol{d})$ is a $(1,1)$-criss-cross deletion correcting code by presenting a decoding algorithm.
Assume that $\boldsymbol{X} \in \mathcal{C}_2(\boldsymbol{a},\boldsymbol{b},\boldsymbol{c},\boldsymbol{d})$ undergoes a row deletion at position $i$ followed by a column deletion at position $j$, resulting in the array $\boldsymbol{Y}$, as illustrated in Figure \ref{fig:array}. 

We define an array $\boldsymbol{X}'' \in \Sigma_q^{n \times n}$ that satisfies the row/column sum constraints, where the subarray indexed by the first $n-1$ rows and the first $n-1$ columns is equal to $\boldsymbol{Y}$.
Combining Remark \ref{rmk:binary} with Equations (\ref{eq:row}) and (\ref{eq:column}), we can conclude that $\boldsymbol{X}'' \in \Sigma_q^{n \times n}$ is obtained from $\boldsymbol{X}$ by moving its $i$-th row to the bottom followed by shifting its $j$-th column to rightmost position.

Next, we consider the column composition representation of $\boldsymbol{X}''$, denoted as $\mathrm{CCR}(\boldsymbol{X}'')$. 
We observe that $\mathrm{CCR}(\boldsymbol{X}'')_{[1:n-1]}$ is obtained from $\mathrm{CCR}(\boldsymbol{X})$ by deleting $\mathrm{CCR}(X'')_n$ at position $j$.
Since $\sum_{t=1}^{n-1} t \cdot \alpha(\mathrm{CCR}(\boldsymbol{X}))_t \equiv c \pmod{n}$, by Corollary \ref{cor:VTdecoder}, we can utilize the non-binary VT decoder to recover $\mathrm{CCR}(\boldsymbol{X})$ from $\mathrm{CCR}(\boldsymbol{X}'')$.
Furthermore, since $\boldsymbol{X}$ is valid, the compositions of any three consecutive columns of $\boldsymbol{X}$ are not all identical.
As a result, in the worst case, we can locate the column deletion position $j$ in an interval of length two by comparing $\mathrm{CCR}(\boldsymbol{X})_{[1:n-1]}''$ with the recovered $\mathrm{CCR}(\boldsymbol{X})$.
Similarly, we can locate the row
deletion position $i$ within an interval of length two in the worst case.

Since we have identified two consecutive positions, one of which is $ i $, there exists some $ k \in [1:3] $ such that $ i \not\in [(k-1)\ell+ 1: k\ell] $. Without loss of generality assume $k=1$, then the subarray $\boldsymbol{X}_{[1:\ell],[1:n]}''$ does not experience a row deletion. Consequently, the subarray $\boldsymbol{X}_{[1: \ell],[1:n-1]}''$ is obtained from $\boldsymbol{X}_{[1: \ell],[1:n]}$ by deleting its $ j $-th column, $\boldsymbol{X}_{[1: \ell],n}''$.
Now, consider the vector $\mathrm{CIR}(\boldsymbol{X}_{[1: \ell],[1:n]})$, which records the integer representation of each column of $\boldsymbol{X}_{[1: \ell],[1:n]}$. It follows that $\mathrm{CIR}(\boldsymbol{X}_{[1: \ell],[1:n-1]}'')$ is obtained from $\mathrm{CIR}(\boldsymbol{X}_{[1: \ell],[1:n]})$ by deleting its $ j $-th entry, $\mathrm{CIR}(\boldsymbol{X}_{[1: \ell],n}'')$.
Since $\boldsymbol{X}$ is valid, in the first $\ell$ rows of $ \boldsymbol{X} $, any two adjacent columns are distinct.
Recall that we have identified an interval of length two containing $ j $. It follows by \cite[Lemma 6.9]{Sun-23-IT-BDR} that inserting $\mathrm{CIR}(\boldsymbol{X}_{[1: \ell],n}'')$ into these two consecutive positions of $\mathrm{CIR}(\boldsymbol{X}_{[1: \ell],[1:n-1]}'')$ yields two new vectors whose inversions have distinct parities. 
By leveraging the condition $\mathrm{Inv}\big(\mathrm{CIR}(\boldsymbol{X}_{[1: \ell],[1:n]})\big) \equiv d_1 \pmod{2}$, we can precisely determine the column deletion position $ j $.
We then move the last column of $\boldsymbol{X}''$ to the $ j $-th column to obtain the desired array $\boldsymbol{X}'$.

Now, we consider the row integer representation of $\boldsymbol{X}'$, denoted as $\mathrm{RIR}(\boldsymbol{X}')$.
Clearly, $\mathrm{RIR}(\boldsymbol{X}')_{[1:n-1]}$ is obtained from $\mathrm{RIR}(\boldsymbol{X})$ by deleting its $i$-th entry $\mathrm{RIR}(X')_n$.
Recall that we have identified an interval of length two containing $ i $.  
Similar to the previous discussion, we can recover $\mathrm{RIR}(\boldsymbol{X})$ using the condition $\mathrm{Inv}\big(\mathrm{RIR}(\boldsymbol{X})\big) \equiv d_4 \pmod{2}$.
This process yields the correct $\boldsymbol{X}$, as the function $\mathrm{RIR}(\cdot)$ is a bijection.
The proof is completed.
\end{proof}

\begin{remark}
In general, we define the constraint for row/column composition representations to permit maximal runs of $ f-1 $ identical entries while prohibiting runs of length $ f $, where $ f \geq 3 $. When $ f \geq 4 $, deletions can only be localized within intervals of length $ f-1 > 2 $ in the worst case. Under this configuration, inversion-based correction becomes insufficient. To overcome this difficulty, we can employ the non-binary shifted VT code framework from \cite[Lemma 1]{Schoeny-17-SVT} to correct one deletion within a small interval.  
\end{remark}

\begin{remark}\label{rmk:row}
  If we further require that any two consecutive rows in the array $\boldsymbol{X}\in \mathcal{C}_2(\boldsymbol{a},\boldsymbol{b},\boldsymbol{c},\boldsymbol{d})$ are distinct, then decoding $\boldsymbol{X}$, which is distorted by a $(1,1)$-criss-cross deletion, allows us to precisely identify the row and column deletion positions.
  This property will be used later in the construction of the criss-cross burst-deletion correcting code.  
\end{remark}

\begin{remark}
The decoding algorithm described in the proof of Theorem \ref{thm:binary} operates with a time complexity of $O(n^2)$, as detailed below:
\begin{itemize}
    \item Each $X_{i,t}$ and $X_{t,j}$ can be computed in $O(n)$ time. Since a total of $2n-1$ values need to be calculated, the overall complexity for this step is $O(n^2)$.
    \item The composition of each row and column can also be computed in $O(n)$ time. With $n$ rows and $n$ columns to calculate, the overall complexity for this step is $O(n^2)$.
    \item The non-binary VT decoder operates in $O(n)$ time.
    \item Locating the column deletion position $ j $ within an interval of length at most two can be done in $ O(n) $ time when obtaining $\mathrm{CCR}(\boldsymbol{X})_{[1:n-1]}''$ and $\mathrm{CCR}(\boldsymbol{X})$. Similarly, locating the row deletion position $ i $ within an interval of length at most two can also be accomplished in $ O(n) $ time. 
    \item The integer representation of each column of $\boldsymbol{X}_{[(k-1)\ell + 1: k\ell],[1:n]}''$ can be computed in $O(n)$ time. Since there are $n$ columns to calculate, the overall complexity for this step is $O(n^2)$. Similarly, the integer representations of all rows of $\boldsymbol{X}'$ can be computed in $O(n^2)$ time.
    \item The number of inversions in a sequence of length $ n $ can be computed in $ O(n^2) $.
\end{itemize}
In summary, the total complexity is linear with respect to the codeword size, which makes it optimal for two-dimensional scenarios.
\end{remark}

%\begin{remark}
%Although Lemma \ref{lem:equiv} has established the equivalence for codes that correct $(1,1)$-criss-cross deletions and $(1,1)$-criss-cross insdels, the decoding procedures for addressing these two types of errors may differ. It is worth noting that the decoding strategies provided in the proof of Theorems \ref{thm:non-binary} and \ref{thm:binary} for correcting $(1,1)$-criss-cross deletions can be adapted to the $(1,1)$-criss-cross insdels model with slight modifications.
%\end{remark}

To determine the redundancy of $\mathcal{C}_2(\boldsymbol{a},\boldsymbol{b},\boldsymbol{c},\boldsymbol{d})$, we need to calculate the number of valid arrays.
We assume that $n$ is a multiple of $q$. In cases where this assumption does not hold, we may need to use either the floor or ceiling function in specific instances.
While this may introduce more intricate notation, it does not influence the asymptotic analysis when employing Stirling’s formula.

\begin{lemma}\label{lem:valid}
  Assume $n\geq \max\{3\ell, q^2\}$ and $q|n$.
  Let $N$ denote the number of $\ell$-valid arrays of size $n\times n$, the following statements hold:
  \begin{itemize}
      \item if $q=2$, then $N\geq \big(1-\frac{3n}{2^{\ell}}- \frac{2\sqrt{2}}{\pi} \big)\cdot 2^{n^2}$ and $N\geq 0.052\cdot 2^{n^2}$ when $\ell\geq \log n+6$;
      \item if $q\geq 3$, then $N\geq \big(1-\frac{3n}{q^{\ell}}- \frac{2}{n}\big)\cdot q^n \geq \frac{4}{9} \cdot q^{n^2}$ when $\ell\geq \log n+2$.
  \end{itemize}
\end{lemma}

\begin{proof}
    We prove the lemma by a probabilistic analysis.
    Choose an array $\boldsymbol{X}\in \Sigma_q^{n\times n}$ uniformly at random, let $P$ be the probability that $\boldsymbol{X}$ is not valid, then the number of valid arrays of size $n\times n$ is given by $(1-P)\cdot q^{n^2}$.
    To complete the proof, it remains to show that $P\leq \frac{3n}{2^{\ell}}+ \frac{2\sqrt{2}}{\pi}$ when $q=2$ and $P\leq \frac{3n}{q^{\ell}}+\frac{2}{n}$ when $q\geq 3$, which we will demonstrate as follows.

    For $k\in [1:3]$, let $p_k$ denote the probability that in rows $(k-1)\ell+1$ to $k\ell$ of $ \boldsymbol{X} $, there exist two adjacent columns which are identical.
    Clearly, we have $p_1=p_2=p_3$.
    Moreover, we let $p_4$ (respectively, $p_5$) represent the probability that there exist three consecutive columns (respectively, rows) of $\boldsymbol{X}$ whose compositions are all identical.
    It is clear that $p_4=p_5$.
    Then by the definition of valid array and by the union bound, we can calculate $P\leq 3p_1+2p_4$.

    We first provide an upper bound on the value of $p_1$.
    For any $t\in [1:n-1]$, the probability that in the first $\ell$ rows of $\boldsymbol{X}$, the $t$-th column and the $(t+1)$-th column are identical, i.e., $\boldsymbol{X}_{[1:\ell],t}= \boldsymbol{X}_{[1:\ell],t+1}$, is given by $\frac{1}{q^{\ell}}$.
    Then by the union bound, we can compute $p_1\leq \frac{n}{q^{\ell}}$.

    We now provide an upper bound on the value of $p_4$. For any $t\in [1:n-2]$, the probability that the columns $t$ to $t+2$ of $\boldsymbol{X}$ share a common composition, i.e., $\mathrm{CCR}(X)_t= \mathrm{CCR}(X)_{t+1}= \mathrm{CCR}(X)_{t+2}$, can be calculated as
    \begin{equation*}
        p_4':= \frac{\sum\limits_{s_0+s_1+\cdots+s_{q-1}=n} \binom{n}{s_0,s_1,\ldots,s_{q-1}}^3}{q^{3n}}.
    \end{equation*}
    When $q=2$, we can compute
    \begin{equation}\label{eq:valid}
    \begin{aligned}
      p_4'
      &= \frac{\sum\limits_{m=0}^n \binom{n}{m}^3}{2^{3n}}
      \leq \frac{\binom{n}{\frac{n}{2}} \sum\limits_{m=0}^n \binom{n}{m}^2}{2^{3n}}\\
      &\stackrel{(\ast)}{=} \frac{\binom{n}{\frac{n}{2}} \binom{2n}{n}}{2^{3n}}
      = \frac{(2n)!}{2^{3n} \cdot n! \cdot \left((\frac{n}{2})!\right)^2}\\
      &\stackrel{(\star)}{\leq } \frac{\sqrt{4\pi n} (\frac{2n}{e})^{2n} e^{\frac{1}{24n}}}{2^{3n} \cdot \sqrt{2\pi n} (\frac{n}{e})^n e^{\frac{1}{12n+1}} \cdot \pi n (\frac{n}{2e})^n e^{\frac{2}{6n+1}}}\\
      &\leq \frac{\sqrt{2}}{\pi n},
    \end{aligned}
    \end{equation}
    where $(\ast)$ follows by \cite[Page 17, Exercise 1.10]{Jukna} and $(\star)$ follows by Equation (\ref{eq:stirling}).
    When $q\geq 3$, we can compute
    \begin{align*}
      p_4'
      &\leq \frac{\binom{n}{\frac{n}{q},\frac{n}{q},\ldots,\frac{n}{q}}^2 \sum\limits_{s_0+s_1+\cdots+s_{q-1}=n} \binom{n}{s_0,s_1,\ldots,s_{q-1}}}{q^{3n}}\\
      &=\frac{\binom{n}{\frac{n}{q},\frac{n}{q},\ldots,\frac{n}{q}}^2}{q^{2n}}\leq \frac{1}{n^2},
    \end{align*}
    where the last inequality follows by Equation (\ref{eq:M}).
    Then by the union bound, we can compute
    $p_4\leq np_4' \leq \frac{\sqrt{2}}{\pi}$ when $q=2$ and $p_4\leq np_4' \leq \frac{1}{n}$ when $q\geq 3$.

    Consequently, we get $P= 3p_1+2p_4\leq \frac{3n}{2^{\ell}}+ \frac{2\sqrt{2}}{\pi}$ when $q=2$ and $P= 3p_1+2p_4\leq \frac{3n}{q^{\ell}}+\frac{2}{n}$ when $q\geq 3$.
    Then the conclusion follows.
\end{proof}

\begin{remark}
    It is well known that $ \sum_{m=0}^n \binom{n}{m}^3 $ is the Franel number. For sufficiently large $ n $, we can obtain the following sharp estimation from \cite[Page 282]{Kotesovec}:  
\begin{align*}  
    \sum_{m=0}^n \binom{n}{m}^3 \sim \frac{2^{3n+1}}{\sqrt{3} \pi n}.  
\end{align*}  
This estimation may help provide a tighter bound for the quantity $ N $ defined in Lemma \ref{lem:valid}.   
\end{remark}

With the help of Lemma \ref{lem:valid}, we are now prepared to calculate the redundancy of $\mathcal{C}_2(\boldsymbol{a},\boldsymbol{b},\boldsymbol{c},\boldsymbol{d})$.

\begin{corollary}\label{cor:binary}
  Assume $n\geq \max\{3\ell, q^2\}$ and $q|n$, where $\ell=\lceil \log n \rceil+6$ if $q=2$ and $\ell=\lceil \log n\rceil+2$ if $q\geq 3$. 
  There exists a choice of parameters such that the redundancy of $\mathcal{C}_2(\boldsymbol{a},\boldsymbol{b},\boldsymbol{c},\boldsymbol{d})$ (as defined in Construction \ref{constr2}) is at most $2n+2\log n+3- \log (0.052)$ when $q=2$ and $(2n-1)\log q+2\log n+4- \log \frac{4}{9}$ when $q\geq 3$, which is optimal up to an additive constant.
\end{corollary}

\begin{proof}
By considering all possible choices for $\boldsymbol{a}\in \Sigma_q^n$, $\boldsymbol{b}\in \Sigma_q^{n-1}$,  $\boldsymbol{c}\in \Sigma_n^2$, and $\boldsymbol{d}\in \Sigma_2^4$, we find that the total number of codes $\mathcal{C}_2(\boldsymbol{a},\boldsymbol{b},\boldsymbol{c},\boldsymbol{d})$ is $16 n^2 q^{2n-3}$, which forms a partition of valid arrays in $\Sigma_q^{n \times n}$. Consequently, by the pigeonhole principle, there exists at least one choice of $\boldsymbol{a}\in \Sigma_q^n$, $\boldsymbol{b}\in \Sigma_q^{n-1}$,  $\boldsymbol{c}\in \Sigma_n^2$, and $\boldsymbol{d}\in \Sigma_2^4$, such that the code $\mathcal{C}_2(\boldsymbol{a},\boldsymbol{b},\boldsymbol{c},\boldsymbol{d})$ contains at least $\frac{N}{16n^2q^{2n-3}}$ codewords, where $N$ is defined in Lemma \ref{lem:valid}. Thus, the conclusion follows.
\end{proof}


