\section{Definitions and notations}

Consider a finite field $\F_q$ of characteristic $p$. The elements of $\F_q$ are ordered in some way, and this order is fixed.
For the rest of the paper we fix a natural number $n \geq 1$ and two sets of variables: $E_1$, $\dots$, $E_n$
and $X_1$, $\dots$, $X_n$.

\begin{definition}{\rm The set Mon$(q,n)$ is the set of all monomials $E_1^{\alpha_1}E_2^{\alpha_2}\dots E_n^{\alpha_n}$
with $0 \leq \alpha_i < q$.  There are $q^n$ many such monomials.}
\end{definition}

\begin{definition}{\rm Let $\F_q\{E_1, \dots, E_n\}$ be the vector space over $\F_q$ freely generated by Mon$(q,n)$.

$\F_q\{E_1, \dots, E_n\}$ has dimension $q^n$ over $\F_q$. 
It has also a canonical structure of finite ring induced
by the epimorphism:
\[ s : \F_q[E_1, \dots, E_n] \longrightarrow \F_q\{E_1, \dots, E_n\}\]
with Ker$(s) = (E_1^q-E_1, \dots , E_n^q-E_n)$ as ideal in $\F_q[E_1, \dots , E_n]$. 
Observe that $\F_q \models \,\, \forall x \,\, x^q=x$.}
\end{definition}

\begin{definition}{\rm For  $f:\F_q^n \rightarrow \F_q$  
and a permutation $\sigma \in S_n$ we define  $f^\sigma({\vec X}) 
= f(\sigma (\vec X))$ where $\sigma (\vec X) = (X_{\sigma(1)}, \dots, X_{\sigma(n)})$.
The function $f$ is called symmetric if  for all  $\sigma \in S_n$, $f = f^\sigma$. }
\end{definition}

\begin{definition}{\rm  Let ${\cal F}(q,n)$ denote the set of all functions
$f:\F_q^n \rightarrow \F_q$ and ${\cal S}(q,n) \subset {\cal F}(q,n)$ 
the subset of all symmetric functions. Both sets equipped with the 
point-wise operations are finite rings and finite vector spaces over $\F_q$. }
\end{definition}

\begin{definition}{\rm  For every $F \in \F_q[X_1, \dots , X_n]$ and $\sigma \in S_n$
we define $F^\sigma (\vec X) = F(\sigma(\vec X))$, where $\sigma(\vec X) = (X_{\sigma(1)}, \dots , X_{\sigma(n)})$.
$F$ is called symmetric if for all $\sigma \in S_n$, $F^\sigma = F$. }
\end{definition}

\begin{definition}{\rm For $0 \leq k \leq n$ denote by ${\cal P}^n_k$ be
the set of $k$-element subsets of $\{1, \dots, n\}$. 
Recall that the elementary symmetric polynomials $e_k(X_1, \dots , X_n)$ are defined as:
\[e_k(X_1, \dots, X_n) = \sum \limits _{ J \in {\cal P}^n_k} \prod \limits _{i \in J} X_i.\] }
\end{definition}

\begin{definition}{\rm Consider the function
\[ \Phi : \F_q \{E_1, \dots, E_n \} \longrightarrow {\cal S}(q,n) \]
defined such that
\[\forall \vec a \in \F_q^n \,\,\,\, \Phi(f)(\vec a) = f(e_1(\vec a), \dots , e_n(\vec a)), \]
where $f \in \F_q\{E_1, \dots, E_n\}$. Here we understand $E_k$ as a symbol for the elementary symmetric polynomial $e_k$.
$\Phi$ is a well defined homomorphism of finite rings and  finite $\F_q$-vector spaces. }
\end{definition}

\begin{definition}{\rm The ideal ${\cal I}(q,n) =$ Ker$(\Phi) \subset \F_q\{E_1, \dots, E_n\}$ 
is the {\bf ideal of algebraic relations} 
between elementary symmetric functions over $\F_q$.  }
\end{definition}

${\cal I}(q,n)$ is also a vector subspace of $\F_q\{e_1, \dots, e_n\}$.

We also consider the following chain of homomorphisms:

\[\F_q\{E_1, \dots, E_n\}   \xrightarrow{  \Psi  } \F_q\{X_1, \dots , X_n\} 
\xrightarrow{  \Gamma  } {\cal F}(q,n),\]

where $\Psi (P) = P(\vec e (\vec X)) $ is the substitution homomorphism 
and $\Gamma $ is the homomorphism associating to every polynomial $Q$ its polynomial function.
Of course $\Phi = \Gamma \circ \Psi$.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{The number of algebraic relations}


\begin{definition}{\rm Let WM$(q,n)$ be the set of all weakly  monotone increasing tuples $(a_1, \dots, a_n)$ 
in $\F_q$ according to the fixed order. Denote by wm$(q,n)$ the cardinality of the set WM$(q,n)$. }
\end{definition}

\begin{lemma}\label{wm}
\[{\rm dim}_{\F_q} \,\, {\cal S}(q,n) = {\rm wm}(q,n) = \binom{n+q-1}{n}.\]
\end{lemma}

{\bf Proof}:  In order to define an $f \in {\cal S}(q,n)$, 
it is enough to define its values for every ${\vec \iota} \in$ WM$(q,n)$.
This number of sequences is the same as the number of possibilities to put $n$ unsigned balls in $q$ numbered urns, see \cite{WF}. As done there, the $q$ urns can be represented by $q+1$ vertical bars and the $n$ balls as $n$ circles. A possible distribution as it follows:
\[| \circ | | \circ \circ ||\]
Because the first and the last symbols in distribution must be bars, we have to distribute $n$ circles in $n+q-1$ positions and to complete the remaining positions with bars. There are
\[\binom{n+q-1}{n}\]
possibilities to do so.\qed

\begin{definition}{\rm Consider the following matrix 
$M(q,n) \in {\cal M}({\rm wm}(q,n) \times q^n , \F_q)$. The rows of $M(q,n)$ are 
indexed using the tuples $\vec \iota \in $ WM$(q,n)$, 
the columns are indexed using the monomials $m \in $ Mon$(q,n)$, 
and if $M(q,n) = (a(\vec \iota, m)\,\,|\,\, \vec \iota \in {\rm WM}(q,n), m \in {\rm Mon}(q,n))$,
\[a(\vec \iota, m) = [\Phi(m)](\vec \iota) = e_1^{\alpha_1}({\vec \iota}) \dots e_n^{\alpha_n}({\vec \iota}),\]
where $m = E_1^{\alpha_1}\dots E_n^{\alpha_n}$.
 }
\end{definition}

\begin{lemma}\label{surj}

The morphism $\Phi: \F_q \{E_1, \dots, E_n \} \rightarrow {\cal S}(q,n)$ with 
${\rm Ker}\,\,\Phi = {\cal I}(q,n)$ 
is surjective.

\end{lemma}

{\bf Proof}: The proof consists of two steps. 

{\bf Step} 1: Let $f : \F_q^n \rightarrow \F_q $ be some function, for the moment not necessarily symmetric. 
For $a \in \F_q$ 
define the polynomial $h_a \in \F_q[X]$:
\[h_a(X) = \prod \limits _{\lambda \in \F_q \setminus \{a\}} \frac{X-\lambda}{a - \lambda}.\]
Observe that $h_a(a) = 1$ and $h_a(\F_q\setminus \{a\}) = 0$. For a tuple $\vec a \in \F_q^n$ 
define $h_{\vec a} \in \F_q[X_1, \dots, X_n]$:
\[h_{\vec a}(\vec X) = h_{a_1}(X_1)\dots h_{a_n}(X_n).\]
A polynomial interpolating $f$ is:
\[H(\vec X) = \sum \limits _{\vec a \in \F_q^n} h_{\vec a}(\vec X) f(\vec a).\]
We observe that for all $\sigma \in S_n$, 
${(h_{\vec a})} ^\sigma = h_{\sigma ^ {-1}(\vec a)}$. 
If the function $f$ is symmetric, then $f^\sigma = f$ and it follows:
\[H^\sigma(\vec X) = \sum \limits _{\vec a \in \F_q^n} h_{\vec a}^\sigma(\vec X) f(\vec a) 
= \sum \limits _{\sigma ^{-1}(\vec a) \in \F_q^n} h_{\sigma ^{-1}(\vec a)}(\vec X) f(\sigma ^{-1}(\vec a)) = H(\vec X).\]
We proved that the interpolation algorithm applied to a symmetric function leads to a symmetric polynomial. 
Observe also that all exponents occurring in $H$ are $< q$.

{\bf Step} 2: We repeat the argument that a symmetric polynomial 
is a polynomial in elementary symmetric polynomials as given in \cite{BLW} and reformulated in \cite{BS}.
The following total order is defined over the set of monomials in $\vec X$: 
$X_1^{\alpha_1} \dots  X_n^{\alpha_n} < X_1^{\beta_1} \dots  X_n^{\beta_n}$ 
if and only if $\sum \alpha_i < \sum \beta_i$ or 
$\sum \alpha_i = \sum \beta_i$ but $(\alpha_i) < (\beta_i)$ lexicographically. This is the graded lexicographic order.
For a polynomial $H(\vec X) \in \F_q[\vec X]$ define
Init$(H)$ to be the maximal monomial occurring in $H$, according to this order. 
It follows from symmetry that Init$(H)$ has the form 
$cX_1^{\gamma_1} \dots X_n^{\gamma_n}$ with $\gamma_1 \geq \gamma_2 \geq \dots \geq \gamma_n$ 
with $c \in \F_q \setminus\{0\}$. 
Consider the polynomial:
\[ H_1(\vec X) = H(\vec X) - c e_1(\vec X)^{\gamma_1-\gamma_2}e_2(\vec X)^{\gamma_2 - \gamma_3} 
\dots e_{n-1}(\vec X)^{\gamma_{n-1}-\gamma_n} e_n(\vec X)^{\gamma_n}.\]
Observe that Init$(H_1)$ $<$ Init$(H)$. Continue by constructing in the same way a polynomial
$H_2$ with Init$(H_2)$ $< $ Init$(H_1)$, and so on. This process ends in finitely many steps. 
Adding the $S_i$-monomials defined during the process,
one gets a polynomial $F \in \F_q[e_1, \dots , e_n]$ with the property that for all $\vec a \in \F_q^n$, 
$F(e_1(\vec a), \dots , e_n(\vec a)) = f(\vec a)$. Finally, 
observe that all exponents occurring in $F$ are again $< q$, so 
$F \in \F_q\{e_1, \dots , e_n\}$ and $\Phi(F) = f$. 

\qed


\begin{theo} \label{main}
The rank of the matrix $M(q,n)$ is maximal:
\[{\rm rank} \,\, M(q,n) = {\rm wm}(q,n) = \binom{n+q-1}{n}.\]
The dimension of the ideal ${\cal I}(q,n)$ of algebraic relations as a vector space over $\F_q$ is:
\[ {\rm dim}_{\F_q} {\cal I}(q,n) = q^n - {\rm wm}(q,n) = q^n - \binom{n+q-1}{n}.\]

\end{theo}

{\bf Proof}: Follows directly from Lemma \ref{wm} and the  Lemma \ref{surj}. \qed



\begin{remark}{\rm
If $q$ is kept constant and $n \rightarrow \infty$,
\[ \frac{{\rm dim}_{\F_q} {\cal I}(q,n)}{{\rm dim}_{\F_q} \F_q\{S_1, \dots , S_n\} } \,\, \longrightarrow \,\, 1.\]
If $n$ is kept constant and $q \rightarrow \infty$,
\[ \frac{{\rm dim}_{\F_q} {\cal I}(q,n)}{{\rm dim}_{\F_q} \F_q\{S_1, \dots , S_n\} } \,\, \longrightarrow \,\, 1 - 
\frac{1}{n!}.\]}
\end{remark}


Indeed, if $q$ is kept constant and $n \rightarrow \infty$,
\[\frac{q^n - \binom{n+q-1}{n}}{q^n} = 1-\frac{1}{(q-1)!}\frac{(n+1)\dots (n+q-1)}{q^n} \,\, \longrightarrow \,\,1.\]
If $n$ is kept constant and $q \rightarrow \infty$,
\[\frac{q^n - \binom{n+q-1}{n}}{q^n} =  1 - \frac{1}{n!} \frac{q(q+1)\dots(q+n-1)}{q^n} \,\, \longrightarrow \,\, 1 - 
\frac{1}{n!}.\]


\begin{remark}{\rm Define the set of non-monotone tuples NM$(q,p)$ as the set of tuples 
$(a_1, \dots , a_n)$ with $a_i \in \F_q$
such that there are $1 \leq i < j \leq n$ with $a_i > a_j$ according to the order fixed on $\F_q$. 
Let nm$(q,n)$ be the cardinality of the set NM$(q,n)$.
According to Theorem \ref{main}, ${\cal I}(q,n)$ has dimension nm$(q,n)$. But is there 
any natural correspondence between NM$(q,n)$ and a basis of the vector space ${\cal I}(q,n)$? As far I know, this problem is open. }
\end{remark}

\begin{remark}{\rm Recall the chain of homomorphisms:

\[\F_q\{E_1, \dots, E_n\}   \xrightarrow{  \Psi  } \F_q\{X_1, \dots , X_n\} 
\xrightarrow{  \Gamma  } {\cal F}(q,n),\]

where $\Psi (P) = P(\vec e (\vec X)) $ is the substitution homomorphism 
and $\Gamma $ is the homomorphism associating to every polynomial $Q$ its polynomial function, and $\Phi = \Gamma \circ \Psi$. Using the interpolation part of the proof of Lemma \ref{surj} one sees that $\Gamma $ is an isomorphism of rings and vector spaces. 
Indeed, $\Gamma$ is a surjective homomorphism and both rings have $q^{q^n}$ elements. }
\end{remark}

\begin{cor}\label{kerpsi}
${\rm Ker} \, \Psi = {\cal I}(q,n)$ and ${\rm Im} \, \Psi = \Gamma ^{-1} ({\cal S}(q,n))$. Consequently, the 
subring of symmetric polynomials in $\F_q\{X_1, \dots , X_n\}$ is a vector space of dimension {\rm wm}$(q,n)$ over $\F_q$.
\end{cor}



