\subsection{Some Preliminary Observations}
\label{sec: Some Preliminary Observations}


To simplify the notation, we remind the reader of some existing abbreviations and introduce new ones. Throughout our analysis, we will work with a fixed $k \in \mathbb{N}$, and $\theta, c \in [0, 2\pi]$, where $\theta < \pi/2$ and $\theta \leq 2c$. For such fixed $k$, $c$, and $\theta$, we define:
\begin{align}
    \phi_i & := 2\theta + \frac{c - 2\theta}{k} i, \quad i = 0, \ldots, k \label{def:phii} \\
    P_i & := \mathcal{P}_{\phi_i}, \quad i = 0, \ldots, k \label{def:pii}
\end{align}
The values $\phi_i$ are chosen such that the intervals $[\phi_i, \phi_{i+1}]$ form a (non-disjoint) partition of the interval $[2\theta, c]$, for $i = 0, \ldots, k - 1$. Additionally, the points $P_i$ represent the endpoints of the corresponding arcs on the perimeter of the unit disk.

For some $\phi \in [0, 2\pi]$, we also consider the parametric equation of the line $\mathcal{L}_{\phi}(t)$, which is tangent to the disk at the point $\mathcal{P}_{\phi}$:
\begin{equation}
\label{equa: parametric tangent line}
\mathcal L_{\phi}(t):=
\left(
\begin{array}{c}
\cos(\phi) \\
\sin(\phi) 
\end{array}
\right)
+
t
\left(
\begin{array}{c}
\sin(\phi) \\
-\cos(\phi)
\end{array}
\right).
\end{equation}
For the same fixed $k,c,\theta$, we will also need to consider the tangent $\mathcal L_{\phi}(t)$ at $\phi=\phi_i$, hence it is convenient to introduce the abbreviation 
%\begin{equation}
%\label{def: parametric tangent}
$L_i(t) := \mathcal L_{\phi_i}(t), ~~t\in \reals, ~~i=0,\ldots,k.$
%\end{equation}

The following lemma summarizes some important observations pertaining to conditions that guarantee when points on the perimeter of the disk are inspected. 

\begin{lemma}\label{lem: preliminary inspections}
\begin{enumerate}[label=(\alph*), ref=\thelemma(\alph*)]
    \item \label{lem: coverage} An agent at point with polar coordinates $(r, \phi)$ and $r\geq 1$ inspects all points $\mathcal P_t$ that satisfy $|t- \phi| \leq \arccoss{1/r}$. 

    \item \label{lem: inspection range of first point}
    For every $\theta \in [0,\pi/2)$, an agent at point $(1,\tann{\theta})$ inspects all $\mathcal P_t$, with $t\in [0,2\theta]$. 

    \item \label{lem: inspection on tangent line} 
%    Let $L_\phi$ denote the tangent line at point $P_\phi$ of the perimeter of the unit disk. 
    An agent inspects point $\mathcal P_\phi$ if and only if it lies in the closed halfspace defined by $\mathcal L_\phi$ that does not contain the interior of the unit disk. 
In particular, an agent residing on any point of $\mathcal L_\phi$ inspects $\mathcal P_\phi$.

%    Let $L_\phi$ denote the tangent line at point $P_\phi$ of the perimeter of the unit disk. 

        \item \label{lem: inspection of sector}
        Consider points $A= \mathcal L_\phi(t_1)$ and $B=\mathcal L_{\phi+\gamma}(t_2)$ satisfying $\gamma<\pi/2$, $t_1\geq 0$ and $t_2\geq \frac{1-\coss{\chi}}{\sinn{\chi}}$. Then, for each $\phi \leq \chi \leq \chi+\gamma$, point $\mathcal P_\chi$ is inspected by some convex combination of $A,B$. In other words, the movement $A\rightarrow B$, inspects all points $\mathcal P_\chi$, with $\chi \in [\phi, \phi+\gamma]$. 
\end{enumerate}
\end{lemma}



\begin{proof}
