%    \hspace{1cm}%
%    \begin{minipage}{0.55\textwidth}
        \caption{The last phase of the Isbell-type algorithm for \pshoreline{2\pi} (also \shoreline{1}). 
        }
        \label{fig: finalpointavg}
%    \end{minipage}
\end{figure}
Note that in order to reach point $\mathcal P_{3\pi/2}$, and by our previous analysis, time $1/\coss{\theta}+\tann{\theta}+3\pi/2 -2\theta$ has passed. The additional time that is needed to inspect $\mathcal P_\phi$ is by Lemma~\ref{lem: inspection on tangent line} equal to the length of $\mathcal P_{3\pi/2}G$. Now, the angle of triangle $GO\mathcal P_{3\pi/2}$ (at vertex $O$) is $(\pi/2-(2\pi-\phi))/2 = \phi/2-3\pi/4$, since triangles $GO\mathcal P_{3\pi/2}, GO\mathcal P_\phi$ are equal. But then $\mathcal P_{3\pi/2}G = \tann{\phi/2-3\pi/4}$, making the cumulative cost in this case equal to
\begin{align*}
\int_{3\pi/2}^{2\pi} \inspect{\phi} \dd \phi 
& = 
\tfrac{\pi}2
\left( \tfrac{1}{\coss{\theta}}+\tann{\theta}+3\pi/2 -2\theta \right)
+
\int_{3\pi/2}^{2\pi} \tann{\phi/2-3\pi/4} \dd \phi \\
& =
\tfrac{\pi}2
\left(\tfrac{1}{\coss{\theta}}+\tann{\theta}+3\pi/2 -2\theta\right)
+
\log 2
,
\end{align*}
where the last equality is based on that $\int \tann{x} = - \log(\coss{x})$. 
Adding then all cumulative inspection costs and scaling by $2\pi$ gives the average inspection cost, as described in the lemma. 
\end{enumerate}
\qed  \end{proof}




The value of $\theta$ that minimizes the worst-case inspection cost $I_W(\theta)$, as described in Lemma~\ref{lem: isbell performance}, is $\theta_W = \pi/6 \approx 0.523599$ (see also Theorem~\ref{thm: original Isbell} from \cite{isbell1957optimal}, or our more general Theorem~\ref{thm: general wrs optimal} for $n = 1$). For this value of $\theta_W$, we have%:
%\begin{align*}
%I_W(\theta_W) & = 1 + \sqrt{3} + \frac{7\pi}{6} \approx 6.39724, \\
%I_A(\theta_W) & = \frac{5}{2\sqrt{3}} + \frac{91\pi}{144} + \frac{\log(6)}{2\pi} \approx 3.71386.
%\end{align*}
$I_W(\theta_W)  = 1 + \sqrt{3} + \frac{7\pi}{6} \approx 6.39724$ 
and
$I_A(\theta_W)  = \frac{5}{2\sqrt{3}} + \frac{91\pi}{144} + \frac{\log(6)}{2\pi} \approx 3.71386$.
Similarly, the value of $\theta$ that minimizes the average inspection cost $I_A(\theta)$, from Lemma~\ref{lem: isbell performance}, is $\theta_A = 0.592334$, which results in :
\begin{align*}
I_W(\theta_A) & \approx 6.406, \\
I_A(\theta_A) & \approx 3.70737.
\end{align*}
%$I_W(\theta_A) \approx 6.406$ and $I_A(\theta_A) \approx 3.70737$.
We expect the Pareto frontier of Isbell-type algorithms to be determined by $\theta \in [0.52359, 0.59233]$. However, for completeness, we plot the pairs $I(\theta) := (I_W(\theta), I_A(\theta))$ for all $\theta \in [0.4, 0.75]$ in Figure~\ref{fig: all tradeoff}, on page~\pageref{fig: all tradeoff}.

In Theorem~\ref{thm: general avg upper bound}, we achieved an average inspection cost as low as $3.5509015$. We are ready to demonstrate how to significantly improve both the worst-case and average inspection costs across the entire Pareto frontier, effectively proving Theorem~\ref{thm: pareto bounds}.


\begin{proof}[of Theorem~\ref{thm: pareto bounds}]
The upper bound to the Pareto frontier will be obtained by the family of algorithms \textsc{EPS}$(\theta,t_1,\ldots,t_k)$, with $k=1000$, and for appropriate choices of parameters $\theta,t_i$. 

For this, we recall Lemma~\ref{lem: reduction from discrete to continuous wrs}, from which for any feasible choice of the parameters, we obtain a formula $S_W(\theta,t_1,\ldots,t_k)$ for the worst case cost. 
Let also $S_A(\theta,t_1,\ldots,t_k)$ denote the objective of \eqref{NLP-avg}, with $c=2\pi$ and $\epsilon =10^{-3}$. For all NLP solutions we obtain, the optimizer values for $\theta$ are bounded away from $\pi/2$ (in fact, they admit values in $[0.5,0.6]$), and hence the value of $\epsilon$ does not affect the cost of the solution, rather only is there to justify its correctness (see also Figure~\ref{fig: theta valus for trade-offs}).
% on page~\pageref{fig: theta valus for trade-offs}).
