\begin{lemma}
\label{lem: minimizer of f1}
For every $c\in [0,3\pi/2]$, function $f_1(\theta) := 1/\coss{\theta}+\sinn{c-\theta-\pi/2}/\coss{\theta}+1$, subject to that $\theta \geq c/2-\pi/4$ and $\theta<\pi/2$, attains the following minima:
$$
\begin{cases}
f_1(c/2), 			& \textrm{ if}~ 0 \leq c \leq 2\pi/3\\ 
f_1(\pi-c),	 	& \textrm{ if}~ 2\pi/3 < c \leq 5\pi/6\\ 
f_1(c/2-\pi/4),		& \textrm{ if}~ 5\pi/6 < c \leq 3\pi/2.
\end{cases}
$$
\end{lemma}

\begin{proof}
For every $c\in [0,3\pi/2]$, we aim to find the minimum of the function
$
f_1(\theta) = \frac{1 + \sin(c - \theta-\pi/2)}{\cos\theta} + 1,
$
subject to the constraints \(\theta \geq \dfrac{c}{2} - \dfrac{\pi}{4}\) and \(\theta < \dfrac{\pi}{2}\). For this we rely on the derivative $f_1'(\theta) = ( \sinn{\theta} - \sinn{\theta})/\coss{\theta}$. Next we examine cases for the range of parameter $c$. 

Case 1: If $0\leq c\leq \pi/2$, we have that that $f_1'(\theta)=0$ if and only if $\theta=c$ (for $0\leq \theta <\pi/2$), whereas $f_1'(0)=-\sinn{c} <0$. This means that the function is initially decreasing, up to $\theta =c$. However, $c/2-\pi/4\leq \theta \leq c/2\leq c$, and therefore $f_1(\theta)$ is minimized at the end of its domain, that is at $\theta = c/2$,

Case 2: If $\pi/2\leq c\leq \pi$, and since $0\leq \theta <\pi/2$, we have that that $f_1'(\theta)=0$ if and only if $\theta=\pi-c$. At the same time, $c/2-\pi/4\leq \theta \leq c/2$, hence we see that $c/2-\pi/4\leq \pi-c \leq c/2$ if and only if $2\pi/3 \leq c \leq 5\pi/6$. 
At the same time, for every $\epsilon>0$ sufficiently small, we have that $f_1'(\pi-c-\epsilon)=
( \sinn{c+\epsilon} - \sinn{c})/\coss{c+\epsilon}$ implying that $f_1$ is decreasing for $c\leq \pi-c$. We conclude that for $c\in [2\pi/3 \leq c \leq 5\pi/6]$, $f_1(\theta)$ is minimized at $\theta=\pi-c$. 
For $c\in [\pi/2,2\pi/3]$, we have that $\pi-c \geq c/2$. Hence, $f_1(\theta)$, is decreasing up to $\theta \leq c/2$, and hence the minimum in this case is attained at $\theta=c/2$. 
Finally, for the case 2, if $c\in [5\pi/6,\pi]$, we have that $\pi-c \leq c/2-\pi/4$, hence $f_1(\theta)$ is increasing when $\theta \in [c/2-\pi/4,c/2]$, inducing the minimizer $\theta=c/2-\pi/4$. 

Case 3: Finally, if $\pi\leq c\leq 3\pi/2$, we have that $\sinn{c}\leq 0$, and hence $f_1'(\theta) = ( \sinn{\theta} - \sinn{\theta})/\coss{\theta} \geq 0$. For this reason, $f_1(\theta)$ is increasing in $[c/2-\pi/4,\pi/2)$, and so the minimum is attained at $\theta=c/2-\pi/4$.
\qed  \end{proof}




\begin{lemma}
\label{lem: minimizer of f2}
For every $c\in [\pi/2,2\pi]$, function $f_2(\theta) = 1/\coss{\theta}+\tann{\theta}+c-\pi/2-2\theta+1$, subject to that $0\leq \theta \leq c/2-\pi/4$ and $\theta<\pi/2$, attains the following minima:
$$
\begin{cases}
f_2(c/2-\pi/4),		& \textrm{ if}~ \pi/2 \leq c \leq 5\pi/6 \\
f_2(\pi/6), 			& \textrm{ if}~ 5\pi/6 < c \leq 2\pi.
\end{cases}
$$
\end{lemma}

\begin{proof}
For each fixed parameter $c\in [\pi/2,2\pi]$, we study the monotonicity of $f_2(\theta) = 1/\coss{\theta}+\tann{\theta}+c-\pi/2-2\theta+1$ in the domain identified by that $0\leq \theta \leq c/2-\pi/4$ and $\theta<\pi/2$. For this we see that 
$f_2'(\theta)=(1/\coss{\theta}+\tann{\theta})/\coss{\theta} -2$, 
and that 
$f_2''(\theta)=(1/\coss{\theta}+\tann{\theta})^2/\coss{\theta}$.

The above imply that $f_2(\theta)$ is convex, and $f_2'(\theta)$ is increasing in $[0,\pi/2)$. The only root of $f_1'(\theta)$ in $[0,\pi/2)$ is at $\theta = \pi/6$, while it is also easy to see that $f_2'(0)=-1$. Therefore, $f_2(\theta_2)$ is initially decreasing, it is minimized at $\theta=\pi/6$, and then it is increasing for up to $\theta <\pi/2$. 

We recall the domain of $f_2(\theta)$, identified by that $0\leq \theta \leq c/2-\pi/4$ and $\theta<\pi/2$. Hence, $\theta=\pi/6$ is a minimizer if and only if $\pi/6 \leq c/2-\pi/4$ iff and only if $c \in [5\pi/6,2\pi]$. 
For parameters $c\in [\pi/2, 5\pi/6]$, we see that $f_2(\theta)$ is decreasing in its domain, and hence it is minimized at $\theta = c/2-\pi/4$. 
\qed  \end{proof}



\begin{lemma}
\label{lem: f1-f2 comparison}
For every $c\in [\pi/2,3\pi/2]$, let $f_1(\theta), f_2(\theta)$ be as in Lemma~\ref{lem: minimizer of f1} and Lemma~\ref{lem: minimizer of f2}. Let $\theta_1,\theta_2$ denote the corresponding minimizers. Then, 
$$
\min\{f_1(\theta_1), f_2(\theta_2) \}=
\begin{cases}
f_1(c/2) = 1/\coss{c/2}			& \textrm{ if}~ \pi/2 \leq c \leq 2\pi/3 \\
f_1(\pi-c) = 1-2\coss{c}		& \textrm{ if}~ 2\pi/3 < c \leq 5\pi/6 \\
f_2(\pi/6)= \sqrt3+c-5\pi/6+1	& \textrm{ if}~ 5\pi/6 < c \leq 2\pi 
\end{cases}
$$
\end{lemma}

\begin{proof}
For each $c\in [0,2\pi]$, let $\theta_1=\theta_1(c),\theta_2=\theta_2(c)$ denote the minimizers of $f_1(\theta), f_2(\theta)$ as in Lemma~\ref{lem: minimizer of f1} and Lemma~\ref{lem: minimizer of f2}, and for the values of $c$ that each is defined. By direct substitution we see that 
$$
f_1(\theta_1)=
\begin{cases}
1/\coss{c/2}, 			& \textrm{ if}~ 0 \leq c \leq 2\pi/3\\ 
1-2\coss{c},	 	& \textrm{ if}~ 2\pi/3 < c \leq 5\pi/6\\ 
1+1/\sinn{c/2+\pi/4}+\tann{c/2-\pi/4},		& \textrm{ if}~ 5\pi/6 < c \leq 3\pi/2.
\end{cases}
$$
and
$$
f_2(\theta_2)=
\begin{cases}
1+1/\sinn{c/2+\pi/4}+\tann{c/2-\pi/4},		& \textrm{ if}~ \pi/2 \leq c \leq 5\pi/6 \\
\sqrt3+c-5\pi/6+1, 			& \textrm{ if}~ 5\pi/6 < c \leq 2\pi.
\end{cases}.
$$
For $c\leq \pi/2$ only $f_1(\theta_1)$ is defined, while for $c\geq 3\pi/2$ only $f_2(\theta_2)$ is defined. Taking also the piece-wise definition of the minimizers, we conclude that $\min\{f_1(\theta_1),f_2(\theta_2)\}$ over $c \in [\pi/2,3\pi/2]$ should be analyzed in the following three subintervals. 

\begin{align*}
M_1:=& \min_{c \in [\pi/2,2\pi/3]}\{f_1(\theta_1),f_2(\theta_2)\}
=
\min
\left\{
\frac{1}{\coss{c/2}}, 1+\frac{1}{\sinn{c/2+\pi/4}}+\tann{c/2-\pi/4}
\right\}
\\
M_2:=&
\min_{c \in [2\pi/3, 5\pi/6]}\{f_1(\theta_1),f_2(\theta_2)\}
=
1+ \min 
\left\{
-2\coss{c},
\frac{1}{\sinn{c/2+\pi/4}}+\tann{c/2-\pi/4}
\right\}
\\
M_3:=&
\min_{c \in [5\pi/6, 3\pi/2]}\{f_1(\theta_1),f_2(\theta_2)\}
=
1+ \min
\left\{
\frac{1}{\sinn{c/2+\pi/4}}+\tann{c/2-\pi/4}
,\sqrt3+c-5\pi/6
\right\}
\end{align*}

We claim that $M_1 = \coss{c/2}$, and for this we consider function 
$$
g_1(c) =   \frac{1}{\sinn{c/2+\pi/4}}+\tann{c/2-\pi/4}+1 - \frac1{\coss{c/2}}
$$
over $c\in [\pi/2,2\pi/3]$. We will show that $g_1(c)\geq 0$. For this we see that $g_1(2\pi/3) = \left(\sqrt{2}-1\right) \left(\sqrt{3}-1\right) >0$. Hence, it suffices to show that $g_1(c)$ is decreasing. First it is easy to see that 
$$
g_1'(c) =
\frac{1}{16} \sec ^2\left(\frac{c}{2}\right) \sec ^2\left(\frac{1}{8} (2 c+\pi )\right) \left(-4 \sin \left(\frac{c}{2}\right)-2 \sin \left(c+\frac{\pi }{4}\right)+2 \cos (c)+\sqrt{2}+2\right).
$$
Hence, it suffices to show that $h_1(c) = -4 \sin \left(\frac{c}{2}\right)-2 \sin \left(c+\frac{\pi }{4}\right)+2 \cos (c)+\sqrt{2}+2 <0$ for $c\in [\pi/2,2\pi/3]$. Indeed, we have $h_1(c) = 2-2\sqrt2 <0$. Hence, it further suffices to show that $h_1(c)$ is decreasing. 
To that end we note that $\sinn{c}$ is strictly decreasing in $c\in [\pi/2,2\pi/3]$, and hence, after performing the transformation $\sinn{c} = x$, we obtain function 
$$
s_1(x) = h_1(\arcsin(x)) = -\sqrt{2-2 x^2}-\left(\sqrt{2}-2\right) x-2 \sqrt{2-2 x}+\sqrt{2}+2,
$$
over the domain $x\in [\sqrt3/2,1]$, which we need to show is increasing. For that, we calculate $s_1'(x) = \frac{2 x}{\sqrt{2-2 x^2}}+\frac{2}{\sqrt{2-2 x}}-\sqrt{2}+2$, which is well defined for all $x\in [\sqrt3/2,1)$. But then, note that for all $x\geq 0$, we have that $s_1'(x)>0$, hence indeed, $s_1(x)$ is increasing as wanted. 





Next we claim that $M_2 = 1-2\coss{c}$, and for this we consider function 
$$
g_2(c) =   \frac{1}{\sinn{c/2+\pi/4}}+\tann{c/2-\pi/4}+2\coss{c}
$$
over $c\in [2\pi/3, 5\pi/6]$. We see that $g_2(5\pi/6) =0$, and hence it is enough to show that $g_2(c)\geq 0$. For this we calculate $g_2'(c) = \frac{1}{4} \sec ^2\left(\frac{1}{8} (2 c+\pi )\right)- 2 \sin (c)$, and we show that $g_2'(c)\leq 0$, for all $c\in [2\pi/3, 5\pi/6]$, implying that $g_2(c)$ is decreasing, and hence concluding what we claimed. To show that the derivative is negative, we apply transformation $x=\coss{c/4+\pi/8}$, hence defining function 
$$
s_2(x) = g_2(4\arccos(x) - \pi/2)= 2 + 1/(4 x^2) - 16 x^2 + 16 x^4
$$
with $1/2\leq x \leq \sinn{5\pi/24}\approx 0.608761$. Clearly, it suffices to show that $s_2(x) \leq 0$ in the latter interval. Applying also the transformation $2x^2=y$, we obtain  
$ s_2(\sqrt{y/2}) = 4 y^2-8 y+\frac{1}{2 y}+2 = \frac{8 y^3-16 y^2+4 y+1}{2 y}$, and hence it suffices to prove that 
$q_2(y) = 8 y^3-16 y^2+4 y+1 \leq 0$, in the domain $1/2 \leq y \leq 2 \sin ^2\left(\frac{5 \pi }{24}\right) \approx 0.741181$ obtained from the transformation. The three real roots of  $q_2(y)$ are easy to derive: $y_1=1/2, y_2=\frac{1}{4} \left(3-\sqrt{13}\right) \approx -0.151388$ and $y_3=\frac{1}{4} \left(\sqrt{13}+3\right) \approx 1.65139$. Since the leading coefficient of $q_2(y)$ is positive, it follows that $q_2(x)$ is negative for all $1/2 \leq y \leq \frac{1}{4} \left(\sqrt{13}+3\right)$. The main claim then follows by noticing that 
$2 \sin ^2\left(\frac{5 \pi }{24}\right) \leq \frac{1}{4} \left(\sqrt{13}+3\right)$. 

Finally, we claim that $M_3 = 1+\sqrt3+c-5\pi/6$, and for this we consider function 
$$
g_3(c) = \frac{1}{\sinn{c/2+\pi/4}}+\tann{c/2-\pi/4} - \sqrt3 - c + 5\pi/6 
$$
over $c\in [5\pi/6,3\pi/2]$. We need to show that $g_3(c) \geq 0$, and we see that $g_3(5\pi/6) = 0$. Therefore, it suffices to prove that $g_3'(c) = -1+1/2\cos^2(c/4+\pi/8) \geq 0$. 
Recall that $c\in [5\pi/6,3\pi/2]$, and hence $c/4+\pi/8 \in [\pi/3,\pi/2]$. But then, since $\cos(\cdot)$ is decreasing in $[\pi/3,\pi/2]$, we see that $\cos(c/4+\pi/8)\leq \coss{\pi/3} =1/2$. This implies that 
$g_3'(c) = -1+1/4\cos^2(c/4+\pi/8) \geq -1+1=0$ as wanted. 
\qed  \end{proof}








