\section{Smooth double-well potentials with quadratic convex part}\label{appendix W_R}

We construct a smooth doublewell potential $W$ such that $W(u) = u^2 + W_{conc}(u)$ where $W_{conc}$ is a differentiable concave function. 
The functions we consider are smoother versions of $W(u) = u^2  + 1 - 2|u|$ for which most analytic results apply without further modification.

\begin{example}
For $R, \beta, \gamma >0$, the potential
\[
W(u) = W_{\beta, \gamma, R}(u) := u^2 + \beta - \gamma \sqrt{R u^2 +1}
\]
satisfies $\lim_{u\to\pm \infty} W(u)/u^2 = 1$. As $\gamma>0$, the function
\[
W_{conc}(u) := \beta -\gamma\sqrt{Ru^2+1}
\]
is smooth and concave.
We see that
\[
0 = W'(u) = 2u - \frac{2\gamma Ru}{2\sqrt{Ru^2+1}} = \left(2 - \frac{\gamma R}{\sqrt{Ru^2+1}}\right)u = 0
\]
if $u=0$ and at $u = \pm 1$ if $\gamma = \frac{2\sqrt{R+1}}R$. The critical point at zero is a local maximum and 
\[
W(\pm 1) = 1 + \beta - \gamma \sqrt{R+1} = 0
\]
if $\beta = \gamma\sqrt{R+1}-1 = \frac{2(R+1)-1}R = 1 + 2/R$. At the origin, we have
\[
W(0) = \beta -\gamma = 1+ \frac2R - \frac{2\sqrt{R+1}}R = \frac{R+2 - 2\sqrt{R+1}}R = \frac{(\sqrt{R+1}-1)\sqrt{R+1}}R>0
\]
for all $R>1$. This ansatz therefore yields a one parameter family of doublewell potentials with quadratic convex part and potential wells at $\pm 1$, which we denote by $W_R$. We note that $W$ is even and that
\[
\gamma = \frac{2\sqrt{R+1}}R \quad\Ra\quad W''(1) = 2 - \gamma \,\frac{R}{\sqrt{R+1}}+ \gamma \,\frac{R^2}{(R+1)^{3/2}} = 2 - 2 + \frac{2R}{R+1}= \frac{2R}{R+1}>0.
\]
As $R\to\infty$, we observe that
\begin{align*}
\lim_{R\to \infty} W_R(u) &= \lim_{R\to\infty}\left(u^2 + 1 + \frac2R - \frac{2\sqrt{R+1}}R \sqrt{Ru^2+1}\right)\\
    &= u^2+1 - 2\,\lim_{R\to \infty}\left(\sqrt{\frac{R(R+1)}{R^2}u^2+ \frac{R+1}{R^2}}\right)\\
    &= u^2 + 1 - 2|u|,
\end{align*}
i.e.\ we can see $W_R$ as a smooth approximation to $\overline W$ -- see Figure \ref{fig:ws}.

\begin{figure}
    \centering
    \includegraphics[width = .33\textwidth]{./images/W_Rs.png}
    \includegraphics[width = .33\textwidth]{./images/quadratic_doublewell_with_derivatives.png}\

    \caption{{\bf Left:} The doublewell potential $W_R$ for varying values of $R$. {\bf Right:} $W_R$ and its first two derivatives for $R=1$.}
    \label{fig:ws}
\end{figure}
\end{example}

The fact that $W_R(u)\nearrow \overline W(u) =  (|u|-1)^2$ is no coincidence.

\begin{lemma}\label{lemma w bound}
Assume that $W(u) = u^2+ W_{conc}(u)$ where $W_{conc}$ is a concave $C^1$-function, $W\geq 0$ and $W(\pm 1) = 0$. Then $W(z) \leq (1-|z|)^2$ for all $z\in[-1,1]$.
\end{lemma}

\begin{proof}
We observe that $W$ is minimal at $\pm 1$ and differentiable, so
\[
0 = W(u) = u^2 + W_{conc}(u) = 1 + W_{conc}(u) \qquad \forall\ u\in\{-1,1\}
\]
and
\[
0 = W'(u) = 2u + W_{conc}'(u) \qquad \Ra\quad W_{conc}'(u) = -2\,sign(u) \qquad\forall\ u\in \{-1,1\}.
\]
Since $W_{conc'}$ is non-increasing on $[0, \infty)$, we see that $W_{conc}' \geq -2$ on $[0,1]$ and thus 
\[
W_{conc}(z) = - \int_z^1 W_{conc}'(t)\dt + W_{conc}(1) \leq -1-\int_z^1(-2)\dt = 2(1-z)-1 = 1 - 2z \qquad\ \forall\ z\in [0,1],
\]
i.e.\ 
\[
W(u) = u^2 + W_{conc}(u) \leq u^2 + 1-2u\qquad \forall\ u\in [0,1].
\]
The case $u\in[-1,0]$ follows analogously.
\end{proof}


\section{The thresholding scheme with radially symmetric kernels}\label{appendix thresholding}

We briefly summarize the convergence result of \cite{ishii1995generalization, ishii1999threshold} for thresholding schemes with general kernel convolutions. We specialize the result of \cite[Theorem 3.3]{ishii1999threshold} to the setting of radially symmetric kernels, which was initially treated in the unfortunately hard to obtain article \cite{ishii1995generalization}.

Assume that $K$ is a measurable function on $\R^d$ and $K(Ox) = K(x)$ for all $x\in\R^d$ and $O\in O(d)$. Assume additionally that
\[
\int_{\R^d}K(x) \dx =1, \qquad \int_{\R^d}|x|^2\,K(x)\dx < +\infty, \qquad \int_{\R^{d-1}} K(\xi, 0) \big(1+\|\xi\|^2\big)\d\xi <\infty.
\]
This comprises assumptions (3.1) -- (3.4) of \cite{ishii1999threshold}, noting that
the continuity condition (3.3) for hyperplane integrals of $K$ in \cite{ishii1999threshold} is automatically satisfied for radially symmetric kernels since the integrals do not depend on the choice of hyperplane. Additionally, we require that
\[
\lim_{\rho\to 0^+} \sup_{r\in (0,\rho)}\left|\int_{B_{R(\rho)}(0_{d-1})} K\left(\xi, r \big(a + \xi^TS\xi\big)\right)\big(a + \xi^TS\xi\big)\d\xi - \int_{\R^{d-1}} K\left(\xi, 0\right)\,\big(a+ \xi^TS\xi\big)\d\xi\right| =0
\]
where $a\in \R$ and $S\in \R^{(d-1)\times (d-1)}_{sym}$ are arbitrary and $R(\rho)$ can be any function such that $R(\rho)\to +\infty$ and $\sqrt{\rho}\,R(\rho)\to 0$ as $\rho\to0^+$. This `localization' condition (3.7) of \cite{ishii1999threshold} implies consistency with MCF for quadratic graph approximations of smooth surfaces. Here $0_{d-1}$ denotes the origin in $\R^{d-1}$.

For the kernel $K(x) = \frac{\exp(\|x\|)}{4\pi\,\|x\|}$ on $\R^3$, we observe that
\begin{align*}
\int_{\R^3} K(x) \dx 
    &= 4\pi\int_0^\infty \frac{\exp(-r)}{4\pi\,r}r^2\dr
    =\int_0^\infty r\,\exp(-r)\dr 
    = \int_0^\infty \exp(-r)\dr 
    = 1\\
\int_{\R^3} K(x)\,\|x\|^2\dx 
    &= \int_0^\infty r^3\exp(-r)\dr 
    = \int_0^\infty 3r^2 \exp(-r)\dr 
    = 6\int_0^\infty r\,\exp(-r)\dr 
    = 6\\
\int_{\R^2}K(\xi,0)\,\big(1+\|\xi\|^2\big)\d\xi
    &= 2\pi \int_0^\infty \frac{\exp(-r)}{4\pi\,r}\,(1+r^2) \,r\dr
    = \frac12 \int_0^\infty (1+r^2) \exp(-r)\dr = \frac32,
\end{align*}
i.e.\ the conditions (3.1) -- (3.4) of \cite{ishii1999threshold} hold for $K$.
The consistency condition (3.7) of \cite{ishii1999threshold} can be established in two steps: For any fixed $a, S$ we have
\[
\sup_{r\in(0,\rho)}\left|\int_{\R^{2}\setminus B_{R(\rho)}(0)} K\left(\xi, r \big(a + \xi^TS\xi\big)\right)\big(a + \xi^TS\xi\big)\d\xi\right| \leq 2\pi \int_{B_{R(\rho)}^c}\frac{\exp(-r)}{4\pi r} \big(|a| + \|S\|_{op}r^2\big)\dr \to 0^+
\]
as $\rho\to 0$ since the integrand is in $L^1(\R^2)$ and $R(\rho)\to \infty$ as $\rho\to 0$. Additionally, we have
\begin{align*}
\limsup_{\rho\to 0^+}\sup_{r\in (0,\rho)} \left|\int_{\R^2} \big\{K(\xi,0) - K\big(\xi, r(a+\xi^TS\xi)\big)\big\} (a+\xi^TS\xi) \d\xi \right| \leq \lim_{\rho \to 0^+} \int_{\R^2} f_\rho(\xi) \d\xi 
\end{align*}
where 
\begin{align*}
f_\rho(\xi) &= \sup_{0<r<\rho} \big|K(\xi,0) - K\big(\xi, r(a + \xi^TA\xi)\big)\big|(|a| + \|S\|_{op}\|\xi\|^2\big)\\
    &\leq \left[K(\xi, 0) - K\big(\xi, \rho\big\{a + \|S\|_{op}\|\xi\|^2\big\}\big) \right]\,\big\{|a| + \|S\|_{op}\|\xi\|^2\big\}.
\end{align*}
The inequality follows since the function $s\mapsto \exp(-s)/s$ is monotone decreasing, so $s\mapsto K(\xi, s)$ is monotone decreasing. We note that $\lim_{\rho\to 0^+} f_\rho(x) = 0$ for all $x\in\R^3$ and $|f_\rho(x)| \leq C(1+\|x\|^2)\exp(-\|x\|)$, so $\int_{\R^2}f_\rho \dx \to 0^+$ as $\rho\to 0^+$ by the dominated convergence theorem. The two estimates together establish that the compatibility condition (3.7) of \cite{ishii1999threshold} holds for the kernel $K$.

We compute the velocity function as in \cite{ishii1999threshold} with $\Sigma\in\R^{3\times 3}_{sym}$ as a proxy for the second fundamental form and $n$ as a proxy for the normal of the evolving surface:
\[
v(\Sigma, n ) = \frac{-\frac12 \int_{\langle n\rangle ^\bot} \xi^T\Sigma\xi\,K(\xi)\,\d\xi }{\int_{\R^2}K(\xi,0)\,\d\xi} = - \int_{\langle n\rangle^\bot}\xi^T\Sigma\xi\,\frac{\exp(-\|\xi\|)}{4\pi\,\|\xi\|}\,\d\xi.
\]
We choose an orthonormal coordinate system $\{n, e_1, e_2\}$ and note that 
\begin{align*}
v(\Sigma, n) &= \frac{-1}{4\pi} \int_0^\infty\int_0^{2\pi} r\big(\cos\phi\, e_1+\sin\phi \,e_2)^T\,\Sigma \, r(\cos \phi\,e_1 + \sin\phi\,e_2) \frac{\exp(-r)}r\,r\dr\\
    &=\frac{-1}{4\pi} \left(\int_0^{2\pi}\cos^2\phi\,e_1^T\Sigma\,e_1 + \sin^2\phi\,e_2^T\Sigma\,e_2\,\d\phi\right) \left(\int_0^\infty\exp(-r)r^2\dr\right)\\
    &= - \frac1{4\pi} \cdot\pi \big(e_1^T\Sigma e_1 + e_2^T \Sigma e_2\big)\cdot 2
    = - \frac12\,\mathrm{tr}_{\langle n\rangle^\bot}\Sigma.
\end{align*}
If $\Sigma$ is indeed the second fundamental form of a surface and $n$ is its normal, this is precisely the negative of the (geometric) mean curvature, i.e.\ the average of its principal curvatures. For surfaces, the geometric mean curvature differs from the `analytic' mean curvature (the sum of the principal curvatures) by a factor two. The analytic mean curvature appears more naturally e.g.\ in the Allen-Cahn equation. 
By \cite[Theorem 3.3]{ishii1999threshold}, we find that the thresholding scheme indeed approximates a viscosity solution to mean curvature flow at the time-scale $\frac{\eps^2}2$, at least on the whole space $\R^3$.




\section{On the uniform convexity of power law functions}\label{appendix power law}

In this Section, we prove Lemma \ref{lemma power law}. The special cases $p=2$ and $p=4$ follow directly from algebraic manipulation. If $f_p(u) := |u|^p$, then
\begin{align*}
f_2(u+v) &= (u+v)^2
    = u^2 + 2uv+v^2
    = f_p(u) + f_p'(u)\,v + v^2
\end{align*}
and
\begin{align*}
f_4(u+v) &= (u+v)^4\\
	 &= u^4 + 4u^3v + 6u^2v^2 + 4uv^3 + v^4\\
	 &= f_4(u) + f_4'(u)\,v + v^2 \big(6u^2+4uv + v^2\big)\\
	 &=  f_4(u) + f_4'(u)\,v + v^2\left(\sqrt{6}\,u+\frac2{\sqrt 6}\,v\right)^2 + v^2\left(1- \frac{4}6\right)\,v^2\\
	 &\geq f_4(u) + f_4'(u)\,v + \frac13\,v^4.
\end{align*}
The inequality holds with equality if $v = -3u$. We will see in the proof of the general case that $v = -cu$ for $c\approx 2$ is indeed the most restrictive case also for general $p$.

\begin{proof}[Proof of Lemma \ref{lemma power law}]
If $u=0$, the inequality holds for any $\beta\leq 1$, so we may assume that $u\neq 0$. Dividing by $|u|^p$ and denoting $\xi = v/|u|$, we see that the inequality is equivalent to
\[
\big|1 + \sign(u)\xi\big|^p = \big|\sign(u) + \xi\big|^p \geq 1 + p\,\sign(u)\,\xi + \beta\,|\xi|^p \qquad \forall\ u\neq 0,\: \xi\in \R.
\]
Replacing $\zeta = \sign(u)\xi$, it reduces further to the claim that
\begin{equation}\label{eq improved bernoulli}
\big|1+ \zeta\big|^p \geq 1 + p\zeta + \beta\,|\zeta|^p\qquad\forall\ \zeta \in\R.
\end{equation}
This can be seen as an improved version of Bernoulli's inequality which attains the right kind of growth both at $\xi=0$ and as $|\xi|\to \infty$. 

We differentiate between three cases: (i) $\zeta\geq 0$, (ii) $\zeta \in[-1,0)$ and $\zeta \in(-\infty,-1]$. In the first case, the inequality reduces to
\[
\big(1+ \zeta\big)^p - 1 - p\zeta - \beta\,\zeta^p \geq 0.
\]
We note that the inequality holds with equality for $\zeta = 0$ independently of $\beta$ and 
\[
\frac{d}{d\zeta}\left\{\big(1+ \zeta\big)^p - 1 - p\zeta - \beta\,\zeta^p\right\} = p(1+\zeta)^{p-1} - p - \beta p\zeta^{p-1} = 0
\]
for $\zeta=0$. The second derivative satisfies
\[
\frac{d^2}{d\zeta^2}\left\{\big(1+ \zeta\big)^p - 1 - p\zeta - \beta\,\zeta^p\right\} = p(p-1) \left\{\big(1+\zeta\big)^{p-2}- \beta \zeta^{p-2} \right\}\geq 0
\]
for $\beta \leq 1$ since $p\geq 2$ implies that $(1+\zeta)^{p-2}\geq \zeta^{p-2}$. Thus the first derivative is increasing from zero, meaning that the function itself is increasing (and, in fact, convex with minimizer at $0$).

In the second case, we write $z= -\zeta$ and reduce the inequality to
\[
(1-z)^p \geq 1-pz + \beta z^p\qquad \forall\ z \in [0,1].
\]
We again note that the inequality holds as equality for $z=0$ and compute
\[
\frac{d}{dz} \big\{(1-z)^p - 1 + pz - \beta\,z^p\big\} = -p(1-z)^{p-1} + p - p\beta\,z^{p-1} = p \big(1- z^{p-1} - \beta (1-z)^{p-1}\big) \geq 0
\]
for $\beta \leq 1$ as $p-1\geq 1$. 
Thus \eqref{eq improved bernoulli} holds for $\zeta\in[-1,\infty)$. It remains to consider the third case $\zeta \in (-\infty, -1]$. Here, we will encounter sharper restrictions on $\beta$.

After replacing $z= -\zeta$ again, the inequality reads as
\[
(z-1)^p \geq 1 -pz + \beta\,z^p \qquad \LRa\quad \frac{(z-1)^p + pz -1}{z^p}\geq \beta \qquad \forall\ z\in [1,\infty)
\]
We can find admissible $\beta$ as
\begin{align*}
\beta(p) := \min_{z\geq 1} \frac{(z-1)^p + pz -1}{z^p} &= \min\left\{\min_{z\in[1,R]}\frac{(z-1)^p + pz -1}{z^p} , \min_{z\in[R,\infty)} \frac{(z-1)^p + pz -1}{z^p}\right\}\\
	&\geq \min\left\{\min_{z\in[1,R]}\frac{pz -1}{z^p} , \min_{z\in[R,\infty)} \frac{(z-1)^p}{z^p}\right\}.
\end{align*}
We note that
\[
\frac{pz -1}{z^p} \geq \frac{(p-1)z}{z^p} = (p-1)\,R^{1-p} \quad\forall\ z\in[1,R], \qquad \frac{(z-1)^p}{z^p} = \left(1- \frac1z\right)^p \geq \left(1-\frac1R\right)^p \quad\forall\ z\in [R, \infty).
\]
As the bound holds for any choice of $R>1$, we can evaluate at $R=2$ to obtain
\[
\beta(p) \geq \min\{(p-1)\,2^{1-p}, \:2^{-p}\} = 2^{-p}. \qedhere
\]
\end{proof}

This bound scales almost optimally as $p\to\infty$ as
\[
\beta(p) = \min_{z\geq 1} \frac{(z-1)^p + pz -1}{z^p}  \leq\frac{(2-1)^p + p\cdot 2 -1}{2^p} = \frac{2p}{2^p} = p\,2^{1-p}.
\]


\section{Calculations for Example \ref{example obstacle}}\label{appendix obstacle}
We make the ansatz
\[
u(s) = \begin{cases} 1 & s < r_i\\ a + b\,G_d(s) - \frac1{2d\,\eps^2}\,s^2 & r_i < s <r\\ c+e\,G_d(s) + \frac1{2d\,\eps^2}s^2 & r < s < r_o\\ -1 &s > r_o\end{cases}
\]
for coefficients $a, b, c, e$ which make $u$ $C^1$-regular at the radii $r_i, r, r_o$. Note that also $r_i, r_o$ are problem parameters, leading to the system
\[
\begin{cases}
a + b \,G_d(r_i) - \frac1{2d\,\eps^2} \,r_i^2 & = 1\\
b\,G_d'(r_i) - \frac{1}{d\,\eps^2}\,r_i &= 0\\
a + b \,G_d(r) - \frac1{2d\,\eps^2} \,r^2 & = c + e \,G_d(r) + \frac1{2d\,\eps^2} \,r^2\\
b\,G_d'(r) - \frac{1}{d\,\eps^2}\,r &= e\,G_d'(r) + \frac1{d\,\eps^2}r\\
c + e \,G_d(r_o) + \frac1{2d\,\eps^2} \,r_o^2 & = -1\\
e\,G_d'(r_o) + \frac{1}{d\,\eps^2}\,r_o &= 0\\
\end{cases}
\]
of six equations in six unknowns $a,b, c,e, r_i, r_o$. Note that $G_d'(s) = \frac1{d\omega_d} s^{1-d}$ for all $d\geq 2$, so the second and sixth equation simplify to
\[
0 = b\,\frac1{d\omega_d} \,r_i^{1-d} - \frac{1}{d\,\eps^2}\,r_i \qquad \Ra \quad b = \frac{d\,\omega_d}{d\,\eps^2}\,r_i^d = \frac{\omega_d}{\eps^2}\,r_i^d \qquad \text{and analogously} \quad e = - \frac{\omega_d}{\eps^2}\,r_o^d.
\]
Inserting this into the first and fifth equation, we obtain
\[
a = 1 - b\,G_d(r_i) + \frac1{2d\,\eps^2}\,r_i^2 = 1 - \frac{\omega_d}{\eps^2} \,r_i^d\,\frac{-1}{d(d-2)\omega_d}r_i^{2-d} + \frac1{2d\,\eps^2}\,r_i^2 =
1 +\frac{r_i^2}{d\,\eps^2}\left(\frac1{d-2} + \frac12\right)
\]
in dimension $d\geq 3$ and analogously
\[
a = 1 + \frac{r_i^2}{2(d-2)\,\eps^2}, \qquad c = -\left(1 + \frac{r_o^2}{2(d-2)\,\eps^2}\right).
\]
Having determined $a,b,c,e$ for given $r_i, r_o$, we need to exploit the smoothness of $u$ at the contact sphere $\{s=r\}$ to find $r_i, r_o$. Again, we start with the simpler condition for the derivative
\[
\left(\frac{1}{d\,\eps^2}\,r_i^dr^{-d} - \frac1{d\,\eps^2}\right)r =  b\,G_d'(r) - \frac{1}{d\,\eps^2}\,r = e\,G_d'(r) + \frac1{d\,\eps^2}r = \left(\frac{-1}{d\,\eps^2}\left(\frac{r_o}r\right)^d + \frac1{d\,\eps^2}\right) r,
\]
which yields that $(r_i/r)^d + (r_o/r)^d = 2$. The continuity condition becomes
\begin{align*}
1 + \frac{r_i^2}{2(d-2)\eps^2} - \frac{1}{d(d-2)\eps^2} r_i^dr^{2-d} - \frac1{2d\,\eps^2} \,r^2  = -\left(1 + \frac{r_o^2}{2(d-2)\eps^2} \right) + \frac{1}{d(d-2)\eps^2} r_o^dr^{2-d} + \frac1{2d\,\eps^2} \,r^2 
\end{align*}
or equivalently 
\[
2 + \frac 1{2(d-2)\eps^2}\,(r_i^2 + r_o^2)  -\frac{1}{d(d-2)\eps^2}\left\{ \left(\frac{r_i}r\right)^d + \left(\frac{r_o}r\right)^d\right\}r^2 = \frac2{2d\,\eps^2}r^2.
\]
Simplifying by the smoothness identity $(r_i/r)^d + (r_o/r)^d = 2$ and multiplying by $2d(d-2)\eps^2)$, this simplifies to 
\[
4d(d-2)\eps^2 + d(r_i^2 + r_o^2) - 4 r^2 = 2(d-2)\,r^2
\]
and overall
\[
r_i^2 + r_o^2 = 2r^2 - 4(d-2)\eps^2, \qquad r_i^d + r_o^d = 2r^2.
\]
We can thus find $r_i$ as the root of the auxiliary function
\[
\xi_\eps(s) = \sqrt{2\,r^2 - 4(d-2)\eps^2 - s^2} - \sqrt[d]{2r^d - s^d}.
\]
We observe that
\[
\xi_\eps(0) = \sqrt{2r^2 - 4(d-2)\eps^2} - \sqrt[d]{2}r \approx (\sqrt{d}-\sqrt[d]{2})r>0, \qquad \xi_\eps(r) = \sqrt{r^2 - 4(d-2)\eps^2} - r<0
\]
if $\eps$ is a small positive number. In particular, $\xi_\eps$ is well-defined on $[0,r]$ and guaranteed to have a root which can be found by bisection. Note that
\begin{align*}
\xi_\eps'(s) &= s^{d-1}\big(2r^d-s^d\big)^\frac{1-d}d - s\big(2r^2 - s^2- 4(d-2)\eps^2 \big)^{-\frac12}\\
	&<   s^{d-1}\big(2r^d-s^d\big)^\frac{1-d}d - s\big(2r^2 - s^2 \big)^{-\frac12}\\
	&= \left(\frac{2r^d - s^d}{s^d}\right)^\frac{1-d}d - \left(\frac{2r^2 - s^2}{s^2}\right)^{-\frac12}
	\quad\leq 0
\end{align*}
i.e.\ $\phi_\eps$ is strictly monotone decreasing on $(0,r)$. In particular, the radii $r_i, r_o$ are uniquely determined. To see that $\xi_\eps'<0$, note that
\[
\left(2\zeta^d-1\right)^\frac{d-1}d \geq (2\zeta^2-1)^{1/2}\qquad\forall\ \zeta \in (1,\infty)
\]
where $\zeta$ serves as the proxy for $r/s$ and we took inverses. This inequality holds true since $\zeta^d\geq \zeta^2$ for $d\geq 2$ and $\zeta\geq 1$, and also $z^{(d-1)/d}\geq z^\frac12$ for $z\geq 1$ and $d\geq 2$.

