		M_{6,1}\arrow[r,red, thick] \arrow[d,red, thick]\&  \textcolor{green}{M_{6,2}}\arrow[d] \& \arrow[l,red, thick] M_{6,3}\arrow[d]\arrow[r,red, thick] \& \textcolor{green}{M_{6,4}}\arrow[d] \&\arrow[l,red, thick] M_{6,5} \arrow[d]\arrow[r,red, thick]\& \textcolor{green}{M_{6,6}}\arrow[d] \& \arrow[l]M_{6,7}\arrow[d] \\
