\appendix	
	\section{Categorical definitions}\label{app:cat_defis}
	In this section, we revise some necessary categorical definitions. \\
	Let $\mathcal{C}$ be a category.
	\subsection{Limits and Colimits}
	\begin{definition}
		A \emph{diagram} $F$ indexed by a poset $(P,\leq)$ is a functor from the poset category $P$ to $\mathcal{C}$, i.e. every $p\in P$ is mapped to an object $F_p$ in $\mathcal{C}$ and any $p\leq q$ to a morphism $\phi_{p,q}:F_p\to F_q$ in $\mathcal{C}$, such that for any $p\leq q$ and $q\leq r$, it holds that $\phi_{q,r}\circ\phi_{p,q}=\phi_{p,r}$. 
	\end{definition}
	\begin{definition} Let $F:(P,\leq)\to\mathcal{C}$ be a diagram indexed by $(P,\leq)$. 
		A \emph{cone} of $F$ is an object $A$ of $\mathcal{C}$ together with a family $(\rho_p)_{p\in P}$ of morphisms $\rho_p:A\to F_p$, such that for any morphism $\phi_{p,q}:F_p\to F_q$ we have that $\rho_q=\phi_{p,q}\circ\rho_p$.\\
		A \emph{limit} of the diagram $F$ is a universal cone in the following sense: it is a cone $(L,(\psi_p)_{p\in P})$ with the property that for any other cone $(A,(\rho_p)_{p\in P})$ there exist a unique morphism $u:A\to L$ such that $\rho_p=\psi_p\circ u$ for all $p\in P$. 
	\end{definition}

	\begin{definition}
		Let $F:(P,\leq)\to\mathcal{C}$ be a diagram indexed by $(P,\leq)$. 
		A \emph{cocone} of $F$ is an object $B$ of $\mathcal{C}$ together with a family $(\tau_p)_{p\in P}$ of morphisms $\tau_p: F_p\to B$, such that for any morphism $\phi_{p,q}:F_p\to F_q$ we have that $\tau_p=\tau_q\circ\phi_{p,q}$.\\
		A \emph{colimit} of the diagram $F$ is a universal cocone in the following sense: it is a cocone $(C,(\sigma_p)_{p\in P})$ with the property that for any other cone $(B,(\tau_p)_{p\in P})$ there exist a unique morphism $u:C\to B$ such that $\tau_p=u\circ\sigma_p $ for all $p\in P$. 
	\end{definition} 
	Note that the limit and colimit, respectively, are \textit{essentially unique}, meaning that they are only unique up to an unique isomorphism. 

	\subsection{Kan extensions}\label{app:subsec_Kan}
	In order to extend persistence modules indexed by a poset $P$ to persistence modules indexed by another poset $Q$, which is a superset of $P$, we use categorical concepts that are called \textit{Kan extensions}. We will directly apply it to the setting of posets and functors between posets, however, the general definitions can be found in introductory books on category theory, for example in \cite{maclane_categories}. \\
	For a given functor between two posets $F:A\to B$ and a given $b\in B$ we define the sets 
	\begin{align*}
		A(F\leq b):=\{a\in A:F(a)\leq b\} \quad \mbox{ and }\quad A(F\geq b):=\{a\in A:F(a)\geq b\}.
	\end{align*}
	Let $M:A\to\cat{Vec}$ be a persistence module, then the \textit{left} Kan extension along the functor $F:A\to B$ is a persistence module $\mathrm{Lan}_F(M):B\to\cat{Vec}$ defined by
	\begin{align*}
		\mathrm{Lan}_F(M)(b):=\colimit M|_{ A(F\leq b)}.
	\end{align*}
	The structure maps $\mathrm{Lan}_F(M)(b)\to \mathrm{Lan}_F(M)(b')$ for $b\leq b'$ are given by the universal property of colimits. Again by universality of colimits, a morphism $f:M\to N$ between persistence modules $M,N\in\cat{Vec}^A$ induces a morphism $\mathrm{Lan}_F(f):\mathrm{Lan}_F(M)\to\mathrm{Lan}_F(N)$, making the left Kan extension a functor.\\
	In an analogous way we define the \textit{right} Kan extension of a persistence module $M:A\to\cat{Vec}$ along a functor $F:A\to B$ as
	\begin{align*}
		\mathrm{Ran}_F(M)(b):=\limit M|_{A(F\geq b)}
	\end{align*}
	with structure maps $\mathrm{Ran}_F(M)(b)\to \mathrm{Ran}_F(M)(b')$ for $b\leq b'$ given by the universal property of limits. As in the previous case, due to the universality of limits the right Kan extension is functorial meaning that it sends a morphism between persistence modules $f:M\to N$ to an induced morphism $\mathrm{Ran}_F(f):\mathrm{Ran}_F(M)\to\mathrm{Ran}_F(N)$.

	\begin{remark}
		Kan extensions are useful for the definition of \textit{continuous extensions} of discrete persistence modules. Given a $\Z^n$-indexed module, one obtains a $\R^n$-indexed module for example by taking the left Kan extension of the $\Z^n$-indexed module along the inclusion functor $\iota:\Z^n\hookrightarrow \R^n$.
	\end{remark}



