			&=g\circ h^{-1}\circ i^M_p \circ \pi^L_p\circ f((v_r)_{r\in\partial I})=g\circ h^{-1}\circ i^M_p \circ \pi^{L}_p((v_r)_{r\in L})\\
			&=g\circ h^{-1}\circ i^M_p (v_p)=g\circ h^{-1}\circ i^M_q (M_{p\leq q}(v_p)).
		\end{align*}
		Now, we define $w_q:=M_{p\leq q}(v_p)$. Since $q\geq p$, there is a path $\Gamma'=(q,p,p_1,...,p_n,q) $ in $P$ and a section $(w_q,v_p,v_{p_1},...,v_{p_n},v_q)$ of $M$ along $\Gamma'$ and hence by Proposition \ref{prop_path} it holds that $[w_q]_M=[v_q]_M$ in the colimit of $M$. In other words, $i^M_q(w_q)=i^M_q(v_q)$. This yields
		\begin{align*}
			g\circ h^{-1}\circ i^M_q (M_{p\leq q}(v_p))&=g\circ h^{-1}\circ i^M_q (w_q)=g\circ h^{-1}\circ i^M_q (v_q)=g\circ i^U_q(v_q) \\
			&=i^{\partial I}_q(v_q) = [v_q]_{\partial I}.
		\end{align*}
		It remains to show that $f$ is surjective and $g$ is injective.\\
		\underline{Surjectivity of $f$:} Let $r':\limit M\to\limit M_{\partial I}$ be the canonical section restriction map $(v_r)_{r\in P}\mapsto (v_r)_{r\in\partial I}$. Then, the restriction $r:\limit M\to \limit M|_L$ can be seen as composition of two restrictions, i.e. $r=f\circ r'$. Since $r$ is the inverse of the isomorphism $e$, $r$ is surjective and so is $f$.\\
		\underline{Injectivity of $g$:} Let $h':\colimit M_{\partial I}\to \colimit M$ be the unique map such that $i^{M}_q(v_q)=h'\circ i^{\partial I}_q(v_q)$ for all $q\in\partial I$ and $v_q\in M_q$, which exists by the universal property of $\colimit M_{\partial I}$ since $\colimit M$ is in particular a cocone of the diagram $M_{\partial I}$. Hence, $h'$ maps $[v_q]_{\partial I}$ to $[v_q]_{M}$. It holds that $h=h'\circ g$ for the isomorphism $h$ in Diagram \ref{comm_diag_1_app}. This shows that $g$ is injective.
	\end{proof}

	\section{Probability in Banach spaces}\label{app:prob_banach}

	Here we summarize a few results from the theory of probability of Banach spaces, as presented in \cite{bubenik2015}. We assume that $\mathcal{B}$ is a real separable Banach space with norm $\|\cdot\|$ and topological dual space $\mathcal{B}^*$. Assume further that $V:(\Omega,\mathcal{F},P)\to \mathcal{B}$ is a Borel measurable random variable defined on the probability space $(\Omega,\mathcal{F},P)$. By composition $\|V\|:\Omega\stackrel{V}{\to} \mathcal{B}\stackrel{\|\cdot\|}{\to}\mathbb{R}$ we obtain a real valued random variable. Furthermore, we obtain a real valued random variable by composition with elements $f$ of the dual space $f(V):\Omega\stackrel{V}{\to}\mathcal{B}\stackrel{f}{\to}\mathbb{R}$. Recall that the expected value of a real random variable $X:(\Omega,\mathcal{F},P)\to \R$ is defined as $E(X)=\int XdP=\int_{\Omega}X(\omega)dP(\omega)$. For random variables with values in a Banach space the so-called \textit{Pettis integral} yields an analogue to the expected value.

	\begin{definition}\label{def:pettis_integral}
		Let $V:(\Omega,\mathcal{F},P)\to \mathcal{B}$ be a Borel random variable with values in the real separable Banach space $\mathcal{B}$. An element $E(V)\in\mathcal{B}$ is called the Pettis integral of $V$ if $E(f(V))=f(E(V))$ for all $f\in\mathcal{B}^*$. 
	\end{definition}
	The following proposition yields a sufficient condition for Pettis integrability. 
	\begin{proposition}
		If $E\|V\|<\infty$, then $V$ has a Pettis integral and $\|E(V)\|\leq E\|V\|$.
	\end{proposition}
	For the further framework two notions of convergence of random variables with values in a Banach space are important. Let $(V_n)_{n\in \mathbb{N}}$ be a sequence of independent copies of $V$ and let further $S_n:=\sum_{i=1}^n V_n$. Analogously as for real valued random variables, we define that $(V_n)_{n\in\mathbb{N}}$ converges \textit{almost surely} to $V$ if $P(\lim_{n\to\infty}V_n=V)=1$. Furthermore, $(V_n)_{n\in\mathbb{N}}$ converges \textit{weakly} to $V$ if for all bounded continuous functions $\phi:\mathcal{B}\to\R$ it holds that $\lim_{n\to\infty}E(\phi(V_n))=E(\phi(V))$. 
	\begin{theorem}(Strong law of large numbers)\\
		It holds that $(\frac{1}{n}S_n)\to E(V)$ almost surely iff $E\|V\|<\infty$.
	\end{theorem}
	We call a random variable $V$ with values in a Banach space \textit{Gaussian} if $f(V)$ is a real Gaussian random variable with mean zero for each $f\in\mathcal{B}^*$. The \textit{covariance structure} of a random variable with values in a Banach space is defined as the set of expectations $E[(f(V)-E(f(V)))(g(V)-E(g(V)))]$ for $f,g\in\mathcal{B}^*$ and it determines a Gaussian random variable completely. 
	\begin{theorem}(Central limit theorem)\\
		Let $\mathcal{B}$ be a Banach space that has type 2. Let further $E(V)=0$ and $E(\|V\|^2)<\infty$. Then, $\frac{1}{\sqrt{n}}S_n$ converges weakly to a Gaussian random variable with the same covariance structure as $V$.
	\end{theorem}  
	Recall that for $2\leq p<\infty$, the $L^p$-spaces are of type 2.





