\begin{remark}[The Idea of Proposed Scheme]
  To achieve the proposed sum-SDoF lower bound, we propose a unified transmission scheme for arbitrary antenna configurations, detailed in Section-IV. The idea of this scheme is integrating RIS interference and leakage elimination, ZF transmit beamforming, and receiver ID techniques together. Specifically, we adopt RIS beamforming to reduce the rank of interference and leakage matrices, yielding a closed-form relationship for matrices rank and number of RIS elements. After that, ZF transmit beamforming and receiver ID are taken into use with judiciously chosen configurations. Finally, we establish a sum-SDoF maximization problem, namely Problem (P0), by linear integer programming.
\end{remark}

\begin{remark}[Solution Algorithm to Problem (P0)]
	Note that Problem (P0) is a linear integer programming problem, which is NP-hard and non-convex. Thus, the optimal solution to Problem (P0) can be given by the BnB approach, which relies on bounding technique reduces the complexity of exhaustive search. We therefore invoke GROUBI software for solving this linear integer programming problem, where BnB is used with optimal solutions returned.	
\end{remark}

\begin{corollary}[Symmetry Antenna Configurations]
	If we assume that symmetry antenna configuration $M_1=M_2=M,\,N_1=N_2=N$, we can re-write Problem (P0) as
	\begin{subequations}
		\begin{eqnarray}
			\!\!\!\!\!\!\!\!\!\!\!\!\! (\text{P0}_1) \, \max_{\substack{
					t, f_{e}, \\
					f \in \mathbb{Z}^+
			}} && \!\!\!\!\!\!\!\! t \nonumber \\
			\text{s.t.} &&  \!\!\!\!\!\!\!\! t \le N - D + M  -D_{e}, \\
			&& \!\!\!\!\!\!\!\! t \le M - D + N -D_{e}, \\
			&& \!\!\!\!\!\!\!\! t \le 2\min\{N,M-D_{e}\},   \\
			&& \!\!\!\!\!\!\!\! D_e = \min\{N_e,M\} -f_e, \\
			&& \!\!\!\!\!\!\!\! D =  \min\{N,M\} - f, \\ 
			&& \!\!\!\!\!\!\!\! f_e \max\{N_e,M\} + f\max\{N,M\} \le \frac{R}{2}.  
		\end{eqnarray}
	\end{subequations} 
By analysis, we can obtain tabular closed-form sum-SDoF from Problem $(\text{P0}_1)$ in Table 2. Please refer to Appendix B for details of the derivation. 
\end{corollary}


	\begin{algorithm}[t]
	\caption{Algorithm for Minimizing Nuclear Norm to Rank Minimization}
	\begin{algorithmic}[1]
		\State \textbf{Input:} $\overline{\mathbf{H}} = \mathbf{H} + \mathbf{G} \mathbf{\Phi} \mathbf{D}$
		\State \textbf{Output:}  \text{min\_rank}
		\State \textbf{Initialization:} $\text{min\_rank} = \infty$ 
		\For{$\textit{Iteration} = 0$ \textbf{to} $\textit{Iteration} =\textit{Iteration}_{\max}$}   
		\State Solve optimization problem $\min_\mathbf{\Phi} \|\mathbf{H}\|_*$ using the splitting conic solver in CVXPY
		\If{Solution is successful}
		\State Obtain optimal $\mathbf{\Phi}^*$ from $\min_\mathbf{\Phi} \|\mathbf{H}\|_*$
		\State Compute $\mathbf{M}_{\text{optimal}} = \mathbf{H} + \mathbf{G} \mathbf{\Phi}^* \mathbf{D}$
		\State Set elements of $\mathbf{M}_{\text{optimal}}$ with absolute value less than $10^{-3}$ to $0$
		\State Compute singular values of $\mathbf{M}_{\text{optimal}}$
		\State Reconstruct $\mathbf{M}_{\text{modified}}$  by setting singular values less than $10^{-3}$ to $0$
		\State Compute the rank of $\mathbf{M}_{\text{modified}}$ as $D$
		\If{$D < \text{min\_rank}$}
		\State Update $\text{min\_rank} = D$	 
		\EndIf
		\Else
		\State Output failure message
		\EndIf
		\EndFor
		\State \textbf{Output:}   $\text{min\_rank}$
	\end{algorithmic}
\end{algorithm}

