			}} && \!\!\!\! t \nonumber \\
			\text{s.t.} &&  \!\!\!\!\! t \le N_2- \min\{N_2,M_1\} + M_1 + f_{21}, \\
			&& \!\!\!\! t \le N_1 - \min\{N_1,M_2\} + M_2 + f_{12}, \\
			&& \!\!\!\! t \le  \min\{N_1,M_1\} + \min\{N_2,M_2\},   \\
			&& \!\!\!\! f_{12} \max\{N_1,M_2\} + \nonumber \\   
			&& \!\!\!\! \qquad \qquad \quad f_{21}\max\{N_2,M_1\}   \le R. 
