\begin{theorem}[Linear and Numerical Upper Bound]
%It is divided into two cases based on whether leakage signals can be completely eliminated by RIS.	

A linear and numerical sum-SDoF  upper bound of an active RIS-assisted MIMO wiretap IC, defined in Section-II, is given as follows:
\begin{eqnarray}
 && \!\!\!\!\!\!\!\!\!\!\!\! d_1 + d_2 \le \nonumber \\
 && \!\!\!\!\!\!\!\!\!\!\!\!	\begin{cases}
		\min\{M_1 + M_2, N_1 + N_2, M_1 + N_2 - D_{21},  \\
		\quad \quad   M_2 + N_1 - D_{12}\}, \qquad \,\, R > (M_1 + M_2)N_e,  \\
		\min\{M_1 + M_2-D_e, N_1 + N_2,\max\{M_1,N_2\},  \\ \quad \quad \,\,  \max\{M_2,N_1\}\},  \qquad \quad  R \le (M_1 + M_2)N_e.
			\end{cases}
			\label{eq6}
		\end{eqnarray}
where the rank of matrix $\overline{\mathbf{H}}_{ji}$ by denoted by $D_{ji}$ with  $\mathbf{\Phi} \in \mathbb{C}^{\overline{R} \times \overline{R}}$ and $\overline{R}  = R - (M_1 + M_2)N_e$, the rank of  matrix $\overline{\mathbf{H}}_{e} \triangleq [\mathbf{H}_{e1},\mathbf{H}_{e2}] + \mathbf{G}\mathbf{\Phi}[\mathbf{D}_{1},\mathbf{D}_{2}]$ is denoted by $D_{e}$. The value of those matrices' rank can be obtained from Algorithm 1.

%When $R \le (M_1 + M_2)N_e$, a linear and numerical sum-SDoF upper bound of an active RIS-assisted MIMO wiretap IC, defined in Section-II, is given as follows: 
