\section{Proof of Theorem 1}





\subsection{The Proposed Scheme and Associated Sum-SDoF Lower Bound Maximization Problem}

In our proposed scheme, there are three steps regarding to the scheme design.

\textit{Step-I (SVD Transformation):} We first use  brief notations on the cascaded channel. To this end, we denote leakage channels as $\overline{\mathbf{H}}_{ei} \triangleq \mathbf{H}_{\mathrm{e}i}+\mathbf{G}_{\mathrm{e}}\mathbf{\Phi }\mathbf{D}_{i},\,i=1,2$, and interference and desired signal channels as $\overline{\mathbf{H}}_{ji} \triangleq \mathbf{H}_{ji}+\mathbf{G}_{j}\mathbf{\Phi }\mathbf{D}_{i},\,i,j=1,2$. Using these short notations, we have the following input-output relationship, 
\begin{subequations}
	\begin{eqnarray}
	&&	\mathbf{y}_\mathrm{e} = \overline{\mathbf{H}}_{\mathrm{e}1}\mathbf{P}_1\mathbf{x}_1 + 
		\overline{\mathbf{H}}_{\mathrm{e}2}\mathbf{P}_2\mathbf{x}_2, \\
	&&	\mathbf{y}_1 = \overline{\mathbf{H}}_{11}\mathbf{P}_1\mathbf{x}_1 + 
		\overline{\mathbf{H}}_{12}\mathbf{P}_2\mathbf{x}_2, \\
	&&	\mathbf{y}_2 = \overline{\mathbf{H}}_{21}\mathbf{P}_1\mathbf{x}_1 + 
		\overline{\mathbf{H}}_{22}\mathbf{P}_2\mathbf{x}_2,
	\end{eqnarray}
\end{subequations}
where $\overline{\mathbf{H}}_{\mathrm{e}i} \in \mathbb{C}^{N_e \times M_i},\,i=1,2$,  $\overline{\mathbf{H}}_{ji} \in \mathbb{C}^{N_j \times M_i},\,i,j=1,2$, $\mathbf{P}_i \in \mathbb{C}^{M_i \times \delta_i},\,i=1,2$, and $\mathbf{x}_i \in \mathbb{C}^{\delta_i \times 1},\,i=1,2$. Note that $\delta_i$ denotes the amount of data symbols transmitted at $\text{Tx}_i$, which will be designated later on. Next, we perform SVD of the matrices of IC, leading to the following input-output relationship, 
\begin{subequations}
	\begin{eqnarray}
		&&	\mathbf{y}_\mathrm{e} = \overline{\mathbf{H}}_{\mathrm{e}1}\mathbf{P}_1\mathbf{x}_1 + 
		\overline{\mathbf{H}}_{\mathrm{e}2}\mathbf{P}_2\mathbf{x}_2, \label{4a}\\
		&&	\mathbf{y}_1 = \overline{\mathbf{H}}_{11}\mathbf{P}_1\mathbf{x}_1 + 
	\mathbf{U}_{12}{\bf{\Sigma}}_{12}\mathbf{V}^T_{12}\mathbf{P}_2\mathbf{x}_2, \label{4b} \\
		&&	\mathbf{y}_2 = \mathbf{U}_{21}{\bf{\Sigma}}_{21}\mathbf{V}^T_{21}\mathbf{P}_1\mathbf{x}_1 + 
		\overline{\mathbf{H}}_{22}\mathbf{P}_2\mathbf{x}_2, \label{4c}
	\end{eqnarray}
\end{subequations}
where unitary matrices $\mathbf{U}_{12} \in \mathbb{C}^{N_1 \times N_1}$, $\mathbf{V}_{12} \in \mathbb{C}^{M_2 \times M_2}$, $\mathbf{U}_{21} \in \mathbb{C}^{N_2 \times N_2}$, $\mathbf{V}_{21} \in \mathbb{C}^{M_1 \times M_1}$, and diagonal matrices for singular values ${\bf{\Sigma}}_{12} \in \mathbb{C}^{N_1 \times M_2}$ and  ${\bf{\Sigma}}_{21} \in \mathbb{C}^{N_2 \times M_1}$. Note that ${\bf{\Sigma}}_{12}$ and  ${\bf{\Sigma}}_{21}$ rank are with $D_{12}$ and $D_{21}$, respectively. Through $\mathbf{y}_1' = \mathbf{U}_{12}^H\mathbf{y}_1, \overline{\mathbf{H}}_{11}' = \mathbf{U}_{12}^H\overline{\mathbf{H}}_{11},$ $\mathbf{y}_2' = \mathbf{U}_{21}^H\mathbf{y}_2, \overline{\mathbf{H}}_{22}' = \mathbf{U}_{21}^H\overline{\mathbf{H}}_{22},$ we can transform \eqref{4a}-\eqref{4c} into 
\begin{subequations}
	\begin{eqnarray}
		&&	\mathbf{y}_\mathrm{e} = \overline{\mathbf{H}}_{\mathrm{e}1}\mathbf{P}_1\mathbf{x}_1 + 
		\overline{\mathbf{H}}_{\mathrm{e}2}\mathbf{P}_2\mathbf{x}_2, \\
		&&	\mathbf{y}_1' = \overline{\mathbf{H}}_{11}'\mathbf{P}_1\mathbf{x}_1 + 
	 {\bf{\Sigma}}_{12}\mathbf{V}^T_{12}\mathbf{P}_2\mathbf{x}_2, \\
		&&	\mathbf{y}_2' =  {\bf{\Sigma}}_{21}\mathbf{V}^T_{21}\mathbf{P}_1\mathbf{x}_1 + 
		\overline{\mathbf{H}}_{22}'\mathbf{P}_2\mathbf{x}_2.
	\end{eqnarray}
\end{subequations}
To maximize the sum-SDoF achieved and ensure zero leakage, we need to design the transmit beamforming matrices $\mathbf{P}_i,\,i=1,2$ and RIS beamforming matrix ${\bf{\Phi}}$, which will be addressed in Step-II. 

\textit{Step-II (Design of Beamforming Matrices):} We then consider 
the transmit beamforming matrices and RIS beamforming matrix design. In order to enlarge the capabilities of ZF and ID following RIS beamforming, the design principle of RIS beamforming is to reduce the rank of leakage and interference matrices by explicitly eliminating their rows/columns.
To this end, we establish the following linear equations, 
\begin{subequations}
	\begin{eqnarray}
&& \!\!\!\!\!\!\!\!\!\!\!\!\!\!  	\text{vec}(\underbrace{\mathbf{H}_{\mathrm{e}i}+\mathbf{G}_{\mathrm{e}}\mathbf{\Phi }\mathbf{D}_{i}}_{\overline{\mathbf{H}}_{ei}}) = \begin{bmatrix}
			\mathbf{0}_{ f_{ei}\max\{N_e,M_i\}}\\ 
			\mathbf{*}
		\end{bmatrix},  
	i=1,2, \label{6a} \\
&&	\!\!\!\!\!\!\!\!\!\!\!\!\!\!  	\text{vec}(\underbrace{\mathbf{H}_{ji}+\mathbf{G}_{j}\mathbf{\Phi }\mathbf{D}_{i}}_{\overline{\mathbf{H}}_{ji}}) = \begin{bmatrix}
		\mathbf{0}_{ f_{ji}\max\{N_j,M_i\}}\\ 
		\mathbf{*}
	\end{bmatrix}, \nonumber \\ 
&&\!\!\!\!\!\!\!\!\!\!\!\!\!\!  \qquad \qquad \qquad \qquad \qquad \qquad \qquad  	i,j=1,2,\,i\ne j, \label{6b}
	\end{eqnarray}
\end{subequations}
where $*$ denotes non-zero elements. Obviously, \eqref{6a} stands for 
the elimination of $f_{ei}$ rows if $N_e \leq M_i$ or the elimination of $f_{ei}$ columns if $M_i < N_e$.  Likewise, \eqref{6b} stands for the elimination of $f_{ji}$ rows if $N_j \leq M_i$ or the elimination of $f_{ji}$ columns if $M_i < N_j$.
This leads to the following rank reduction relationship, 
\begin{subequations}
	\begin{eqnarray}
&&		D_{e1} = \min\{N_e, M_1\} - f_{e1},  \label{7a} \\
&&      D_{e2} = \min\{N_e, M_2\} - f_{e2}, \label{7b} \\
&&		D_{12} = \min\{N_1, M_2\} - f_{12}, \label{7c}\\
&&		D_{21} = \min\{N_2, M_1\} - f_{21}, \label{7d}
	\end{eqnarray}
\end{subequations}
where $D_{e1}$, $D_{e2}$, $D_{12}$, $D_{21}$ denote the rank of matrices $\overline{\mathbf{H}}_{\mathrm{e}1}$, $\overline{\mathbf{H}}_{\mathrm{e}2}$, $\overline{\mathbf{H}}_{12}$, $\overline{\mathbf{H}}_{21}$, respectively. In order to solve \eqref{6a}-\eqref{6b}, due to Appendix A, the following relationship should satisfy
\begin{eqnarray}
&&	\!\!\!\!\!\!\!\! f_{e1} \max\{N_e, M_1\} + f_{e2} \max\{N_e, M_2\} +  \nonumber  \\ && \quad \!\!\!\!\!\!\!\! f_{12}\max\{N_1,M_2\} + f_{21}\max\{N_2,M_1\} \le R.  \label{8}
\end{eqnarray}


Under these rank-deficient leakage and interference matrices, we then design the transmit beamforming matrices with reference to \cite{Krishnamurthy}. Foremost, we need to null all leakage signals out, i.e.,
\begin{equation}
	\overline{\mathbf{H}}_{\mathrm{e}1}\mathbf{P}_1 = \mathbf{0}, \quad 	\overline{\mathbf{H}}_{\mathrm{e}2}\mathbf{P}_2 = \mathbf{0}. 
\end{equation} 
Equivalently, $\mathbf{P}_1 \in \mathbb{C}^{M_1 \times \delta_1}$ and $\mathbf{P}_2 \in \mathbb{C}^{M_2 \times \delta_2}$ must locate at the null-space of $\overline{\mathbf{H}}_{\mathrm{e}1}$ and $\overline{\mathbf{H}}_{\mathrm{e}2}$, respectively.   
Then, there can be two attempts regarding to the order of ZF and ID used for interference signals. 

\textit{Attempt 1:} Let $\delta_1 = \min\{N_1,M_1 - D_{e1}\}$, i.e., $\text{Tx}_1$ transmits at its maximal ability. Regarding this, we design the transmission at $\text{Tx}_2$ by using ZF first then ID. To be specific, let the first $M_1 - \delta_1 -D_{e1}$ elements in $\mathbf{V}^T_{21}\mathbf{P}_1$ be zero, which can be done by solving
\begin{equation}
\begin{bmatrix}
	\mathbf{V}^T_{21}\\
	\overline{\mathbf{H}}_{\mathrm{e}1}
\end{bmatrix}\mathbf{P}_1 	 = \begin{bmatrix}
		\mathbf{0}_{M_1 - \delta_1},	\mathbf{*},  
		\mathbf{0}_{N_e}
	\end{bmatrix}^T.  
\end{equation}
After ZF, it can be seen that there are $D_{21} - (M_1 - \delta_1 -D_{e1})$ interference at $\text{Tx}_2$. The above interference is then dealt with ID at  $\text{Tx}_2$. As such, $\text{Tx}_2$ should transmit $N_2 - (D_{21} - (M_1 - \delta_1 -D_{e1}))$ symbols, namely $\delta_2 = N_2 - (D_{21} - (M_1 - \delta_1 -D_{e1}))$. 

\textit{Attempt 2:} Let $\delta_1 = \min\{N_1,M_1 - D_{e1}\}$, i.e., $\text{Tx}_1$ transmits at its maximal ability. Regarding this, we design the transmission at $\text{Tx}_2$ by using ID first then ZF. To be specific, let the first $N_1 - \delta_1$ elements in $\mathbf{V}^T_{12}\mathbf{P}_2$ be non-zero, which is dealt with ID. Then, we suffice to null  remaining $D_{12} - (N_1 - \delta_1)$ interference at $\text{Tx}_1$ out. This can be done by solving
\begin{equation}
	\begin{bmatrix}
		\mathbf{V}^T_{12}\\
		\overline{\mathbf{H}}_{\mathrm{e}2}
	\end{bmatrix}\mathbf{P}_2 	 = \begin{bmatrix}
		\mathbf{*}, 	\mathbf{0}_{D_{12} - (N_1 - \delta_1)}, 
		\mathbf{0}_{N_e}
	\end{bmatrix}^T.  
\end{equation}
As such, $\text{Tx}_2$ should transmit $M_2 - (D_{12} - (N_1 - \delta_1)) -D_{e2}$ symbols, namely $\delta_2 = M_2 - (D_{12} - (N_1 - \delta_1))-D_{e2}$.

Furthermore, the number of symbols transmitted at $\text{Tx}_2$ should satisfy the maximum transmission and decoding ability, namely $\min\{N_2,M_2-D_{e2}\}$. Therefore, we have $\delta_2 \le \min\{N_2,M_2-D_{e2}\}$. To obtain the exact sum-SDoF achieved, we next formulate and solve a sum-SDoF lower bound maximization problem.

\textit{Step-III (Optimization):} Because from Step-II, we have
\begin{equation}
	\delta_1 + \delta_2 \le   
	\begin{cases}
		N_2 - D_{21} + M_1  -D_{e1}, \\ 
		M_2 - D_{12} + N_1 -D_{e2}, \\
		\min\{N_1,M_1-D_{e1}\} +    \min\{N_2,M_2-D_{e2}\},
	\end{cases} \nonumber 
\end{equation}
the sum-SDoF lower bound maximization problem can be formulated as follows,
\begin{eqnarray}
\!\!\!\!\!\!\!\!\!\!\!\! (\text{P0$'$}) \,\,\,	\max_{\substack{
		  f_{e1}, 
			f_{e2},  f_{12},   \\
			f_{21} \in \mathbb{Z}^+, t
	}} && \!\!\!\!\!\! t \nonumber \\
	\text{s.t.} &&  \!\!\!\!\!\! t \le N_2 - D_{21} + M_1  -D_{e1}, \\
	&& \!\!\!\!\!\! t \le M_2 - D_{12} + N_1 -D_{e2}, \\
	&& \!\!\!\!\!\! t \le \min\{N_1,M_1-D_{e1}\} + \nonumber \\
	&& \!\!\!\!\!\! \qquad \qquad \min\{N_2,M_2-D_{e2}\}, \\
	&& \!\!\!\!\!\! \eqref{7a}-\eqref{7d},\,\eqref{8}.
\end{eqnarray}
It can be seen that Problem (P0$'$) is equivalent to Problem (P0), thus Theorem 1 is proven. 



\section{Proof of Theorem 2}

In order to prove $R > (M_1 + M_2)N_e$, leakage signals can be completely canceled by RIS. Thus, $\overline{R} = R - (M_1 + M_2)N_e$ RIS elements are used for eliminating interference, which is equivalent to that in MIMO IC. In this case, we therefore first utilize the result of in \cite[Theorem 4]{Tang}. This is because, at $R > (M_1 + M_2)N_e$, all leakage signals can be removed by the RIS and it is equivalent to a MIMO IC without eavesdropping. Then, by means of in \cite[Theorem 4]{Tang}, we discuss case by case for deriving the desired upper bound. The details of this proof are illustrated as follows:


According to \cite[Theorem 4]{Tang}, we have
\begin{align}
	d_1 + d_2 &\leq \text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} & \mathbf{H}_{12} \end{bmatrix} \right) + \text{rk} \left( \begin{bmatrix} \mathbf{H}_{12} \\ \mathbf{H}_{22} \end{bmatrix} \right) - \text{rk}(\mathbf{H}_{12}), \ \label{EE01} \\
	d_1 + d_2 &\leq \text{rk} \left( \begin{bmatrix} \mathbf{H}_{22} & \mathbf{H}_{21} \end{bmatrix} \right) + \text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} \\ \mathbf{H}_{21} \end{bmatrix} \right) - \text{rk}(\mathbf{H}_{21}) . \label{EE02}
\end{align}

For the first part, we divide \eqref{EE01} into two cases, and then expand them into the following.

For $N_1 \leq M_2$ Case, we have
\begin{subequations}
	\begin{eqnarray}
		&& \!\!\!\!\!\!\!\!\! \text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} & \mathbf{H}_{12} \end{bmatrix} \right) = \min \{N_1,M_1+M_2\} = N_1, \\
		&& \!\!\!\!\!\!\!\!\! \text{rk} \left( \begin{bmatrix} \mathbf{H}_{12} \\ \mathbf{H}_{22} \end{bmatrix} \right) = \min \{M_2,D_{12}+N_2\}, \\
		&& \!\!\!\!\!\!\!\!\! \text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} & \mathbf{H}_{12} \end{bmatrix} \right) + \text{rk} \left( \begin{bmatrix} \mathbf{H}_{12} \\ \mathbf{H}_{22} \end{bmatrix} \right) - \text{rk}(\mathbf{H}_{12}) \nonumber \\
		&&\!\!\!\!\!\!\!\!\! \quad = \min \{N_1+M_2-D_{12},N_1+N_2\}.\label{EE03}
	\end{eqnarray}
\end{subequations}

Otherwise, for $N_1 > M_2$ Case, we have
\begin{subequations}
	\begin{eqnarray}
		&&\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} & \mathbf{H}_{12} \end{bmatrix} \right) = \min \{N_1,M_1+D_{12}\}, \\
		&&\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\text{rk} \left( \begin{bmatrix} \mathbf{H}_{12} \\ \mathbf{H}_{22} \end{bmatrix} \right) = \min \{M_2,N_1+N_2\} = M_2, \\
		&&\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} & \mathbf{H}_{12} \end{bmatrix} \right) + \text{rk} \left( \begin{bmatrix} \mathbf{H}_{12} \\ \mathbf{H}_{22} \end{bmatrix} \right) - \text{rk}(\mathbf{H}_{12}) \nonumber \\
		&&\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\quad = \min \{N_1+M_2-D_{12},M_1+M_2\}.\label{EE04}
	\end{eqnarray}
\end{subequations}

For the second part, we divide \eqref{EE02} into two cases, and then expand them into the following.

For $N_2 \leq M_1$ Case, we have
\begin{subequations}
	\begin{eqnarray}
		&& \!\!\!\!\!\!\!\! \text{rk} \left( \begin{bmatrix} \mathbf{H}_{22} & \mathbf{H}_{21} \end{bmatrix} \right) = \min \{N_2,M_1+M_2\} = N_2, \\
		&& \!\!\!\!\!\!\!\! \text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} \\ \mathbf{H}_{21} \end{bmatrix} \right) = \min \{M_1,D_{21}+N_1\}, \\
		&& \!\!\!\!\!\!\!\! \text{rk} \left( \begin{bmatrix} \mathbf{H}_{22} & \mathbf{H}_{21} \end{bmatrix} \right) + \text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} \\ \mathbf{H}_{21} \end{bmatrix} \right) - \text{rk}(\mathbf{H}_{21}) \nonumber \\
		&&\!\!\!\!\!\!\!\! \quad = \min \{N_2+M_1-D_{21},N_1+N_2\}.\label{EE05}
	\end{eqnarray}
\end{subequations}

Otherwise, for $N_2 > M_1$ Case, we have
\begin{subequations}
	\begin{eqnarray}
		&&\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\text{rk} \left( \begin{bmatrix} \mathbf{H}_{22} & \mathbf{H}_{21} \end{bmatrix} \right) = \min \{N_2,M_2+D_{21}\}, \\
		&&\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} \\ \mathbf{H}_{21} \end{bmatrix} \right) = \min \{M_1,N_1+N_2\} = M_1, \\
		&&\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\text{rk} \left( \begin{bmatrix} \mathbf{H}_{22} & \mathbf{H}_{21} \end{bmatrix} \right) + \text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} \\ \mathbf{H}_{21} \end{bmatrix} \right) - \text{rk}(\mathbf{H}_{21}) \nonumber \\
		&&\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\quad = \min \{N_2+M_1-D_{21},M_1+M_2\}.\label{EE06}
	\end{eqnarray}
\end{subequations}

Combining \eqref{EE03} and \eqref{EE04}, we can obtain 
\begin{equation}
	\begin{aligned}
		d_1 + d_2 &\leq \text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} & \mathbf{H}_{12} \end{bmatrix} \right) + \text{rk} \left( \begin{bmatrix} \mathbf{H}_{12} \\ \mathbf{H}_{22} \end{bmatrix} \right) - \text{rk}(\mathbf{H}_{12}) \\  
		&\leq \min\{M_1 + M_2, N_1 + N_2, N_1 + M_2 - D_{12} \}.
	\end{aligned}
	\label{EE07}
\end{equation}

Combining \eqref{EE05} and  \eqref{EE06}, we can obtain 
\begin{equation}
	\begin{aligned}
		d_1 + d_2 &\leq \text{rk} \left( \begin{bmatrix} \mathbf{H}_{22} & \mathbf{H}_{21} \end{bmatrix} \right) + \text{rk} \left( \begin{bmatrix} \mathbf{H}_{11} \\ \mathbf{H}_{21} \end{bmatrix} \right) - \text{rk}(\mathbf{H}_{21}) \\
		&\leq \min\{M_1 + M_2, N_1 + N_2, N_2 + M_1 - D_{21} \}.
	\end{aligned}
	\label{EE08}
\end{equation}

Combining \eqref{EE07} and  \eqref{EE08}, we can obtain the desired upper bound 
\begin{equation}
	\begin{aligned}
		d_1 + d_2 &\leq \min\{M_1 + M_2, N_1 + N_2, \\
		&\quad M_1 + N_2 - D_{21}, M_2 + N_1 - D_{12}\}
	\end{aligned}
\end{equation}


\section{Conclusion}
In this paper, we established novel linear and numerical bounds for the active RIS-assisted MIMO wiretap IC, with linear beamforming techniques~\cite{Issa,Sridharan,Kao} and numerical bound derivation. Our contributions included: 1) we developed a linear and numerical lower bound through an enhanced transmission scheme building upon~\cite{Krishnamurthy} and~\cite{zheng2023dof}, formulated as an innovative linear integer programming problem for sum-SDoF lower bound maximization that  generalized~\cite{zheng2023dof} with security constraints; 2) we established a linear and numerical upper bound by combining the linear sum-DoF bound from~\cite[Theorem 4]{Tang} with nuclear norm minimization as a convex relaxation of the rank function; and 3) for symmetry antenna configurations, we obtained closed-form expressions for our lower bound through analysis. Extensive numerical simulations showed that our proposed bounds  tight alignment across many antenna configurations.



