\end{align}
In what follows, we use $\iota_i$ in place of $\iota_i^n$. Now, we consider the following two intervals of $[n]^2$ (see Figure \ref{fig:filt_sec5}):
\begin{equation}\label{eq:U_and_D}
U:=\{(i,j)\in [n]^2 : \ n\leq i + j \}\ \  \mbox{and} \ \ D:=\{(i,j)\in [n]^2 : n\leq i + j \leq n+1 \}.
\end{equation}

By proving the following claims, we complete the proof for the case of $\m=0$.
\begin{claim} \label{cl:rank_J=0}
    If $J\in \Int([n]^2)$ is not a proper subset of $U$, then $\rk_M(J)=0$.
\end{claim}

\begin{claimproof}

First, assume that 
there exists a point $p \in J-U$. Then, by the construction of $M$, $\dim (M(p)) = 0$ and thus $\rk_M (J)=0$ by monotonicity of $\rk_M$ (Remark \ref{rem:basic_properties}~\cref{item:monotonicity}).
Next, assume that $J=U$.
Since $\rk_M(U)=\rank(\varprojlim M|_U\rightarrow \varinjlim M|_U)$, it suffices to show $\varprojlim M|_U=0$. Again, since $D=\minzz(U)$
, by Lemma \ref{lem:fence}, it suffices to show that $\varprojlim M|_D=0$. 
By Equation (\ref{eq:iota}), the diagram $M|_D$ is given by 
\[\F^n\stackrel{\iota_0}{\longrightarrow}\F^{n+1}\stackrel{\iota_1}{\longleftarrow}\F^n\stackrel{\iota_1}{\longrightarrow}\F^{n+1}\stackrel{\iota_2}{\longleftarrow}\F^n\stackrel{\iota_2}{\longrightarrow}\F^{n+1}\stackrel{\iota_3}{\longleftarrow} \F^n \stackrel{\iota_3}{\longrightarrow}\cdots \stackrel{\iota_n}{\longleftarrow}\F^n.\]
From this, it is not difficult to see that $\varprojlim M|_D=0$. 
Without loss of generality, assume that $n=2$. Then, $M|_D$ is given by
$\F^2\stackrel{\iota_0}{\longrightarrow}\F^{3}\stackrel{\iota_1}{\longleftarrow}\F^2\stackrel{\iota_1}{\longrightarrow}\F^{3}\stackrel{\iota_2}{\longleftarrow}\F^2.$
By Convention \ref{con:limit_formula}, {a} vector $v:= (v_1,\ldots,v_{12})\in \F^{12}$ belongs to
$\varprojlim M|_D$ if and only if
\[(v_1,v_2)\stackrel{\iota_0}{\mapsto}(v_3,v_4,v_5)\stackrel{\iota_1}{\mapsfrom}(v_6,v_7)\stackrel{\iota_1}{\mapsto}(v_8,v_9,v_{10})\stackrel{\iota_2}{\mapsfrom}(v_{11},v_{12}),\]
{i.e.,} 
$v_k=0$ for all $k=1,\ldots, 12$.  

A more general proof follows. For $p \in D$, let $\pi_p: \varprojlim {M|}_D \to M(p)$ be the canonical projection. Since $M(i, n-i) = \mathbb{F}^n$ for $i = 0, \dots, n$, 
for any $v\in \varprojlim {M|}_D$, let
$\pi_{(i, n-i)}(v) =: (v_1^i, v_2^i, \dots, v_n^i) \in \mathbb{F}^n.$
Equations (\ref{eq:limit}) and (\ref{eq:iota}) imply the following equalities:
\[\begin{array}{rcccl}
    \pi_{(1, n)}(v) &=& \iota_{0} \circ \pi_{(0, n)}(v) &=& (0, v_1^0, v_2^0, \dots, v_n^0), \\
    \pi_{(1, n)}(v) &=& \iota_{1} \circ \pi_{(1, n-1)}(v) &=& (v_1^1, 0, v_2^1, \dots, v_n^1), \\
    \pi_{(2, n-1)}(v) &=& \iota_{1} \circ \pi_{(1, n-1)}(v) &=& (v_1^1, 0, v_2^1, v_3^1, \dots, v_n^1), \\
    \pi_{(2, n-1)}(v) &=& \iota_{2} \circ \pi_{(2, n-2)}(v) &=& (v_1^2, v_2^2, 0, v_3^2, \dots, v_n^2), \\
    && \vdots && \\
    \pi_{(i, n-i+1)}(v) &=& \iota_{i-1} \circ \pi_{(i-1, n-i+1)}(v) &=& (v_1^{i-1}, v_2^{i-1}, \dots, v_{i-1}^{i-1}, 0, v_i^{i-1}, \dots, v_n^{i-1}), \\
    \pi_{(i, n-i+1)}(v) &=& \iota_{i} \circ \pi_{(i, n-i)}(v) &=& (v_1^i, v_2^i, \dots, v_{i-1}^i, v_i^i, 0, \dots, v_n^i), \\
    && \vdots && \\
    \pi_{(n, 1)}(v) &=& \iota_{n-1} \circ \pi_{(n-1, 1)}(v) &=& (v_1^{n-1}, v_2^{n-1}, \dots, v_{n-1}^{n-1}, 0, v_n^{n-1}), \\
    \pi_{(n, 1)}(v) &=& \iota_{n} \circ \pi_{(n, 0)}(v) &=& (v_1^n, v_2^n, \dots, v_{n-1}^n, v_n^n, 0).
\end{array}\]
By comparing 
the $(2i-1)$-th and $(2i)$-th lines for $i=1\ldots,n$, we deduce that $v^i_j = 0$ for all $i = 0, 1, \dots, n$ and $j = 1, 2, \dots, n$. 
Therefore, 
$\pi_{(i, n-i)}(v) = 0$
for all $i=0,1,\ldots,n$ and in turn $v = 0$.
Since $v$ was an arbitrary element of $\varprojlim M|_D$, we have 
$\varprojlim M|_{D}=0$. \claimqedhere


\end{claimproof}


