\begin{claim} \label{cl:rank_Ui=1} 
    Let $J\in \Int([n]^2)$ such that $\bigcap_{i=0}^{n}U_i \subseteq J \subsetneq U$. Then, $\rk_M(J)=1$.
\end{claim}
\begin{claimproof}
Since $J \subsetneq U$, there exists $i\in [n]$ such that $J \subseteq U_i$.
Fix such $i$. Since $\max(J)=\{(n,n)\}$, by Lemma \ref{lem:fence}, we have the isomorphism 
$\varinjlim M|_{J} \stackrel{(\ast)}{\cong} M(n,n)$.
Observe that for every $p\in J \subseteq U_i$, $\{z_i\}\in \Fcal_{p}$. Hence, by Convention \ref{con:limit_formula} and the definition of $M$, we have that \[( [z_i] )_{p\in J}\in \varprojlim M|_{J} \subset \bigoplus_{p\in J} \Hrm_0(\Fcal_p;\F).\] 
 Clearly, this tuple $( [z_i] )_{p \in J}$ maps to $[z_i] \in \Hrm_0(\Fcal_{(n,n)};\F) = M(n,n)$ via the limit-to-colimit map of $M$ over $J$, followed by the isomorphism $(\ast)$. Since $[z_i]\in M(n,n)$ is nonzero and $\dim M(n,n)=1$ (cf. \Cref{eq:M}), we have that $\rk_M(J)= 1$, as desired. \claimqedhere
\end{claimproof}

\begin{claim} \label{cl:dgm_Ui=1}
    $\dgm_M(U_i)=1$ for every $i\in [n]$.
\end{claim} 
\begin{claimproof}
We have:
\begin{align*}
1&= \rk_M(U_i)&\mbox{by Claim \ref{cl:rank_Ui=1}}
\\&=\sum_{\substack{I\in \Int([n]^2)\\I\supseteq U_i}}\dgm_M(I)
&\mbox{by Equation \eqref{eq:rk_in_terms_of_dgm}} \\&= \dgm_M(U_i)&\mbox{by Claim \ref{cl:rank_J=0} and Remark \ref{rem:basic_properties}~\cref{item:supports_of_rk_and_dgm}. 
\claimqedhere} 
\end{align*}
\end{claimproof}
For each nonempty $S \subset [n]$, we define $U_{S} := \bigcap_{i \in S} U_i$, which is an interval of $[n]^2$.

\begin{claim} \label{cl:dgm_wedgeS}
For each nonempty $S \subset [n]$, we have that $\dgm_{M}(U_{S}) = (-1)^{|S|+1}$. 
\end{claim}
\begin{claimproof}
Let $I:=U_{S}$.
When $|S|=1$, there exists $i\in [n]$ such that $I=U_i$. We already proved that $\dgm_M(U_i)=(-1)^{1+1}=1$.
If $|S| > 1$, then
\begin{align*}
\dgm_M(I)&=\sum_{\substack{J\in \Int(P)\\ J \supseteq I}}\ \mu(J, I)\cdot  \rk_M(J) &\mbox{by \Cref{eq:dgm}}\\&=\sum_{\substack{J\in \Int(P)\\ U \supsetneq J \supseteq I}}\ \mu(J, I)\cdot  \rk_M(J) 
&\mbox{by Claim \ref{cl:rank_J=0}}
\\ &= \sum_{\substack{J\in \Int(P)\\ U \supsetneq J \supseteq I}} (-1)^{|J-I|}\cdot  \rk_M(J) &\mbox{by Lemma \ref{lem:J-I}}
\\ &= \sum_{S' \subsetneq S} (-1)^{|S'|} 
&\mbox{by Claim \ref{cl:rank_Ui=1}, letting $S' = J - I$} 
\\ &= (1-1)^{|S|} - (-1)^{|S|} = (-1)^{|S|+1}& \mbox{by the binomial theorem}
\end{align*}
as desired. 
The number of nonempty subsets $S\subset [n]$ is $2^{n+1}-1$
and each $S$ corresponds to the interval $U_S$ such that $\dgm_M (U_S) \ne 0$.
Hence, $\norm{\dgm_0(\Fcal)}=\norm{\dgm_M}\geq 2^{n+1}-1.$ 
In particular, there is no $k\in \N$ such that  $2^{n+1}-1\in O(N^k)$ for $N:=(n^2+n)/2$, the number of simplices in the filtration $\Fcal$, completing the proof. 
\end{claimproof}

\subparagraph*{Case 2 ($\m\geq 1$).}
Let $K':=K_{n,m}$ be the smallest simplicial complex 
on the vertex set $\{x_0, \cdots, x_n, y_0, \cdots, y_\m\}$, containing all  $\m$-simplices $\tau, \tau_{ij}$, and  $(\m+1)$-simplices $\sigma_{ij}$ that are the underlying sets of the following oriented simplices (see \Cref{fig:nonpoly_dgm_case2_simpcomp}):
\begin{align*}
    \tau^{+} &:= [y_0,\cdots,y_\m] &  \\
    \tau_{ij}^{+} &:= [x_i, y_0, \cdots, y_{j-1}, y_{j+1}, \cdots, y_\m], &\text{ for } 0 \leq i \leq n,\, 0 \leq j \leq \m, \\
    \sigma_{ij}^{+} &:= [x_{i-1}, x_i, y_0, \cdots, y_{j-1}, y_{j+1}, \cdots, y_\m], &\text{ for } 1 \leq i \leq n,\, 0 \leq j \leq \m.
\end{align*}
For $0 \leq k \leq n$, let $L_k$ be the $\m$-dimensional subcomplex of $K'$, whose $\m$-simplices are exactly $\tau$ and $\{\tau_{kj} : 0 \leq j \leq \m\}$  (see Figure \ref{fig:nonpoly_dgm_case2_simpcomp}). 

We define 
the filtration $\Fcal':=\Fcal'_{n,m}:[n]^2\rightarrow \Delta K'$ ($=\Delta K_{n,m}$) as (see \Cref{fig:nonpoly_dgm_case2_filt}): 
\begin{equation} \label{eq:F'}
    \Fcal'_{(i,j)}:=
    \begin{cases}
        \emptyset,  &\mbox{if $i+j<n$} \\
        \bigcup_{k \in [n]- \{i\}} L_k,    &\mbox{if $i+j=n$} \\
        \bigcup_{k\in [n]} L_k,  &\mbox{if $i + j > n$ and $(i, j)\neq (n, n)$} \\
        K',  &\mbox{if $(i, j)= (n, n)$}.
    \end{cases}
\end{equation}

Note that, for each $0 \leq i \leq n$, the $\m$-chain $c_i = \tau^{+} - \sum_{j=0}^{\m} (-1)^{j}\tau_{ij}^{+}$ in $C_{\m}(K';\F)$ satisfies $\partial c_i = 0$, i.e.
$c_i$ is an $\m$-cycle. Moreover, 
$\Hrm_\m(L_i;\F)$, which is isomorphic to $Z_\m(L_i;\F)$, is the 1-dimensional vector space generated by the cycle $[c_i]$. 

