Let $N:=\Hrm_\m(\Fcal';\F):[n]^2\rightarrow \vect$. We claim that
$N$ is isomorphic to $M$, given in 
\Cref{eq:M}. Indeed,
\[N{(i, j)} \cong
\begin{cases}
0,&\mbox{if $i+j<n$}
\\ \langle [c_0], \cdots, [c_{i-1}], [c_{i+1}], \cdots ,[c_n] \rangle \cong \F^{n},&\mbox{if $i+j=n$}
\\ \langle [c_0], \cdots ,[c_n] \rangle \cong \F^{n+1},&\mbox{if $i+j>n$ and $(i, j)\neq (n, n)$}
\\ \F,&\mbox{if $(i,j)=(n,n)$}
\end{cases}\]
and for each pair $p \leq q$ in $[n]^2$, $N(p \leq q) \cong M(p \leq q)$.
Therefore, 
there is no $k\in \N$ such that $\norm{\dgm_\m(\Fcal')} = \norm{\dgm_N}=\norm{\dgm_M}=2^{n+1}-1\notin O(N^{k})$ for 
$N$, the number of simplices in the filtration $\Fcal'$, which belongs to $O(n^{m+2})$. 
\end{proof}


In order to prove Theorem \ref{thm:nonpolynomial size1} for the case where $d > 2$, we utilize a result from \cite[Section 3.2]{botnan2024signed} and techniques present in \cite[Section 3]{clause2022discriminating}. 
For any connected $P' \subset P$, let $\overline{P'}$ be the convex hull of $P'$, which is the smallest interval in $P$ containing $P'$.
By a \emph{morphism of lattices} $g : P \rightarrow Q$, we mean a monotone map between lattices $P$ and $Q$, such that for any $p_1, p_2 \in P$, $g(p_1 \wedge p_2) = g(p_1) \wedge g(p_2)$ and $g(p_1 \vee p_2) = g(p_1) \vee g(p_2)$.


\begin{proof}[Proof of Theorem \ref{thm:nonpolynomial size1} when $d>2$]
    Let $m=0$, and let $\Fcal: [n]^2 \rightarrow \Delta K$ be the filtration defined in Equation \eqref{eq:F}.
    Letting 
    $\pi : [n]^d \rightarrow [n]^2$ be the map
    $(x_1, x_2, \cdots, x_d) \mapsto (x_1, x_2)$,
    we obtain a simplicial filtration $\widetilde{\Fcal} := \Fcal \circ \pi : [n]^d \rightarrow \Delta K$, since $\pi$ is monotone.
    Let $M := \Hrm_\m(\Fcal;\F)$, $\Mtilde := \Hrm_\m(\widetilde{\Fcal};\F)$, and
    let $f: \Int([n]^d) \rightarrow \Z$ be defined as
    \begin{equation} \label{eq:f_is_dgm}
        f(I):=
        \begin{cases}
        \dgm_{M}(I'), &\mbox{ if $I = I' \times [n]^{d-2}$ for $I' \in \Int([n]^2)$,} \\
        0, &\mbox{otherwise.}
        \end{cases}
    \end{equation}
    Let $I \in \Int([n]^d)$. Since $\pi$ is a morphism of lattices, by \cite[Corollary 3.13]{botnan2024signed}, we have $\rk_{\Mtilde}(I) = \rk_M\left(\overline{\pi(I)} \right)$. For $I' \in \Int([n]^2)$, we have $\pi^{-1} (I') = I' \times [n]^{d-2} \in \Int([n]^d)$ 
    and thus $I' \times [n]^{d-2} \supseteq I$ iff $I' \supseteq \overline{\pi(I)}$. Now, by the definitions of $f$ and $\dgm_{M}$,
    we have:
    \[ \rk_{\Mtilde}(I) = \rk_M\left(\overline{\pi(I)}\right) =\! \sum_{\substack{J' \supseteq \overline{\pi(I)} \\ J' \in \Int([n]^2) }}\! \dgm_M(J') =\! \sum_{\substack{J' \times [n]^{d-2} \supseteq I \\ J' \in \Int([n]^2) }} \! \dgm_M(J') =\! \sum_{\substack{J \supseteq I \\ J \in \Int([n]^d)}} f(J). \]
    By the existence and uniqueness of $\dgm_{\Mtilde}$ (Theorem \ref{thm:GPD_existence} \cref{item:finite_GPD} and \cref{item:uniqueness}), we have $f = \dgm_{\Mtilde}$. This equality and Equation \eqref{eq:f_is_dgm} imply that $ \norm{\dgm_m(\widetilde{\Fcal})} = \norm{\dgm_{\Mtilde}} = \norm{\dgm_M}\not\in  O(N^k)$ for \emph{any} $k\in \Zplus$ where $N \in O(n^{m+2})=O(n^2)$.

    In the case of  $m \geq 1$, the proof is similar; we simply replace $\Fcal$ above by the filtration $\Fcal'$ defined in Equation \eqref{eq:F'}.
\end{proof}

\begin{remark} {
Notably, the supports of the GPDs we have considered contain many overlapping intervals with opposite-signed values. This makes it difficult to interpret the information the GPDs convey, unlike persistence diagrams for one-parameter persistence modules.}
\end{remark}





\section{Super-Polynomial Growth of the GPDs Induced by Finite Metric Spaces}\label{sec:super-metric-space}

In this section, 
we show that the sizes of the 1-st GPDs of the sublevel-Rips, sublevel-\v{C}ech, degree-Rips, and degree-\v{C}ech bifiltrations are \emph{not} bounded by \emph{any} polynomial in the number of points in the input metric space  (\Cref{thm:sub-Rips,thm:degree-Rips}).
We prove these results by constructing specific point sets in $\R^3$ that induce persistence modules isomorphic, or structurally similar to, those appearing in the proof of \Cref{thm:nonpolynomial size1}. Also, we make use of Rota's Galois connection.

A \textbf{Galois connection} between two posets $P$ and $Q$ is a pair of monotone maps $g_1:P\rightleftarrows Q:g_2$ satisfying $g_1(p)\leq q$ iff $p \leq g_2(q)$ for any $p \in P$ and $q \in Q$.
Let $f:P \to Q$ be any function. For any $h:P \to \Z$, the \textbf{pushforward} of $h$ along $f$ is the function $f_{\sharp}h: Q \to \Z$ given by $f_{\sharp}h(q) = \sum\limits_{p \in f^{-1}(q)}h(p).$
For any $\ell:Q \to \Z$, the \textbf{pullback} of $\ell$ along $f$ is the function $f^{\sharp}\ell:P \to \Z$ defined by $f^{\sharp}\ell(p)=(\ell\circ f)(p)$. 
For any poset $P$, let $\partial_P$ denote the M\"obius inversion operator over $P$. To say that the GPD of a $P$-module $M$ exists is equivalent to stating that $\partial_{\Int(P)} \rk_M$ is well-defined and equals $\dgm_M$.


\begin{lemma}[{\cite[Theorem 3.1]{gulen2022galois}}]\label{prop:galois_connection}
    Let $P$ be a finite poset, $Q$ be any poset, and $g_1:P\rightleftarrows Q:g_2$ be a Galois connection. Then,
    $
    \partial_Q \circ g^{\sharp}_2 = {g_1}_{\sharp} \circ \partial_P.
    $
\end{lemma}


\Cref{{prop:galois_connection}} is crucial for establishing the following lemma, whose second item is essential for the proofs of both \Cref{thm:sub-Rips} and \Cref{thm:degree-Rips}. 

\begin{lemma}\label{lem:Interval_projection}
    Let $P$ be a finite poset, $M$ be a $P$-module, and $I \subset P$ be an interval of $P$. Then, 
    \begin{romanenumerate}
        \item\label{item:Interval_projection_1} for every $J \in \Int(I)$, we have \[
        \dgm_{M|_I}(J)=\sum\limits_{\substack{J'\in \Int(P)\\  J\in \Pi(J' \cap \ I) }} \dgm_{M}(J'),
    \] 
    where $\Pi(J'\cap I)$ denotes the coarsest partition of $J \cap I$ into disjoint intervals of $I$.
    \item\label{item:Interval_projection_2} Furthermore, if $P$ and $I$ are finite 2-d grid, then $\norm{\dgm_M} \geq \norm{\dgm_{M|_I}}.$
    \end{romanenumerate}
\end{lemma}
\begin{proof} 

\cref{item:Interval_projection_1}
Let $p$ be an arbitrary element of $I$.
Consider the two posets $\Int(I)_p:= \{J \in \Int(I) \mid p \in J \}$ and $\Int(P)_p:= \{J \in \Int(P) \mid p \in J \}$, both of which are full subposets and upper sets of $\Int(P)$. Clearly, we have
    $\Int(I)_p \subset \Int(P)_p$. 
    Now, we define the following two maps: 
    \begin{itemize}
        \item For $ J\in \Int(P)_p$, there is the unique coarsest partition $\Pi(J\cap I) = \{J_1 , \ldots, J_k\}$ of $J \cap I$ into disjoint intervals of $I$.
        Since $p \in J \cap I$, there exists some $J_j \in \Pi(J\cap I)$ 
        such that $p \in J_j$. We define the map
        \[
        \pi : \Int(P)_p \to \Int(I)_p, \quad \pi(J) = J_j.
        \]
        \item Let $i : \Int(I)_p \to \Int(P)_p$ be the inclusion map. 
    \end{itemize}
    We claim that the pair $\pi:\Int(P)_p 
    \rightleftarrows \Int(I)_p:i$ is a Galois connection.
    Let $J' \in \Int(P)_p$ and $J \in \Int(I)_p$.
    First, if $\pi(J') \supseteq J$, then $J' \supseteq \pi(J') \supseteq J = i(J)$.
    Conversely, assume $J' \supseteq i(J) = J$. 
    We have $J' \cap I \supseteq J$ for $J' \supseteq J$ and $I \supseteq J$.
    As $J$ is connected, it must be entirely contained in one of the elements of $\Pi(J'\cap I)$. Since $p \in \pi(J') \in \Pi(J'\cap I)$, we conclude that $\pi(J') \supseteq J$.

  Note that if $J_1\in \Int(P)_p$ and $J_2\in \Int(P)$ with $J_2\supseteq J_1$, then $J_2 \in \Int(P)_p$. Likewise, if $J_1\in \Int(I)_p$ and $J_2\in \Int(I)$ with $J_2\supseteq J_1$, then $J_2\in \Int(I)_p$.
  These two facts and the uniqueness of the GPD (\Cref{thm:GPD_existence} \cref{item:uniqueness}) imply: 
    \begin{align}
    &\partial_{\Int(P)_p}(\rk_M|_{\Int(P)_p}) = \left(\partial_{\Int(P)}(\rk_M)\right)|_{\Int(P)_p}=\dgm_{M}|_{\Int(P)_p}, \label{eq:long_dgm_P} \\
    &
    \partial_{\Int(I)_p}({\rk_{M|_I}}|_{\Int(I)_p}) = \left(\partial_{\Int(I)}(\rk_{M|_I})\right)|_{\Int(I)_p}=\dgm_{{M|_I}}|_{\Int(I)_p}. \label{eq:long_dgm_I}
    \end{align}
    Also, \Cref{prop:galois_connection} implies that 
    \begin{equation}\label{eq:Galois}\partial_{\Int(I)_p} ( i^{\sharp}( \rk_{M}{|_{\Int(P)_p}})){}=\pi_{\sharp}(\partial_{\Int(P)_p}( \rk_{M}{|_{\Int(P)_p}})){}.
    \end{equation}
    Since 
     $i^{\sharp}( \rk_{M}{|_{\Int(P)_p}})=\rk_M|_{\Int(I)_p}=\rk_{M|_I}|_{\Int(I)_p}$, 
    by \Cref{eq:long_dgm_I}, the LHS of \Cref{eq:Galois} equals
    $
    \dgm_{{M|_I}}|_{\Int(I)_p}.
    $  
 By \Cref{eq:long_dgm_P}, the RHS of \Cref{eq:Galois} equals $\pi_{\sharp} ( \dgm_{M}{|_{\Int(P)_p}})$. 
    Therefore, \Cref{eq:Galois} reads as, for $J\in \Int(I)_p$,
    \[
    \dgm_{M|_I}(J)=\pi_{\sharp} ( \dgm_{M}{|_{\Int(P)_p}})(J) 
    =\sum\limits_{\substack{J'\in \Int(P)_p\\ \pi(J')=J}  } \dgm_{M}(J')
    =\sum\limits_{\substack{J'\in \Int(P)\\  J\in \Pi(J' \cap \ I) }} \dgm_{M}(J').
    \]
    Since $p\in I$ is arbitrary, the claim follows.


    \cref{item:Interval_projection_2}
    Let $P$ and $I$ be finite 2-d grids. Then, for every interval $J' \in \Int(P)$ with $J' \cap I \neq \emptyset$, the intersection $J' \cap I$ is itself an interval of $I$. 
    Therefore, we can rewrite the equation in \Cref{item:Interval_projection_1} as 
    \[
        \dgm_{M|_I}(J)=\sum\limits_{\substack{J'\in \Int(P)\\ J' \cap \ I = J}} \dgm_{M}(J').
    \]

    Hence, for each $J \in \Int(I)$ such that $\dgm_{M|_I}(J) \ne 0$, there exists $J' \in \Int(P)$ so that $J' \cap I = J$ and $\dgm_M(J') \ne 0$. This fact ensures the existence of a surjective map
    from the support of $\dgm_M$ to that of $\dgm_{M|_I}$, which implies $\norm{\dgm_M} \geq \norm{\dgm_{M|_I}}$. \qedhere
\end{proof}
\begin{remark}
    \Cref{lem:Interval_projection} \cref{item:Interval_projection_2} 
    does not generally 
    hold in higher dimensions, i.e. for $d \geq 3$, there exist $d$-d grids $P$ and $I$ with $I \subseteq P$ and a $P$-module $M$ such that $\norm{\dgm_M} < \norm{\dgm_{M|_I}}$.
\end{remark}



\subsection{Sublevel-Rips and Sublevel-\v{C}ech Bifiltrations}


 For $r \in \Rplus$, the \textbf{Vietoris-Rips complex} of a metric space $(X, \dd_X)$ at scale $r$ is defined as
\begin{align*}
        \Rips((X, \dd_X))_r &= \left\{\text{finite }\sigma \subset X : \max\limits_{x, y \in \sigma} \dd_X(x, y) \leq r \right\}.
\end{align*}
Now assume that $X \subset \R^d$, where $\R^d$ is equipped with a metric $\dd$, and $\dd_X = \dd|_{X \times X}$. The \textbf{\v{C}ech complex of $(X,d_X)$ in $(\R^d,\dd)$ at scale $r$} is
\begin{align*}
    \Cech((X, \dd_X))_r &= \left\{\text{finite }\sigma \subset X : \bigcap_{x \in \sigma} B_r(x)\neq \emptyset \right\},
\end{align*} 
where $B_r(x) = \{ y \in \R^d : \dd(x, y) \leq r \}$. 





\begin{lemma}[{\cite[Lemma VII]{ghrist2005coverage}}]\label{lem:Cech_Rips}
    Let $(\R^d, \rho)$ be the Euclidean space with the supremum metric $\rho$. For any finite $X\subset \R^d$ and any $r \in \R_{\geq 0}$, we have
    $\Cech((X,\rho|_{X\times X}))_r = \Rips((X,\rho|_{X\times X}))_{2r}$.
\end{lemma}


    Let $\gamma: X \to \R$ be a function.
    For any $a\in \R$ and any $r\in \Rplus$ (see e.g. \cite{carlsson2009theory}), 
    \begin{romanenumerate}
    \item the \textbf{sublevel-Rips complex at scale $r$ and threshold $a$}  is $\Rips^{\downarrow}((X, \dd, \gamma))_{a,r} := $ \\ $ \Rips(\gamma^{-1}((-\infty, a]))_{r}$. The \textbf{sublevel-Rips bifiltration} of $(X, \dd, \gamma)$ is the simplicial filtration $\Rips^{\downarrow}((X, \dd, \gamma)) := \{\Rips^{\downarrow}((X, \dd, \gamma))_{a,r}\}_{a \in \R, r \in \R_{\geq 0}}$ over $\R \times \Rplus$. 

    \item the \textbf{sublevel-\v{C}ech complex at scale $r$ and threshold $a$}  is $\Cech^{\downarrow}((X, \dd, \gamma))_{a,r} :=$ \\ $ \Cech(\gamma^{-1}((-\infty, a]))_{r}$. The \textbf{sublevel-\v{C}ech bifiltration} of $(X, \dd, \gamma)$ is the simplicial filtration $\Cech^{\downarrow}((X, \dd, \gamma)) := \{\Cech^{\downarrow}((X, \dd, \gamma))_{a,r}\}_{a \in \R, r \in \R_{\geq 0}}$ over $\R \times \Rplus$.
    \end{romanenumerate}


Let
\begin{equation}\label{eq:gamma_and_T}
  \Gamma_X:=\im (\gamma)  \subset \R \ \  \mbox{and} \ \ T_X:=\im (\dd) \subset \Rplus.  
\end{equation}
By Remarks \ref{rem:finite_filtration_and_fp} and \ref{rem:discrete_poset}, for each $\m\in \Zplus$, 
the size of the GPD of $M:=\Hrm_\m(\Rips^{\downarrow}((X, \dd, \gamma)),\F):\R \times \Rplus \rightarrow \vect$ equals 
$\norm{\dgm_{M|_{\Gamma_X \times T_X}}}$. 


\begin{theorem}[Super-polynomial GPD of Sublevel-Rips and Sublevel-\v{C}ech filtrations]
\label{thm:sub-Rips}

    There does \emph{not} exist $k\in \N$ such that for \emph{every} metric space $(X, \dd)$ and \emph{every} function $\gamma: X \to \R$, $\norm{\dgm_1(\Fcal_{(X,\dd, \gamma)})} $ 
    belongs to $ O(\abs{X}^k)$, where $\Fcal_{(X,\dd, \gamma)}\in \{\Rips^{\downarrow}((X,\dd, \gamma)),\Cech^{\downarrow}((X,\dd, \gamma))\}$.


\end{theorem}

Given any set $A\subset \R^d$ and $r\in \R$, let $rA:=\{ra\in \R^d:a\in A\}$. When $d\geq 2$, let $\pi:\R^d\rightarrow \R^2$ be the projection $(x_1,\ldots,x_d)\mapsto (x_1,x_2)$.

