\subsection{Degree-Rips and Degree-\v{C}ech Bifiltrations}

    Let $(X, \dd)$ be a metric space.
    For $d\in \Z$ and $r\in \Rplus$, 
    \begin{romanenumerate}
        \item  the \textbf{Degree-Rips complex at scale $r$ and degree $d$} \cite{lesnick2015interactive}, denoted $ \DRips((X, \dd))_{d,r} $, is the maximal subcomplex of $ \Rips((X, \dd))_{r} $ whose vertices have degree at least \( d - 1 \) in the 1-skeleton of $ \Rips((X, \dd))_{r} $.  The \textbf{Degree-Rips bifiltration} of $(X, \dd)$ is the simplicial filtration  $\DRips((X, \dd)):=\{\DRips((X, \dd))_{d, r} \}_{d\in \Zop, r\in \Rplus}$ over $\Zop \times \Rplus$. 
        \item The \textbf{Degree-\v{C}ech complex at scale $r$ and degree $d$} \cite{edelsbrunner2021multi}, denoted $ \DCech((X, \dd))_{d,r} $, is the maximal subcomplex of $ \Cech((X, \dd))_{r} $ whose vertices have degree at least \( d - 1 \) in the 1-skeleton of $ \Cech((X, \dd))_{r} $. The \textbf{Degree-\v{C}ech bifiltration} of $(X, \dd)$ is the simplicial filtration $\DCech((X, \dd)) := \{\DCech((X, \dd))_{d, r}\}_{d \in \Zop, r \in \R_{\geq 0}}$ over $\Zop \times \Rplus$.
    \end{romanenumerate}

We consider the finite subposets
\begin{equation*}
  J_X:= \{|X|-1< |X|-2 < \ldots < 1 \} \subset \Zop\ \  \mbox{and} \ \ T_X:=\im (\dd) \subset \Rplus.   
\end{equation*}
By Remarks \ref{rem:finite_filtration_and_fp} and \ref{rem:discrete_poset}, for each $\m\in \Zplus$, 
the size of the GPD of $M:=\Hrm_\m(\DRips((X, \dd)),\F):\Zop \times \Rplus \rightarrow \vect$ equals $\norm{\dgm_{M|_{J_X\times T_X}}}$.

\begin{theorem}[Super-polynomial GPD of Degree-Rips and Degree-\v{C}ech filtrations]\label{thm:degree-Rips}

 There does \emph{not} exist $k\in \N$ such that for \emph{every} finite metric space $(X,\dd)$, $\norm{\dgm_1(\Fcal_{(X,\dd)})} $ 
 belongs to $ O(\abs{X}^k)$, where $\Fcal_{(X,\dd)}\in \{\DRips((X,\dd)),\DCech((X,\dd))\}$.
\end{theorem}


