    Then, on the interval $J'_n \times T'_n$, $M_n$ $:=\Hrm_1(\DRips((X_n, \dd_n)),\F)$ is given by (see \Cref{fig:deg_rips_1}):
    \[
    M_n{(\alpha_{i }, b_{j})}=
    \begin{cases}
        0,&\mbox{if $i+j<n$} \\
        \F^n,&\mbox{if $i+j=n$} \\
        \F^{n+1},&\mbox{if $i+j>n$ and $j < n + 1$} \\
        \F,&\mbox{if $j = n + 1$.}
    \end{cases}
    \]
    Let $i\in [n]$. Then, for every $(x,y)\in U$ that covers $(\alpha_{i }, b_{n-i})$, we have that
    \begin{align}
    M_n((\alpha_{i}, b_{n-i}) \leq (x, y))&&=&&\iota_i^n:&&\F^{n}&\to \F^{n+1}\nonumber
    \\
    &&&&&&(v_1, \dots, v_n) &\mapsto (v_1, \dots, v_{i}, 0, v_{i+1}, \dots, v_n) \label{eq:iota_deg}
    \end{align}
    We consider the following interval of $J'_n \times T'_n$ (see Figure \ref{fig:deg_rips_1}): 
    \begin{equation}\label{eq:Interval_deg_D}
        D:=\{(\alpha_{i },b_{j})\in J'_n \times T'_n : \ n \leq i + j\leq  n + 1, \ i\leq n, \ j\leq n \}.
    \end{equation}

\begin{claim} 
For $J\in \Int(J'_n \times T'_n)$ with $J \not\subseteq U$ or $J = U$, $\rk_{M_n}(J)=0$.
\end{claim}
\begin{proof}
First, assume that 
there exists a point $p \in J-U$. Then, by the construction of $M_n$, $\dim (M_n(p)) = 0$ and thus $\rk_{M_n} (J)=0$ by monotonicity of $\rk_{M_n}$ (Remark \ref{rem:basic_properties}~\cref{item:monotonicity}).
Next, assume that $J=U$.
Since $\rk_{M_n}(U)=\rank(\varprojlim {M_n}|_U\rightarrow \varinjlim {M_n}|_U)$, it suffices to show $\varprojlim {M_n}|_U=0$. Again, since $D=\minzz(U)$
, by Lemma \ref{lem:fence}, it suffices to show that $\varprojlim {M_n}|_D=0$. 
    The persistence module $\varprojlim {M_n}|_D$ is isomorphic to the persistence module $\varprojlim {M}|_D$ defined in the proof of \Cref{thm:nonpolynomial size1}. Therefore, the remainder of the proof follows similarly to the proof of \Cref{cl:rank_J=0} in \Cref{thm:nonpolynomial size1}. 
\claimqedhere
\end{proof}
    Now, for each $i\in [n]$, let $U_i := U-\{(\alpha_{n-i },b_{i})\}$
    , which is an interval of $J'_n \times T'_n$.
\begin{claim} $\rk_{M_n}(U_i)=1$ for every $i\in [n]$. \end{claim}
\begin{proof}
    Fix $i\in [n]$. For every $p\in U_i$, the $1$-cycle (see Figure \ref{fig:deg_rips_1})
    \[ 
    \delta_i = \sum_{ x=0 }^{3}{ \Big[\big(a \cos\frac{\pi x}{2}, a \sin\frac{\pi x}{2}, i(n+\epsilon_n) \big), \big(a \cos\frac{\pi (x+1)}{2}, a \sin\frac{\pi (x+1)}{2}, i(n+\epsilon_n) \big) \Big]} 
    \]    
    is carried by the simplicial complex $\DRips(X_n)_{p}$. Hence, according to Convention \ref{con:limit_formula} and the definition of ${M_n}$, we have that $( [\delta_i] )_{p\in U_i}\in \varprojlim {M_n}|_{U_i} \subset \bigoplus_{p\in U_i} \Hrm_1(\DRips(X_n)_p;\F)$. Since $\max(U_i)=\{(\alpha_{n+1},b_{n+1})\}$, by Lemma \ref{lem:fence}, this tuple $( [\delta_i] )_{p \in U_i}$ maps to \\ $[\delta_i] \in \Hrm_1(\DRips(X_n)_{(\alpha_{n + 1},b_{n+1})};\F) = {M_n}(\alpha_{n + 1},b_{n+1})$ via the limit-to-colimit map of ${M_n}$ over $U_i$, followed by the isomorphism $\varinjlim {M_n}|_{U_i} \cong {M_n}(\alpha_{n + 1},b_{n+1})$. \\ Since $[\delta_i]\in \Hrm_1(\DRips(X_n)_{(\alpha_{n +1},b_{n+1})};\F)\cong \F$ is nonzero, we have $\rk_{M_n}(U_i)= 1$. \claimqedhere
\end{proof}
    The proofs of \Cref{cl:dgm_Ui=1_new} and  \Cref{cl:dgm_wedgeS_new} 
    below can be obtained by simply replacing $M$ in the proofs of \Cref{cl:dgm_Ui=1} and \Cref{cl:dgm_wedgeS} by $M_n$.


\begin{claim} \label{cl:dgm_Ui=1_new} $\dgm_{M_n}(U_i)=1$ for every $i\in [n]$.
\end{claim}


    For each nonempty $S \subset [n]$, we define $U_{S} := \bigcap_{i \in S} U_i$, which is also an interval of $J'_n \times T'_n$. 

\begin{claim} \label{cl:dgm_wedgeS_new}
    For each nonempty $S \subset [n]$, we have that $\dgm_{M_n}(U_{S}) = (-1)^{|S|+1}$. 
\end{claim}

    The number of nonempty subsets $S\subset [n]$ is $2^{n+1}-1$. Hence, $\norm{\dgm_{M_n}}$
    is at least $2^{n+1}-1$, which does not belong to $O(|X_n|^k)$ for any $k\in \Z_{\geq 0}$. 
 \end{proof}   



It is known that, for $m\in \N$, adding $m$ integers {has} time complexity $O(m)$ \cite{jevrabek2023note}. Hence, as a direct corollary of \Cref{thm:nonpolynomial size1,thm:degree-Rips,thm:sub-Rips}, we obtain:


\begin{corollary}\label{cor:exp-time} 
Let $n,d\in \Zplus$, $d\geq 2$, and $I\in \Int([n]^d)$. For an arbitrary $[n]^d$-module $M$,
computing $\dgm_M(I)$ via the M\"obius inversion of the {GRI} 
of $M$ requires at least $\Theta(2^n)$ in time. In particular, $M$ can arise as the homology of a simplicial filtration over $[n]^d$, with the number of simplices being polynomial in $n$.
\end{corollary}
\begin{proof}
Let $M$ be the persistence module defined in the proof of Theorem \ref{thm:nonpolynomial size1} for $d=2$ and $m=0$. Let $I:=U_{[n]}$,
 as described immediately above Claim \ref{cl:dgm_wedgeS} in that proof. By Lemma \ref{lem:J-I}, we have 
$\dgm_M(I)=\sum_{S'\subsetneq [n]}(-1)^{\abs{S'}}=(-1)^{n+2}$.  
 This sum contains $2^{n+1}-1$ nonzero summands, 
requiring $\Theta(2^n)$ time for computation.
\end{proof}


\section{Conclusion}\label{sec:discussion}

We showed that the size of the GPD can be super-polynomial in the number of simplices in a given multi-parameter filtration, and such sizes can arise even from well-known constructions. Furthermore, we noted that the GRI can be ``locally densely supported'' (see Claim \ref{cl:dgm_wedgeS}), which suggests that using the M\"obius inversion of the GRI to compute the GPD can be intractable. These findings highlight the need to compute the GPD (or any invariant approximating it) directly, without relying on the GRI.



From a different perspective, developing an output-sensitive algorithm for computing the GPD might be a more practical approach, potentially extending or adapting ideas from \cite{morozov2021output}. {Moreover, combining optimization techniques to address challenges in computing the GPD appears to be a promising research direction. In line with this, \cite{carriere2024sparsification} proposes a method for ``sparsifying'' 
the GPD via gradient descent.}


It also remains an interesting question whether special types of multi-parameter filtrations not explored in this work can also give rise to GPDs of super-polynomial size. Examples include 
multicover and barycentric (subdivision) bifiltrations 
\cite{sheehy2012multicover}.

