\subsection{System Class}\label{sec:systemClass} 

We consider the discrete-time, LTI system class, whose input $u(t) \in \mathbb{R}^m$ and output $y(t) \in \mathbb{R}^q$ constitute a stationary joint process
\begin{align*}%\label{eqn:procDef} 
    z(t) = \begin{bmatrix} y(t) \\ u(t)  \end{bmatrix} \in \mathbb{R}^{q+m}.
\end{align*}
The stationary joint process can be represented using an infinite-length/steady-state ARX representation:%\footnote{Any causal linear system can be represented as \eqref{eqn:sysDef}.} 
\begin{align}\label{eqn:sysDef}
    y(t+1) &= \sum_{i=1}^{\infty} \phi_{\infty, i} z(t-i+1) + e(t+1),
\end{align}
with $\phi_{\infty, i} \in \mathbb{R}^{q \times (q+m)}$. $e$ is zero-mean white noise which results in prediction errors, or the \emph{stationary innovation}.

Given a finite past-horizon of length $l$, we have a finite-length/transient ARX representation:
\begin{align}\label{eqn:sysDefFinite}
    y(t+1) = \sum_{i=1}^{l} \phi_{l,i} z(t-i+1) + \epsilon_{l}(t+1),
\end{align} 
where $\phi_{l,i} \in \mathbb{R}^{q \times (q+m)}$ is the $i^\text{th}$ block-entry of the $l$-long optimal (minimum variance, linear, unbiased) ``transient'' single-step predictor.
% where $\phi_{l,i} \in \mathbb{R}^{q \times (q+m)}$ is the $i^\text{th}$ block-entry of the $l$-long ``transient'' single-step predictor $\Phi_l$,
% \begin{align*}
%     \Phi_l := \begin{bmatrix}
%         \phi_{l,l} & \hdots & \phi_{l,1}
%     \end{bmatrix}.
% \end{align*}
$\epsilon_{l}$ is the \emph{transient innovation} for $l$ \emph{lead-in} data \cite{moffat2024transient}.




\subsection{Variables and definitions} % Maybe introduce a nomenclature table?

The future, $\tau$-long input and output sequences are 
\begin{align*}
    u_f := u_f(t) &:= \begin{bmatrix} u^T(t+1) & \hdots & u^T(t + \tau) \end{bmatrix}^T \text{ and} \\
    y_f := y_f(t) &:= \begin{bmatrix} y^T(t+1) & \hdots & y^T(t + \tau) \end{bmatrix}^T.
\end{align*}
The $\rho$-long lead-in measurement sequence is
\begin{align*}
    z_p := z_p(t) &:= \begin{bmatrix} z^T(t-\rho+1) & \hdots & z^T(t) \end{bmatrix}^T \in \mathbb{R}^{(q+m)\rho},
\end{align*}
which encodes the initial condition at time $t$. 
The innovation sequence for the future $\tau$ steps with $\rho$ lead-in data is
\begin{align*}
    \epsilon_f := \epsilon_f(t) &:= \begin{bmatrix} \epsilon_\rho^T(t+1) & \hdots \epsilon_{\rho+\tau-1}^T(t + \tau) \end{bmatrix}^T \in \mathbb{R}^{q\tau}.
\end{align*}

