\section{The Bias of DeePC and $\gamma$-DDPC}\label{sec:DDPCbias}

The DeePC \cite{coulson2019data} optimization is 
\begin{align}
    \underset{u_f, y_f, g}{\min} \quad & J(u_f, y_f, g) \label{eqn:optiDef_DeePC} \\
    \text{s.t.} \quad \quad &\begin{bmatrix}
                    v \\ y_f
                \end{bmatrix} =\begin{bmatrix}
                    V \\ Y_f
                \end{bmatrix} g. \nonumber
\end{align}
% Defining $\begin{bmatrix}
%     \gamma_v^T & \gamma_{\epsilon}^T
% \end{bmatrix}^T := \gamma$, 
The $\gamma$-DDPC \cite{breschi2022unified} optimization is %, equivalently,
\begin{align}
    \underset{u_f, y_f, \gamma_v, \gamma_{\epsilon}}{\min} \quad & J(u_f, y_f, \gamma_v, \gamma_{\epsilon}) \label{eqn:optiDef_gammaDDPC}\\
    \text{s.t.} \quad \quad &\begin{bmatrix}
                    v \\ y_f
                \end{bmatrix} =
                \begin{bmatrix}
                    L_{VV} & 0 \\
                    L_{Y V} & L_{Y \Epsilon}
                \end{bmatrix}
                \begin{bmatrix}
                    \gamma_v \\ \gamma_{\epsilon}
                \end{bmatrix}, \nonumber
\end{align}
% where $v = \begin{bmatrix} z_p^T & u_f^T \end{bmatrix}^T$. 
which uses the LQ decomposition of the training data,
\begin{align}\label{eqn:LQdecompData}
    \begin{bmatrix}
        V \\ Y_f
    \end{bmatrix} &=: LQ =: 
    \begin{bmatrix}
        L_{VV} & 0 \\
        L_{Y V} & L_{Y \Epsilon}
    \end{bmatrix}
    \begin{bmatrix}
        Q_V \\ Q_{\Epsilon}
    \end{bmatrix}.
\end{align}




