The (LTI) \emph{$\gamma$-DDPC Bias} for a $\gamma$ from \eqref{eqn:optiDef_gammaDDPC} is 
\begin{align*}
    b_{\gamma}(\gamma) := \begin{bmatrix}
        L_{Y V} & L_{Y \Epsilon}
    \end{bmatrix} \gamma 
    % \begin{bmatrix}
    %     \gamma_v \\ \gamma_{\epsilon}
    % \end{bmatrix} 
    - H L_{VV} \gamma_v,
\end{align*}
and the (LTI) \emph{DeePC Bias} for a $g$ from \eqref{eqn:optiDef_DeePC} is
\begin{align*}
    b_{g}(g) := Y_f g 
    - H V g.
\end{align*}
% \begin{align*}
%     b_{g}(g) := \begin{bmatrix}
%         L_{Y V} & L_{Y \Epsilon}
%     \end{bmatrix} Q g 
%     - H L_{VV} Q_V g.
% \end{align*}

\begin{lemma}\label{lemma:DDPCbias}
    The $\gamma$-DDPC Bias as a function of $\gamma$ is 
    \begin{align}\label{eqn:gammaDDPCbias}
        b_{\gamma}(\gamma) := \begin{bmatrix}
            \beta L_{VV} & L_{Y \Epsilon}
        \end{bmatrix} \gamma,
    \end{align}
    and the DeePC Bias as a function of $g$ is 
    \begin{align}\label{eqn:DeePCbias}
        b_{g}(g) := \big(
            \beta_V + L_{Y \Epsilon} Q_{\Epsilon}
        \big) g.
    \end{align}
\end{lemma}


