\subsection*{Proof of Lemma \ref{lemma:SPCBias}}
\begin{proof}[\unskip\nopunct]
    \begin{align*}
        \beta &= \mathbb{E}\left[Y_f V^T\right] \mathbb{E}\left[V V^T\right]^{-1}  - H \\
        &= \mathbb{E}\left[\left(H V  + H_\epsilon \Epsilon_f\right) V^T\right] \mathbb{E}\left[V V^T\right]^{-1} - H  \\
        % &=  \left(H \mathbb{E}\left[V V^T\right] \mathbb{E}\left[V V^T\right]^{-1} V \right. \\ &  \qquad \qquad \qquad \left. + H_\epsilon \mathbb{E}\left[\Epsilon_f V^T\right] \mathbb{E}\left[V V^T\right]^{-1} V \right) \\ &  \qquad \qquad \qquad - H Z \\
        &= H_\epsilon \mathbb{E}\left[\Epsilon_f V^T\right] \mathbb{E}\left[V V^T\right]^{-1}
    \end{align*}
    Defining
    \begin{align}
            \Omega &:= \mathbb{E}\left[U_f U_f^T \right] - \mathbb{E}\left[U_f Z_p^T \right] \mathbb{E}\left[ Z_p Z_p^T \right]^{-1} \mathbb{E}\left[Z_p U_f^T \right] \text{, and} \nonumber \\
            M &:= \begin{bmatrix}
            - \Omega^{-1} \mathbb{E}\left[U_f Z_p^T \right] \mathbb{E}\left[ Z_p Z_p^T \right]^{-1} & \Omega^{-1} \label{eqn:Mdef}
            \end{bmatrix}, 
    \end{align}
    and using the fact that $\mathbb{E}\left[\Epsilon_f Z_p^T\right] = 0$, we have
    \begin{align*}
        \beta &= H_\epsilon \begin{bmatrix}
            0 & \mathbb{E}\big[\Epsilon_f U_f^T\big]
        \end{bmatrix} \begin{bmatrix}
            \mathbb{E}\left[Z_p Z_p^T \right] & \mathbb{E}\left[Z_p U_f^T \right] \\
            \mathbb{E}\left[U_f Z_p^T \right] & \mathbb{E}\left[U_f U_f^T \right] 
        \end{bmatrix}^{-1} \\
        &= H_\epsilon \mathbb{E}\big[\Epsilon_f U_f^T\big] M
    \end{align*}
    % where the last line comes 
    from the formula for the inverse of $2 \times 2$ block matrix.
\end{proof}


