\subsection*{Proof of Theorem \ref{thm:bias}}%\label{app:}
\begin{proof}[\unskip\nopunct]
    % Since $e$ is noise, the innovations are uncorrelated with past measurements: $\mathbb{E}\left[\Epsilon_f V^T\right] = 0$ if $\mathbb{E}\big[\Epsilon_f U_f^T\big] = 0$.
    (a) follows from Lemma \ref{lemma:SPCBias}, and that $\mathbb{E}\big[\Epsilon_f U_f^T\big] = 0$ when the training data is gathered in open loop.

    The first statement in (b) follows from Lemma \ref{lemma:spcBiasLinComb} and the definition of $\sigma_\text{max}$.

    The second statement in (b) follows from 
    \begin{align*}
        b_{S}(v) &= H_\epsilon \begin{bmatrix}
            0 & \mathbb{E}\big[\Epsilon_f U_f^T\big]
        \end{bmatrix} \mathbb{E}\left[ V V^T \right]^{-1/2} \mathbb{E}\left[ V V^T \right]^{-T/2} v \\
        &= A \xi \text{, where } \xi := \mathbb{E}\left[ V V^T \right]^{-T/2} v \text{, and } \mathbb{E}\left[ \xi \xi^T \right] = I
    \end{align*}
    if $v$ is drawn from the same distribution as $V$.
    \begin{align*}
        \mathbb{E}\left[ \left\Vert b_{S}(v)\right\Vert^2 \right] &= \mathbb{E}\left[\left(\xi^T A^T A \xi \right) \right]\\ &=\mathbb{E}\left[\Tr\left(A^T A \xi \xi^T \right) \right]\\
        &= \Tr\left( A^T A \right) \\ % A is not a random variable
        &= \left\Vert H_\epsilon \begin{bmatrix}
            0 & \mathbb{E}\big[\Epsilon_f U_f^T\big]
        \end{bmatrix} \mathbb{E}\left[ V V^T \right]^{-1/2}\right\Vert^2_F 
    \end{align*}
\end{proof}



