\subsection*{Proof of Lemma \ref{lemma:DDPCbias}}

\begin{proof}[\unskip\nopunct]
    The Lemma follows directly from $\beta = S - H$ and the definitions of $b_{\gamma}(\gamma)$ and $b_{g}(g)$. For \eqref{eqn:gammaDDPCbias} we use $S = L_{YV} L_{VV}^{-1}$, and for \eqref{eqn:DeePCbias} we use $V = L_{VV} Q_V$ and $Y_f = L_{YV} Q_V + L_{Y\Epsilon} Q_\Epsilon$. % $\gamma = Q g$.
\end{proof}



\subsection*{Proof of Theorem \ref{thm:biasDDPC}}

\begin{proof}[\unskip\nopunct]
    % The Theorem follows immediately from Lemma \ref{lemma:DDPCbias}.
    The Theorem follows from Lemma \ref{lemma:DDPCbias} and the definition of $\sigma_\text{max}$. For DeePC, $b_{g}(g) = \begin{bmatrix}
        \beta L_{VV} & L_{Y \Epsilon}
    \end{bmatrix} Q g$. As $Q$ is unitary, $\sigma_\text{max} \! \left( \begin{bmatrix}
        \beta L_{VV} & L_{Y \Epsilon}
    \end{bmatrix} Q \right) = \sigma_\text{max} \! \left( \begin{bmatrix}
        \beta L_{VV} & L_{Y \Epsilon}
    \end{bmatrix} \right)$.
    For (a), as with Theorem \ref{thm:bias}, $\beta = 0$ when the data is collected in open loop.
\end{proof}



