As long as $|w-y_p| \leq \bar s$, namely, the saturation function $\Pi$ is inactive, $\hat{d} = w-y_p$ holds. Thus, $w$ and $y_p$ in (\ref{w}) and (\ref{yp}) are needed to be rewritten with the transformed states $\xi$ and $\zeta$ by utilizing the following notes.

\textit{Note 1:} For a matrix $\Gamma_\tau $ of the following structure
\begin{equation*}
    \Gamma_\tau = \begin{bmatrix}
        \gamma_1 & \gamma_2 \tau & \cdots &  \gamma_{j-1} \tau^{j-2} & \gamma_j \tau^{j-1} \\
        0 & \gamma_1 & \cdots & \gamma_{j-2} \tau^{j-3} & \gamma_{j-1} \tau^{j-2} \\
        \vdots & \ddots & \ddots & \ddots & \vdots \\
        0 & \cdots  & 0 & \cdots & \gamma_{j-i+1} \tau^{j-i}  \\
    \end{bmatrix}~~\in {\mathbb R}^{i \times j},
\end{equation*} where $0<i\leq j$ and $\{\gamma_1,\gamma_2,...,\gamma_j \}\subset {\mathbb R}$, the below equality is hold:
\begin{equation*}
    \Gamma_\tau \diag(\tau^{-1},...,\tau^{-j}) = \diag(\tau^{-1},...,\tau^{-i})\Gamma_1.
\end{equation*}

\textit{Note 2:} If $\Gamma_\tau$ defined in Note 1 is invertible, then $\Gamma^{-1}_\tau$ also has the same structure of $\Gamma_\tau$ with respect to $\tau$.

We share the fact that $C_\tau$, $\bar C_\tau$, and $M_l^\nu (C_\tau)$ have the matrix structure with respect to $\tau$ introduced in Note 1.

First, $y_p$ in (\ref{yp}) applied the transformation (\ref{coordi2}) becomes \begin{equation*}
\begin{split}
    y_p & = \frac{a_0}{\tau^l}C_\tau \left( \tau^{l+1} \diag(\tau^{-1},...,\tau^{-l}) \zeta + \tau^l \hat{\mathbf e}_1\Xi^\ast_\zeta \right) \\
    & = a_0 C_1 \zeta + a_0 \Xi^\ast_\zeta,
    \end{split}
\end{equation*} with $C_\tau$ structure with respect to $\tau$ and Note 1.

Next, for the sake of constructing $w$ in (\ref{w}) with $\xi$, the terms inside $w$ associated with $q$ are organized \begin{align} 
    M_l^\nu(C_\tau) T_\tau ^{-1}q & = \tau^{\nu+1} M_l^\nu(C_\tau) T_\tau ^{-1} \diag(\tau^{-1},...,\tau^{-l}) \xi \nonumber \\
    & \quad \,+ M_l^\nu(C_\tau) T_\tau ^{-1} \left( \hat{\mathbf e}_{\nu+1} \hat{\mathbf e}^\top_\nu \Xi^\ast_\zeta + [x; \; 0_{l-\nu}] \right) \nonumber \\ 
    &= \diag(\tau^\nu,...,\tau) M_l^\nu(C_1)T_1 ^{-1} \xi \nonumber \\
    & \quad \, + M_l^\nu(C_\tau)T_\tau ^{-1} \left(\hat{\mathbf e}_{\nu+1}\hat{\mathbf e}_{\nu}^\top \Xi^\ast_\xi  + [x; ~ 0_{l-\nu}] \right), \label{w-1-1} \\
        C_\tau A_l^\nu T_\tau ^{-1} q & = C_1 A_l^\nu T_1 ^{-1}\xi \nonumber \\
        & \quad \, +C_\tau A_l^\nu T_\tau ^{-1} \left(\hat{\mathbf e}_{\nu+1}\hat{\mathbf e}_{\nu}^\top \Xi^\ast_\xi + [x; ~ 0_{l-\nu}] \right) \nonumber \\
        & = C_1 A_l^\nu T_1 ^{-1}\xi+ \hat{\mathbf e}_{\nu}^\top \Xi^\ast_\xi, \label{w-1-2}
\end{align} utilizing $C_\tau A_l^\nu T_\tau ^{-1} [x; ~ 0_{l-\nu}]  = 0$ and Note 1 in both (\ref{w-1-1}) and (\ref{w-1-2}). For (\ref{w-1-1}). Let us recall $\bar C_\tau = C_\tau - Z^\top_1 T_\tau$, then the following arises \begin{equation*}
    M_l^\nu(C_\tau)T_\tau ^{-1} = M_l^\nu(\bar C_\tau)T_\tau ^{-1}+\begin{bmatrix}
        I_\nu ~~0_{\nu \times(l-\nu)}
    \end{bmatrix}. 
\end{equation*} Then, the following is obtained by premultiplying the row vector $\bar \phi^\top$ to (\ref{w-1-1}) \begin{multline}
    \bar{\phi}^\top M_l^\nu(C_\tau)T_\tau ^{-1}q = \tau \bar g {\mathbf C}_\tau \xi + \bar \phi^\top x \\ 
    + \tau \bar{\phi}^\top M_l^\nu(\tau^{-1} \bar C_\tau)T_\tau ^{-1} \left(\hat{\mathbf e}_{\nu+1}\hat{\mathbf e}_{\nu}^\top \Xi^\ast_\xi  + [x; ~ 0_{l-\nu}] \right), \label{w-deri1}
\end{multline}  with $\tau M_l^\nu(\tau^{-1} \bar C_\tau) = M_l^\nu(\bar C_\tau)$.

Depending on the structure of Byrnes-Isidori normal form \cite{byrnes1991asymptotic}, the following holds \begin{multline}
    \hat{\mathbf e}_{\nu+1}\hat{\mathbf e}_{\nu}^\top \Xi^\ast_\xi  + [x; ~0_{l-\nu}] \\ = [\hat{\mathbf e}_2 \,\cdots \, \hat{\mathbf e}_{\nu+1} \, 0_{l \times (n_{\mathrm e} -\nu)}] \Xi^\ast_\xi
    + [x_1;~ 0_{l-1}], \label{w-deri2}
\end{multline} invoking $\Xi^\ast_\xi  ={\mathbf A}_{\mathrm s} e-\dot \chi_{\mathrm n}$. Since the first entry of the row vector $\bar C_\tau$ is zero and $T_\tau^{-1}$ is upper triangular, $\bar C_\tau T_\tau^{-1} [x_1;~ 0_{l-1}] = 0$ holds. Then, we have $w$ in terms of $\xi$ by (\ref{w-1-2})--(\ref{w-deri2}) as follows \begin{equation*}
\begin{split}
    w & = \frac{1}{\bar{g}}\left( -\bar{\psi}^\top \bar{z}- \bar \phi^\top x+ \hat{\mathbf e}_{\nu}^\top \Xi^\ast_\xi \right) \\
    & \quad \, -\frac{1}{\bar{g}}\left(\tau\bar g {\mathbf C}_\tau  \xi  +\tau\bar g \bar{\mathbf C}_\tau  \Xi^\ast_\xi - C_1 A_l^\nu T_1 ^{-1} \xi \right) \\
    & = u_{\mathrm r} -\tau {\mathbf C}_\tau  \xi  - \tau\bar{\mathbf C}_\tau  \Xi^\ast_\xi + \frac{1}{\bar{g}}C_1 A_l^\nu T_1 ^{-1} \xi + D v.
    \end{split} 
\end{equation*} The first equality also relies on the definition of $\bar{\mathbf C}_\tau$, and the second equality is from $\hat{\mathbf e}_{\nu}^\top \Xi_\xi^\ast = \bar{\phi}^\top x + \bar{\psi}^\top \bar{z}  +\bar{g} \left( u_{\mathrm r}+D v\right)$. Hence, $w-y_p$ is obtained as \begin{equation}
\begin{split} \label{d esti.}
    w-y_p & = \left( u_{\mathrm r} -\tau {\mathbf C}_\tau  \xi  - \tau\bar{\mathbf C}_\tau  \Xi^\ast_\xi + \frac{1}{\bar{g}}C_1 A_l^\nu T_1 ^{-1} \xi + D v \right) \\
    & \quad \, - \left(a_0 C_1 \zeta + a_0 \Xi^\ast_\zeta \right) \\ 
    & = {\mathbf d}+\frac{1}{\bar{g}} C_1 A_l^\nu T_1^{-1} \xi - a_0C_1\zeta +\frac{g-\bar{g}}{g}D v \\
    & \quad \,  - \tau \left( {\mathbf C}_\tau \xi +  \bar{\mathbf C}_\tau \Xi^\ast_\xi\right),
\end{split}
\end{equation} by $\Xi^\ast_\zeta = (u_{\mathrm r}- {\mathbf d} + (\bar g D v)/g)/a_0$. As a result, manipulate the equations (\ref{noisy-semi-singular}) for $\dot \xi$, $\dot \zeta$, and $\dot e$ by $\hat d = w-y_p$ in (\ref{d esti.}):
\begin{align*}
    \tau \dot{\xi} & = A_l \xi -a_0T_1\hat{\mathbf e}_l \xi_1 -\hat{\mathbf e}_\nu (g{\mathbf d}-g(w-y_p)) -\bar g D v) \\
    & \quad \, +\frac{a_0}{\tau^\nu} T_1\hat{\mathbf e}_l v - \tau \hat{\mathbf e}_{\nu+1} \hat{\mathbf e}_\nu^\top \dot \Xi^\ast_\xi \\
    &  =  {\mathbf A}_{\mathrm 11} \xi + {\mathbf A}_{\mathrm 12} \zeta  -\tau g\hat{\mathbf e}_\nu \left( {\mathbf C}_\tau \xi  + \bar{\mathbf C}_\tau \Xi_\xi^\ast \right) \\
    & \quad \, - \tau \hat{\mathbf e}_{\nu+1} \hat{\mathbf e}_\nu^\top \dot \Xi^\ast_\xi + \frac{a_0}{\tau^\nu}T_1 \hat{\mathbf e}_l v  + {\mathbf N}_\xi v, 
\end{align*}
\begin{align*}
    \tau \dot{\zeta} & = A_l\zeta-a_0\hat{\mathbf e}_l\hat{\mathbf e}_1^\top T_1 \zeta \\
    & \quad \, +\hat{\mathbf e}_l\left({\mathbf d} -(w-y_p) -\frac{\bar g}{g} D v\right)- \tau \hat{\mathbf e}_1 \dot{\Xi}^\ast_\zeta \\
    & = A_l\zeta-a_0\hat{\mathbf e}_l\hat{\mathbf e}_1^\top T_1 \zeta - \tau \hat{\mathbf e}_1 \dot{\Xi}^\ast_\zeta - D\hat{\mathbf e}_l v \\
    & \quad \, -\hat{\mathbf e}_l\left(\frac{1}{\bar{g}} C_1 A_l^\nu T_1^{-1} \xi - a_0C_1\zeta  - \tau \left( {\mathbf C}_\tau \xi + \bar{\mathbf C}_\tau \Xi^\ast_\xi\right) \right) \\
     & = {\mathbf A}_{\mathrm 21} \xi + {\mathbf A}_{\mathrm 22}\zeta +\tau \hat{\mathbf e}_l\left({\mathbf C}_\tau \xi  + \bar{\mathbf C}_\tau \Xi_\xi^\ast\right) - \tau \hat{\mathbf e}_1 \dot{\Xi}^\ast_\zeta + {\mathbf N}_\zeta v,
\end{align*} and
\begin{align*}
    \dot{e} & = {\mathbf A}_{\mathrm s}e +g \hat{\mathbf e}_\nu \left( {\mathbf d}- (w-y_p) \right) - N v \\
    & = {\mathbf A}_{\mathrm s}e - g \hat{\mathbf e}_\nu \left(\frac{1}{\bar{g}} C_1 A_l^\nu T_1^{-1} \xi - a_0C_1\zeta  - \tau \left( {\mathbf C}_\tau \xi +  \bar{\mathbf C}_\tau \Xi^\ast_\xi\right) \right)\\
    & \quad \, +(\bar g - g) D \hat{\mathbf e}_\nu v -Nv\\
    & = {\mathbf A}_{\mathrm s}e + {\mathbf F}_{\mathrm 1}\xi + {\mathbf F}_{\mathrm 2}\zeta + \tau g\hat{\mathbf e}_\nu \left( {\mathbf C}_\tau \xi  + \bar{\mathbf C}_\tau \Xi_\xi^\ast \right) + {\mathbf N}_{\mathrm e}v. \label{noisy-perfor}
\end{align*} Thus, the claim is proved.

Also for the proof of Lemma 1, let $v \equiv 0$ be in the transformed system (\ref{noisy-singular}), then the standard perturbation form shown in Lemma 1 can be obtained.



\subsection*{B. Proof for Lemma 2}

Calculate the first and second partial derivatives of $\bar \Sigma(\mu, \tau)$ with respect to $\tau$, then we have \begin{equation} \label{1st/2nd}
    \pdv{\bar \Sigma}{\tau} = b_2   -\frac{\nu b_1 \sigma_3 }{\tau^{\nu+1}}\mu + b_1\sigma_5,~ \pdv[2]{\bar \Sigma}{\tau} =\frac{\nu (\nu+1)b_1 \sigma_3 }{\tau^{\nu+2}}\mu.
\end{equation} It is shown that for $\mu>0$, $\bar \Sigma(\mu, \tau)$ is strongly convex function of $\tau$ due to $\partial^2\bar \Sigma / \partial \tau^2 > 0$ for all $\tau>0$. Also, $\bar \Sigma(0, 0)$ holds by definition, and $\bar \Sigma(0, \tau)$ is strictly increasing function of $\tau$ due to $\partial\bar \Sigma / \partial \tau > 0$ for all $\tau>0$. Hence (a) is clear.

Further, (b) is proved due to $\partial\bar \Sigma / \partial \tau = 0$ on $\tau = \tau^\dagger(\mu) = \{\nu b_1 \sigma_3  \mu /  (b_2 +b_1 \sigma_5) \}^{1/(\nu+1)}$ in (\ref{1st/2nd}). By substituting $\tau^\dagger(\mu)$ into $\bar \Sigma$, it is clear that $h(\mu)$ is radially unbounded strictly increasing function and has $\lim_{\mu \rightarrow 0}h(\mu) = 0$, i.e., $h^{-1}: {\mathbb R}_{>0} \rightarrow {\mathbb R}_{>0}$ is bijection.

Next, existence of $\mu^\ast=h^{-1}(k_0)$ for arbitrary given $k_0>0$ is relying on bijection $h^{-1}$. Since $\bar \Sigma(\mu, \tau)$ has both $\tau^{-\nu}$ and $\tau$ order terms for all $\mu \neq 0$, it is clear that $\lim_{\tau \rightarrow 0}\bar \Sigma(\mu, \tau)=\infty$, and $\lim_{\tau \rightarrow \infty}\bar \Sigma(\mu, \tau)=\infty$. Hence, for $\mu\in (0, \mu^\ast)$, there are unique $\underline{\tau}(\mu)\neq 0$ and $\bar \tau(\mu)>\tau^\dagger (\mu)$ so that (\ref{lem2-2}) is satisfied, depending on the continuity of $\bar \Sigma$, (a), and (b).

At last, (d) is easily obtained, after reorganizing the inequality $\bar \Sigma(\mu, \tau) < k_0$.



