\title{\textit{RTNinja}: a generalized machine learning framework for analyzing random telegraph noise signals in nanoelectronic devices}
% Example usage with superscripts
\authorAndAffiliations{Anirudh Varanasi\textsuperscript{1,2}, Robin Degraeve\textsuperscript{1}, Philippe Roussel\textsuperscript{1}, Clement Merckling\textsuperscript{1,2}}{%
