    \centering
    \includegraphics[width=0.32\linewidth]{Figures/FP_curves_2.pdf}
    \includegraphics[width=0.32\linewidth]{Figures/FP_curves.pdf}
    \includegraphics[width=0.32\linewidth]{Figures/FP_acrits.pdf}
