\section{Equilibrium 1-RSB computation for the symmetric \texorpdfstring{$p$}{p}-MAS problem}
\label{sec:1-RSB}
In order to compute the averaged free entropy (see \eqref{eq:gibbs} and \eqref{eq:repl}), we first need to compute the averaged replicated partition function
\begin{equation}\begin{split}
    \bbE_J[Z^n] &= \bbE_J\left[\Tr e^{\beta\sum_{\alpha=1}^{n}(E_J(\sigma^\alpha) + N h m(\sigma^\alpha))}\right] \\
    &= \int \prod_{i_1 < \dots < i_p} D J_{i_1,\dots,i_p} \Tr \exp(\beta\sqrt{\frac{p!}{N^{p-1}}}\sum_{i_1<\dots<i_p} J_{i_1,\dots,i_p} \sum_{\alpha=1}^{n} \sigma_{i_1}^\alpha\dots\sigma_{i_p}^\alpha + \beta h  \sum_{i=1}^N \sum_{\alpha=1}^{n}\sigma_i^\alpha), 
\end{split}\end{equation}
where we introduce $n$ replicas labelled with the index $\alpha$. We integrate over each $J_{i_1,\dots,i_p}$ independently explicitly
\begin{equation}\begin{split}
    \bbE_J[Z^n] = \Tr \exp(\frac{\beta^2 p!}{2N^{p-1}}\sum_{\alpha,\beta = 1}^n \sum_{i_1 < \dots < i_p} \sigma_{i_1}^\alpha\sigma_{i_1}^\beta \dots \sigma_{i_p}^\alpha\sigma_{i_p}^\beta + \beta h \sum_{\alpha=1}^{n} \sum_{i=1}^N \sigma_i^\alpha).
\end{split}\end{equation}
We can split the sums over the replicas into diagonal and non-diagonal terms
\begin{align*}
    \sum_{\alpha,\beta=1}^n \sum_{i_1<\dots<i_p} \sigma_{i_1}^\alpha\sigma_{i_1}^\beta \dots \sigma_{i_p}^\alpha\sigma_{i_p}^\beta  = \left( \sum_{\alpha=\beta=1}^{n}  + 2\sum_{\alpha < \beta} \right)\sum_{i_1<\dots<i_p} \sigma_{i_1}^\alpha\sigma_{i_1}^\beta \dots \sigma_{i_p}^\alpha\sigma_{i_p}^\beta,
\end{align*}
with
\begin{align*}
    \sum_{\alpha=\beta=1}^n \sum_{i_1 < \ldots < i_p} \sigma_{i_1}^\alpha  \sigma_{i_1}^b \ldots \sigma_{i_p}^\alpha  \sigma_{i_p}^\beta 
    =& \sum_{\alpha=1}^n \sum_{i_1 < \ldots < i_p} (\sigma_{i_1}^\alpha)^2 \ldots (\sigma_{i_p}^\alpha)^2 
    = \sum_{\alpha=1}^n \sum_{i_1 < \ldots < i_p} \sigma_{i_1}^\alpha \ldots \sigma_{i_p}^\alpha \\
    \approx& \frac{1}{p!} \sum_{\alpha=1}^n \sum_{i_1, \ldots, i_p} \sigma_{i_1}^\alpha \ldots \sigma_{i_p}^\alpha = \frac{1}{p!} \sum_{\alpha=1}^n\left(\sum_i \sigma_i^\alpha\right)^p,
\end{align*}
where we used that $\sigma_i^2 = \sigma_i$ for a boolean spin; and with 
\begin{align*}
    \sum_{\alpha<\beta} \sum_{i_1 < \ldots < i_p} \sigma_{i_1}^\alpha  \sigma_{i_1}^\beta \ldots \sigma_{i_p}^\alpha  \sigma_{i_p}^\beta
    &\approx \frac{1}{p!} \sum_{\alpha<\beta} \sum_{i_1, \ldots, i_p} \sigma_{i_1}^\alpha  \sigma_{i_1}^\beta \ldots \sigma_{i_p}^\alpha  \sigma_{i_p}^\beta \\
    &= \frac{1}{p!} \sum_{\alpha<\beta} \left(\sum_i \sigma_i^\alpha\sigma_i^\beta\right)^p.
\end{align*}
We notice that the approximations become exact in the thermodynamic limit, as the diagonal terms become negligible.

After splitting the sums, the averaged partition function is
\begin{equation}
    \bbE_J[Z^n] = \Tr \exp(N\beta^2\sum_{\alpha<\beta}\left( \frac{1}{N}\sum_{i}\sigma_i^\alpha \sigma_i^\beta \right)^p + \frac{N\beta^2}{2}\sum_\alpha\left(\frac{1}{N}\sum_i \sigma_i^\alpha\right)^p + \beta h \sum_\alpha\sum_i\sigma_i^\alpha). 
\end{equation}
We now introduce the variables
\begin{equation}
    q_{\alpha\beta} = \frac{1}{N}\sum_i \sigma_i^\alpha \sigma_i^\beta, \quad m_\alpha = \frac{1}{N} \sum_{i} \sigma_i^\alpha
\end{equation}
and we enforce their definition with Fourier transform of Dirac deltas:
\begin{equation}\begin{split}
    \bbE_J[Z^n] = &\int \prod_{\alpha < \beta}d q_{\alpha\beta} \int \prod_{\alpha}d m_\alpha \exp(N\beta^2\sum_{\alpha<\beta}q_{\alpha\beta}^p + \frac{N\beta^2}{2}\sum_\alpha m_\alpha^p)\\
    &\Tr \exp(\beta h \sum_\alpha\sum_i \sigma_i^\alpha) \prod_{\alpha < \beta}\delta(\sum_i \sigma_i^\alpha \sigma_i^\beta - N q_{\alpha\beta})\prod_{\alpha}\delta(\sum_i \sigma_i^\alpha - Nm_\alpha)  \\
    = &\int \prod_{\alpha < \beta} d q_{\alpha\beta} d \hat{q}_{\alpha\beta}\prod_{\alpha} d m_\alpha d \hat{m}_\alpha \exp(N\beta^2\sum_{\alpha<\beta}q_{\alpha\beta}^p + \frac{N\beta^2}{2}\sum_\alpha m_\alpha^p)  \\
    &\Tr \exp(\beta h \sum_\alpha \sum_i \sigma_i^\alpha + \sum_{\alpha < \beta}\hat{q}_{\alpha\beta}(\sum_i \sigma_i^\alpha \sigma_i^\beta - N q_{\alpha\beta}) + \sum_{\alpha}\hat{m}_\alpha(\sum_i \sigma_i^\alpha - Nm_\alpha)) .
\end{split}\end{equation}
Spins have now become decoupled with respect to the site variable $i$, so we can factorize the trace:
\begin{equation}\begin{split} \label{eq:Z_n}
    \E[Z^n] = &\int \prod_{\alpha < \beta} d q_{\alpha\beta} d \hat{q}_{\alpha\beta}\prod_{a} d m_\alpha d \hat{m}_\alpha \exp(N\left[ \beta^2\sum_{\alpha<\beta}q_{\alpha\beta}^p + \frac{\beta^2}{2}\sum_\alpha m_\alpha^p - \sum_{\alpha < \beta} \hat{q}_{\alpha\beta}q_{\alpha\beta} - \sum_{\alpha}\hat{m}_\alpha m_\alpha \right]) \\
    &\left(\Tr \exp(\beta h \sum_\alpha \sigma^\alpha + \sum_{\alpha < \beta}\hat{q}_{\alpha\beta} \sigma^\alpha \sigma^\beta + \sum_{\alpha}\hat{m}_\alpha \sigma^\alpha) \right)^N  \\
    = &\int \prod_{\alpha < \beta} d q_{\alpha\beta} d \hat{q}_{\alpha\beta}\prod_{a} d m_\alpha d \hat{m}_\alpha \exp\Biggl\{N\Biggl[ \beta^2\sum_{\alpha<\beta}q_{\alpha\beta}^p + \frac{\beta^2}{2}\sum_\alpha m_\alpha^p - \sum_{\alpha < \beta} \hat{q}_{\alpha\beta}q_{\alpha\beta} - \sum_{\alpha}\hat{m}_\alpha m_\alpha  \\
    & + \log\Biggl(\Tr\exp(\beta h \sum_\alpha \sigma^\alpha + \sum_{\alpha < \beta}\hat{q}_{\alpha\beta} \sigma^\alpha \sigma^\beta + \sum_{\alpha}\hat{m}_\alpha \sigma^\alpha) \Biggr) \Biggr]\Biggr\}.
\end{split}\end{equation}
Under the 1-RSB ansatz, the terms in \eqref{eq:Z_n} are
\begin{align*}
    \sum_{\alpha < \beta} q_{\alpha\beta}^p &= \frac{1}{2}\left( n^2 q_0^p + \frac{n}{x} x^2 (q_1^p - q_0^p) -n q_1^p \right) \\
    \sum_{\alpha < \beta} q_{\alpha\beta} \hat{q}_{\alpha\beta} &= \frac{1}{2}\left( n^2 q_0 \hat{q}_0 + \frac{n}{x} x^2 (q_1 \hat{q}_1 - q_0 \hat{q}_0) -n q_1 \hat{q}_1 \right) \\
    \sum_{\alpha < \beta} \hat{q}_{\alpha\beta}\sigma^\alpha\sigma^\beta &= \frac{1}{2}\left( \hat{q}_0 \left( \sum_{\alpha=1}^n \sigma^\alpha \right)^2 +(\hat{q}_1 - \hat{q}_0) \sum_{\mathrm{block}}^{n/x} \left( \sum_{\alpha\in\mathrm{block}}^{x} \sigma^\alpha \right)^2 - \hat{q}_1 \sum_{\alpha=1}^{n} \sigma^\alpha \right).
\end{align*}
The magnetization $m$ is still assumed to be replica symmetric. In order to evaluate the log term, we need to introduce one Gaussian integral to deal with the sum $\left( \sum_{\alpha=1}^n \sigma^\alpha \right)^2$ and $n/x$ Gaussian integrals to deal with the sums $\left( \sum_{a\in\mathrm{block}}^{x} \sigma^\alpha \right)^2$:
\begin{align*}
    &\Tr_{\sigma^\bullet} \exp(\frac{\hat{q}_0}{2}\left( \sum_{\alpha=1}^{n}\sigma^\alpha \right)^2 + (\hat{m} + \beta h - \frac{\hat{q}_1}{2})\sum_{\alpha=1}^{n} \sigma^\alpha +\frac{\hat{q}_1-\hat{q}_0}{2}\sum_{\mathrm{block}}^{n/x}\left( \sum_{\alpha\in \mathrm{block}}^{x} \sigma^\alpha \right)^2) \\
    &= \Tr_{\sigma^\bullet} \int D u \exp(\left( \sqrt{\hat{q}_0}u + \hat{m} + \beta h -\frac{\hat{q}_1}{2} \right)\sum_{\alpha=1}^{n}\sigma^\alpha) \prod_{\mathrm{block}}^{n/x} \int D v_{\mathrm{block}}\exp(\sqrt{\hat{q}_1 - \hat{q}_0}v_{\mathrm{block}}\sum_{\alpha\in\mathrm{block}}^{x}\sigma^\alpha) \\
    &= \Tr_{\sigma^\bullet} \int D u \prod_{\mathrm{block}}^{n/x} \int D v_{\mathrm{block}} \exp(\left( \hat{m} + \beta h - \frac{\hat{q}_1}{2} + \sqrt{\hat{q}_0}u + \sqrt{\hat{q}_1 - \hat{q}_0}v_{\mathrm{block}} \right) \sum_{\alpha\in\mathrm{block}}^{x}\sigma^\alpha) \\
    &= \int D u \prod_{\mathrm{block}}^{n/x} \int D v_{\mathrm{block}} \left( \Tr_\sigma \exp(( \hat{m} + \beta h - \frac{\hat{q}_1}{2} + \sqrt{\hat{q}_0}u + \sqrt{\hat{q}_1 - \hat{q}_0}v_{\mathrm{block}} )\sigma) \right)^x \\
    &= \int D u \left[ \int D v \left( 1+ \exp( \hat{m} + \beta h - \frac{\hat{q}_1}{2} + \sqrt{\hat{q}_0}u + \sqrt{\hat{q}_1 - \hat{q}_0}v) \right)^x \right]^{n/x}.
\end{align*}
We take the $n \to 0$ limit to obtain the 1-RSB free entropy density:
\begin{equation}\begin{split}\label{eq:1RSB_Phi}
    \phi_{1-RSB} &= \mathrm{Extr}_{q_0,\hat{q}_0,q_1,\hat{q}_1,m,\hat{m},x} \Biggl\{ \frac{\beta^2}{2}m^p + \frac{\beta^2}{2}x(q_1^p - q_0^p) - \frac{\beta^2}{2}q_1^p - \frac{x}{2}(q_1 \hat{q}_1 - q_0 \hat{q}_0) + \frac{1}{2}q_1 \hat{q}_1 - m \hat{m} \\
    & + \frac{1}{x}\int D u \log \int D y \left( 1 + \exp(\hat{m} + \beta h - \frac{\hat{q}_1}{2} + \sqrt{\hat{q}_0}u + \sqrt{\hat{q}_1 - \hat{q}_0}v) \right)^{x} \Biggr\} 
\end{split}\end{equation}

The extremization of the 1-RSB free entropy with respect to $m$, $q_0$ and $q_1$ gives the relations:
\begin{equation*}
    \hat{m} = \frac{\beta^2}{2}p m^{p-1} ,\qquad \hat{q}_0 = \beta^2 p q_0^{p-1}, \qquad \hat{q}_1 = \beta^2 p q_1^{p-1}.
\end{equation*}
Substituting the hat variables into \eqref{eq:1RSB_Phi} gives the expression of the 1-RSB free entropy density
\begin{equation}
\begin{aligned}
    \phi_{1-RSB} &= (1-p) \frac{\beta^2}{2}\left[ m^p + (x-1)q_1^p - x q_0^p \right] + \frac{1}{x} \int D u \log \int D v \left( 1 + \exp(\beta H_{u,v}) \right)^x,
\end{aligned}
\end{equation}
where
\begin{equation}
    H_{u,v} = h + \frac{\beta p}{2}(m^{p-1} - q_1^{p-1}) + \sqrt{p q_0^{p-1}}u + \sqrt{p(q_1^{p-1}-q_0^{p-1})}v.
\end{equation}

The saddle-point equations then follow similarly an in the usual $p$-spin model. The expression for the energy and magnetization, as well as for the complexity, then follow by taking the respective partial derivatives w.r.t. $\beta, m, x$.

\section{The small magnetization limit of the equilibrium behavior of the \texorpdfstring{$p$}{p}-MAS}
\label{sec:small_m}
\subsection{RS solution}\label{sec:RS_m}
We consider the RS equations (i.e. \eqref{eq:1RSB} with $q_0=q_1=q$):
\begin{equation}
\begin{aligned}
    m &= \int D u \log(\beta H_u), \\
    q &= \int D u l^2(\beta H_u), \\
    H_u &= h + \frac{\beta p}{2}(m^{p-1}-q^{p-1}) + \sqrt{p q^{p-1}}u
\end{aligned}
\end{equation}
in the scaling limit:
\begin{equation}
\begin{aligned}
    \beta &= b\sqrt{m^{1-p}\log\frac{1}{m}} \\
    h &= \eta\sqrt{m^{p-1}\log\frac{1}{m}}.
\end{aligned}
\end{equation}
Plugging the scalings in the RS saddle-point equations gives
\begin{equation}
    \beta H_u = b\left(\eta + \frac{pb}{2} - \frac{pb}{2}(\frac{q}{m})^{p-1}\right)\log\frac{1}{m} + b\sqrt{p(\frac{q}{m})^{p-1}}\sqrt{\log\frac{1}{m}}u.
\end{equation}
As $m^2 \leq q \leq m$, we assume $q = cm^{1+\alpha}$ with $c>0$ and $\alpha\geq0$. For $\alpha > 0$, the second term goes to 0 and the dependence on $u$ drops in $H_u$, implying that 
\begin{equation}
    q = l^2(H) = m^2 \implies c = \alpha = 1,
\end{equation}
consistently with our assumption for $q$. The equation for $m$ becomes
\begin{equation}
    m = l(b(\eta+pb/2)\log\frac{1}{m}) \implies \log\frac{m}{1-m} = b(\eta+pb/2)\log\frac{1}{m}.
\end{equation}
Solving for $\eta$:
\begin{equation}
    \eta = -\frac{1}{b}-\frac{pb}{2}.
\end{equation}
We can also compute the energy and entropy density:
\begin{equation}
\begin{aligned}
   e_{\mathrm{RS}} &= \beta (m^p-q^p) \sim \beta m^p = b\sqrt{m^{p+1}\log \frac{1}{m}} \\
   s_{\mathrm{RS}} &= \phi_{\mathrm{RS}} - \beta e - \beta h m \sim (1-p)\frac{b^2}{2}m\log\frac{1}{m} - b^2 m \log\frac{1}{m} - b(-\frac{1}{b}-\frac{pb}{2})m\log\frac{1}{m} \\
   &= (1-\frac{b^2}{2})m\log\frac{1}{m}.
\end{aligned}
\end{equation}
We can recover the subtensor average from the energy:
\begin{equation}\label{eq:units}
\begin{aligned}
    \avg &= \frac{\sqrt{p! N^{1-p}}}{m^p}e = \sqrt{(mN)^{1-p}\log\frac{1}{m}}\sqrt{p!}b \\
    &= b\sqrt{p!}\sqrt{k^{1-p}\log N}.
\end{aligned}
\end{equation}

\subsection{1-RSB solution}\label{sec:1RSB_m}
Consider now \eqref{eq:1RSB} in the 1-RSB dynamic case, i.e. $x=1$. We use the scaling
\begin{equation}
\begin{aligned}
    \beta &= b\sqrt{m^{1-p}\log \frac{1}{m}} \\
    h &= \eta \sqrt{m^{p-1}\log \frac{1}{m}} \\
    q_0 &= m^2 \\
    q_1 &= c^2m,
\end{aligned}
\end{equation}
with $c=\mathcal{O}_m(1)$ to keep the dependence on $v$ in $H_{u,v}$. We have
\begin{equation}
    \beta H_{u,v} = \left(b\eta + \frac{pb^2}{2}(1-c^{2(p-1)})\right)\log \frac{1}{m} + b\sqrt{pm^{p-1}\log\frac{1}{m}}u + b\sqrt{p(c^{2(p-1)}-m^{p-1})\log\frac{1}{m}}v.
\end{equation}
We see that the $u$ term is going to $0$, and the dependence on $u$ drops, giving $q_0=m^2$ and 
\begin{equation}\label{eq:H_v}
    H_v = \left(b\eta + \frac{pb^2}{2}(1-c^{2(p-1)})\right)\log\frac{1}{m} + b\sqrt{pc^{2(p-1)}}\sqrt{\log\frac{1}{m}}v \equiv A N + B\sqrt{N}v,
\end{equation}
where we defined $A = b\eta + \frac{pb^2}{2}(1-c^{2(p-1)})$, $B=b\sqrt{p}c^{p-1}$ and $N=\log\frac{1}{m}$.
We now want to solve the saddle-point equations in the region of positive complexity where $x=1$. To do so, we need to compute integrals of the form
\begin{equation}
    I_s = \int D v (1+e^{\beta H_v})l^s(\beta H_v).
\end{equation}
We begin by computing $I_2$:
\begin{equation}
\begin{split}
    I_2 &= \int d v \frac{e^{-v^2/2}}{\sqrt{2\pi}}(1+e^{\beta H_v})l^2(\beta H_v) = \int d v \frac{e^{-v^2/2}}{\sqrt{2\pi}}(1+e^{AN+B\sqrt{N}v})^{-1}e^{2(AN+B\sqrt{N}v)} \\
    &= \int \frac{d v}{\sqrt{2\pi}}e^{-v^2/2+2AN+2B\sqrt{N}v-\logpexp(AN+B\sqrt{N}v)},
\end{split}
\end{equation}
where $\logpexp(x)=\log(1+\exp(x))$.
We make the change of variable $v = \sqrt{N}w$:
\begin{equation}
    I_2 = \sqrt{N}\int\frac{d w}{\sqrt{2\pi}}e^{N\left(-w^2/2+2A+2Bw-\frac{1}{N}\logpexp(N(A+Bw))\right)} \equiv \sqrt{N}\int\frac{d w}{\sqrt{2\pi}}e^{N\mathcal{H}}
\end{equation}
to put the integral in a form amenable to the saddle-point method. The logpexp term can be approximated by
\begin{equation}
    \frac{1}{N}\logpexp(N(A+Bw)) \approx \max(0,A+Bw) + \mathcal{O}(e^{-N\abs{A+Bw}})
\end{equation}
when $\abs{A+Bw}$ is sufficiently far from 0. We compute the derivative of the exponent:
\begin{eqnarray}
    \del_w{\mathcal{H}}{w} = \begin{cases}
        -w + B &w > -\frac{A}{B} \\
        -w + 2B &w < -\frac{A}{B}
    \end{cases} = 0,
\end{eqnarray}
giving two solutions:
\begin{equation}
    \begin{cases}
        w_1^* = B &w > -\frac{A}{B} \\
        w_2^* = 2B &w < -\frac{A}{B}
    \end{cases}.
\end{equation}
We now distinguish different cases:
\begin{itemize}
    \item if $2B > -\frac{A}{B}$ and $B > -\frac{A}{B}$, i.e. $-\frac{A}{B^2} < 1$, then $w^* = B$ and 
    \begin{equation}
        I_2 = \sqrt{\frac{N}{2\pi}}e^{N(-B^2/2 + 2A + 2B^2 - (A+B^2))} = \sqrt{\frac{N}{2\pi}}e^{N(B^2/2 + A)}
    \end{equation}
    \item if $B < -\frac{A}{B}$ and $2B < \frac{A}{B}$, i.e. $2 < -\frac{A}{B^2}$, then $w^* = 2B$ and
    \begin{equation}
        I_2 = \sqrt{\frac{N}{2\pi}}e^{N(-2B^2 + 2A + 4B^2)} = \sqrt{\frac{N}{2\pi}}e^{N(2A + 2B^2)}
    \end{equation}
    \item if $B > -\frac{A}{B}$ and $2B < -\frac{A}{B}$, we have $1 > 2$ which is impossible
    \item if $B < -\frac{A}{B}$ and $2B > -\frac{A}{B}$, i.e. $1 < -\frac{A}{B^2}< 2$, the derivative is never equal to $0$ far from $w = -\frac{A}{B}$. We see that the derivative is $>0$ for $w < -\frac{A}{B}$ and $<0$ for $w > -\frac{A}{B}$, meaning we must look for the maximum at $-\frac{A}{B}$, which is where the approximation of the $\logpexp$ breaks down.
\end{itemize}
We then compute $I_1$ and $I_0$:
\begin{equation}\begin{split}
&\begin{aligned}
    I_1 &= \int D v (1+e^{\beta H_v})l(\beta H_v) = \int D v e^{\beta H_v} \\
    &= \sqrt{N}\int\frac{d w}{\sqrt{2\pi}}e^{N(-w^2/2 + A  + Bw)} = \sqrt{\frac{N}{2\pi}}e^{N(B^2/2+A)},
\end{aligned} \\
    &I_0 = \int D y (1+e^{\beta H_v}) = 1+I_1.
\end{split}\end{equation}
The 1-RSB equations in the small $m$ limit are:
\begin{equation}\begin{split}
    m &= \frac{I_1}{I_0} \\
    q_1 &= c^2 m = \frac{I_2}{I_0}.
\end{split}\end{equation}
If $B^2/2 + A > 0$, $I_1 \approx I_0$ which is not compatible with $m \to 0$, further constraining $-\frac{A}{B^2} > \frac{1}{2}$. We are then left with the following cases :
\begin{itemize}
    \item $\frac{1}{2} < -\frac{A}{B^2} < 1$: the equation for $q_1$ gives
    \begin{equation}
        I_1 = I_2 \implies c^2 = 1 \implies A = b\eta ,\quad B = b\sqrt{p}
    \end{equation}
    and the equation for $m$ gives
    \begin{equation}
        m = \frac{I_1}{I_0} = \frac{I_1}{1+I_1} = \frac{\sqrt{N/2\pi}e^{N(\frac{B^2}{2} + A)}}{1+\sqrt{N/2\pi}e^{N(\frac{B^2}{2} + A)}} = \frac{e^{N(\frac{B^2}{2} + A)}}{\sqrt{2\pi / N}+e^{N(\frac{B^2}{2} + A)}}.
    \end{equation}
    Taking the $\log$ on both sides we get
    \begin{equation}
        \log m = N(\frac{B^2}{2} + A) - \underbrace{\log(\sqrt{2\pi/N} + e^{N(\frac{B^2}{2} + A)})}_{\sim \log N} \approx N(\frac{B^2}{2} + A).
    \end{equation}
    Remembering that $N = \log \frac{1}{m}$, we have $\frac{B^2}{2} + A = -1$, giving us
    \begin{equation}
        \eta = -\frac{1}{b}-\frac{pb}{2}.
    \end{equation}
    \item $2 < -\frac{A}{B^2}$: $\implies A + 2B^2 < 0$, therefore we have
    \begin{equation}
        c^2 = \frac{I_2}{I_1} = e^{N(A+\frac{3}{2}B^2)} \to 0.
    \end{equation}
    The dependence on $v$ drops in Eq. \eqref{eq:H_v} and we get $q_1 = m^2 = q_0$, recovering the RS solution.
    \item $1 < -\frac{A}{B^2} < 2$: following \cite{Erba_2024} we also recover the RS solution.
\end{itemize}
To sum up, for $-\frac{A}{B^2} < \frac{1}{2}$ there is no solution, for $\frac{1}{2} < -\frac{A}{B^2} < 1$ we find a 1-RSB solution different from the RS one while for $-\frac{A}{B^2} > 1$ we recover the RS solution.
Recalling that $A= b\eta = -1-\frac{pb^2}{2}$ and $B=b\sqrt{p}$ for $c=1$, the condition for the existence of the 1-RSB solution is:
\begin{equation}
    \frac{1}{2} < -\frac{A}{B^2} < 1 \implies \frac{1}{2} < \frac{1 + pb^2/2}{pb^2} = \frac{1}{pb^2}+\frac{1}{2} < 1 \implies b > \sqrt{2/p}.
\end{equation}
In the region with positive complexity, we fix $x=1$ and the 1-RSB energy is equal to the RS one. To find the complexity \eqref{eq:complexity}, we first compute:
\begin{equation}
\begin{aligned}
    -x^2\partial_x \phi_{\mathrm{1-RSB}}(x) &= -x^2(1-p)\frac{b^2}{2}(q_1^p-q_0^p)+ \overbrace{\int D u \log \int D v (1+\exp(\beta H))^{x}}^{D} \\
    &- \underbrace{x\int D u \frac{\int D v \log(1+e^{\beta H})(1+e^{\beta H})^{x}}{\int D v (1+e^{\beta H})}}_{E}
\end{aligned}
\end{equation}
In the small $m$ limit, the dependence on $u$ drops, and setting $x=1$ we have
\begin{equation}
\begin{aligned}
    D &= \log(I_0) = \log(1+I_1) \approx I_1 \sim m \\
    E &= \int D v \log(1+e^{\beta H})(1+e^{\beta H}) \approx \sqrt{\frac{\log\frac{1}{m}}{2\pi}}e^{\log\frac{1}{m}(B^2/2 + A)}(A\log\frac{1}{m} + B^2\log\frac{1}{m}) \\
    &\approx (A+B^2)m\log\frac{1}{m} = (-1+\frac{pb^2}{2})m\log\frac{1}{m},
\end{aligned}
\end{equation}
where we used that $A+B^2/2 = -1$. Collecting the terms, we are left with
\begin{equation}
    \Sigma = -x^2\partial_x \phi_{\mathrm{1-RSB}}(x)\vert_{x=1} = (1-\frac{b^2}{2})m\log\frac{1}{m}.
\end{equation}

\section{The non-symmetric case}\label{sec:non-symmetric}
We start from \eqref{eq:gibbs-non-symm}.
Then ($a, b$ are replica indices)
\begin{equation}
    \begin{split}
        \mathbb{E}_J Z^n 
        &=
        \Tr \prod_{i_1 \dots i_p} \int DJ \exp\left( J \beta N^{\frac{1-p}{2}} \sum_a  \prod_{\alpha = 1}^p \sigma^{(\alpha), a}_{i_{\alpha}} \right)
        \\
        &=
        \Tr \prod_{i_1 \dots i_p} 
        \exp\left( \frac{1}{2}\beta^2 N^{1-p} \sum_{a, b} 
        \prod_{\alpha = 1}^p
        \sigma^{(\alpha), a}_{i_{\alpha}} 
        \sigma^{(\alpha), b}_{i_{\alpha}}
        \right)
        \\
        &=
        \Tr 
        \exp\left( \frac{1}{2}\beta^2 N^{1-p} \sum_{a, b} 
        \prod_{\alpha = 1}^p
        \sum_{i_\alpha} 
        \sigma^{(\alpha), a}_{i_{\alpha}} 
        \sigma^{(\alpha), b}_{i_{\alpha}}
        \right)
        \\
        &=
        \Tr 
        \exp\left( \frac{1}{2}\beta^2 N \sum_{a, b} 
        \prod_{\alpha = 1}^p
        q(
        \sigma^{(\alpha), a}_{i_{\alpha}} ,
        \sigma^{(\alpha), b}_{i_{\alpha}} )
        \right)
        \\
        &=
        \int dm dq
        \exp\left( 
        \beta^2 N \sum_{a < b} 
        \prod_{\alpha = 1}^p
        q^{ab}_\alpha
        +
        \frac{1}{2} \beta^2 N \sum_{a} 
        \prod_{\alpha = 1}^p
        m^{a}_\alpha
        \right)
        \\&\qquad\times
        \Tr
        \delta\left( N q^{ab}_\alpha - \sum_{i} 
        \sigma^{(\alpha), a}_{i} 
        \sigma^{(\alpha), b}_{i}\right)
        \delta\left( N m^{a}_\alpha - \sum_{i} 
        \sigma^{(\alpha), a}_i\right)
    \end{split}
\end{equation}
Now assume the "tensor symmetric" solution $q^{ab}_\alpha = q^{ab}$ and $m^a_\alpha = m^a$, then
 \begin{equation}
    \begin{split}
        \mathbb{E}_J Z^n 
        &=
        \int dm dq
        \exp\left( 
        \beta^2 N \sum_{a < b} 
        q_{ab}^p
        +
        \frac{1}{2} \beta^2 N \sum_{a} 
        m_{a}^p
        \right)
        \\&\qquad\times
        \left[
        \Tr
        \delta\left( N q^{ab} - \sum_{i} 
        \sigma^{a}_{i} 
        \sigma^{b}_{i}\right)
        \delta\left( N m^{a} - \sum_{i} 
        \sigma^{a}_i\right)
        \right]^p
    \end{split}
\end{equation}
Then we see that the trace term will contribute a term proportional to $p$ to the free entropy, as it is a product over $p$ of identical terms, while the first term has not such factor of $p$. 
We also see that by setting $\beta = \sqrt{p} \beta_s$ this free entropy is just $p$ times the free entropy of the symmetric model. 
Thus the saddle-point equations are the same as those for the symmetric model at any level of RSB.

\section{Asymptotics of the IGP algorithm}\label{sec:IGP}
We first recall the following two facts:
\begin{itemize}
    \item the maximum of $N$ Gaussian random variables $X_i \sim \mathcal{N}(0,\sigma^2)$ is asymptotically $\sqrt{2\sigma^2\log N}$,
    \item the sum of $n$ i.i.d. standard Gaussian random variables is also Gaussian, with $\sigma^2 = n$.
\end{itemize}
We begin by recalling the argument laid out in \cite{Gamarnik2018} in the non-symmetric matrix case to fix the notation and ideas, before generalizing to arbitrary $p$ and adapting the argument to the symmetric case.

\subsection{Non-symmetric case}
\subsubsection{\texorpdfstring{$p=2$}{p=2} case} We denote by $\mathcal{I}$ the set of row indices belonging to the submatrix and by $\mathcal{J}$ the set of column indices belonging to the submatrix. In the initial step of the algorithm, we pick a random index $i_1$ such that $\mathcal{I} = \{i_1\}$ and $\mathcal{J} = \varnothing$. In the row indexed by $i_1$, denoted $J_{i_1,[N]}$, we find the largest entry $J_{i_1,j_1}$, adding its column index to $\mathcal{J}$ to form an initial $1\times1$ submatrix. It is the maximum out of $N$ i.i.d. standard Gaussians and is asymptotically $\sqrt{2\log N}$. We then find the largest entry $J_{i_2,j_1}$ in the column $J_{[N]\backslash \mathcal{I},j_1}$, which is the column of $J_{i_1,j_1}$ with $J_{i_1,j_1}$ removed. It is also $\sqrt{2\log N}$ asymptotically as the maximum of $N-1$ standard Gaussians (in general, the maximum out of $N-l$ Gaussians with $l \ll N$ is also $\sqrt{2\log N}$). Adding its row index to our submatrix, $\mathcal{I}=\{i_1,i_2\}$, we now have a $2\times1$ submatrix. To form a $2\times 2$ submatrix, we find the index $j_2$ such that sum of the two entries in the $2\times1$ column $J_{\mathcal{I},j_2}$ is maximal, among the pairs in the $2\times (N-1)$ submatrix $J_{\mathcal{I},[N]\backslash \mathcal{J}}$, which is the submatrix formed of the two rows indexed by $\mathcal{I}$, with the two entries already in our submatrix removed. The sum of two standard Gaussians is also a Gaussian with a variance of 2, so the maximum of the sum of two entries among $N-1$ pairs is asymptotically $\sqrt{2\cdot 2 \log N}$.

Let us take stock of the steps taken so far:
\begin{enumerate}
    \item we start by finding the largest entry in an arbitrary row, with an asymptotic value of $\sqrt{2\log N}$, to form a $1\times 1$ submatrix,
    \item in the corresponding column, we find the next largest entry, also with an asymptotic value of $\sqrt{2 \log N}$, forming a $2\times 1$ submatrix,
    \item in the two rows corresponding to the two entries we selected so far, we find the pair of entries with the second largest sum, asymptotically $\sqrt{4\log N}$, and form a $2\times 2$ submatrix.
\end{enumerate}
We then repeat steps 2 and 3, increasing each time the size of the submatrix from $r\times r$ to $(r+1)\times(r+1)$ and contributing $\sqrt{2(r)\log N} + \sqrt{2(r+1)\log N}$ to the total of the final submatrix. An illustration of two of those steps is shown in Figure \ref{fig:IGP_NS_2d}. Once the submatrix is of size $k\times k$, the sum of all its entries is
\begin{equation}
    T = \sqrt{2\log N} + \sum_{r=1}^{k-1}(\sqrt{2r\log N}+\sqrt{2(r+1)\log N}) \approx 2 \int_{1}^{k}\sqrt{x}d x \sqrt{2\log N} \approx \frac{4}{3}k^{3/2}\sqrt{2\log N}.
\end{equation}
Diving by the number of entries in the submatrix, $k^2$, we find the average
\begin{equation}
    A_{IGP, p=2}^{non-sym} = \frac{4}{3}\sqrt{2k^{-1}\log N}.
\end{equation}
We assumed that the maximizations over Gaussian variables were independent even though they are not, but the algorithm can be slightly adjusted with no change in the asymptotic values, as shown in \cite{Gamarnik2018}.

