\subsubsection{Generic \texorpdfstring{$p$}{p}} In the tensorial case, the difference is that $p$ steps are needed to increase the size of the subtensor from $r^{\otimes p}$ to $(r+1)^{\otimes p}$. In the first of those $p$ steps, we find a $(p-1)-$dimensional slice along the first dimension such that the sum of its entries is larger than the sum of other possible slices. This slice has $r^{p-1}$ entries, and therefore contributes $\sqrt{2r^{p-1}\log N}$ to the total of the subtensor. Having added this $r^{\otimes (p-1)}$ slice to the subtensor, it is now of size $(r+1)\times r^{\otimes (p-1)}$. We then repeat this search along each dimension, adding the highest sum slice to the subtensor, with a contribution of $\sqrt{2(r+1)^{d-1}r^{p-d}\log N}$, where $d$ is the index of dimension along which we're currently enlarging the subtensor. We illustrate the first two steps needed to increase a 3-subtensor from $4\times4\times4$ to $5\times5\times5$ in Figure \ref{fig:IGP_NS}. The total contribution of the $p$ steps needed to increase the size of the subtensor from $r^{\otimes p}$ to $(r+1)^{\otimes p}$ is therefore
\begin{equation}
    T_r = \sum_{d=1}^{p}\sqrt{(r+1)^{d-1}r^{p-d}}\sqrt{2\log N}.
\end{equation}
The final total is
\begin{equation}
    T = \sum_{r=1}^{k-1}T_r = \sum_{r=1}^{k-1}\sum_{d=1}^{p}\sqrt{(r+1)^{d-1}r^{p-d}}\sqrt{2\log N}.
\end{equation}
We can once again approximate the sum over $r$ with integrals:
\begin{equation}
    \sum_{r=1}^{k-1}\sum_{d=1}^{p}\sqrt{(r+1)^{d-1}r^{p-d}} \approx \sum_{d=1}^{p}\int_{2}^{k} x^{\frac{d-1}{2}}(x+1)^{\frac{p-d}{2}}d x.
\end{equation}
In the large $k$ limit, we have
\begin{equation}
    \int_{2}^{k} x^{\frac{d-1}{2}}(x+1)^{\frac{p-d}{2}}d x \approx \frac{2}{p+1}k^{\frac{p+1}{2}}.
\end{equation}
We see that the dependence on $d$ drops, leaving us with
\begin{equation}
    T = \frac{2p}{p+1}k^{\frac{p+1}{2}}\sqrt{2\log N}.
\end{equation}
We divide by $k^p$ to find the average
\begin{equation}
    A_{IGP,p}^{non-sym} = \frac{2p}{p+1}\sqrt{2k^{1-p}\log N}.
\end{equation}

