\section{Asymptotics of the LAS algorithm}
\label{sec:LAS}
The structure theorem (theorem 2.5 in \cite{Bhamidi2017}) implies that all entries in a typical locally optimal submatrix are concentrated around $\sqrt{2k^{-1}\log N}$, which coincides with the freezing threshold. We sketch here the adjustments required to extend the proof to subtensors of arbitrary dimension.

The definitions of row and column dominant are generalized by considering a subtensor to be slice dominant if its average cannot be improved by swapping one of its index along a dimension to another not yet included. We can then define the events $\mathcal{R}^{(\alpha)}_k$ as the subtensor being slice optimal along dimension $\alpha$, and we are interested in the event $\mathcal{I}_{k,n} = \cap_{\alpha = 1}^p\mathcal{R}_k^{(\alpha)}$ corresponding to locally optimal subtensors.

As the ANOVA decomposition plays an important role in the original proof, we introduce the tensor-ANOVA decomposition of a subtensor $\mathbf{C}$ as:
\begin{equation}
    C_{i_1,\ldots,i_p} = \Tilde{c}_{i_1,\ldots,i_p} + (c_{\bullet,\ldots,\bullet,i_p}-c_{\bullet,\ldots,\bullet}) + (c_{\bullet,\ldots,\bullet ,i_{p-1},\bullet}-c_{\bullet,\ldots,\bullet}) + \ldots + (c_{i_1,\bullet, \ldots,\bullet}-c_{\bullet,\ldots,\bullet}) + c_{\bullet,\ldots,\bullet},
\end{equation}
where $c_{\bullet,\ldots,\bullet}$ is the average of the entries of $\mathbf{C}$ and $c_{\bullet,\ldots,i_\alpha,\ldots,\bullet}=k^{-(p-1)}\sum_{i_1,\ldots,i_{\alpha-1},i_{\alpha+1},\ldots,i_p=1}^k W_{i_1,\ldots,i_p}$ is the average of the first $k\times^{(p-1)}$ entries in the $i_\alpha$th slice along dimension $\alpha$. One can check that this decomposition has the same independence properties as the matrix one. The rest of the proof follows the matrix case closely, leading to the same conclusion as for submatrices, that is the average of locally optimal subtensors is identic to the freezing threshold.

\section{Annealed OGP computation for the \texorpdfstring{$p$}{p}-MAS problem}
\label{sec:annealed_OGP}
We start from the partition function
\begin{equation}
    Z_{p,r} = \sum_{\sigma^1,\dots,\sigma^r}\prod_{\alpha < \beta}e^{\gamma q(\sigma_\alpha,\sigma_\beta)}\prod_{\alpha}e^{\beta E(\sigma_\alpha)+N\beta h m(\sigma_\alpha)},
\end{equation}
with $r$ real replicas. We compute its average
\begin{equation}
\begin{aligned}
    &\bbE_J[Z_{p,r}] \\
    &= \bbE_J\left[ \Tr\exp(\beta\sum_\alpha\sqrt{\frac{p!}{N^{p-1}}}\sum_{i_1<\dots<i_p}J_{i_1,\dots,i_p}\sigma_{i_1}^\alpha \dots\sigma_{i_p}^{\alpha} + N\beta h\sum_\alpha m(\sigma_\alpha)+N\gamma\sum_{\alpha<\beta}q(\sigma_\alpha,\sigma_\beta)) \right] \\
    &= \Tr \exp(\frac{p!}{2N^{p-1}}\beta^2\sum_{\alpha,\beta}\sum_{i_1<\dots<i_p}\sigma_{i_1}^\alpha \sigma_{i_1}^\beta \dots \sigma_{i_p}^\alpha\sigma_{i_p}^\beta + N\beta h \sum_\alpha m(\sigma^\alpha) + N \gamma \sum_{\alpha<\beta}q(\sigma^\alpha,\sigma^\beta)) \\
    &= \Tr \exp(N\beta^2\sum_{\alpha<\beta}q(\sigma^\alpha,\sigma^\beta)^p+\frac{N}{2}\beta^2\sum_\alpha m(\sigma^\alpha)^p + N\beta h \sum_\alpha m(\sigma^\alpha) + N \gamma \sum_{\alpha<\beta}q(\sigma^\alpha,\sigma^\beta)).
\end{aligned}
\end{equation}
To take the trace, we define $q_{\alpha\beta} = q(\sigma^\alpha,\sigma^\beta)$ and $m_\alpha = m(\sigma^\alpha)$ and enforce the equalities with Diracs, that we write in Fourier:
\begin{equation}
\begin{aligned}
    &\bbE_J[Z_{p,r}] \\
    &= \exp(N\beta^2\sum_{\alpha<\beta}q_{\alpha\beta}^p + \frac{N}{2}\beta^2 \sum_\alpha m_\alpha^p) \\
    &\times \Tr \int \prod_\alpha d m_\alpha d \hat{m}_\alpha \prod_{\alpha<\beta} d q_{\alpha\beta}d\hat{q}_{\alpha\beta} \exp(\sum_\alpha \hat{m}_\alpha\left( \sum_i \sigma_i^\alpha-Nm_\alpha \right)+\sum_{\alpha<\beta}\hat{q}_{\alpha\beta}\left( \sum_i \sigma_i^\alpha\sigma_i^\beta- Nq_{\alpha\beta} \right)) \\
    &\times \exp(N\beta h\sum_\alpha m(\sigma^\alpha)+N\gamma\sum_{\alpha<\beta}q(\sigma^\alpha,\sigma^\beta)) \\
    &= \int \prod_\alpha d m_\alpha d \hat{m}_\alpha \prod_{\alpha<\beta} d q_{\alpha\beta}d\hat{q}_{\alpha\beta} \exp(N\beta^2\sum_{\alpha<\beta}q_{\alpha\beta}^p + \frac{N}{2}\beta^2 \sum_\alpha m_\alpha^p - N \sum_\alpha \hat{m}_\alpha m_\alpha - N \sum_{\alpha<\beta}\hat{q}_{\alpha\beta}q_{\alpha\beta}) \\
    &\times \Tr \exp(\sum_\alpha(\hat{m}_\alpha + \beta h)\sum_i \sigma_i^\alpha + \sum_{\alpha<\beta}(\hat{q}_{\alpha\beta} + \gamma)\sum_i \sigma_i^\alpha\sigma_i^\beta).
\end{aligned}
\end{equation}
We can factorize the trace over the site index $i$ to obtain
\begin{equation}
\begin{aligned}
    \bbE_J[Z_{p,r}] &= \int \prod_\alpha d m_\alpha d \hat{m}_\alpha \prod_{\alpha<\beta} d q_{\alpha\beta}d \hat{q}_{\alpha\beta} \exp\Biggl(N\biggl[ \beta^2\sum_{\alpha<\beta}q_{\alpha\beta}^p + \frac{\beta^2}{2}\sum_\alpha m_\alpha^p  \\
    &- \sum_\alpha \hat{m}_\alpha m_\alpha - \sum_{\alpha<\beta}\hat{q}_{\alpha\beta}q_{\alpha\beta} +\log \Tr_{\sigma^\bullet} \exp L\biggr]\Biggr) ,
\end{aligned}
\end{equation} 
where 
\begin{equation}
    L = \sum_\alpha (\hat{m}_\alpha + \beta h)\sigma^\alpha + \sum_{\alpha<\beta}(\hat{q}_{\alpha\beta}+\gamma)\sigma^\alpha\sigma^\beta.
\end{equation}
The saddle-point equations are
\begin{equation}
\begin{aligned}
    m_\alpha &= \frac{\Tr \sigma^\alpha e^L}{\Tr e^L} = \langle \sigma^\alpha \rangle_{L}, \quad q_{\alpha\beta} = \langle \sigma^\alpha \sigma^\beta \rangle_{L} \\
    \hat{m}_\alpha &= p\frac{\beta^2}{2}m_\alpha^{p-1},\quad \hat{q}_{\alpha\beta} = p\beta^2q_{\alpha\beta}^{p-1}
\end{aligned}
\end{equation}
and we can eliminate the hat variables to get
\begin{equation}
    \bbE_J[Z_{p,r}] = \int \prod_\alpha d m_\alpha \prod_{\alpha<\beta} d q_{\alpha\beta} \exp N\left( (1-p)\beta^2\sum_{\alpha<\beta}q_{\alpha\beta}^p + (1-p)\frac{\beta^2}{2}\sum_\alpha m_\alpha^p + \log \Tr\exp L \right).
\end{equation}
We consider the real replica symmetric ansatz, i.e. $m_\alpha = m$ and $q_{\alpha\beta} = q$ for all the real replicas:
\begin{equation}\label{eq:D8}
    \bbE_J[Z_{p,r}] = \int d m d q \exp(N\left[ r(1-p)\frac{\beta^2}{2}m^p + \frac{r(r-1)}{2}(1-p)\beta^2q^p + \log \Tr \exp L \right]),
\end{equation}
with
\begin{equation}
    L = (p\frac{\beta^2}{2}m^{p-1}+\beta h)\sum_\alpha \sigma^\alpha + (p \beta^2q^{p-1} + \gamma)\sum_{\alpha<\beta}\sigma^\alpha\sigma^\beta.
\end{equation}
We can factorize with respect to the replica index:
\begin{equation}
    \bbE_J[Z_{p,r}] = \int d m d q \exp N \left[r(1-p)\frac{\beta^2}{2}m^p + \frac{r(r-1)}{2}(1-p)\beta^2 q^p + \log(\int D z (1+e^{H_z})^r) \right],
\end{equation}
with
\begin{equation}
    H_z = \beta h - \frac{\gamma}{2} + p\frac{\beta^2}{2}(m^{p-1}-q^{p-1}) + \sqrt{p\beta^2 q^{p-1}+\gamma}z = A + Bz.
\end{equation}
The saddle-point equations are 
\begin{equation}
\begin{aligned}
    m &= \frac{\int D z (1+\exp(H_z))^r l(H_z)}{\int D_z (1+\exp(H_z))^r} \\
    q &= \frac{\int D z (1+\exp(H_z))^r l^2(H_z)}{\int D_z (1+\exp(H_z))^r}.
\end{aligned}
\end{equation}
Noticing that 
\begin{equation}
    (1+\exp(H_z))^r = \sum_{k=0}^{r}\binom{r}{k}\exp(kH_z),
\end{equation}
we can write
\begin{equation}
\begin{aligned}
    &\int D z (1+\exp(H_z))^r = \sum_{k=0}^{r}\binom{r}{k}\exp(kA+\frac{1}{2}k^2B^2) \\
    &\int D z (1+\exp(H_z))^{r-1}\exp(H_z) = \sum_{k=1}^{r}\binom{r-1}{k-1}\exp(kA + \frac{1}{2}k^2B^2) \\
    &\int D z(1+\exp(H_z))^{r-2}\exp(H_z) = \sum_{k=2}^{p}\binom{r-2}{k-2}\exp(kA + \frac{1}{2}k^2B^2).
\end{aligned}
\end{equation}
We use the scalings:
\begin{equation}
\begin{aligned}
    \beta &= b\sqrt{m^{1-p}\log \frac{1}{m}} \\
    h &= \eta \sqrt{m^{p-1}\log \frac{1}{m}} \\
    \gamma &= g \log \frac{1}{m} + 2g_0 
\end{aligned}
\end{equation}
where we add a subleading term in $\gamma$ to ensure that $l\in(0,1)$, having parametrized $q=lm$. We have
\begin{equation}
\begin{aligned}
    A &= \left[ b\eta-\frac{g}{2} + p\frac{b^2}{2}(1-l^{p-1}) \right] \log\frac{1}{m} = -\mathcal{A}\log\frac{1}{m} \\
    B^2 &= \left[pb^2l^{p-1} + g \right]\log\frac{1}{m} + 2g_0 = -2\mathcal{B}\log\frac{1}{m} + 2g_0
\end{aligned}
\end{equation}
and the saddle-point equations are
\begin{equation}
\begin{aligned}
    m &= \frac{\sum_{k=1}^{r}\binom{r-1}{k-1}m^{f(k)}e^{g_0 k^2}}{\sum_{k=0}^{r}\binom{r}{k}m^{f(k)}} \\
    q&= \frac{\sum_{k=2}^{r}\binom{r-2}{k-2}m^{f(k)}e^{g_0 k^2}}{\sum_{k=0}^{r}\binom{r}{k}m^{f(k)}},
\end{aligned}
\end{equation}
with $f(k) = \mathcal{A}k + \mathcal{B}k^2$. As $f(0) = 0$, all other terms need to be of order $m$ or $o(m)$, therefore $f(k) \geq 1$ for all $k \geq 1$ and the denominator equals 1 in the limit. The SP equations reduce to
\begin{equation}
\begin{aligned}
    m &= \sum_{k=1}^{r}\binom{r-1}{k-1}m^{f(k)}e^{g_0 k^2} \\
    q &= \sum_{k=2}^{r}\binom{r-2}{k-2}m^{f(k)}e^{g_0 k^2},
\end{aligned}
\end{equation}
and each sum will be dominated by the term with the smallest $f(k)$. We first consider the case where $\mathcal{B} < 0$, as in this case $f(k)$ is concave down and is minimized on the border of the domain, i.e. $k=1,2$, $k=r$, or both, depending on conditions on $\mathcal{A}$ and $\mathcal{B}$ that we detail now. \\
For the $m$ equation:
\begin{itemize}
    \item $f(1) < f(r)$ if $\mathcal{A} > -(1+r)\mathcal{B}$, then $m^{f(1)}$ dominates,
    \item $f(1)=f(r)$ if $\mathcal{A} = -(1+r)\mathcal{B}$, then $m^{f(1)}$ and $m^{f(r)}$ both dominate,
    \item $f(1) > f(r)$ if $\mathcal{A} < -(1+r)\mathcal{B}$, then $m^{f(r)}$ dominates.
\end{itemize}
For the $q$ equation:
\begin{itemize}
    \item $f(2) < f(r)$ if $\mathcal{A} > -(2+r)\mathcal{B}$, then $m^{f(2)}$ dominates,
    \item $f(2) = f(r)$ if $\mathcal{A} = -(2+r)\mathcal{B}$, then $m^{f(2)}$ and $m^{f(r)}$ both dominate,
    \item $f(2) > f(r)$ if $\mathcal{A} < -(2+r)\mathcal{B}$, then $m^{f(r)}$ dominates.
\end{itemize}
Combining the cases and taking into account that $-(2+r)\mathcal{B} > -(1+r)\mathcal{B}$ as $\mathcal{B}< 0$, we have:
\begin{itemize}
    \item $\mathcal{A} < -(1+r)\mathcal{B}$, $m^{f(r)}$ dominates in both equations, implying that $l=1$. We discard this case as we want $l\in(0,1)$.
    \item $\mathcal{A} = -(1+r)\mathcal{B}$, the $m$ equation is dominated by $m^{f(1)}$ and $m^{f(r)}$ and the $q$ equation by $m^{f(r)}$. Imposing that $f(1) = f(p) = 1$ implies $\mathcal{A} = 1+1/p$ and $\mathcal{B} = -1/p$ which is consistent with the condition. We also have $1 = e^{g_0}+e^{p^2g_0}$ and $l=e^{p^2 g_0}$, leaving $l$ free to take any value in $(0,1)$ by tuning the subleading parameters.
    \item $\mathcal{A} > -(1+r)\mathcal{B}$, the $m$ equation imposes that only $f(1) = 1$ while the $q$ equation implies that another value of $k$ dominates, which is a contradiction.
\end{itemize}
Keeping the only valid option, we have $\mathcal{A} = 1+1/p$ and $\mathcal{B} = -1/p$, giving
\begin{equation}
    b\eta - \frac{g}{2} + p\frac{b^2}{2}(1-l^{p-1}) = -1-1/p, \quad pb^2l^{p-1} + g = 2/p, 
\end{equation}
that is
\begin{equation}
    b\eta = -1-p\frac{b^2}{2},\quad g = \frac{2}{r}-pb^2l^{p-1}.
\end{equation}
The free entropy density is obtained from \eqref{eq:D8}:
\begin{equation}
    \phi_{\mathrm{ann}}^{(p,r)} = (1-p)r\frac{\beta^2}{2}\left[ m^p + (r-1)q^p \right] + \log\Tr\exp L,
\end{equation}
where the $\log$ term is subleading in the small magnetization limit and can be dropped. We can obtain the entropy via a Legendre transform:
\begin{equation}
    s_{\mathrm{ann}}^{(p,r)} = \phi_{\mathrm{ann}}^{(p,r)} - r \beta e - r \beta h m - \frac{r(r-1)}{2}\gamma q,
\end{equation}
where the energy is $e=\beta(m^p+(r-1)q^p)$. In the limit, we have
\begin{equation}
\begin{aligned}
    \frac{s_{\mathrm{ann}}^{(p,r)}}{m\log\frac{1}{m}} &= (1-p)r\frac{b^2}{2}(1+(r-1)l^p)\\
    &- rb^2(1+(r-1)l^p) + r(1+p\frac{b^2}{2}) -\frac{r(r-1)}{2}(\frac{2}{r}-pb^2l^{p-1})l \\
    &= r - (r-1)l - r\frac{b^2}{2}(1+(r-1)l^p).
\end{aligned}
\end{equation}
The rescaled average can be obtained from the expression for the energy and is
\begin{equation}
    a = \sqrt{2} b(1+(r-1)l^p).
\end{equation}
We can therefore rewrite the entropy as
\begin{equation}
    \frac{s_{\mathrm{ann}}^{(p,r)}(a,l)}{m\log\frac{1}{m}} = r-(r-1)l - \frac{r}{4}\frac{a^2}{1+(r-1)l^p}.
\end{equation}


\section{Franz-Parisi analysis}
\label{app:FP}

To gain a more comprehensive understanding of the configuration space surrounding a typical configuration, we employ 
a free entropy landscape analysis. This approach constrains a spin configuration, the probe,  to maintain a fixed overlap with a 
reference configuration sampled from the Gibbs measure. The framework was originally introduced by Franz and
Parisi \cite{franz1995recipes} as a potential that characterizes meta-stable state structures in mean-field spin glasses. 
This potential provides a characterization of the free entropy associated with maintaining a system at given 
temperature while conditioning a fixed overlap with an equilibrium configuration sampled at a different temperature.
We should recall that in the MAS problem, there is a mapping between the average value of the submatrix and the temperature associated with the Gibbs measure.

To compute this potential, we introduce a field $\gamma$, that enforces a fixed overlap $\rho_{\rm ref} = q(\boldsymbol{\sigma}^{\mathrm{ref}},\boldsymbol{\sigma})  \overset{!}{=} q_{c}$ between a system probe  configuration $\boldsymbol{\sigma}$ and a quenched reference configuration $\boldsymbol{\sigma}^{\mathrm{ref}}$. Then we defined the Franz-Parisi partition function at fixed $\gamma$  as:
\begin{equation}
    Z_c(\beta,\,J,\,q_{\rm ref},\,\boldsymbol{\sigma}^{\rm ref}) = \sum_{\boldsymbol{\sigma}}e^{\beta E_J(\boldsymbol{\sigma}) + N\beta h m(\boldsymbol{\sigma}) + N\beta\beta_{\rm ref}\gamma q(\sigma_{\rm ref}, \sigma)}
\end{equation}


Therefore, the free entropy of the probe configuration $\boldsymbol{\sigma}$, the so-called Franz-Parisi potential, is:
\begin{equation}
          \Psi_{FP}:= \frac{1}{N} \mathbb{E}_{\boldsymbol{\sigma}^{\rm ref},J }\Bigg[ \log Z_c\Bigg] = \mathbb{E}_{J }\Bigg[\sum_{\boldsymbol{\sigma}^{\rm ref}}e^{\beta_{\rm ref}E(\boldsymbol{\sigma}^{\rm ref})+ N \beta_{\rm ref}h_{\rm ref}m(\boldsymbol{\sigma}^{\rm ref})} Z^{-1} \log Z_c\Bigg].\label{Eq. appx. FP definition}
\end{equation}
where the partition function of the Gibbs measure associated to the reference configuration at inverse temperature 
$\beta_{\rm ref}$ and magnetic field $h_{\rm ref}$ is
\begin{equation}
    Z(\beta_{\rm ref},J) = \sum_{\Bar{\boldsymbol{\sigma}}}e^{\beta_{\rm ref}E(\Bar{\boldsymbol{\sigma}})+ N \beta_{\rm ref}h_{\rm ref}m(\Bar{\boldsymbol{\sigma}})} .
\end{equation}
To compute the average with respect to the quenched variable, we make use of the replica trick, which allows us to 
bypass the difficulty of computing the expected value of the product of $Z^{-1}$ and the logarthm of the coupled 
partition function $Z_c$, in Eq.\eqref{Eq. appx. FP definition}. This is achieve by introducing $n'$ integer replicas 
of the reference system and $n$ integer replicas of the coupled system; to finally proceed to perform the analytical 
continuation of both functions:
\begin{equation}
    N\Psi_{FP} =\lim_{n,n'\to 0 } \mathbb{E}_J\left[\sum_{\boldsymbol{\sigma}^{\rm ref}}e^{\beta_{\rm ref}E(\boldsymbol{\sigma}^{\rm ref})+ N \beta_{\rm ref}h_{\rm ref}m(\boldsymbol{\sigma}^{\rm ref})} Z^{n'-1}\left(\frac{Z_c^n-1}{n}\right)\right].
\end{equation}
The replicated partition functions are
\begin{equation}
    Z_c^n = \sum_{\alpha}\sum_{\boldsymbol{\sigma}^\alpha}e^{\beta \sum_{\alpha}E(\boldsymbol{\sigma}^\alpha)+N\beta h \sum_{\alpha}m(\boldsymbol{\sigma}^\alpha)  + N\beta\beta_{\rm ref}\gamma q(\sigma_{\rm ref}, \sigma^\alpha)},
\end{equation}
\begin{equation}
    Z^{n'-1} = \sum_{a}\sum_{\Bar{\boldsymbol{\sigma}}^a}e^{\beta_{\rm ref} \sum_{\alpha}E(\Bar{\boldsymbol{\sigma}}^a)+N\beta_{\rm ref} h_{\rm ref} \sum_{a}m(\Bar{\boldsymbol{\sigma}}^a) }.
\end{equation}
Here we use the upper indices $\alpha\in[n]$ and $a\in[n'-1]$ to indicate the replica of the system, and the lower 
indices $i\in\mathcal{N}$ to indicate the sites.

We introduce the replicated partition function of the FP potential, which is the central object of interest for its 
computation:
\begin{equation}
    Z^{(n',n)} = \sum_{\boldsymbol{\sigma}^{\rm ref}}e^{\beta_{\rm ref}E(\boldsymbol{\sigma}^{\rm ref})+ N \beta_{\rm ref}h_{\rm ref}m(\boldsymbol{\sigma}^{\rm ref})} Z^{n'-1}Z^n
\end{equation}
\subsection{Average of the replicated partition function}

The explicit form of the replicated partition function is 
\begin{equation}
    \begin{split}
    Z^{(n',n)} &=\sum_{\boldsymbol{\sigma}^{\rm ref}} \Bigg\{ \exp\left( \frac{\beta_{\rm ref}}{\sqrt{N}}\sum_{i<j}J_{ij}\sigma^{\rm ref}_i\sigma^{\rm ref}_j 
    + \beta_{\rm ref} h_{\rm ref}\sum_{i}\sigma^{\rm ref}_i\right) \\
    &\cdot \Tr_{\left\{\Bar{\boldsymbol{\sigma}}^{a}\right\}_{a=1}^{n'-1}}\exp\left( 
     \frac{\beta_{\rm ref}}{\sqrt{N}}\sum_{i<j}J_{ij}\sum_{a=1}^{n'-1}\Bar{\sigma}_i^a\Bar{\sigma}_j^a 
     + \beta_{\rm ref} h_{\rm ref}\sum_{i}\sum_{a=1}^{n'-1}\Bar{\sigma}_i^a
     \right) \\
     &\cdot  \Tr_{\{\boldsymbol{\sigma}^{\alpha}\}_{\alpha=1}^n} \exp\left( \frac{\beta}{\sqrt{N}}\sum_{i<j}J_{ij}\sum_{\alpha=1}^n\sigma_i^{\alpha}\sigma_j^{\alpha} 
          + \beta h\sum_{i}\sum_{\alpha=1}^n\sigma_i^{\alpha} + \beta\beta_{\rm ref}\gamma\sum_i\sum_{\alpha=1}^n \sigma_i^{\rm ref}\sigma_i^{\alpha}\right)\Bigg\}
    \end{split}
\end{equation}
Notice that the sum over $\boldsymbol{\sigma}^{\rm ref}$ is equivalent to add an extra replica to the $(n'-1)$th power of the partition function $Z$; consequently, we can trace over $n'$ different replicas in the second line of the previous equation, but constraining only the replica $\Bar{\boldsymbol{\sigma}}^1$ to have a fixed overlap with $\boldsymbol{\sigma}^\alpha$. Then, we can rewrite the replicated partition function as:
\begin{equation}
    \begin{split}
         Z^{(n',n)} &=\sum_{\{\Bar{\boldsymbol{\sigma}}^a,\boldsymbol{\sigma}^\alpha\}} \exp\left[\sum_{i<j}\frac{J_{ij}}{\sqrt{N}}\left(\beta_{\rm ref}\sum_a\Bar{\sigma}^a_i\Bar{\sigma}_j^a + \beta\sum_\alpha\sigma_i^{\alpha}\sigma_j^{\alpha}\right) + \beta_{\rm ref}h_{\rm ref}\sum_{i,a}\Bar{\sigma}_i^a + \beta h\sum_{i,\alpha}\sigma^\alpha \right.\\
         &\hspace{30em}+ \beta\beta_{\rm ref}\gamma\sum_{i,\alpha} \sigma_i^{\rm ref}\sigma_i^{\alpha}\Bigg]    
    \end{split}
\end{equation}
where now $a\in[n']$ and $\alpha\in[n]$.

Following the prescription of the replica method, after taking the expectation value with respect to $J_{ij}$, we have:
\begin{equation}
\begin{split}
        \mathbb{E}_J\left[Z^{(n',n)}\right] &= \sum_{\Bar{\{\boldsymbol{\sigma}}^a\boldsymbol{\sigma}^{\alpha}\}}\exp\Bigg[\frac{1}{2N}\sum_{i<j}\left(\beta_{\rm ref}\sum_a\Bar{\sigma}^a_i\Bar{\sigma}_j^a + \beta\sum_\alpha\sigma_i^{\alpha}\sigma_j^{\alpha}\right)^2 + \\
        &\hspace{5em}\sum_i\left(\beta_{\rm ref}h_{\rm ref}\sum_a\Bar{\sigma}^a_i + \beta h\sum_{\alpha}\sigma_i^{\alpha}+\beta\beta_{\rm ref}\gamma\sum_{\alpha} \sigma_i^{\rm ref}\sigma_i^{\alpha}\right)\Bigg]
\end{split}
\end{equation}
We conveniently reorganize the replicated partition function as
\begin{equation}
\begin{split}
        \mathbb{E}[Z^{(n',n)}] = \sum_{\Bar{\{\boldsymbol{\sigma}}^a\boldsymbol{\sigma}^{\alpha}\}}\exp\Bigg[&\frac{\beta^2}{4N}\sum_{\alpha}\Big(\sum_i\sigma_i^\alpha\Big)^2 + \frac{\beta^2}{2N}\sum_{\alpha<\beta}\Big(\sum_i\sigma_i^\alpha\sigma_i^\beta\Big)^2 + \beta h\sum_\alpha\Big(\sum_i\sigma_i^\alpha\Big) \\
        +&\frac{(\beta_{\rm ref})^2}{4N}\sum_a\Big(\sum_i\Bar{\sigma}_i^a\Big)^2 + \frac{(\beta_{\rm ref})^2}{2N}\sum_{a<b}\Big(\sum_i\Bar{\sigma}_i^a\Bar{\sigma}_i^b\Big)^2 + \beta_{\rm ref}h_{\rm ref}\sum_a\Big(\sum_i\Bar{\sigma}_i^a\Big)\\
        +&\frac{\beta\beta_{\rm ref}}{2N}\sum_{a,\alpha}\Big(\sum_i\Bar{\sigma}^a\sigma^\alpha\Big)^2 + \beta\beta_{\rm ref}\gamma\sum_\alpha\sum_i\Bar{\sigma}^1\sigma_i^\alpha  \Bigg]
\end{split}
\end{equation}
Here, we  expressed each Dirac delta function in terms of its Fourier transform to extract the terms within the constraints. In this form, we identify five squared terms per replica, each of which can be linearized using a Hubbard-Stratonovich transformation. This transformation naturally introduces the usual overlaps, $m_\alpha$ and $q_{\alpha,\beta}$, for the constrained system, as well as the overlaps, $m^{\rm ref}_a$ and $q_{a,b}^{\rm ref}$ for the reference systems. Additionally, it introduces the overlap $\rho_{a,\alpha}$, which indicates the overlap between the replicas of the constrained system and the reference one. Thus the replicated partition function can be written as:
\begin{equation}
    \begin{split}
         &\mathbb{E}[Z^{(n',n)}] = \int\prod_\alpha \mathrm{d}m_\alpha \prod_{\alpha<\beta}\mathrm{d}q_{\alpha,\beta}\prod_a\mathrm{d}m_a^{\rm ref}\prod_{a<b}\mathrm{d}q_{a,b}^{\rm ref}\prod_{a,\alpha}\mathrm{d}p_{a,\alpha}\\
         &\cdot\exp\Bigg(-\frac{N\beta^2}{4}\sum_{\alpha}m_\alpha^2 + \frac{\beta^2}{2}\sum_{\alpha}m_\alpha\sum_i\sigma_i^\alpha - \frac{N\beta^2}{2}\sum_{\alpha<\beta}q_{\alpha,\beta}^2 + \beta^2\sum_{\alpha<\beta}q_{\alpha,\beta}\sum_i\sigma_i^\alpha\sigma_i^\beta\Bigg) \\
         &\cdot\exp\Bigg(-\frac{N(\beta_{\rm ref})^2}{4}\sum_{a}(m_a^{\rm ref})^2 + \frac{(\beta_{\rm ref})^2}{2}\sum_{a}m_a^{\rm ref}\sum_i\Bar{\sigma_i}^a - \frac{N(\beta_{\rm ref})^2}{2}\sum_{a<b}(q_{a,b}^{\rm ref})^2 + (\beta_{\rm ref})^2\sum_{a<b}q_{a,b}^{\rm ref}\sum_i\sigma_i^a\sigma_i^b\Bigg) \\
         &\cdot\exp\Bigg(-\frac{N\beta\beta_{\rm ref}}{2}\sum_{a,\alpha}\rho_{a,\alpha} + \beta\beta_{\rm ref}\sum_{a,\alpha}\sum_i\Bar{\sigma}_i^a\sigma_i^\alpha + h_{\rm ref}\beta_{\rm ref}\sum_a\sum_i\Bar{\sigma}^a\Bigg)\\
         &\cdot\exp\Bigg(\beta\sum_\alpha \sum_i(h+\beta_{\rm ref}\gamma \Bar{\sigma}^1_i)\sigma_i^\alpha  + \caO(\log N) \Bigg)
    \end{split}
\end{equation}

After tracing over each independent site $i$, the expression becomes
\begin{equation}
    \begin{split}
        \mathbb{E}&[Z^{(n',n)}] = \int\prod_\alpha \mathrm{d}m_\alpha\prod_{\alpha<\beta}\mathrm{d}q_{\alpha,\beta}\prod_a\mathrm{d}m_a^{\rm ref}\prod_{a<b}\mathrm{d}q_{a,b}^{\rm ref}\prod_{a,\alpha}\mathrm{d}p_{a,\alpha}\\
        & \cdot \exp\Bigg(-\frac{\beta^2}{4}\sum_{\alpha}m_\alpha^2 - \frac{\beta^2}{2}\sum_{\alpha<\beta}q_{\alpha,\beta}^2 - \frac{(\beta_{\rm ref})^2}{4}\sum_{a}(m_a^{\rm ref})^2 - \frac{(\beta_{\rm ref})^2}{2}\sum_{a<b}(q_{a,b}^{\rm ref})^2 -\frac{\beta\beta_{\rm ref}}{2}\sum_{a,\alpha}p_{a,\alpha}^2 \Bigg)^N\\
        &\cdot\exp\Bigg(N\log(\psi_e) \Bigg)
    \end{split}
\end{equation}
where we had defined
\begin{equation}
\begin{split}
    \psi_s &:=\Tr_{\{\Bar{\sigma}^a,\sigma^\alpha\}}\exp\Bigg( \frac{\beta^2}{2}\sum_\alpha m_\alpha\sigma^\alpha  +\beta^2\sum_{\alpha<\beta}q_{\alpha, \beta}\sigma^\alpha\sigma^\beta + \beta\sum_{\alpha}(h+\beta_{\rm ref}\Bar{\sigma}^1\gamma)\sigma^\alpha \\
    &+\frac{(\beta_{\rm ref})^2}{2}\sum_a m_a^{\rm ref}\Bar{\sigma}^a + (\beta_{\rm ref})^2\sum_{a<b}q_{a,b}^{\rm ref}\Bar{\sigma}^a\Bar{\sigma}^b + \beta_{\rm ref}h_{\rm ref}\sum_a\Bar{\sigma}^a + \beta\beta_{\rm ref}\sum_{a,\alpha}\rho_{a,\alpha}\Bar{\sigma}^a\sigma^\alpha\Bigg)
\end{split}
\end{equation}

We use the replica symmetry assumption to study the Franz-Parisi potential, given our interest in the frozen 1-RSB phase where the Parisi parameter is equal to one, which makes the free entropy well described by the replica symmetric solution. However, we recall that the 1-RSB assumption and the Parisi parameter also allow us to compute the number of typical clusters in the system, as explained in \cite{Erba_2024}. Therefore, after imposing the RS ansatz for the overlap matrices and taking the limits  $n',n\to0$ as prescribed by the replica trick:

\begin{equation}
    \Psi_{FP} = \Psi_{s} + \Psi_e 
\end{equation}
where we define the RS energetic potential
\begin{equation}
        \Psi_e = -\frac{\beta^2}{4}(m^2-q^2)  - \frac{\beta\beta_{\rm ref}}{2}(\rho_{\rm ref}^2- \rho^2 ) 
\end{equation}


And the entropic potential
\begin{equation}
    \begin{split}
                \Psi_s &= \lim_{n',n\to0}\frac{1}{n}\log\Big(\psi_s\Big) = \lim_{n'\to 0}(\partial_{n}\psi_s|_{n=0}  + n'\partial_{n'}\psi_s|_{n=0})\\
               \psi_s &=  \Tr_{\{\Bar{\sigma}^a,\sigma^\alpha\}}\exp\Bigg( \frac{\beta^2(m-q)}{2}\sum_\alpha \sigma^\alpha  + \frac{\beta^2 q}{2}\left(\sum_{\alpha}\sigma^\alpha\right)^2 + (h+\beta_{\rm ref}\Bar{\sigma}^1\gamma) \beta\sum_{\alpha}\sigma^\alpha \\
    &\hspace{2em}+\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2}\sum_a \Bar{\sigma}^a +\frac{(\beta_{\rm ref})^2q_{\rm ref}}{2}\left(\sum_{a}\Bar{\sigma}^a\right)^2 + \beta_{\rm ref}h_{\rm ref}\sum_a\Bar{\sigma}^a + \beta\beta_{\rm ref}\rho_{\rm ref}\sum_{\alpha}\Bar{\sigma}^1\sigma^{\alpha}\notag\\
    &\hspace{2em}+ \beta\beta_{\rm ref}\rho\sum_{a\neq1,\alpha}\Bar{\sigma}^a\sigma^\alpha\Bigg)
    \end{split}
\end{equation}

To compute the trace over each replica, we need the replicas to be decoupled; that is, the exponent must be linear in each replicated spin $\sigma^\alpha$ and $\Bar{\sigma}^a$. To achieve this, we use a  similar algebraical trick to the one employed to linearize the replicas of the same system, which allows us to apply a Hubbard-Stratonovich transformation.
\begin{equation}
    \begin{split}
        \sum_{a\neq1,\alpha}\Bar{\sigma}^a\sigma^\alpha &= - \sum_{\alpha}\Bar{\sigma}^1\sigma^\alpha + \sum_{a,\alpha}\Bar{\sigma}^a\sigma^\alpha\\
        &=- \sum_{\alpha}\Bar{\sigma}^1\sigma^\alpha + \frac{1}{2}\left(\sum_a\Bar{\sigma}^a + \sum_{\alpha}\sigma^\alpha\right)^2 - \frac{1}{2}\left(\sum_{a}\Bar{\sigma}^{a}\right)^2 - \frac{1}{2}\left(\sum_{\alpha}\sigma^\alpha\right)^2
    \end{split}
\end{equation}
Applying this transformation on the entropic potential, we obtain
\begin{equation}
    \begin{split}
        \psi_s &=  \Tr_{\{\Bar{\sigma}^a,\sigma^\alpha\}}\exp\Bigg( \frac{\beta^2(m-q)}{2}\sum_\alpha \sigma^\alpha  + \frac{\beta^2 q-\beta\beta_{\rm ref}\rho}{2}\Big(\sum_{\alpha}\sigma^\alpha\Big)^2 + (h+\beta_{\rm ref}\Bar{\sigma}^1\gamma) \beta\sum_{\alpha}\sigma^\alpha \\
        &+\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2}\sum_a \Bar{\sigma}^a +\frac{(\beta_{\rm ref})^2q_{\rm ref}-\beta\beta_{\rm ref}\rho}{2}\Big(\sum_{a}\Bar{\sigma}^a\Big)^2 + \beta_{\rm ref}h'\sum_a\Bar{\sigma}^a \\
        &\hspace{2em}+ \beta\beta_{\rm ref}(\rho_{\rm ref}-\rho)\sum_{\alpha}\Bar{\sigma}^1\sigma^{\alpha} + \frac{\beta\beta_{\rm ref}\rho}{2}\Big(\sum_a\Bar{\sigma}^a + \sum_{\alpha}\sigma^\alpha\Big)^2\Bigg)^2\\
    &= \Tr_{\{\Bar{\sigma}^a,\sigma^\alpha\}}\int\mathrm{D}x_1\mathrm{D}x_2\mathrm{D}x_3 \exp\Bigg( \frac{\beta^2(m-q)}{2}\sum_\alpha \sigma^\alpha  + x_1\sqrt{\beta^2 q-\beta\beta_{\rm ref}\rho}\sum_{\alpha}\sigma^\alpha + (h+\beta_{\rm ref}\Bar{\sigma}^1\gamma) \beta\sum_{\alpha}\sigma^\alpha \\
    &+\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2}\sum_a \Bar{\sigma}^a +x_2\sqrt{(\beta_{\rm ref})^2q_{\rm ref}-\beta\beta_{\rm ref}\rho}\sum_{a}\Bar{\sigma}^a + \beta_{\rm ref}h_{\rm ref}\sum_a\Bar{\sigma}^a + \beta\beta_{\rm ref}(\rho_{\rm ref}-\rho)\sum_{\alpha}\Bar{\sigma}^1\sigma^{\alpha}\\
    &+x_3\sqrt{\beta\beta_{\rm ref}\rho}\Big(\sum_a\Bar{\sigma}^a + \sum_{\alpha}\sigma^\alpha\Big)\Bigg)
    \end{split}
\end{equation}
We reorder the trace terms by isolating those proportional to $\Bar{\sigma}^1$, for which we will take the trace after \textit{tracing} over the rest of the replicas.
\begin{equation}
    \begin{split}
        \psi_s &= \Tr_{ \Bar{\sigma}^1 } \int\mathrm{D}x_1\mathrm{D}x_2\mathrm{D}x_3 \exp\Bigg(\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2} \Bar{\sigma}^1 +x_2\sqrt{(\beta_{\rm ref})^2q_{\rm ref}-\beta\beta_{\rm ref}\rho}\Bar{\sigma}^1 + (\beta_{\rm ref}h_{\rm ref}+x_3\sqrt{\beta\beta_{\rm ref}\rho})\Bar{\sigma}^1 \Bigg)\\
        &\cdot\left[\Tr_{\sigma^\alpha}\exp\Bigg( \frac{\beta^2(m-q)}{2} \sigma^\alpha  + x_1\sqrt{\beta^2 q-\beta\beta_{\rm ref}\rho}\sigma^\alpha + (\beta h + \beta\beta_{\rm ref}\Bar{\sigma}^1\gamma+x_3\sqrt{\beta\beta_{\rm ref}\rho})\sigma^\alpha + \beta\beta_{\rm ref}(\rho_{\rm ref}-\rho)\Bar{\sigma}^1\sigma^{\alpha}\Bigg)\right]^n \\
    &\cdot\left[\Tr_{\Bar{\sigma}^a}\exp\Bigg(\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2} \Bar{\sigma}^a +x_2\sqrt{(\beta_{\rm ref})^2q_{\rm ref}-\beta\beta_{\rm ref}\rho}\Bar{\sigma}^a + (\beta_{\rm ref}h_{\rm ref}+x_3\sqrt{\beta\beta_{\rm ref}\rho})\Bar{\sigma}^a \right]^{n'-1}
    \end{split}
\end{equation}


\begin{equation}
    \begin{split}
        \psi_s &= \Tr_{ \Bar{\sigma}^1 } \int\mathrm{D}x_1\mathrm{D}x_2\mathrm{D}x_3 \exp\Bigg(\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2} \Bar{\sigma}^1 +x_2\sqrt{(\beta_{\rm ref})^2q_{\rm ref}-\beta\beta_{\rm ref}\rho}\Bar{\sigma}^1 + (\beta_{\rm ref}h_{\rm ref}+x_3\sqrt{\beta\beta_{\rm ref}\rho})\Bar{\sigma}^1 \Bigg)\\
        &\cdot\exp\left[n\logpexp \Bigg( \frac{\beta^2(m-q)}{2}  + x_1\sqrt{\beta^2 q-\beta\beta_{\rm ref}\rho} + (\beta h + \beta\beta_{\rm ref}\Bar{\sigma}^1\gamma+x_3\sqrt{\beta\beta_{\rm ref}\rho}) + \beta\beta_{\rm ref}(\rho_{\rm ref}-\rho)\Bar{\sigma}^1\Bigg)\right] \\
    &\cdot\exp\left[(n'-1)\logpexp \Bigg(\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2}  +x_2\sqrt{(\beta_{\rm ref})^2q_{\rm ref}-\beta\beta_{\rm ref}\rho} + (\beta_{\rm ref}h_{\rm ref}+x_3\sqrt{\beta\beta_{\rm ref}\rho}) \right]
    \end{split}
\end{equation}

To simplify the integrals, let's consider the following unitary transformations:
\begin{equation}
    \begin{split}
        &\begin{pmatrix}
            y_2 \\ y_3 
        \end{pmatrix} = 
        \frac{1}{\beta_{\rm ref}\sqrt{q_{\rm ref}}}\begin{pmatrix}
            \sqrt{(\beta_{\rm ref})^2q_{\rm ref}-\beta\beta_{\rm ref}\rho} & \sqrt{\beta\beta_{\rm ref}\rho}\\
            -\sqrt{\beta\beta_{\rm ref}\rho} & \sqrt{(\beta_{\rm ref})^2q_{\rm ref}-\beta\beta_{\rm ref}\rho}
        \end{pmatrix}
        \begin{pmatrix}
            x_2 \\ x_3
        \end{pmatrix} \\
        & \implies x_3\sqrt{\beta\beta_{\rm ref}\rho} = y_2\frac{\beta\rho}{\sqrt{q_{\rm ref}}} + y_3\sqrt{\frac{\beta\beta_{\rm ref} q_{\rm ref}\rho - \beta^2\rho^2}{q_{\rm ref}}}
    \end{split}
\end{equation}
then
\begin{equation}
    \begin{split}
        \psi_s &= \Tr_{ \Bar{\sigma}^1 } \int\mathrm{D}y_1\mathrm{D}x_2\mathrm{D}y_3 \exp\Bigg(\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2} + \beta_{\rm ref}h_{\rm ref}+ y_2\beta_{\rm ref}\sqrt{q_{\rm ref}} \Bigg)^{\Bar{\sigma}^1 }\\
        &\cdot\exp\Bigg[n\logpexp \Bigg( \frac{\beta^2(m-q)}{2}  + \beta h + \beta\beta_{\rm ref}\Bar{\sigma}^1\gamma + \beta\beta_{\rm ref}(\rho_{\rm ref}-\rho)\Bar{\sigma}^1 \\&\hspace{5em}+x_1\sqrt{\beta^2q-\beta\beta_{\rm ref}\rho} +y_2\frac{\beta\rho}{\sqrt{q_{\rm ref}}} + y_3\sqrt{\frac{\beta\beta_{\rm ref} q_{\rm ref}\rho - \beta^2\rho^2}{q_{\rm ref}}}\Bigg)  \Bigg] \\
    &\cdot\exp\left[(n'-1)\logpexp \Bigg(\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2}  + \beta_{\rm ref}h_{\rm ref}+ y_2\beta_{\rm ref}\sqrt{q_{\rm ref}}\Bigg) \right]
    \end{split}
\end{equation}

and one extra unitary transformation:
\begin{equation}
    \begin{pmatrix}
        y_1\\y_3'
    \end{pmatrix} = \frac{1}{\beta\sqrt{(q - \rho^2/q_{\rm ref})}}
    \begin{pmatrix}
      \sqrt{\beta^2q-\beta\beta_{\rm ref}\rho} &\sqrt{\frac{\beta\beta_{\rm ref} q_{\rm ref}\rho - \beta^2\rho^2}{q_{\rm ref}}}\\
        -\sqrt{\frac{\beta\beta_{\rm ref} q_{\rm ref}\rho - \beta^2\rho^2}{q_{\rm ref}}} & \sqrt{\beta^2q-\beta\beta_{\rm ref}\rho}
    \end{pmatrix}
    \begin{pmatrix}
        x_2\\ y_3
    \end{pmatrix}
\end{equation}
We manage to reduce the number of gaussian integrals:
\begin{equation}
    \begin{split}
        \psi_s &= \Tr_{ \Bar{\sigma}^1 } \int\mathrm{D}y_1\mathrm{D}y_2 \exp\Bigg(\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2} + \beta_{\rm ref}h_{\rm ref}+ y_2\beta_{\rm ref}\sqrt{q_{\rm ref}} \Bigg)^{\Bar{\sigma}^1 }\\
        &\cdot\exp\left[n\logpexp \Bigg( \frac{\beta^2(m-q)}{2}  + \beta h + \beta\beta_{\rm ref}\Bar{\sigma}^1\gamma + \beta\beta_{\rm ref}(\rho_{\rm ref}-\rho)\Bar{\sigma}^1 +y_1\beta\sqrt{q - \rho^2/q_{\rm ref}} + y_2\beta\rho/\sqrt{q_{\rm ref}}\Bigg)  \right] \\
    &\cdot\exp\left[(n'-1)\logpexp \Bigg(\frac{(\beta_{\rm ref})^2(m_{\rm ref}-q_{\rm ref}) }{2}  + \beta_{\rm ref}h_{\rm ref}+ y_2\beta_{\rm ref}\sqrt{q_{\rm ref}}\Bigg) \right]
    \end{split}
\end{equation}


After taking the replica limit
\begin{equation}
\begin{split}
        \Psi_s &= \int\mathrm{D}y_1\mathrm{D}y_2\ell\Big(-\beta_{\rm ref}H_{\rm RS}^{\rm ref}(y_2)\Big)\logpexp\Big(\beta H_C(y_1,y_2)\Big)\\
        &+ \int\mathrm{D}y_1\mathrm{D}y_2\ell\Big(\beta_{\rm ref}H_{\rm RS}^{\rm ref}(y_2)\Big)\logpexp\Big(\beta H_C(y_1,y_2) + \beta\beta_{\rm ref}(\gamma+\rho_{\rm ref} -\rho)\Big)
\end{split}
\end{equation}
where
\begin{equation}
    H_{\rm RS}^{\rm ref}(y_2) = \frac{\beta_{\rm ref}}{2}(m_{\rm ref}-q_{\rm ref}) + h_{\rm ref} + y_2\sqrt{q_{\rm ref}}
\end{equation}
\begin{equation}
    H_C(y_1,y_2) = \frac{\beta}{2}(m-q) + h + y_1\sqrt{q-\rho^2/q_{\rm ref}} + y_2\rho/\sqrt{q_{\rm ref}}
\end{equation}

Finally, we obtain the free entropy of the probe system at fixed $h$:
\begin{equation}
\begin{split}
    \Psi_{FP} &= \Psi_e + \Psi_s\\
    \Psi_e &= -\frac{\beta^2}{4}(m^2-q^2)  - \frac{\beta\beta_{\rm ref}}{2}(\rho_{\rm ref}^2- \rho^2 ) \\
    \Psi_s &=\int\mathrm{D}y_1\mathrm{D}y_2\,\ell\Big(-\beta_{\rm ref}H_{\rm RS}^{\rm ref}(y_2)\Big)\logpexp\Big(\beta H_C(y_1,y_2)\Big)\\
        &+ \int\mathrm{D}y_1\mathrm{D}y_2\,\ell\Big(\beta_{\rm ref}H_{\rm RS}^{\rm ref}(y_2)\Big)\logpexp\Big(\beta H_C(y_1,y_2) + \beta\beta_{\rm ref}(\gamma+\rho_{\rm ref} -\rho)\Big)
\end{split}
\end{equation}
Then the Franz-Parisi potential which is defined as the  free entropy of the probe system at fixed magnetization $m$ and overlap with the reference system $\rho \overset{!}{=} q_{c}$, it is provided by the Legendre transform:
\begin{equation}
    \Phi_{FP} = \Psi_{FP}(m,m_{\rm ref},\beta,\beta_{\rm ref}) -  \beta h m - \beta\beta_{\rm ref}\gamma q_c
\end{equation}

\subsection{Saddle-point equations}
Before computing the SP, we recall that the reference configuration is sampled independently from the Gibbs measure. Consequently, the typical values of the order parameters,  $q_{\rm ref}=q_{RS}$ and $h' = h_{RS}$, correspond to the  values that extremize the RS variational free entropy. 
This result can be recovered by taking the limit $n\to0$ and extremizing with respect to $q_{\rm ref}$ and $m_{\rm ref}$  the terms proportional to $n'$, being $n'$ non-zero. From this, we obtain the variational free entropy of the reference configuration at equilibrium, along with the corresponding saddle-point equations:
\begin{equation}
    \begin{split}
    m_{\rm ref} & = \int\mathrm{D}y \ell(\beta_{\rm ref}H^{\rm ref}_{\rm RS}(y))\\
    q_{\rm ref} & = \int\mathrm{D}y \ell^2(\beta_{\rm ref}H^{\rm ref}_{\rm RS}(y))
    \end{split}\label{eq. appx - reference sp equations}
\end{equation}
Then we only need to solve the SP - equations  for the constrained system : 
\begin{equation}
    \begin{split}
          \rho &=  \int\mathrm{D}y_1\mathrm{D}y_2\,\biggl[
    \ell(\beta_{\rm ref} H^{\rm ref}_{\rm RS})\ell(\beta H_C) 
    - \ell^2(\beta_{\rm ref} H_{\rm RS}^{\rm ref}) 
    \left[ \ell(\beta H_C) - \ell(\beta H_C+\beta\beta_{\rm ref}(\gamma +\rho_{\rm ref}-\rho)) \right]
    \biggr]\\
   m &= \int\mathrm{D}y_1\mathrm{D}y_2\biggl[
    \ell(\beta H_C)
    - \ell(\beta_{\rm ref} H_{\rm RS}^{\rm ref}) 
    \left[ \ell(\beta H_C) - \ell(\beta H_C+\beta\beta_{\rm ref}(\gamma +\rho_{\rm ref}-\rho)) \right]
    \biggr]\\
     q &= \int\mathrm{D}y_1\mathrm{D}y_2\biggl[
     \ell^2(\beta H_C)
     - \ell(\beta_{\rm ref} H_{\rm RS}^{\rm ref}) 
    \left[ \ell^2(\beta H_C) - \ell^2(\beta H_C+\beta\beta_{\rm ref}(\gamma + \rho_{\rm ref}-\rho)) \right]\biggr]\\
    \rho_{\mathrm{ref}} &=  \int \mathrm{D}x_1\,\mathrm{D}x_2\,\ell(\beta_{\rm ref}H_{\rm RS}^{\rm ref})\ell\left(\beta H_C + \beta\beta_{\rm ref}(\gamma +\rho_{\rm ref}-\rho)\right)
    \end{split}\label{Eq. appx SP Eq. FP}
\end{equation}

\subsection{The small magnetization limit --  Saddle point equations }



We now turn of attention to the study of te FP potential in the limit where $m_{\rm ref}=m\to 0$, which corresponds to the regime where $k\ll N$. By using the same combinatorial argument to re-scale the temperature and thus the energy of the system, comparable to the entropy; we impose the leading order terms for the following parameters:
\begin{equation}
    \begin{aligned}[c]
        \beta_{\rm ref} &= b_{\rm ref}\sqrt{\frac{1}{m}\log\frac{1}{m}} \\
        q_{\rm ref} &= m^2\\
        h_{\rm ref} &= -\eta_{\rm ref}\sqrt{m\log\frac{1}{m}}
    \end{aligned}
    \hspace{5em}
     \begin{aligned}[c]
        \beta &= b\sqrt{\left(\log\frac{1}{m}\right)\frac{1}{m}} \\
        q & = r^2m \\
        h &= -\eta\sqrt{m\left(\log\frac{1}{m}\right)} 
    \end{aligned}
\end{equation}
With this scaling, we see that the dependency on $y_1$ in $H_{\rm RS}^{\rm ref}(y_1)$ and $H_C(y_1,y_2)$ drops, and from the SP equations of the reference system \eqref{eq. appx - reference sp equations}, we have
\begin{equation}
\begin{split}
    m &= \ell(\beta_{\rm ref}H_{\rm RS}^{\rm ref})\\
    \implies \eta_{\rm ref} &= -\frac{1}{2}\left(\frac{1}{b_{\rm ref}} + \frac{b_{\rm ref}}{2}\right)
\end{split}
\end{equation}
The SP equation \eqref{Eq. appx SP Eq. FP} of the overlap $\rho$ between replica of the reference system and the probe becomes:

\begin{equation}
        \rho = \ell(\beta_{\rm ref}H_{\rm RS}^{\rm ref})\underbrace{ \int\mathrm{D}y_1\mathrm{D}y_2\,\biggl[
    \ell(\beta H_C)
    - \ell(\beta_{\rm ref} H_{RS}) 
    \left[ \ell(\beta H_C) - \ell(\beta H_C+\beta\beta_{\rm ref}(\gamma +\rho_{\rm ref}-\rho)) \right]
    \biggr]}_{= m, \text{ from SP \eqref{Eq. appx SP Eq. FP} w.r.t. }m}\implies \rho=m^2
\end{equation}

Additionally, we propose the scaling $\rho_{\rm ref} \overset{!}{=} q_{\rm ref}= m c$, where $0\leq c\leq 1$, and $\gamma = m \nu$. Then, in the limit $m\to 0$, the set of saddle point equations for the FP potential are
\begin{equation}
    \begin{split}
        m &= \int\mathrm{D}v\, \ell(\beta H_C) + cm\\
        r^2m&= \int\mathrm{D}v\, \ell^2(\beta H_C) + m\int\mathrm{D}v\,\ell^2(\beta H_C + \beta\beta_{\rm ref}(\gamma +q_{\rm ref}))\\
        c &= \int\mathrm{D}v\ell(\beta H_C + \beta\beta_{\rm ref}(\gamma + q_{\rm ref}))
    \end{split}
\end{equation}
where \begin{equation}
    H_C(v) = h + \frac{\beta}{2}(m - q) + v\sqrt{q}
\end{equation}
Note that we have retained only the terms of order  $\caO(m)$  in the Taylor series expansion, so the equations should be understood as equal only to leading order. We have three equations for the three parameters $\eta$, $r$ and $\nu$, while the remaining variables  $c$, $b$ and $b_{\rm ref}$ serve as control parameters.

As mentioned in section \ref{Subsec - Statistical mechanics framework}, given the symmetry of the distribution of the matrix $J$, the inverse temperature $\beta$ can be negative, and so $b$. However, the asymptotic expansion we have are always for positive $\beta$, since the two cases can be mapped one onto each other by simply performing the change of variables $v\mapsto-v$ in the Gaussian integral and $h\mapsto -h$. The case $b=0$ will be treated separately. Similar as it was done before, it is convenient to write the auxiliary term $\beta H_C(v)=AN +B\sqrt{N}$ to asymptotically compute the integrals of the saddle-point equations. Thus, in the scaling limit we we have:
\begin{equation}
    \begin{split}
        A &= -b\eta + \frac{b^2}{2}(1-r^2)\\
        B &= b r\\
        C &= bb_{\rm ref} (c+ \nu)\\
        N &= \log\frac{1}{m}
    \end{split}
\end{equation}
The saddle-point equations are
\begin{equation}
   \begin{split}
    (1-c)m &= I_1(A,B)\\
    c &= I_1(A+C ,B)\\
    r^2 m &= I_2(A,B) +mI_2(A+C,B) 
    \end{split}
\end{equation}
and the rescaled Franz-Parisi potential is
\begin{equation}
\begin{split}
        \phi_{\rm FP} &:= \frac{\Phi_{\rm FP}}{m\log(1/m)} = -\frac{b^2}{4}(1-r^4) - \frac{bb_{\rm ref}}{2}c^2 + b\eta - bb_{\rm ref}\nu c + S\\
        S &:=   \mathcal{G}(A,B) + m \mathcal{G}(A+C,B).
\end{split}\label{Eq. Re-scaled FP potential}
\end{equation}
Here we had defined the Gaussian integral
\begin{equation}
\begin{split}
    I_l(A,B) &:= \int\mathrm{D}v\ell^l(AN +B\sqrt{N})\\
    \mathcal{G}(A,B) &:= \frac{1}{N}\int\mathrm{D}v\,\log(1+e^{AN + B\sqrt{N}})  
\end{split}  
\end{equation}
The asymptotics for the integrals at the leading order\cite{Erba_2024} are
\begin{equation}
    \begin{split}
        I_{l}(A, B) \approx 
        \begin{cases}
            G\left( \frac{A}{B}\sqrt{N} \right) 
            & -\frac{A}{B^2} \leq 0
            \\
            \frac{\exp\left(- \frac{A^2}{2 B^2}N\right) }{\sqrt{2 \pi N}}K(0,l, A, B)
            & 0 < -\frac{A}{B^2} < l
            \\
            e^{Nf_{A,B}(l)}G\left( - \frac{A}{B}\sqrt{N} -l B\sqrt{N} \right)
            & -\frac{A}{B^2} \geq l
        \end{cases}
    \end{split}
\end{equation}
\begin{equation}
    \begin{split}
        \mathcal{G}(A, B) \approx
        \begin{cases}
                                                            A \,G\left( \frac{A}{B}\sqrt{N}  \right)
            &  - \frac{A}{B^2} \leq 0 \\
            \frac{B}{\sqrt{2\pi N}} e^{ -\frac{A^2}{2 B^2}N }
            & 0 < - \frac{A}{B^2} < 1 \\
            e^{AN+\frac{1}{2}B^2N}G\left( - \frac{A}{B}\sqrt{N} - B\sqrt{N} \right)
            & - \frac{A}{B^2} \geq 1 \\
        \end{cases}
    \end{split}
\end{equation}


with 
\begin{equation}
    \begin{split}
        f_{A,B}(k) &= kA + \frac{1}{2}B^2 k^2  + \caO(N^{-1})\\
        K(0, 1, x, y) &= -\frac{\pi  \csc \left(\frac{\pi  x}{y^2}\right)}{y} \\
        K(0, 2, x, y) &= -\frac{\pi  \left(x+y^2\right) \csc \left(\frac{\pi  x}{y^2}\right)}{y^3}
            = \frac{x+y^2}{y^2}K(0, 1, x, y)
        \\
        G(z) &= \frac{1}{2} \left(1 + \erf \left( \frac{z}{\sqrt{2}}\right) \right)
    \end{split}
\end{equation}

\subsubsection{Overlap with the reference configuration equation}
We begin computing the \textbf{equation for $\mathbf{c}$}, which is related to the overlap between the probe and the reference system. We observe that by imposing the condition that the integral $I_1(A+C ,B) \overset{!}{=} \caO(1)$, we require $A+C\geq 0$. In that case:
\begin{equation}
    c = G\left(\frac{A+C}{B}\sqrt{N}\right)
\end{equation}

If instead $A + C < 0$, we have two cases
\begin{itemize}
    \item if $- B^2 < A + C < 0$ we have the equation
        \begin{equation}
            c = \frac{\exp\left(- \frac{(A+C)^2}{2 B^2}N\right) }{\sqrt{2 \pi N} }K(0, 1, A_2 + C, B)
        \end{equation}
        implying 
        \begin{equation}
            \frac{\exp\left(- \frac{(A+C)^2}{2 B^2}N\right) }{\sqrt{2 \pi N} } = \caO(1)
            \implies 
            A + C = 0
        \end{equation}
        which is a contradiction.
    \item if $A + C < - B^2$ we have the equation
        \begin{equation}
            c = e^{N f_{A+C,B}(1)}G\left( - \frac{A}{B}\sqrt{N} - B\sqrt{N} \right)
        \end{equation}
        implying
        \begin{equation}
            f_{A+C,B}(1) = 0 \implies A + C = - \frac{1}{2}B^2
        \end{equation}
        under the condition that
        \begin{equation}
            A + C = - \frac{1}{2}B^2 < - B^2 \implies \frac{1}{2}B^2 < 0
        \end{equation}
        which is a contradiction.
\end{itemize}

Thus,  the only possible choice is  $A + C \geq 0$ and 
\begin{equation}
    c = G\left(\frac{A+C}{B}\sqrt{N}\right)
\end{equation}

In the case where $c=1$, this is equivalent to setting $\rho_{\rm ref} = m$ and requiring $A+C>0$. This is because $0\leq \ell(\cdot)\leq 1$, which implies that $I_2(A,B)\leq I_1(A,B)$, and by using the magnetization saddle point equation of the probe, we obtain $I_1(A,B) = 0\implies I_2(A,B)=0$. Thus, from the overlap saddle-point equation, we find $r^2=c=1$.
The asymptotic expansion at which $I_2(A,B)=0$ corresponds to the case where $-A/B^2<0$, implying that the leading-order expression for the entropic potential is:
\begin{equation}
    S = bb_{\rm ref}(1+\nu) - b\eta
\end{equation}
In this case, we observe that the terms $b\eta$ and $bb_{\rm ref}\nu$ cancel out in the Franz-Parisi potential  \eqref{Eq. Re-scaled FP potential}, meaning they are not needed to compute the observables. Therefore, the relevant Franz-Parisi potential, the probe sub-matrix average, and the probe entropy can be computed directly from the remaining terms. Specifically, we obtain for $c=1$:
\begin{equation}
\begin{split}
    s_{\rm FP} &= \frac{bb_{\rm ref}}{2} mN^2\\
    a &= b_{\rm ref} \\
    s_{\rm probe} &= 0. 
\end{split}
\end{equation}

For this reason, we will focus only on the case $0\leq c<1$ to study the rest of saddle point equations, where we require at least that the leading order of the argument of $G\left(\frac{A+C}{B}\sqrt{N}\right)$ is $\caO(1)$, which leads to the condition $A + C = 0$, i.e., an equation for $\eta$ of the form $\eta = \eta(\nu, r; b, b_{\rm ref}, c)$.
\begin{equation}
    b b_{\rm ref} (c + \nu) = b\left[ \eta-\frac{b}{2}(1-r^2) \right]
    \implies
    \eta = b_{\rm ref} (c + \nu) + \frac{b}{2}(1-r^2)
    \, .
\end{equation}
Moreover, under these assumptions, the overlap equation simplifies to
\begin{equation}
    I_2(A+C, B) \sim c \implies  (r^2 - c) m \sim I_2(A, B) \, .
\end{equation}
Finally, the entropic potential, at the leading order, is given by $S = \mathcal{G}(A,B)$.\\ 


\subsubsection{Magnetization equation}
We now study the saddle-point equation related to the magnetization of the probe system:
\begin{equation}
      (1-c) m = I_1(A, B),
\end{equation}
given the condition $A+C=0$. We need that both sides of the equations are of the same order in $m$, meaning that $I_1(A,B)$ must at least $\caO(m)$. Thus we analyze the three possible cases of this integral:
\begin{itemize}
    \item If $A \geq 0$ then $I_1 = \caO(1)$ making the equation  inconsistent.
    \item If $-B^2<A<0$, then the equation is 
        \begin{equation}
            (1-c)m = \frac{\exp\left(-\frac{A^2}{2B^2}N\right)}{\sqrt{2\pi N}}K(0, 1, A_2, B_1) \label{eq: FP - small m, magnetization case 2}
        \end{equation}
        implying 
        \begin{equation}
            \frac{\exp\left(- \frac{A^2}{2 B^2}N\right) }{\sqrt{2 \pi N}} = \kappa m
            \implies 
            \frac{A^2}{2 B^2} = 1
            \implies
            A = - \sqrt{2} B
            \implies 
            \eta-\frac{b}{2}(1-r^2) =  \sqrt{2} r
        \end{equation}
        for some positive $\kappa$, giving
        \begin{equation}
            \begin{split} 
            \eta(r) &= \sqrt{2}r + \frac{b}{2}(1-r^2)\\
              \nu(r) &= \frac{\sqrt{2} r}{b_{\rm ref}} - c,
            \end{split} \label{eq: FP - small m, magnetization case 2 - eta and nu}
        \end{equation} where the last expression comes from the assumption $A+C=0$.
        Then, the integral condition becomes 
        \begin{equation}
            -B^2<A \implies |b|r>\sqrt{2},
        \end{equation}
        and the equiation to be solved becomes
        \begin{equation}
            1-c = \kappa K(0, 1, -\sqrt{2}|b|r, |b|r),
        \end{equation} which gives $\kappa$ as function of $r$. In this case the entropic potential is
        \begin{equation}
            S =    \frac{B}{\sqrt{2\pi N}} e^{ -\frac{A^2}{2 B^2}N }= \frac{B}{\sqrt{2\pi N}} m  \ll m N
        \end{equation}
    \item If $A<-B^2$, the equation is:
        \begin{equation}
            (1-c)m = e^{f_{A,B}(1)}G\left(-\frac{A+B^2}{B}\sqrt{N}\right)  \label{eq: FP - small m, magnetization case 3}
        \end{equation}
        implying
        \begin{equation}
            e^{Nf_{A,B}(1)}= m^{f_{A,B}(1)} = \kappa m \implies A = -1 - \frac{1}{2}\implies \eta=\frac{b^2+2}{2b}
        \end{equation}
        for some positive $\kappa$, giving an equation
        \begin{equation}
            \frac{b^2+2}{2b} = b_{\rm ref}(c+\eta) + \frac{b}{2}(1-r^2) \implies \nu(r) = \frac{b}{2b_{\rm ref}}r^2 + \frac{1}{bb_{\rm ref}} - c
        \end{equation}

        The integral condition becomes $A<-B^2$ becomes
        \begin{equation}
            - 1 - \frac{1}{2}B^2 +B^2 \leq 0 \implies |b|r \leq \sqrt{2}
        \end{equation}
        and we can rewrite the saddle-point equation as
        \begin{equation}
            1-c = \kappa G\left(-\frac{A+B^2}{B}\sqrt{N}\right),
        \end{equation}
        where $\kappa$ comes from the sub-leading terms of the integral asymptotics that should be included to solve the saddle-point equations. However, we notice that in this case
        \begin{equation}
            S = \mathcal{G}(A,B) \thickapprox m \kappa G\left(-\frac{A+B^2}{B}\sqrt{N}\right)  \ll m\log\frac{1}{m}
        \end{equation}
\end{itemize}
Notice that in all solutions where $0<c<1$, the entropic potential $S\ll m\log\frac{1}{m}$ and does not contribute significantly to the FP potential $\phi_{\rm FP}$ \eqref{Eq. Re-scaled FP potential}.

\subsubsection{Overlap equation}
The equation related to the overlap of the probe system is
\begin{equation}
    (r^2 - c) m = I_2(A,B)
\end{equation} Again, we study the three possible approximations of $I_2$:
\begin{itemize}
    \item If $A\geq 0$, the magnetization is inconsistent since $I_2(A,B) = \caO(1)$\\
    \item If $-B^2<A<0$, we have the equation
    \begin{equation}
        (r^2-c)m = \frac{\exp\left(-\frac{A^2}{2B^2}N\right)}{\sqrt{2\pi N}}K(0,2,A,B) = m(1-c)\frac{K(0,2, -\sqrt{2}|b|r,br)}{K(0,1, -\sqrt{2}|b|r,|b|r)},\label{eq: FP - small m, overlap case 2}
    \end{equation}
    where we replaced the exponent term with the expression founded for the magnetization equation \eqref{eq: FP - small m, magnetization case 2} in this case. This yields :
    \begin{equation}
        \frac{r^2-c}{1-c} = \frac{K(0,2, -\sqrt{2}|b|r,br)}{K(0,1, -\sqrt{2}|b|r,|b|r)} = 1 - \frac{\sqrt{2}}{|b|r} \implies r^3 - r + \frac{1-c}{|b|}\sqrt{2}=0
    \end{equation}
    to be solved for $r\in[0,1[$ and $|b|r>\sqrt{2}$.
    \item if $-2B^2<A \leq -B^2$, we still having equation \eqref{eq: FP - small m, overlap case 2} but we need to consider the magnetization equation \eqref{eq: FP - small m, magnetization case 3}, the relation $A = -1 + \frac{1}{2}B$ and $\eta(r)$, $\nu(r)$ from Eq. \eqref{eq: FP - small m, magnetization case 2 - eta and nu}. Therefore, we have two sub cases:
    \begin{itemize}
        \item If $r=\sqrt{c}$, the equation \eqref{eq: FP - small m, overlap case 2} is consistent only if \begin{equation}
             \frac{\exp\left(-\frac{A^2}{2B^2}N\right)}{\sqrt{2\pi N}} \ll m \implies \frac{A^2}{2B^2}>1 \implies A<-\sqrt{2}B.
        \end{equation}
        Using the relation between $A$ and $B$:
        \begin{equation}
            1 - \sqrt{2}B + \frac{1}{2}B^2  = (1-\frac{B}{\sqrt{2}})^2 > 0 \implies |b|r\neq\sqrt{2}.
        \end{equation}
        Moreover, from the condition for $I_2$:
        \begin{equation}
            -2B^2<-1-\frac{1}{2}B^2 \implies b^2r^2 >\frac{2}{3}.
        \end{equation}
        Gathering all the information:
        \begin{equation}
             r=\sqrt{c}; \hspace{2em} \frac{2}{3}<b^2c < 2; \hspace{2em} \nu =\frac{b}{2b_{\rm ref}}c + \frac{1}{bb_{\rm ref}} - c; \hspace{2em} \eta = \frac{b^2+2}{2b}.
        \end{equation}
        \item If $r>\sqrt{c}$, equation \eqref{eq: FP - small m, overlap case 2} is consistent only if
        \begin{equation}
             \frac{\exp\left(-\frac{A^2}{2B^2}N\right)}{\sqrt{2\pi N}} = \kappa_2 m \implies \frac{A^2}{2B^2} = 1 \implies A = -\sqrt{2}B \implies |b|r = \sqrt{2},
        \end{equation}where in the last line we use $A=-1-\frac{1}{2}B^2$. Then the equation becomes
        \begin{equation}
            \frac{2}{b^2}-c = \kappa_2 K(0,2,-2,\sqrt{2}),
        \end{equation}
        to be solved for $\kappa_2$ through fixing of the sub-leading orders of the integral asymptotics. Additionally, we need to impose the integral condition 
        \begin{equation}
            -2B^2 < A \implies -2B^2 < -\sqrt{2}B \implies \sqrt{2}B(\sqrt{2}B - 1) > 0 \implies |b|r >\frac{1}{\sqrt{2}},
        \end{equation}
        which is automatically satisfied given that $|b|r=\sqrt{2}$. Then, from the condition $r>\sqrt{c}$, we obtain
        \begin{equation}
            \frac{\sqrt{2}}{|b|}>\sqrt{c} \implies b^2c<2.
        \end{equation}
        Gathering all the information:
        \begin{equation}
             r=\frac{\sqrt{2}}{|b|} \hspace{2em} b^2c<2; \hspace{2em} \nu =\frac{2}{bb_{\rm ref}}; \hspace{2em} \eta = \frac{b^2+2}{2b}.
        \end{equation}
    \end{itemize}
    \item If $A\leq -2B^2$, the equation is 
        \begin{equation}
            (r^2-c)m = m^{f_{A,B}(2)}G\left(-\frac{A+2B^2}{B}N\right).\label{eq: FP - small m, overlap case 3}
        \end{equation}
        Again, we have two cases compatible with equation  \eqref{eq: FP - small m, magnetization case 3}:
        \begin{itemize}
            \item If $r=\sqrt{c}$, equation \eqref{eq: FP - small m, overlap case 2} is consistent only if
            \begin{equation}
                m^{f_{A,B}(2)}\ll m \implies f_{A,B}< -1 \implies 2A +2B^2 < -1 \implies B_1^2 < 1 \implies b^2c < 1,
            \end{equation}
            where we use $A = -1-\frac{1}{2}B$. Moreover, we have the condition $b^2 c\leq 2$ and the integral condition 
            \begin{equation}
                A\leq -2B^2 \implies -1 - \frac{1}{2}B^2\leq -2B^2 \implies b^2c \leq \frac{2}{3}
            \end{equation}
            Gathering all the information:
            \begin{equation}
             r=\sqrt{c} \hspace{2em} b^2c<\frac{2}{3}; \hspace{2em} \nu = \frac{b}{2b_{\rm ref}}c +\frac{1}{bb_{\rm ref}} - c; \hspace{2em} \eta = \frac{b^2+2}{2b}.
        \end{equation}
        \item If $r>\sqrt{c}$, the equation is consistent if 
        \begin{equation}
            m^{f_{A,B}(2)} = \kappa_3 m \implies2A + 2B^2 = -1 \implies |b|r=1.
        \end{equation} This implies that  the condition $A<-2B^2$ is not satisfied, and we should ignore this case. 
        \end{itemize}
\end{itemize}

\subsection{The small magnetization limit --  Observables }
Given the solutions of the saddle-point equations from the previous section, we can now compute the rescaled observables:
\begin{equation}
    \begin{split}
       \text{rescaled Franz-Parisi: } \phi_{\rm FP} &:= \frac{\Phi_{FP}}{m\log(1/m)}= - \frac{b^2}{4}(1-r^4) - \frac{bb_{\rm ref}}{2}c^2 + b\eta - bb_{\rm ref} \nu c \\
        \text{rescaled energy density: }     e &:= \partial_b  \phi_{\rm FP} 
        \\
        \text{rescaled submat average: }     a &:= 2 e
        \\
        \text{rescaled entropy density: }    s_{\rm FP} &:= \phi_{\rm FP} - b e
        \\
    \end{split}
\end{equation}
We emphasize that the derivative with respect to $b$, used to compute the rescaled energy density, should be taken only after evaluating $\phi_{\rm FP}$ at the saddle-point solutions obtained in the previous section. 

